-- Generated by tools/quests/quests.py build from tools/quests/mapping.json (build 1.60.1.70009); never edit by hand.
-- QuestPumpLines[questID] = "rep|hold|cardio|flow": a quest's flavour line for each kind of move (Engine.lua ns.Lines).

QuestPumpLines = {
	[1] = "Two kobold vermin. Small foes, but the reps still count.|The vermin sniff around the marsh. Hold, and let them come.|Kobolds scurry through the mud. Stay on their tails.|A test of a quest. Take it easy and find your calm.",
	[2] = "Sharptalon fell to you. Now earn the walk to Senani.|Raise the claw for all of Splintertree Post to see.|The hunt is done. Take the trophy home at a good clip.|The hippogryph is gone. Let the forest go quiet again.",
	[5] = "Jitters has eaten grubs for weeks. Earn him a real meal.|His gut growls in the ghost town. Wait it out with him.|Off to Darkshire and the Scarlet Raven. Don't let Jitters starve.|Let Jitters dream of crab cakes. Slow and warm, like the tavern.",
	[6] = "Garrick has thugs around him. Push through them all.|Watch the shack by the vineyards. Wait for Garrick to show.|Across the bridge, past the vines. Garrick won't get far.|A cutthroat hides east of the Abbey. Calm hands take the bounty.",
	[7] = "Ten kobold vermin in the northern woods. Marshal McBride waits.|The kobolds dig in. So do you.|Chase the vermin from the woods of Northshire.|First task of many. Settle in, young hero.",
	[8] = "A letter for Renee in Brill. Pay for the trip up front.|Keep the letter safe. Don't peek at what it says.|The road to Brill is waiting, and so are the zombies. Go.|The inn at Brill is cozy. Rest your mind before you get there.",
	[9] = "Twenty Harvest Watchers stand in the fields. Knock them down.|A Harvest Watcher stands still for ages. Outlast it.|Field to field, Saldean's and the next. Clear them all.|Farmer Saldean stayed when all others left. Stay calm like him.",
	[11] = "Eight painted armbands for Deputy Rainer. Earn them.|Hold the line south of the guard tower. The gnolls push hard.|From the woods to Stone Cairn Lake. The Riverpaw pack is big.|Gnolls are loud. You are not. Wait for your moment.",
	[12] = "Fifteen Trappers, fifteen Smugglers. Stoutmantle wants them all.|Near Jangolode Mine the Trappers set snares. Stay put.|Molsen Farm, then the Pumpkin Farm. Chase the Defias down.|To join the militia, first learn to wait. Find your calm.",
	[13] = "Pillagers and Looters, fifteen each. Show them the Light.|The Gold Coast Quarry is theirs for now. Stand firm there.|Moonbrook to Alexston Farmstead. The Defias won't slow down.|The shore is near the quarry. Let the waves set your rhythm.",
	[14] = "Highwaymen, Pathstalkers, Knuckledusters. The last Defias fall.|The Dagger Hills hide them. Stay fast until they come out.|Deep into Southern Westfall. The last Defias are on the move.|The final push for the militia. Clear your head before it starts.",
	[15] = "Ten kobold workers at Echo Ridge. Maybe more. Find out.|Wait at the mouth of the mine. Count the candles inside.|North to Echo Ridge Mine. McBride's scouts were right.|Scouts report, you listen. Take in the mine before you strike.",
	[18] = "Twelve red bandanas. Deputy Willem has a weapon for you.|The Defias lurk across the river. Stay low and watch them.|Across the river to the east. The thieves won't give up bandanas.|Nobody knows what the Defias plan. Think it over, calm and slow.",
	[19] = "Tharil'zun leads the Outrunners. Marris wants his head.|Ambush on the road to Stonewatch Keep. Keep your spot.|The Outrunners live up to their name. Outpace them.|An orc leader is no small foe. Gather your wits first.",
	[20] = "Lakeshire waits for ten Battleworn Axes. Take them.|Lakeshire is penned in. Stand like its wall.|North to the keep, then to the southeast pocket. Hunt them all.|The orcs came from the Burning Steppes. Stay cool against the heat.",
	[21] = "Purge Echo Ridge Mine of twelve Kobold Laborers.|The kobolds dig in deeper. Don't give them ground.|Waste no time, says McBride. Back into the mine.|Deep in the mine, the air is still. Match it.",
	[22] = "Salma needs eight livers for her pie. Go get them.|The gravy is on the fire. Wait for Salma's pie with her.|Goretusks roam all of Westfall. Run them down.|Onions, garlic, dill. Smell the kitchen and take it easy.",
	[23] = "Ursangous was a mighty bear. You were mightier.|The paw bears a moon mark. Keep it up where Senani can see.|Take the paw to Splintertree Post. The hunt goes on.|A strange mark on the paw. Think on it, quiet and slow.",
	[24] = "Shadumbra was swift. Your win was swifter.|The nightsaber lies still now. Be as still as it.|Pace like a nightsaber to Senani with the head.|A fight of the Ashenvale Hunt, done. Let your breath settle.",
	[26] = "Moonglade calls. Earn the trip to Nighthaven.|Cenarius gave you many forms. Hold this one for now.|To Nighthaven to see Dendrite Starblaze. The water form waits.|A protector of nature learns to be patient. Start there.",
	[27] = "Dendrite Starblaze has a lesson. Show up ready for it.|Your trainer is proud. Stand tall and let it sink in.|The road to Moonglade is long. Set off now.|Soon you will glide through water. Picture the lake now.",
	[28] = "Dive for the Shrine Bauble. Other druids want it too.|Under the lake, stay on until the bauble is yours.|The bauble fades fast. Race it to the Shrine of Remulos.|Mind and body sharp, the trial says. Start with the mind.",
	[29] = "Lake Elune'ara hides the bauble deep. Reach for it.|Stay down in the depths. The bauble is close.|Tajarri waits at the shrine. The bauble won't last.|Search the lake with calm eyes. Rushing sees nothing.",
	[30] = "One half is speed, one half is grit. Earn both.|The sea lion can stay under for ages. Show that grit.|Ask around Moonglade. The pendant halves are out there.|Join the two halves by the shrine. Two parts, one calm whole.",
	[31] = "Show Turak the pendant. Prove you earned the water.|Turak Runetotem looks you over. Let him see you are ready.|Thunder Bluff is far. The water form is close.|Soon you become one with the water. Flow like it now.",
	[33] = "Eagan likes wolf steaks. Bring him eight hunks of meat.|Timber wolves prowl the hills. Lie in wait for one.|Young wolves dart across the countryside. Keep up.|Eagan hates the wolves but loves the meat. Mull that over.",
	[34] = "Bellygrub trampled the daffodils. Make him pay for it.|Wait by Martie's garden. Bellygrub always comes back.|Southwest of Lakeshire, the boar forages. Go find him.|Next season the daffodils grow back. Think of that garden.",
	[35] = "Guard Thomas has watched the bridge all week. Match his work.|Stand guard like Thomas at the eastern bridge.|East to the Elwynn bridge. Dughan wants that report.|Are the murloc rumors true? Listen closely to Thomas.",
	[36] = "The Furlbrows are leaving. Take Verna's recipe on for her.|Farmer Furlbrow is still fixing the wagon. Wait with Verna.|Past the fork in the road to the Saldean farm.|A recipe is a piece of home. Keep it close and calm.",
	[37] = "Rolf and Malakai went out. They did not come back.|Stop by the river and look. Any sign of the two guards?|Up the river you go. Look for the lost men.|Guard Thomas needs to know. Stay calm and search with care.",
	[38] = "Three of each for the pot. Vulture, snout, eye, okra.|Salma's pot is empty. Stand by it until it fills.|Vultures, boars, murlocs, all over Westfall. Round them up.|Stew takes time. So does a good calm mind.",
	[39] = "Carry the hard news to Dughan. Two guards are lost.|Too few troops to stop the murlocs. You hold instead.|Back to Goldshire. Dughan needs to hear this now.|Bad news needs a steady voice. Find yours before Goldshire.",
	[40] = "Remy says murlocs are here. Make Dughan listen.|Dughan frets about gnolls. Stand your ground for the east.|Murlocs swim up the streams. Hurry to Goldshire.|Remy is worried. Take his warning in and speak it plain.",
	[45] = "Webbed footprints lead east. Follow them to the end.|The murloc village is in sight. Wait before you go in.|Along the shore of Stone Cairn Lake, eyes on the tracks.|Rolf may be gone. Face what you find with a clear head.",
	[46] = "The Stormwind Army pays well. Eight torn fins, please.|Lurkers wait in the reeds. Outwait them.|Stone Cairn Lake, then the fork in the stream. Clear both.|Murlocs gurgle and splash. You keep your cool.",
	[47] = "Ten pinches of Gold Dust. Remy promises the best price.|In Fargodeep, sit tight. The kobolds hoard their dust.|Fargodeep to Jasperlode. Chase the kobolds for their gold.|Gold dust drifts down slowly. Let your mind do the same.",
	[52] = "Prowlers and young bears, eight and five. Eastvale needs you.|Guard the logging camp. The wolves test it night and day.|Deep into the woods past Goldshire. The beasts roam wide.|Far from town, the wild grows bold. Stay calm among it.",
	[54] = "McBride trusts you now. Carry his papers south.|Northshire is safe for now. Stand proud at the gate.|Down the south road, past the border gates, to Goldshire.|Your first duty beyond the Abbey. Take it in.",
	[55] = "Morbent's Bane breaks his magic. Your blows do the rest.|Raven Hill cemetery lies below. Stand firm in Morbent's house.|Morbent's lair sits on the hill. Get up there fast.|The long road ends at Morbent Fel. Be calm as you face him.",
	[56] = "Eight Skeletal Warriors, six Skeletal Mages. The Watch needs you.|Stormwind pulled its guards. You stand in their place.|Just south of Darkshire, the graves are restless. Go.|Darkshire is always dark. Find a quiet spot in it.",
	[57] = "Skeletal Fiends and Horrors, fifteen each. Raven Hill is crowded.|Among the graves, the bones rise slow. Wait them out.|From Raven Hill to the graves south of town. Drive them out.|Old bones rattle in the forest. You stay quiet and calm.",
	[58] = "Darkshire is in your hands. Twenty Plague Spreaders remain.|Hold the mausoleum door. Nothing gets back out.|Once more to Raven Hill. The Watch is too thin to go.|The eastern mausoleum is cold and hushed. Match its hush.",
	[59] = "A marker for one piece of armor. You've earned it.|Sara Timberlain sizes you up. Stand tall for her.|Past Thomas' post lies the Eastvale camp. On you go.|New armor soon. Picture it keeping Elwynn safe.",
	[60] = "The Pestle brothers need wax. Kobolds carry the candles.|A candle burns steady in the mine. So do you.|South to Fargodeep, or east to Jasperlode. Candles await.|Soft candle light, slow wax. Let it calm you down.",
	[61] = "Morgan waits for the candles. Heft the crate and go.|The crate of candles is heavy. Keep a firm grip.|All the way to the Trade District. Morgan will pay well.|Pestle's Apothecary smells of wax and herbs. Soak it in.",
	[62] = "Kobolds in Fargodeep? Go see for Marshal Dughan.|At the mine's mouth, stop and listen for kobolds.|South of Goldshire, between two homesteads. Into the mine.|Dark tunnels ahead. Let your eyes adjust and your mind settle.",
	[63] = "The Corrupt Manifestation fouls the shrine. Beat it back.|At the Brazier of Everfount, wait for the pure spirit.|The Silverpine coast lies west of the Sepulcher. Get there.|Cleanse the pool, then let the water speak. Listen.",
	[64] = "Thieves fill the pumpkin farm. Get past them to the watch.|Quiet by the wardrobe. The thieves are just outside.|West to the field of pumpkins. You can't miss it.|A wedding gift from Verna's pa. Keep that in mind.",
	[65] = "Wiley owes Stoutmantle a favor. Go and collect.|Blend in at the Lakeshire inn. Say little.|Redridge is a long way. Lakeshire's inn waits.|Who leads the Defias? A calm spy finds out.",
	[71] = "Medallions of two lost guards. Bring them to Thomas.|Thomas will need a moment. Stand with him.|Hurry the medallions to the eastern bridge.|Hard news for Guard Thomas. Gather your words first.",
	[73] = "No reward here. Do the reps for the fun of it.|Nothing to fetch. Nothing to fight. Just stay put.|A quest with no words. Fill the quiet with quick feet.|An empty page. Let your mind go blank too.",
	[76] = "Kobolds in Jasperlode? Your reps will tell Dughan.|At the mine door, look for kobold candles in the dark.|East past Azora's tower, then north. The road is long.|Scouts move soft. Slip into Jasperlode without a sound.",
	[83] = "Six red bandanas. Six Defias who wish they wore burlap.|Crouch by the Defias camp. Wait for the red masks.|Defias camps dot all of Elwynn. Go camp to camp.|Sara sews slow and neat. Take her calm to the next camp.",
	[84] = "Bernice hopes Billy chokes. Your reps just bring the pie.|Keep the Pork Belly Pie level. Don't drop a crumb.|Warm pie, long road. Get it to the vineyard fast.|Bernice is cross. You stay calm and smell the pie.",
	[85] = "Billy scuttles like a rat. Your reps say you mean business.|Linger at the vineyard gate until Billy shows up.|East to the Maclure vines. A widow waits on you.|Warm an old widow's heart. Start with a calm one of your own.",
	[86] = "Four chunks of boar meat. The boars won't give them up.|Boars roam the farms. Stay low and let one come close.|Boar to boar across the fields. Bernice needs meat.|Think of warm pie crust. Let the farm go quiet.",
	[87] = "Goldtooth has the necklace. Make him hand it over.|Deep in Fargodeep, watch for a gold grin.|Down the mine, past the kobolds. Goldtooth runs, you run faster.|The necklace goes home. Billy swears it wasn't him.",
	[88] = "Princess is HUGE. Match her with a big set of reps.|Hide in the pumpkin patch. Princess will come to eat.|Get her before she gets hungry. Go, go, go.|Ma Stonefield's veggies are safe for now. Calm down, farmer.",
	[89] = "Five pikes, five rivets. The gnolls stole them. Take them back.|Oslow's bridge needs its iron. Stand firm like a new beam.|Up into the hills behind Lakeshire. The gnolls ran that way.|Let's get to work, says Oslow. First, one calm moment.",
	[90] = "Chef Grual wants ten lean flanks. The wolves disagree.|Wolves howl in the dark trees. Stay still and let them come.|Wolf after wolf through the forest. Chef Grual waits.|Smell the Stormwind herbs. The kabobs are almost ready.",
	[91] = "Shadowhide pendants, ten of them. The law is clear.|The gnolls serve Morganth. Don't give an inch.|The east foothills hide gnolls. Go find them.|Conacher reads the law slow. Take it in with him.",
	[92] = "Condor, snouts and spider meat. Five of each. Big pot.|Breanna's cupboard is bare. Stay put till the pot is full.|Condors, boars, spiders. Redridge has it all. Go get it.|The goulash isn't made yet. Dream of it.",
	[93] = "Gooey legs, six of them. Venom Web spiders have plenty.|Webs in the trees. Don't move, or they will see you.|Spider nests by the river. Hurry up there.|Crab cakes made of spider. Best not to think too hard.",
	[94] = "Morganth is strong. Your reps carry the glyph to his door.|Set the glyph on the Lion Statue. Keep your hand steady.|To the Tower of Ilgalar, fast and quiet.|The Eye of Azora sees far. Be still so it can see.",
	[95] = "Something is buried by the old stump. Dig it out.|By the old stump, all is quiet. Stay there.|Southeast to Sven's farm. The Dark Riders are long gone.|Sven lost his family here. Go softly on his land.",
	[96] = "The Shard of Water is full of life. Earn the right to carry it.|Water is life. Keep the shard safe and still.|From Silverpine to the Barrens. A long road for water.|Like water, move with no rush. Islen waits.",
	[99] = "Six Pyrewood shackles. Each one holds a curse.|Pyrewood looks calm by day. Wait for the sun to set.|Night falls. The folk of Pyrewood turn to worgen. Move!|Dalar studies Arugal's magic. Think like a mage.",
	[100] = "The dark spirits are gone. Your reps honor the water.|The drops stop hissing. Stay in the quiet with the spirit.|Find the Manifestation of Water in Silverpine. Go now.|Light fades. Let the water spirit speak.",
	[101] = "Madame Eva wants fangs, fingers and venom. Get to it.|The winds warn of danger. Stand your ground in Duskwood.|Ghouls, skeletons, spiders. Duskwood never runs out.|The winds whisper to Madame Eva. Listen too.",
	[102] = "Eight gnoll paws. The farmers of Westfall make their stand.|Danuvin will not turn his back. Neither will you.|Patrol the grasslands. The gnolls are out there.|Wind over the Westfall plains. Feel it pass.",
	[103] = "The Harvest Monsters hold five flasks of oil. Take them.|Keep the torch lit. Stand like the lighthouse.|Field to field for oil. Ships near the rocks need that light.|Grayson keeps watch over the sea. Watch with him.",
	[104] = "Old Murk-Eye led the raids. Make him pay, scale by scale.|Murk-Eye rises from the waves. Be ready on the shore.|Along the coast, rock to rock. Find the old murloc.|A ghost asks for peace. Give it to him.",
	[106] = "Maybell's heart is in this letter. Don't let her down.|Tommy Joe sits by the river. Keep the letter dry.|Due west to the Stonefield river. Love can't wait.|Two families at war. Two young hearts. Sigh along.",
	[107] = "A plan from Gramma. Your reps are part of it.|Gramma's note is sealed. Don't peek.|Goldshire's Lion's Pride Inn. Quick now.|A potion to join two lovers. Dream about it on the way.",
	[109] = "You've seen combat. Stoutmantle wants to see more.|On Sentinel Hill, the Militia is watching. Look sharp.|Into Westfall, to the stone tower. Report in.|Farmlands need you. Take one calm look at them first.",
	[111] = "Tommy Joe is lovesick. Your reps give him hope.|Gramma talks slow. Stay and hear her out.|Just east to the house. Tommy Joe is waiting.|Listen close. Gramma knows best.",
	[112] = "Crystal Lake murlocs hoard the kelp. Four fronds, please.|At the lake edge, a murloc will pop up soon.|Around Crystal Lake. Chase the murlocs down.|The lake is calm. Be calm too.",
	[114] = "This liquor is Maybell's way out. Earn the trip.|Don't spill the Invisibility Liquor. Not one drop.|Rush it to Maybell before the magic fades.|Soon Maybell slips away unseen. Be as quiet as she will be.",
	[115] = "Three Midnight Orbs. The shadowcasters won't let them go.|Dark orbs strike hard. Stand firm and take it.|Through the orc camp. Find the shadowcasters. Go.|Marris will be rid of the orbs. The world gets a bit lighter.",
	[116] = "A keg, a cask, a bottle, a skin. Heavy work for a barkeep.|Balance four drinks. Don't let one fall.|Westfall, Stormwind, Darkshire, Goldshire. A long loop.|Daniels will pour a glass for you. Think of that.",
	[118] = "No iron, no horseshoes. Help Verner get his note there.|Verner's horses wait with bare hooves. Wait with them.|Redridge to Goldshire. Argus needs this note.|Smith Argus hums at his forge. Match his easy mood.",
	[119] = "One crate, fifty horseshoes. That is real work.|Keep the crate steady. Verner must read the note.|Fifty shoes on the move to Redridge. The horses wait.|A pleasure doing business, says Argus. Pass the calm on.",
	[120] = "Lakeshire is under siege. This report must get through.|Hold the report tight. Lakeshire's hope is in it.|Stormwind, and make haste. The judge said so.|Bad news or good, carry it with a calm face.",
	[121] = "The General's reply is in your hands. Earn it.|No rest yet. The letter must reach Solomon.|Solomon waits in Lakeshire. Dismissed, so go!|The King will answer when he can. Rest a bit.",
	[122] = "Black dragons don't give up scales. Six, please.|Whelps fly south of Lakeshire. Wait for one to pass.|The whelps wander. Chase them all over Redridge.|Eyes on the sky. Whelps like to wander.",
	[123] = "Gold from the mines to the Collector. Dughan must know.|The schedule names days and times. Guard it close.|Goldshire and Dughan. This sounds important.|Who is the Collector? Think it over on the road.",
	[124] = "Brutes, ten. Mystics, eight. The stable will be safe.|Gnolls prowl the ridge. Stand guard by the stable.|Strays go missing on the ridge. Chase the gnolls off.|Horses rest in the stable. Be as calm as them.",
	[125] = "A toolbox on the lake bed. Oslow wants it back.|Take a big breath. The toolbox is deep in Lake Everstill.|Down to the lake floor and back up. Don't dawdle.|The lake is still and cool. Sink into it.",
	[126] = "Yowler is no mongrel. Bring your best reps.|His cry is louder than the rest. Wait for it.|Scatter the pack in the hills above Lakeshire.|Hear the baying fade. Then go for the leader.",
	[127] = "Reel in ten spotted sunfish from Lake Everstill.|Line in the water. Wait for the tug.|No bite? Go take them from the murlocs.|Lake Everstill is famous for calm days. Enjoy one.",
	[128] = "Fifteen Blackrock Champions. Solomon wants them gone.|These are the King's mountains. Plant your feet.|North to the orc camp, by the road to the Steppes.|Champions lead the clan. Stay cool when you meet them.",
	[129] = "Parker is big and strong. His lunch should be too.|Parker's lunch smells good. It is not yours.|Down the road to Duskwood. Parker is on patrol.|A free lunch waits back in town. Worth the trip.",
	[130] = "Flowers for Darcy. Don't say who they're from.|Martie asks who they're for. Keep your lips shut.|West end of town. The herb shop is there.|Martie's shop has sweet herbs. Take them in.",
	[131] = "A bouquet of daffodils. Martie's favorite, now Darcy's.|Daffodils bruise easy. Mind the petals.|Daffodils wilt. Reach Darcy before they do.|A secret gift is sweet. Keep the secret.",
	[132] = "Wiley's note could cost him his life. Make it count.|Hide Wiley's note. The Defias have eyes.|Sentinel Hill needs this note. Don't be followed.|Gnolls, kobolds, goblins. The plot thickens. Think.",
	[133] = "Seven ghoul ribs. A scarecrow for ghouls needs them.|Bone Chewers pound on Abercrombie's walls. Be his wall.|Flesh Eaters, Brain Eaters, Rotted Ones. Pick a ghoul.|Abercrombie lives far from town. Enjoy the quiet while it lasts.",
	[134] = "The crate lies near the ogre mound. Snatch it.|Ogres swagger past. Stay low until they leave.|In, grab the crate, and out before the ogres notice.|Herbs and tools, safe once more. Abercrombie will smile.",
	[135] = "The Stonemasons and the Defias? Shaw will know.|Old Town has dark corners. Shaw likes those.|Off to Stormwind, to the SI:7 barracks.|A growing mystery. Let the clues settle.",
	[136] = "One rusty anchor. Find it, and the locker is near.|Scan the Western Coast. Only one anchor will do.|Shipwreck to shipwreck along the sand. Hunt the anchor.|Waves roll where Ol' Captain Sanders sleeps.",
	[137] = "A commendation from a Marshal. The General wants proof.|General Jonathan likes a straight back. Show him.|Bring your document to Stormwind. Lion Emblem gloves await.|Your deeds in Elwynn earned this. Take a proud moment.",
	[138] = "Sander wants you east up the bluffs. Climb there in reps.|The old barrel waits by the chimney. Let it wait a bit longer.|Due east, matey! Up the bluffs and on to the road.|Look for the chimney ruins. A pirate's clue likes a calm eye.",
	[139] = "North from the barrel, as the crow flies. Count your reps like steps.|The lone windmill creaks. Stay put by the empty jug.|Keep walking north until the windmill shows on the sea bluffs.|Poke around the jug slowly. Sander hid his clues with care.",
	[140] = "The jug smells of whiskey. The chest smells of gold. Reps first.|Wait at the shore and hold your nerve. The island is out west.|Swim straight west, matey! The treasure island won't come to you.|Float like driftwood between the waves. The chest is close now.",
	[141] = "VanCleef rebuilt Stormwind stone by stone. Match him in reps.|Shaw's letter is sealed. Hold it close and don't budge.|Take it to Stoutmantle at once! Westfall is a long road.|The Stonemasons felt cheated. Think on it calmly on the way.",
	[142] = "The Defias Messenger carries secrets. Pry them loose with reps.|Wait by the road near Moonbrook. The messenger will pass.|Chase him from the Gold Coast Quarry to the Jangolode Mine.|A quiet watcher catches the messenger. Be as quiet as the road.",
	[143] = "Lakeshire needs the militia. Earn their help with your reps.|Solomon's plea is in your pack. Stay put; Stormwind is late.|From Redridge to Westfall, the plea must not wait.|Solomon would not sit by. Stand tall and calm like him.",
	[144] = "Stoutmantle's heart is heavy. Carry his answer with your reps.|No men to spare. Hold the line in Westfall, as he does.|Back to Redridge with the answer. The road is long.|Bad news goes best with a calm face. Take a slow breath.",
	[145] = "The Night Watch could save Lakeshire. Win them over with reps.|Duskwood's woods are dark. Stay on the road and don't budge.|Swiftly to Darkshire! Don't stray from the roads.|Ebonlocke is a mayor. Arrive calm, not out of breath.",
	[146] = "Ebonlocke says no. Push through his letter with your reps.|Darkshire needs its Night Watch at home. Stand guard with them.|The letter must reach Lakeshire. Back through Duskwood you go.|Solomon won't like this news. Walk it back with a calm mind.",
	[147] = "The Collector steals gold from the mines. Make him pay in reps.|He hides in the pumpkin patch. Wait low among the vines.|Go to the Brackwell farm. Find the thief. Get the ring.|The ring may name his boss. Look at it with calm eyes.",
	[148] = "The old man can't make the trip. Your reps will do it for him.|Abercrombie is old and frail. Stay strong in his place.|Darkshire is far for an old man. Not for you.|Madame Eva lives on the square. Let her see you calm.",
	[149] = "Dark things lurk near Mary's farm house. Clear the path with reps.|Blind Mary combs her hair. Wait, and do not startle her.|South into the hills, Spectral Comb in hand.|A sad spirit needs a gentle guest. Move soft and slow.",
	[150] = "Eight Murloc Fins for Baren. The lake's fish count on your reps.|Watch the shore of Lake Everstill. The fishmen will come.|Murlocs fish up a storm. Chase them from the lake.|The lake is still at dawn. Match it before the murlocs wake.",
	[151] = "Eight Handfuls of Oats for Blanchy. Scoop them up in reps.|Freeze in the fields while the harvest machines pass.|Farm to farm across Westfall. Blanchy is hungry.|Blanchy is a tired old beast. Rest with her a while.",
	[152] = "Seven of each kind. Tidehunters first, then more reps.|Grayson keeps the lighthouse. Keep your spot like its light.|Up and down the Westfall coast, past the shipwrecks.|The Great Sea is rough. You can be the calm between waves.",
	[153] = "Fifteen Red Leather Bandanas. Galiaan wants proof in reps.|The Defias Front keeps shifting. You don't.|Track red bandanas across Westfall. Don't lose the trail.|A scout watches first. Follow the Defias with a quiet eye.",
	[154] = "Mary wants the comb gone. Your reps carry it away.|Mary weeps in the farm house. Stay quiet and let her be.|Back to Darkshire with the Ghost Hair Comb!|Some sorrow can't be fixed. Take a slow breath for Blind Mary.",
	[155] = "The Defias want the traitor's head. Your reps guard it.|Stay close by his side. The Defias are watching.|Follow the traitor to the hideout. Don't fall behind.|A scrawny guard, he says. Show him a calm one instead.",
	[156] = "Eight Rot Blossoms in eight skulls. Smitts won't go near them.|Skeletal Fiends roam Raven Hill. Keep your place among the graves.|From graveyard to graveyard, hunt the Skeletal Horrors.|Zombie juice takes patience. So do rot blossoms.",
	[157] = "Ghost Hair Thread can bind spirits. It binds you to your reps.|Abercrombie's shack sits north of the cemetery. Wait at his door.|North past Raven Hill Cemetery. The old man is waiting.|The thread is thin as a ghost's hair. Move gently with it.",
	[158] = "Abercrombie's nights are cold. Build some fire with your reps.|The Scarlet Raven Tavern is warm. Wait by the bar.|Hurry to Smitts! Abercrombie needs fire in his veins.|A tavern at night is a calm place. Enjoy it while it lasts.",
	[159] = "Zombie Juice can raise the dead. Raise your reps instead.|Careful with that bottle. Hold it steady all the way.|Juice for Abercrombie! Don't spill a drop on the way.|Walk slowly with the bottle. It is not a drink for you.",
	[160] = "Abercrombie laughs too much. Keep your reps honest anyway.|The note is sealed. Keep your hands off it and stay put.|Take the note to Mayor Ebonlocke. Old friends can't wait.|Something in that laugh feels wrong. Think it over calmly.",
	[161] = "Strange powder for Stonesmirk. Make the trip count with reps.|Guard the powder like a live spark. Don't let it jolt.|Through the Algaz Gate and the Wetlands. Stop for nothing!|Explosive powder likes a steady hand. Keep yours calm.",
	[163] = "Shadows move at Raven Hill. Face them with a few reps.|Watch the dark window. Wait for the light to show again.|On to Raven Hill, where the shadows move at night.|Calor saw shadows. Stay calm and see what is really there.",
	[164] = "Sven's camp is small. Your reps can do the work of a man.|Sven's few followers stand guard. Stand with them a while.|To the northwest edge of Duskwood with the supplies!|Take your time on the road. Sven does the work of the Light.",
	[165] = "The old man hasn't come to town. Earn a look with reps.|Wait by the shack on the hill. Listen for the hermit.|Out to Raven Hill to check on the hermit.|Something may be amiss. Look around slowly and calmly.",
	[166] = "Edwin VanCleef built Stormwind. Now he must fall. Reps first.|The Deadmines are deep. Brace yourself before VanCleef's ship.|Through the mines, onto the ship, to VanCleef himself.|Stoutmantle takes no joy in this. Face it with a calm heart.",
	[167] = "The tunnel caved in. Dig out the truth with your reps.|Wilder waits for news of his brother. Be as patient as he is.|Deep into the Moonbrook mine to find the badge.|A badge can bring some peace. Carry it gently.",
	[168] = "Four Miners' Union Cards. Four families wait on your reps.|The mine wing is dark and still. Stay put in the rubble.|Search the fallen tunnels for every lost card.|Remember the miners who fell. Take a long, slow breath.",
	[169] = "Gath'Ilzogg leads the Blackrock. Knock him down with reps.|He is holed up in Stonewatch Keep. Wait for the gate to open.|Storm the keep before the Blackrock plan their next raid.|He is very dangerous. A calm mind walks into that keep.",
	[170] = "Six Rockjaw Troggs, six Burly ones. Strong arms, strong reps.|The troggs took the west camp. Dig in by the frozen lake.|Troggs pop up all over the hills. Stay after them.|Balir is shorthanded. Calm hands make up for it.",
	[174] = "A bronze tube for Viktori's star device. Build it up with reps.|Aim the tube at the stars and keep it steady.|Find a skilled engineer. Cog's blueprint can't wait.|Look up at the stars. The truth may be out there.",
	[175] = "Mary carried a looking glass. Earn a peek at it with reps.|Wait at the old farm house. Mary may come out.|South through Duskwood to find Mary.|Ask Mary gently. She has had a hard time.",
	[176] = "Hogger is a big gnoll. Take him down with your reps.|Hogger has beaten every hunter so far. Don't give an inch.|Hunt Hogger through the woods of southwest Elwynn.|Goldshire waits for his claw. Stay calm and aim true.",
	[177] = "The Insane Ghoul has Mary's glass. Win it back with reps.|Wait behind the barn. The ghoul roams the graves at night.|Search the cemetery for the ghoul and the glass.|Mary threw the glass away. Pick it up with care.",
	[178] = "Theocritus speaks from the pendant. Answer him with reps.|A voice speaks from the pendant. Freeze and listen.|To Tower Azora in Elwynn with the Faded Shadowhide Pendant.|Months of study went into this spell. Take it in slowly.",
	[179] = "Eight pieces of Tough Wolf Meat for a pair of warm gloves.|Frost bites in Coldridge. Last until the gloves are yours.|Chase the wolves through the snow. Sten is waiting.|Sten is a kind soul, he says. Be kind and slow too.",
	[180] = "Lieutenant Fangore leads the Shadowhide. Show him your reps.|Fangore works for Morganth. Stand fast against them both.|Track Fangore through Redridge. Bring back his paw.|Solomon wants proof. Take a calm breath, then take the paw.",
	[181] = "Zzarc'Vul wears a big monocle. Pry it off with your reps.|Wait at the ogre mound. Zzarc'Vul knows you're coming.|Into the southern ogre mound for the last lens!|Soon Viktori will see the stars. Look up and breathe with him.",
	[182] = "Fourteen Frostmane Troll Whelps. A few strong reps will do.|Wait at the mouth of the southern cave. The whelps will come.|Clear the troll cave before the Senate hears of it.|No army needed, Grelin says. Just you and a calm mind.",
	[183] = "Twelve Small Crag Boars, all angry already. Meet them with reps.|The boars charge. Plant your feet like Talin.|So many boars in Coldridge. Chase them down.|Talin knows the hunt. Watch the snow before you strike.",
	[184] = "The Defias stole Furlbrow's deed. Take it back with reps.|The Furlbrows sit by a broken wagon. Wait with them a while.|Find the Furlbrows before they leave Westfall.|A whole farm on one paper. Carry it gently.",
	[199] = "A sample of strange powder. Hinderweir wants reps and answers.|The powder smells odd. Keep it steady in your pack.|Back to Hinderweir with the clue!|Think about who left this powder. Take a slow look.",
	[214] = "Ten Red Silk Bandanas. Only the top Defias wear them.|VanCleef's hideout is full of his best men. Don't back off.|Hunt high ranking Defias through the hideout.|Silk means rank. Riell reads the cloth, you read the room.",
	[217] = "Grawmug, Gnasher and Brawler. Three foes, plenty of reps.|Gnasher and Brawler never leave his side. Neither do you.|Lead the charge on Grawmug. Push the troggs back underground.|Plan the attack on the chieftain with a cool head.",
	[218] = "Grik'nir the Cold stole Grelin's journal. Take it back with reps.|Grik'nir's cave is icy. Stay firm in the cold.|Deep into the troll cave to find the big brute.|Odd markings on his face. Look close and stay calm.",
	[219] = "Keeshan is weak. Carry the fight for him with your reps.|Guard Corporal Keeshan. The orcs won't let him go easy.|Lead Keeshan out of the cave and back to Redridge.|You're his last hope. Stay calm for both of you.",
	[220] = "The Vial of Purest Water must reach Islen. Earn it with reps.|Keep the vial level. Water spirits dislike a spill.|Across the Barrens to find Islen Waterseer.|Be like water: calm, clear and patient.",
	[224] = "Ten Stonesplinter Troggs and ten Scouts. Push them back in reps.|Troggs tunnel up from every crack. Guard the Loch.|Across Loch Modan after every trogg you see.|The King's soldiers are far away. Be the calm at home.",
	[226] = "Twelve starving wolves, eight rabid ones. Lars wants them gone.|Stand firm by the river. Let the wolves come to you.|Lars runs home with meat and the wolves chase. Outrun them.|Sven's camp is quiet at dusk. Listen for paws in the trees.",
	[230] = "The mound gave up a book. Dig out your reps for Sven.|The book is dirty and small. Keep it close and stay put.|Sven waits at camp. Get his book there fast.|Wipe the dirt from the cover. Sven will want to read it.",
	[233] = "A stack of letters for Talin. Count them out as reps.|The frozen lake is cold. Stand firm with the mail bag.|West down the road to Talin's camp. The snow won't slow you.|Talin's lake is frozen flat. Let your mind go just as still.",
	[234] = "One letter left for Grelin. Make your reps worth the stamp.|Grelin waits for his mail. You wait right here, firm.|Southeast down the road. Grelin is eager, so be quick.|Last letter of the day. Take a slow look at the snowy valley.",
	[235] = "Senani wants hunters for Ashenvale. Your reps are the tryout.|Splintertree Post stands firm in the woods. So do you.|North out of the Barrens to Ashenvale. Long road, fast feet.|Ashenvale's trees are old and quiet. Take in the green.",
	[237] = "Ten Skullthumpers, ten Seers. Gravelgaw wants them all.|Guard the southern tower till the dwarves come home.|The troggs flee into the hills. Stay right behind them.|The Seers chant in the hills. You stay calm and wait.",
	[239] = "Westbrook needs soldiers. Stormwind has none. You'll do.|Stand guard like the Westbrook men. Gnolls watch the road.|Cross the brook bridge and the garrison is on the right.|Rainer has a list of jobs. Clear your head before you read it.",
	[240] = "Grual's crab cakes are done. Jitters is hungry. Get to work.|Keep the plate level. The cakes must reach Jitters whole.|Hot crab cakes go cold fast. Get them to Jitters.|Smell the cakes, but don't eat one. Jitters is counting.",
	[241] = "A test quest. Mister Wilson says to give it a real try.|Nothing here but a log. Wait it out like a test dummy.|Hey, Mister Wilson! He is not coming. Go anyway.|An empty quest page. A good spot to just breathe.",
	[244] = "Gnoll camps to the north and east. Lakeshire must know.|The road is safe for now. Stand your post a bit longer.|Take word to Feldon in Lakeshire. A scout's wage waits.|Count the gnoll fires in your head before you report.",
	[245] = "Fifteen Venom Web Spiders. Dodds can't pay much. Do it anyway.|The webs are sticky. Don't twitch, or they'll know you're there.|Dodge the venom. Spiders are quick, but you're quicker.|Eight legs, eight eyes. You need only one calm mind.",
	[246] = "Feldon wants a count: ten Mongrels, six Poachers.|Watch the southern road. Count the gnoll camps from cover.|Harry the gnolls all along the road. Don't let up.|Feldon needs a clear report. Think it through slowly.",
	[247] = "The hunt of Ashenvale is done. Show Senani what you've got.|Trophies on the wall at Splintertree. Stand proud by them.|One last lap through the Ashenvale woods for the hunt.|The great hunt is over. Let the forest go quiet again.",
	[248] = "Up the tower by Stonewatch Keep. Orcs below, stairs ahead.|Hide the Glyph in a jar and freeze. The orcs must not see.|Climb the watch tower fast, before the orcs look up.|At the top, look out over Redridge. Theocritus is watching too.",
	[249] = "Morganth seeks the Scythe of Elune. Your reps say he won't use it.|Stand at the top of the Tower of Ilgalar. Face his dark might.|Through the Tower of Ilgalar to the top. Morganth waits.|Theocritus fears him. You don't. Take a calm breath and go in.",
	[250] = "Dark Iron Sappers by the Dam. Hinderweir needs a clue.|Crouch by the eastern ramp. Watch what the Sappers do.|Down the ramp and back. The Dam can't wait.|Look close at the ground. The clue is small.",
	[251] = "Abercrombie's note is a puzzle, and Sirra can read it.|Keep the letter safe in your pack. Its words are dark.|Across Darkshire to Sirra Von'Indi, letter in hand.|Sirra knows old tongues. Be patient while he reads.",
	[252] = "Abercrombie did something awful. Ello has to know.|A doom lumbers toward town. Stand ready for it.|Rush the note to Ello. Doom is on its way.|Read the note once more. Then take it to Ello, calm.",
	[253] = "Eliza waits in her grave. Take back the Embalmer's heart.|The heart still beats. Keep a firm grip till you reach Ello.|The heart beats fast. Get it to Ello before it stops.|A sad tale from a children's book. Face it with a calm mind.",
	[255] = "Four Ogres, four Brutes, four Enforcers. Bluntnose pays.|Thelsamar has no guards. For now, you are the wall.|Ogre camp, northeast of the lake. Bring some friends.|Hired arms plan before they swing. Think through the camp.",
	[256] = "Chok'sul leads the ogre raids. The Magistrate wants his head.|Wait by the ogre camp until Chok'sul shows himself.|Northeast Loch Modan. Chok'sul won't hunt himself.|Read the wanted poster once more. Then go get him.",
	[257] = "Six Mountain Buzzards. Daryl says you can't. Prove him wrong.|Buzzards circle high. Wait till one swoops low.|The clock is on. Daryl is already smirking.|Let Daryl's sneer slide off you. Aim with a clear head.",
	[258] = "Five Elder Mountain Boars. This isn't Coldridge Valley.|Stand your ground when the boar charges. Daryl never did.|Less time this round. The boars won't wait for you.|Daryl tells his scar story again. Tune him out and focus.",
	[259] = "Ol' Kelt chased a lake beast for years. Match his grit.|Kelt waited by the lake for his myth. Wait with him.|Go find Kelt Thomasin before the story gets any taller.|A huge threshadon under the lake? Picture it, calm and slow.",
	[262] = "Sven saw a skulker the night his family fell. Find him.|Show the book and wait. Someone in Darkshire will know it.|Door to door through Darkshire with Sven's book.|A clue hides in plain sight. Look at the book with fresh eyes.",
	[263] = "Wallbang wants ten Shaman and ten Bonesnappers, Trogg-Slayer.|The reserves are gone. You alone hold the guard tower.|Troggs in the hills. Chase them down before they regroup.|Live up to the name. Trogg-Slayers stay cool under fire.",
	[264] = "Clarice wants nothing of Yuriv. Carry her anger to his tomb.|Stand at Yuriv's tomb a while. He was always second to duty.|All the way to the Sepulcher in Silverpine. Long trip.|Set the pendant down with care. Clarice couldn't.",
	[265] = "The book was bought in Darkshire. Ask around. Keep at it.|Someone saw the stranger. Wait for the right face.|Another townsfolk, another clue. On to the next door.|Think back. Who in Darkshire sells books?",
	[266] = "The inn sees all who pass. Earn a seat at the table.|Sit by the fire at the inn. Listen for a name.|Up and down the inn stairs. Any room may hold a clue.|Innkeepers love to talk. Let the stories wash over you.",
	[267] = "Eight Trogg Stone Teeth for Captain Rugelfuss. Go collect.|Rugelfuss can't leave the Gate. Guard it like he does.|Wage an assault on the hills. Troggs don't stop for you.|Stone teeth, stone faces. Be as still as the hills.",
	[268] = "Jitters gave up his journal. Carry the truth to Sven.|Jitters can't face Sven's wrath. You can. Stand firm.|Sven's camp needs the full journal. Quick now.|The journal was Jitters' only friend. Carry it with care.",
	[269] = "Morbent Fel must fall. First, Bishop Farthing must hear.|In the Cathedral of Light, stand tall and wait your turn.|The shadows of Duskwood grow. Hurry to Stormwind.|Farthing is kind and wise. Share his calm for a while.",
	[270] = "Lightforge Iron lies with the Third Fleet. Glorin knows where.|The fleet sank long ago. Stand firm on the harbor dock.|All the way to Menethil Harbor. Morbent Fel won't wait.|Picture the sunken ships of Kul'Tiras, quiet under the waves.",
	[271] = "Ol' Sooty gave Daryl his scar. Give Sooty a bad day.|Ol' Sooty rears up. Stand your ground this time.|Up the hills over Thelsamar to Sooty's lair.|Daryl will be speechless. Enjoy the quiet while it lasts.",
	[272] = "Two halves of the Pendant of the Sea Lion. Go find both.|The sea lion never tires. Stay put and show you don't either.|Glide like a sea lion. Search the Moonglade waters.|Join the halves at the Shrine of Remulos. Calm hands.",
	[273] = "Miran and Saean haul heavy barrels. Match their load.|Huldar's crew moves slow. Wait for the barrels to catch up.|South out of town, round the Loch. Catch up to Huldar.|The Loch shines in the sun. Enjoy it on the long walk.",
	[274] = "Seaforium Powder. Wet, it could blow Ironforge sky high.|Don't spill the powder. Keep it dry and keep it steady.|Tell Hinderweir now, before it's too late!|Silver crystals, a strange smell. Take it all in, calm.",
	[275] = "Rethiel wants twelve Fen Creepers gone. The land needs peace.|Wade in and plant your feet. The Creepers shamble near.|Wade through the Wetlands. Find the next one fast.|Once they fall, the marsh can rest. So can you.",
	[276] = "The fen needs balance: fifteen Gnolls, ten Mongrels.|The gnolls stamp the flowers flat. Don't give an inch.|Hunt south toward the gate of Algaz. Stay on the chase.|Rethiel feels each tree fall. Be as quiet as the fen.",
	[277] = "Nine Crude Flints. No flint, no fire, no cut trees.|Rethiel will suffer this no longer. Neither will you. Stay firm.|Find the big Mosshides. Only they carry flints.|The trees of the Wetlands breathe easy. Join them.",
	[278] = "Lurker Venom, a Crocolisk Tear, a Mo'grosh Crystal. Find all three.|Crocolisks rest by the Loch. Stay low until one shows.|Spiders, crocs, then ogres. A lot of ground to cover.|The crystal is rare. Stay calm. It will turn up.",
	[279] = "Twelve Bluegills on the shore. Make your reps count for Menethil.|Gobbler hides by the inlet. Hold firm until he shows his face.|Chase the Bluegills up the river inlet. Gobbler is getting away!|Murlocs hear loud feet. Go quiet like the fishers of the harbor.",
	[280] = "Stir the mixture in. The Dam's fate is in your hands.|The keg waits at the base of the Dam. Stay steady.|Swim down fast. The keg could blow at any moment!|Deep water is quiet. Keep your head clear down there.",
	[281] = "Crates and barrels wash up on the coast. Your reps pry the lids off.|The statuette of Terenas is in here somewhere. Hold until it turns up.|Murloc camps line the shore. Dash from barrel to barrel.|Wet sand, soft waves. Search the hovels with a calm, patient eye.",
	[282] = "Senir's report needs sure hands. Yours. Don't drop it.|Thalos guards the tunnel. Stand guard beside him.|Back to Anvilmar, then east to the tunnel. On your way.|The tunnel is full of troggs. Get your nerve ready.",
	[283] = "The keg fizzled out. The Dam stands. Tell Hinderweir.|The Dam still stands. So do you. Enjoy it.|Race back up to Hinderweir with the good news.|No boom today. Let the calm of the Loch settle in.",
	[284] = "No statuette here. On to the next Murloc hovel.|Crouch by the hovels. Murlocs don't like guests.|More hovels lie north. Get moving.|Think like a Murloc. Where would you hide shiny things?",
	[285] = "Nothing here either. The next hovel must be the one.|Murlocs turn their backs soon. Then you search.|Up the coast to the north. The statuette is close.|You're sure the next clue is the one. Trust that feeling.",
	[286] = "The statuette is found. Karl Boran will be glad.|The little paladin can break. Don't drop him.|Menethil Harbor waits for its silver prize. Off you go.|A young paladin with his hammer up. Look at him a while.",
	[287] = "Senir was too scared. Five Frostmane Headhunters, please.|Peek into the cave. So many trolls. Wait for a gap.|Follow the frozen river west to Iceflow Lake.|Senir needs his report. Take in the cave before you leave.",
	[288] = "A flagon for the old First Mate. Pay for it in reps.|His head pounds. Stay put while he finds his tale.|Off to the bar and back before his tale runs dry.|Red dragons, burning ships. Let the sea go calm.",
	[291] = "Senir's report weighs little. Barin Redstone's mood weighs more.|Redstone glares. Don't budge while he reads.|North from Kharanos, over the bridge, up to Ironforge.|Say nothing of Senir's help. Just a calm face at court.",
	[297] = "Eight idols, eight mad troggs. Take them back.|The idols drive troggs wild. Stay firm while they rage.|The troggs charge. Go at them and don't slow down.|Magmar wants to study them. Take a slow look at the stone.",
	[298] = "More blastpowder, says Ironband. Your reps make the case.|Report in hand. Stand like a dwarf on guard.|Down the road to Thelsamar. Not hard, but it must be done.|Jern Hornhelm reads slowly. Match him.",
	[301] = "Stormpike is hotheaded. Bring reps, not excuses.|Stormpike yells. Stand firm and let it pass.|Loch Modan to the Assembly of Explorers. Go.|Duck the shouting. Find a calm spot inside.",
	[302] = "By Magni, Ironband gets his powder. And you get your reps.|Eyes open, mind sharp. The last shipment never made it.|Back to Thelsamar before the messenger forgets.|Jern packs the powder. Slow and careful, or boom.",
	[307] = "Four loads of Miners' Gear. Lift them out of the mine.|Kobolds sniff around. Keep low by the crates.|Through the Silver Stream Mine before the kobolds notice.|Good dwarven tools, safe at last. Let the dust settle.",
	[309] = "Dark Irons want that powder. Show them why not.|Miran rests. Guard the powder while he does.|Stay with Miran all the way to the dig site.|Eyes on the hills. Miran feels better with you near.",
	[310] = "Swap a barrel of Scalder for Thunder Ale. Heavy work.|The guard turns. Stay low in the cellar.|Down to the cellar and back. Quick feet, no noise.|Quiet as a barrel. The Thunderbrews never know.",
	[311] = "A barrel of Thunder Ale is your proof. Lug it home.|Keep the barrel steady. No spills on the way.|Kharanos to Brewnall Village with a stolen barrel.|Marleth grins. The prank is done. Let it sink in.",
	[312] = "The locker is thorium. Old Icebeard gave up. You won't.|Old Icebeard sleeps. Don't wake him.|In and out of the cave fast, like Tundra never could.|A bear dreams nearby. Stay soft and quiet.",
	[313] = "Eight Wendigo Manes for Trollplow's rug. Take them.|An iron grip and nerves of steel, says Stonegear. Prove it.|West of Kharanos, the Grizzled Den waits. Go get manes.|Cold air in the den. Let it fill you, then let it go.",
	[314] = "Vagash took two rams. You take one fang.|Vagash lurks above the ranch. Wait for his leap.|Up the hill to Vagash. The herd needs you fast.|Night cries over the ranch. Rudra waits in the calm.",
	[315] = "Six Shimmerweeds for the perfect stout.|Trolls watch the baskets. Wait for your chance.|High in the eastern hills, the shimmerweed grows.|Brewing is in Rejold's blood. Patience is in yours.",
	[317] = "Boar meat and bear fur. Supplies for Jetsteam's long trip.|A bear stands in the snow. So do you.|Snow fields south of the Grizzled Den. Hunt.|Bellowfiz needs soft bedding. Think of warm fur.",
	[318] = "Evershine lays dwarves flat. Stay on your feet.|Rejold fills the cask. Wait for it.|West of Kharanos to Brewnall Village.|Warm as Evershine on a cold road.",
	[319] = "Six bears, eight boars, eight leopards. Brewnall thanks you.|A snow leopard waits in the drifts. Wait longer.|The beasts roam the snow. Chase them from the village.|With the beasts gone, the dwarves get back to brewing.",
	[320] = "One cask of Evershine. It burns hot in Jetsteam's furnace.|Careful with the cask. It's more fire than drink.|Back to Steelgrill's Depot. Jetsteam is ready to roll.|The hunt is over, the cask is here. Bellowfiz smiles.",
	[321] = "The Flying Osprey sank with its iron. Bring it up.|Down in the wreck, stay a bit longer. Search every corner.|South of Menethil Harbor, the wreck lies in the waves.|Burned ships rest below. Drift among them.",
	[322] = "A crate of Lightforge Ingots. Heavy all the way to Stormwind.|Grimand hears your tale. Stand tall as he listens.|Wetlands to Stormwind. The crate won't carry itself.|A weapon to worry Morbent Fel. Picture it.",
	[323] = "Fifteen raiders and six more bones. Sven is counting.|Skeletons clatter close. Hold your ground.|Morbent Fel's minions come in waves. Meet them.|Sven must know your skill. Show him a steady mind.",
	[324] = "Murlocs took the ingots. Five pieces of iron to win back.|Murloc raiders splash near the wreck. Let them come.|Chase the raiders up and down the shore.|Waves lap at the Flying Osprey. Match their pace.",
	[325] = "Morbent's Bane is in your hand. Feel its weight.|You're ready, says the smith. Stand like you mean it.|Stormwind to Duskwood with Morbent's Bane.|A tale of glory waits. Gather yourself first.",
	[332] = "A free bottle of pinot noir. Earn it anyway.|Suzetta reads the ticket. Wait at the counter.|Along the canals to the Gallina Winery.|Wine by the canals. Let the city drift by.",
	[333] = "Everyone buys armor lately. Harlan needs cloth, you need reps.|A cold, harsh season ahead. Brace for it.|Hurry the Cloth Request to the Canal Tailor.|Knitted clothes, soft and warm. Think of those.",
	[334] = "Shears and needles for Thurman. Small kit, big help.|Thurman can't work without his tools. Wait with him.|Deep into the Mage Quarter, near the tower.|Thread through a needle takes a calm hand.",
	[337] = "An overdue book. Muddy, scratched, and still heavy.|The librarian frowns at the date. Take it.|Duskwood to the Stormwind Library. It's late already.|Turn the old pages. History moves slowly.",
	[343] = "The Stresses of Iron. Stress some iron of your own.|Fortitude of the Spirit. Brother Kristoff wants it shown.|To the Royal Library in Stormwind Keep. Find Milton.|A speech of the Light waits. Settle before it starts.",
	[344] = "Margulf Blaggon dug ore for decades. Dig into your reps.|Milton rambles. Wait for the point.|Out of the city to Northshire Abbey.|Paxton took ages to copy it. No hurry for you either.",
	[345] = "Rethban Iron Ore for Paxton's ink. Ask Oslow for it.|The ink dries too fast. You don't.|Northshire to Lakeshire, over the Redridge hills.|Ink that won't smear. A careful hand made it.",
	[346] = "The original Stresses of Iron. Back where it belongs.|Kristoff gets his book at last. Stand while he thanks you.|To Cathedral Square before the speech begins.|Tell Milton sorry for Paxton. Then rest easy.",
	[347] = "Five loads of Rethban Ore. Break it from the stone.|Gnoll Drudgers dig nearby. Wait for your turn.|Into the Rethban Caverns, north of Lakeshire.|Dark, flat ore for Paxton's ink. Look at its color.",
	[350] = "Lescovar thinks he's above the law. Prove him wrong.|Evidence without witnesses. Wait for a better plan.|Through the Trade District to find Trias.|Help from an old friend. Take a calm moment first.",
	[352] = "Great Mammoda has claws like swords. Show her yours.|One swipe and poof. Don't be the next old story.|The Lady of the Loch waits. Go find her.|The old teller walks again. Listen close.",
	[353] = "A weapon for Gringer Stormpike. Carry it with pride.|The package is fine work. Keep it safe.|Stormwind to Loch Modan. A long road north.|The northern guard tower is far. Take it slow and easy.",
	[354] = "Gregor, Nissa and Thurman. Three Agamands, three sets of bones.|The Agamands walled up their home. Be harder than their walls.|Through Agamand Mills, room to room.|Coleman was loyal once. Think on what that cost.",
	[355] = "Sevren heard of your deeds. Add to the list.|The Magistrate wants a word. Stand before him.|Across Brill to the Magistrate.|Coleman has his revenge. Now the Forsaken need you.",
	[356] = "Eight Bleeding Horrors, eight Wandering Spirits. Clear them.|Guard the rear of The Bulwark. Nothing slips past.|Patrol east to Balnir Farmstead.|One front at a time. Keep your mind on this one.",
	[357] = "The lich's minions attack all who come. Push through them.|Wait at the edge of the lich's camp for your chance.|Across to the island in Brightwater Lake and back.|Quiet steps near the lich's spellbook.",
	[358] = "Eight Embalming Ichors from Rot Hide gnolls. Sevren waits.|Stand guard at the Mass Graves. The dead stay put.|From the Mass Graves to Garren's Haunt, hunt the Rot Hides.|The graves are quiet again. Keep them that way.",
	[359] = "Scourge slipped past The Bulwark. Sevren must know.|Watch the border. The Plaguelands never sleep.|South along the road, then east at the fork.|Linnea has the news. Clear your head to hear it.",
	[360] = "Scourge on the road? Take them down on the way.|Keep the news safe in your head. Sevren needs all of it.|Be swift, says Linnea. Back to Brill.|News delivered. Let the quiet of Brill settle in.",
	[361] = "Thurman wrote to Yvette. The letter never came. Fix that.|The seal is old. Keep the letter safe.|Find Yvette Farthing, wherever she is.|Words from a lost son. Handle them gently.",
	[362] = "Devlin Agamand was weak in life. Show him what strong is.|His mad chatter drifts from the mills. Don't let it shake you.|Up the road to Agamand Mills. Follow the chatter.|Coleman wants poor Devlin at rest. Bring a quiet mind.",
	[363] = "You made it out of the crypt. Prove you're awake.|Mordo almost tossed you in the fire. Stay put this time.|Down the hill to the chapel. Sarvis waits.|No longer the Lich King's slave. Feel that.",
	[364] = "Eight Mindless, eight Wretched. The Fallen fall again.|Zombies shamble close. Don't give an inch in Deathknell.|The north of the village is overrun. Sweep it.|Once brothers and sisters. Now just the Mindless.",
	[365] = "Ten pumpkins from a human farm. Heavy, round and stolen.|The Scarlet Crusade patrols. Keep still in the patch.|West to the farm, then all the way to Brill.|Learn the ways of the Forsaken. Patience first.",
	[366] = "Gunther's Spellbook holds a spell. Take it to him.|Gunther sees the book and remembers. Wait for him.|Out to Gunther's Retreat on the island.|Old friends from Dalaran, both free now.",
	[367] = "Five vials of darkhound blood for Johaan.|A darkhound growls. Stare it down.|The darkhounds roam wide. Go after them.|Johaan tests a theory. Wait and watch.",
	[368] = "Five Vile Fin Scales from the murlocs up north.|Murlocs gurgle at the shore. Wait for them to come.|Along the coast north and west, hunting Vile Fins.|Johaan plans a plague for a whole world. Plan your calm.",
	[369] = "Four sacs of venom for Johaan. Count your reps like fangs.|A spider waits in its web without a twitch. Hold like it.|East Tirisfal is far. Keep your feet going to the webs.|Johaan stirs his pot slowly. Match his calm.",
	[370] = "Perrine and six of her men. Pay them back in reps.|The ruined tower is theirs. Hold until the brigade breaks.|Zealots dash around the tower. Stay on their heels.|Zygand plans in silence. Think like him before the tower.",
	[371] = "Five Scarlet Friars, one Vachon. Your reps are the blow.|Vachon raids near Balnir Farmstead. Stand firm there.|From Brill to the southeast tower is a long road. Go.|The friars pray. You breathe, calm, and wait your turn.",
	[372] = "Melrache has two guards. Give them all your reps.|Wait in the shadows past Faol's Rest. The guards must not see.|The last tower is north. Run for the Dark Lady.|This war ends with Melrache. Slow breaths before the strike.",
	[373] = "VanCleef's letter weighs little. Your reps weigh more.|The seal is still fresh. Keep it safe and stay put.|Cathedral Square is far from the mines. Head there now.|A sealed letter, a dead man's words. Take a calm breath first.",
	[374] = "Ten Scarlet rings. Burgess wants proof, so give him reps.|The Crusade holds Tirisfal. Hold longer than they do.|The glades crawl with Crusaders. Chase them all down.|Varimathras is watching. Show him a calm, clear mind.",
	[375] = "Five Duskbat pelts for a blanket. Stitch them in reps.|Gretchen's hands shake. Yours stay still as stone.|The chill is coming for Gretchen. Warm up and go.|Slow and gentle, like a needle through a pelt.",
	[376] = "Six paws, six wings. Elreth has armor for your reps.|Stand like a wolf at the edge of the woods.|Wolves and bats to the south. Off you go, fast.|Elreth sews with care. Move with the same care.",
	[377] = "Dextren Ward waits in his cell. Your reps are his sentence.|Stormwind guards are everywhere. Stand firm, unseen.|From Darkshire to the Stockade is a long road. Move.|Lord Ebonlocke gave the sentence. Carry it out with a calm mind.",
	[380] = "Eighteen spiders in the gold mine. Count them down in reps.|Webs fill the mine. Stay put like a fly who knows better.|Spiders scuttle in the dark. Chase them out of the mine.|Arren says little by little. Go slow and clear the hollow.",
	[381] = "Twelve red armbands. Your reps will fill Arren's bag.|The Crusade camp is set. Stand your ground before it.|Strike first, says Arren. Get to the camp fast.|Their zeal is loud. Your mind stays quiet.",
	[382] = "Meven Korgal carries secrets. Take them from him in reps.|Watch the camp. Wait until the messenger is alone.|The messenger came from the Monastery. Don't let him leave.|Calm hands open his bag. The secrets are yours now.",
	[383] = "The papers are full of secrets. Make your reps count.|At the crossroads, stop. Then take the eastern fork.|Past Cold Hearth Manor, on to Brill. Don't slow down.|The road east is long and quiet. Walk it in your mind.",
	[384] = "Six boar ribs for Ragnar. The Malt is the easy part.|Wait by the fire while the ribs soak in the Malt.|The crag boars won't catch themselves. After them!|The secret's in the Malt. And in a slow, easy breath.",
	[385] = "Five meat, six skins. Wrestle the crocs in reps.|Crocs lie still on the islands. So can you.|Swim out to the islands. The crocs are waiting.|Marek has a story. Breathe easy while he tells it.",
	[386] = "Targorr the Dread awaits his end. Your reps bring it.|A noble put a hold on his end. Your hold lasts longer.|Lakeshire to the Stockade is far. Hurry, before the trick.|Berton wants justice, not rage. Keep your head clear.",
	[387] = "Ten prisoners, sixteen more. Thelwater needs your reps now.|The cells are open. Hold the hall for the warden.|The riot spreads cell to cell. Get ahead of it.|Chaos in the Stockade. You are the calm one.",
	[388] = "Ten red bandanas for Nikova. Mac deserves your reps.|Nikova waits for news of Mac. Stand for him.|The Defias wear red in every cell. Find them all.|Grief runs deep in Nikova. Let yours go, softly.",
	[389] = "The Stonemasons built Stormwind. Build your reps the same way.|Thredd waits in his cell. Wait with him.|The Stockade is across town. Get there quick.|Old wrongs and broken deals. Take in the story slowly.",
	[391] = "Thelwater wants Thredd's head. Your reps earn his trust.|Talk first, then strike. Stay ready while Thredd speaks.|Down through the riots to Thredd's cell. Don't stop.|Hear Thredd out before the end. A clear mind decides.",
	[392] = "Maelik's papers checked out. Now check out your reps.|The description is sealed. Keep it shut and stay firm.|Back to Baros Alexston, from the Stockade to Cathedral Square.|The quiet type, the warden said. Be the quiet type too.",
	[393] = "Shaw owes Alexston a favor. Your reps settle the rest.|SI:7 agents wait in the dark. Wait like one.|Old Town barracks. Slip through the city streets.|Shaw knows every shady deal. Show him a clear head.",
	[394] = "Lescovar is dealt with. Shaw will want the tale in reps.|Don't let praise go to your head. Stand firm and humble.|Old Town is waiting. Bring the news to Shaw.|A hero of Stormwind breathes easy after the storm.",
	[395] = "Alexston wants the Defias story. Tell it in reps.|Say nothing of Trias. Hold your tongue and your spot.|Alexston came by while you were out. Catch up to him.|Shaw's advice is simple. Keep quiet and stay calm.",
	[396] = "King Varian will read this report. Make your reps worthy.|Stand tall before the King. Wait to be called.|Stormwind Keep is a ways off. Hurry to your audience.|Before the King, one calm breath. Then speak.",
	[398] = "Maggot Eye steals corpses. Brill pays for his paw.|Garren's Haunt is quiet. Wait for the gnoll to show.|North of Brill, Maggot Eye is on the move. Chase him.|Mercy is for the weak, says the poster. Focus is for you.",
	[399] = "A lost compass on a burned farm. Dig it out with reps.|Thieves hold the Alexston farm. Stay low and wait.|West of Sentinel Hill lies the old farm. Head out.|A boy's first compass. Let it point you to calm.",
	[400] = "Beldin breaks spanners fast. Bring him more with your reps.|A box of spanners, held tight all the way.|Northeast of Kharanos to Steelgrill's Depot. Go.|Keep your ears open at the Depot. Listen and breathe.",
	[401] = "Sirra is almost done with the note. Fill the wait with reps.|The note is nearly read. Wait right here.|Sirra is still at work on the note. Stay busy.|Let Sirra work in peace. Quiet breaths.",
	[404] = "Seven putrid claws. Beat back the rotting dead in reps.|Hold the old bridge west of Brill. The Scourge won't pass.|Scatter their bones! Dillinger wants you on the go.|Rotting dead are slow. Be slower, and calm.",
	[405] = "Bethor wants a proven agent. Prove it here.|Sevren's orders stay sealed. Stand firm and ready.|South to the Undercity. The Magic Quarter awaits.|A wayward lich waits. Ready your mind first.",
	[406] = "Nothing here but you and your reps.|An empty page. Fill it by staying put.|No road, no map. Go anyway.|A blank quest. A quiet breath to match.",
	[407] = "One laced pumpkin. The zealot won't like his snack.|Wait in the cellar. Let the zealot take a bite.|Down to the Gallow's End cellar. Go now.|The pumpkin looks harmless. Stay calm, like it.",
	[408] = "Sixteen ancestors and one Dargol. Lay them down in reps.|The crypt door is shut. Stand guard before it.|Through Agamand Mills to the crypt. Keep going.|The Agamands deserve rest. Give them a calm moment.",
	[409] = "Lillith wakes when the candle burns. Meet her with reps.|Light the candle and wait at the altar.|Off the island's south coast, the altar waits. Get there.|Gunther needs proof. Show him a calm hand.",
	[411] = "Gunther has much to say. Carry his gem in reps.|The Nether Gem hums. Keep it steady.|From Gunther's island to the Undercity. Go.|Old friends meet again through a gem. Breathe softly.",
	[412] = "Eight cogs, eight gears. The Recombobulator needs your reps.|Leper gnomes swarm outside Gnomeregan. Stand firm.|Grab gears before the gnomes run off with them.|Razzle's machine is almost done. So are you. Slow down.",
	[413] = "A full barrel of Shimmer Stout. Heavy. Show it who's boss.|Keep the barrel steady. Wellart wants it full.|South to the guard tower. Wellart is thirsty.|A brewer's gift, carried with care.",
	[414] = "The cask goes to Kadrell. Your reps bring it.|At the fork, stop. Then turn northeast.|Through the tunnel and on to Thelsamar. Don't stop.|Kadrell will like it. Enjoy the calm road first.",
	[415] = "Rejold has a new drink. Earn a taste with reps.|Rejold talks brew. Stay and listen.|Back to Brewnall Village. Free booze might wait.|The brew is still in the barrel. Let it settle, like you.",
	[416] = "Twelve tunnel rat ears. The bounty waits for your reps.|Kobolds hide in their dens. Wait them out.|Up and down the mountainside after the rats.|The foothills west of Thelsamar are calm again. Almost.",
	[417] = "Mangeclaw is a huge bear. Answer his claws with reps.|Mangeclaw growls in the hills. Face him and don't budge.|The bear roams the hills. Track him down.|Hildelve's last wish. Honor it with a calm mind.",
	[418] = "Bear meat, boar guts, spider goo. Three of each, in reps.|Vidra says you must work for meals. Stand and work.|Bears, boars and spiders all over Loch Modan. Hunt!|Leave the cooking to Vidra. You just breathe.",
	[419] = "Hildelve is tough as nails. So are your reps.|Hammerfoot guards the engines. Guard your spot too.|Search the hills for Mori Hildelve. Keep looking.|Beastly growls at night. Listen close, stay calm.",
	[420] = "Troggs in the tunnel. Grelin says you're tough enough.|Angry troggs ahead. Stand firm in the tunnel.|Through the tunnel and down the road to Kharanos.|Grelin's report is safe. Walk out of the valley calm.",
	[421] = "Five Moonrage Whitescalps. Prove yourself to Dalar.|Stay on the hill above the road. Watch the beasts.|Down the hill to the road. The beasts are near.|Arugal's mess is big. Start with a clear head.",
	[422] = "Arugal's books are dusty. Dig the Remedy out in reps.|Deathstalkers failed here. Stay steady at the farm.|North of the bridge to the wheat farm. Go get it.|Read the spell slowly. Arugal's magic is weak anyway.",
	[423] = "Six Glutton shackles, three Darksoul. Dalar needs your reps.|The Moonrage beasts howl. Stand your ground.|North and east, the Gluttons roam. After them!|Dalar calls Arugal a hack. Stay calm, be better.",
	[424] = "Grimson rules the Deep Elem Mine. Your reps end his shift.|Wait at the mine mouth for the pale foreman.|Southeast into the hills to the mine. Move out.|With Grimson gone, the mine is quiet. Breathe with it.",
	[425] = "Ivar mauled Quinn. Your reps pay him back.|Ivar waits in the barn for a guard to drop. Don't drop.|To the barn yonder. Catch Ivar before he returns.|Quinn needs time and quiet. Give him both.",
	[426] = "Notched Ribs, Blackened Skulls. Rattle loose a few with your reps.|The windmills turn. Stand your ground until the Mills are clear.|West road, the bridge, then north. The battle starts at the windmills.|Dillinger waits in Brill. Let the dust of the Mills settle in you.",
	[427] = "Ten Scarlet Warriors by the tower. Your reps serve the Dark Lady.|Zygand wants initiative. Show it by not giving an inch.|Past the Solliden Farmstead to the tower. Go, and don't slow.|The Scarlet Crusade shouts. The Forsaken wait quietly. Be Forsaken.",
	[428] = "Two lost Deathstalkers. Your reps clear the path to the farms.|Deathstalkers lie low in the farms. Stay low with them.|North through Silverpine, farm to farm. The Yoricks are out there.|Listen for the Yoricks. A scout finds more by being quiet.",
	[429] = "Three worg hearts. The worgs won't give them up without reps.|Worgs prowl toward Malden's Orchard. Let them come to you.|From the worgs to Renferrel at the Sepulcher. Quinn is waiting.|Rane is worried for his brother. Be the calm one.",
	[430] = "One potion for Quinn. Carry it like it weighs a ton.|Don't drop Quinn's potion. Steady hands the whole way.|North from the Sepulcher to the Ivar Patch. Quinn needs this.|Renferrel is back at his work. Take a quiet breath on the road.",
	[432] = "Six Rockjaw Skullthumpers. Stonebrow cheers on your reps from the rim.|Another barrel of powder goes up. Brace and wait for the dust.|Down into the quarry. Stonebrow's aim is bad; yours had better not be.|Stonebrow is angry enough for two. You can stay cool for both.",
	[433] = "Ten Bonesnappers for the Senator. The Senate likes a strong vote.|Stand in Gol'Bolar like the Senate's own statue.|The troggs poured out of the deep. Chase them back in.|Stonehallow wants to rebuild. First, set your own stones in place.",
	[434] = "Lescovar and Marzon. Two traitors, and your reps settle both.|Wait in the garden. Not a word until they speak of the Defias.|Strike fast, before the guards return. Go, go, go!|Spybot plays his part. You play yours: quiet as a garden shadow.",
	[435] = "Hungry wolves outside Erland's door. Show them reps, not dinner.|The wolves eye Erland. Stand beside him and stare them down.|Erland walks to Rane, wolves on all sides. Stay with him.|Erland is nervous enough. Your calm helps him take the next step.",
	[436] = "Ironband's crew is slow. Show them what honest work looks like.|Something works against the dig. Stay put and watch the ruins.|Around the south tip of the lake, then east to the excavation.|Fellhew knows the details. Clear your head before you ask him.",
	[437] = "Rot hides at the Dead Fields until Nightlash shows. Keep at it.|Nightlash's magic breaks the Forsaken lines. Your line stays.|Storm the old farm. The banshee comes when the gnolls fall.|When Nightlash turns to dust, let the Dead Fields go quiet.",
	[438] = "Rot hides patrol the Decrepit Ferry. Push through them.|Watch the ferry from cover. The Scourge are here for a reason.|East of the Sepulcher to the ferry. Find out what they want.|Look, listen, think. The ferry will tell you its secret.",
	[439] = "One small ring, one heavy secret. Lift it for Hadrec.|For Deliah, the ring says. Keep it safe in your grip.|Deliah's Ring goes back to the Sepulcher. Hurry, Hadrec waits.|A name on a ring. Take a quiet moment for Deliah.",
	[440] = "Records of the dead fill Sevren's shelves. Put in your own work.|Hope may be thin, as Hadrec says. Stand firm anyway.|To Brill with the ring. Magistrate Sevren keeps the records.|Who gave Deliah her ring? Let the question sit with you.",
	[441] = "Raleigh waits in the Trade Quarter. Earn the right to knock.|Deliah's Ring in your hand. Stand as still as the Undercity.|Down into the Undercity. The Trade Quarter is a long way in.|Raleigh may know the ring. Go gently with his memories.",
	[442] = "Thule Ravenclaw leads the rot hides. Your reps end his reign.|Fenris Isle is his place of strength. Make this spot yours.|Storm the Isle. Hadrec wants Thule's head, and he wants it now.|As dangerous as it is vital. Gather yourself before the Isle.",
	[443] = "Eight bottles of rot hide ichor. The gnolls pay for each one.|Fenris Isle crawls with gnolls. Plant your feet at the water's edge.|East of the Decrepit Ferry to Fenris Isle. Fill those bottles.|Renferrel reads the ichor like a book. Read the moment the same.",
	[444] = "A sample of ichor for Bethor. Strong arms keep the vial safe.|Warlock and necromantic magic swirl in that vial. Keep it steady.|To the Magic Quarter of the Undercity. Bethor's help can't wait.|Renferrel's findings are not sure yet. Let the answer come.",
	[445] = "Johaan's findings for the New Plague. Lift the load for the Dark Lady.|Time is a luxury, Johaan says. Spend a little of it here.|South from Brill, down the roads to the Sepulcher. No time to waste.|Renferrel is a colleague. Arrive calm, like a proper apothecary.",
	[446] = "Thule betrayed his brethren. Your reps are the reply.|Bethor's Scroll holds the incantations. Keep it flat and safe.|Back to the Sepulcher with the scroll. Renferrel has a potion to make.|A young mage turned to the Scourge. Think on the road he took.",
	[447] = "Six bear hearts, six spider bloods. Faranell expects a full count.|The Skittering Dark is full of spiders. Stay put in the webs.|From the Skittering Dark to the bears of Silverpine. Keep going.|Grizzled bears are slow and heavy. Borrow their calm.",
	[448] = "Hadrec may have gear for Fenris Isle. Show him you can carry it.|Stand before the High Executor. He likes a soldier who waits.|Back to the Sepulcher before the assault. Hadrec is waiting.|The Isle comes next. For now, listen to Hadrec's plan.",
	[449] = "The Deathstalker Report is vital. Push it through for Hadrec.|Rane trusts you with the report. Keep it close and steady.|Quick as you can to the Sepulcher. The report can't be late.|Quinn rests with Rane now. Take the quiet road to Hadrec.",
	[450] = "Sons of Arugal fill Pyrewood. Push through to the inn.|Berard's study is upstairs. Wait for the hall to clear.|Grab the journal and get out of Pyrewood Village. Fast!|Berard studied the dead lake. Read slowly, as he did.",
	[451] = "Moss from Skulkers and Creepers. Six of each for Faranell.|One Vile Fin has the Hardened Tumor. Wait at the shore for it.|Island to island across Lake Lordamere. Don't let up.|The lake was once full of life. Take in its still water.",
	[452] = "Faerleia can't beat the Council alone. Bring your reps.|The Council will be back any moment. Wait with Faerleia.|Council members come one after another. Stay in the fight!|Arugal's puppets are gone. Let Pyrewood fall quiet around you.",
	[453] = "Not from Darkshire, nervous, gone west. Track him down.|A jittery man hides in the wilds. Stay quiet so he won't bolt.|West out of Darkshire. Find him before the beasts do.|Put the three clues together, one calm thought at a time.",
	[454] = "Barrels of powder, trip after trip. Help Miran with the load.|Miran's barrels must not wobble. Steady now.|Miran is ready to go. The road back to the dig is long.|After the ambush, a quiet moment before the next haul.",
	[455] = "Eight Dragonmaw Scouts, six Grunts. Break their grip on Algaz.|The Dragonmaw want Dun Algaz. Stand in the pass and say no.|Through the tunnels, north, then west to Menethil Harbor.|Valstag Ironjaw waits by the sea. Arrive with a clear head.",
	[456] = "Seven Young Nightsabers, four Young Thistle Boars. For balance.|Ilthalaine keeps nature in balance. Find yours and keep it.|Shadowglen is too crowded. Chase down the boars and sabers.|Spring rain, green forest. Breathe in with Shadowglen.",
	[457] = "Seven Mangy Nightsabers, seven Thistle Boars. Even work.|Nature's harmony wobbles. Be the steady part of it.|Deeper into the forest. The work is not done yet.|A hard job for the good of all. Let the forest settle again.",
	[458] = "Show Tarindrella what Shadowglen's new heroes can do.|The forest spirits whisper. Stay quiet and hear them.|Southwest of Aldrassil. Tarindrella won't wait forever.|Something is amiss in the grove. Calm first, questions after.",
	[459] = "Eight Fel Moss from the grells. Pull it off them, one by one.|The Gnarlpine gather in the hills. Watch them from cover.|Grells and grellkin all over the hills. Chase them down.|Fel Moss twists the mind. Keep yours clear and gentle.",
	[460] = "Alaric's body lies in an unmarked grave. Dig in with your reps.|Alaric's head is in your hands. Keep him level, he gets dizzy.|Across Fenris Keep to the stable. Alaric wants his body back.|Head and body together at last. Let Alaric rest in peace.",
	[461] = "Take the body, leave the boots. Alaric is picky.|Behind a dusty shelf, a hidden alcove. Wait while it opens.|Up the southwestern tower of the keep. Alaric knows the way.|Something dear to Thule waits in the niche. Look closely.",
	[462] = "Maruk Wyrmscale cut the road to Menethil. Your reps cut him down.|Across the pond, Maruk waits in his cave. Wait better.|Between the second and third tunnels. Find Maruk's cave.|One scout did not return. Go in with a clear, quiet mind.",
	[463] = "Crocs and worse in the marsh. Greenie is bigger than all of them.|Somewhere among the crocs, the Greenwarden lurks. Don't twitch.|East of the fork to Dun Modr, into the marsh. Mind your gold.|Folk say you're crazy to seek him. Stay calm and prove them wrong.",
	[466] = "Six loads of Incendicite Ore. Swing hard, but careful: it explodes.|Volatile stuff, incendicite. Stay very still near the vein.|To the cave northwest of Algaz Gate. Stonegear wants that ore.|One careful strike at a time. Nobody blows up today.",
	[467] = "Stonegear loves his siege engine. Show him some muscle of your own.|Stonegear talks tanks for ages. Stand there and nod.|Boots itching? Head for Steelgrill's Depot in Dun Morogh.|A rare ore, a rumor. Let the hunt start in your head.",
	[468] = "Rockgar wants volunteers. Step up and show him your reps.|The guard tower stands firm on the road. Stand like it.|North up the road, past the tower, to Dun Algaz.|The soggy Wetlands lie ahead. Enjoy dry boots while you can.",
	[469] = "A heavy bundle of crocolisk skins. Heave it toward Menethil.|He'd rather not face his wife. Brace yourself for him.|To James Halloran in Menethil Harbor. Then maybe a pint.|A good place to relax, Menethil. Arrive in that mood.",
	[470] = "Dripping oozes at Ironbeard's Tomb. One of them ate Sida's bag.|They all look the same. Wait and watch which ooze bulges.|Northeast toward Dun Modr. Sida really needs that bag.|Sida panicked. You won't. Slow and sticky wins this one.",
	[471] = "Six Giant Crocolisk Skins. The crocs won't give them easily.|Big crocs up the coast. Stay low in the marsh grass.|North up the coast, past the murloc huts, to the crocs.|Halloran lost his apprentice's help. Skin with care.",
	[475] = "The Druids of the Talon sleep. Work hard so they can rest.|A troubling breeze blows. Stand firm as it passes.|East to Starbreeze Village. Gaerolas is late with word.|The Sleeping dream with Ysera. Let your breath be just as soft.",
	[476] = "Ursal the Mauler drives the Gnarlpine mad. Carry the news.|Gaerolas can't make the trip. Stand guard for him a while.|Back to Dolanaar with grave news. Athridas must hear it now.|Hope Ban'ethil is safe. Carry that hope gently.",
	[477] = "Dalaran crates by the wagon. Pry one open for the Forsaken.|A camp north of Pyrewood. Wait for the wizards to look away.|South toward Pyrewood Village. Grab the goods and go.|Why Ambermill? Think it over while the camp sleeps.",
	[478] = "One strange pendant. Small, but Allister will weigh it well.|Lid back on the crate. Stay still until no one notices.|Take the pendant to the Sepulcher before they miss it.|Runes on the pendant. Look them over with care.",
	[479] = "Eight Dalaran Pendants from conjurers, mages and protectors.|Ambermill's wizards cast from behind walls. Outlast them.|South down the main road, east fork, into Ambermill.|Dalar hunts the source of their magic. Think like him.",
	[480] = "The archmage has mages and warders all around. Get through them.|The ley node hums. Stand your ground against its power.|Cut through to the archmage fast. Then take his staff.|Great power, many guards. A calm mind picks the right moment.",
	[481] = "Dalar can read runes. You can do reps. Fair trade.|Dalar studies the runes. Wait while he squints.|Across the Sepulcher to Dalar. The wizards won't wait.|Maybe Dalar sheds some light. Let it dawn on you slowly.",
	[482] = "Ley pendants power the node. Each one you take stalls Dalaran.|Keep Ambermill's secret until Allister hears it.|The Sepulcher waits. Get the news there before the wizards act.|Allister likes a clear head. Let the Kirin Tor plot settle in yours.",
	[483] = "Talisman, quill, sapphire, rune. Four relics for your reps.|The druids sleep in the Barrow Den. Stay as calm as their dream.|Gnarlpine roam the Den. Reach the chests before they do.|Soft steps in the barrow. Do not wake what should still sleep.",
	[484] = "Young croc skins, six of them. Halloran pays top coin for your reps.|Young crocs lurk in the shallows. Wait them out like Einar would.|Splash through the water outside Menethil. The crocs are quick.|Menethil's tide rolls in and out. Match its pace.",
	[486] = "Ursal the Mauler hits hard. Your reps answer him.|Stand firm at Gnarlpine Hold. The Mauler must come to you.|The ritual waits on Ursal. Race to the southwest and end it.|Athridas chants the waking rite. Breathe with the sleeping druids.",
	[487] = "Darnassus needs its road. Six ambushers stand in the way.|Amara watches from the vantage point. Stay put like a Sentinel.|Down to the furbolg den and back up the road. No stopping.|The sacred forest hums around Dolanaar. Let it steady you.",
	[488] = "Fangs, feathers, silk. Three of each for a satyr who smiles too much.|Zenn wants it kept secret. Keep quiet and keep your spot.|Nightsabers, owls, spiders. The forest makes you chase them all.|Something about Zenn feels off. Take a calm moment to think it over.",
	[489] = "Three Fel Cones, one smug satyr. Earn back the Council's favor.|Green smoke drifts from the cones. Wait for Foulhoof to take a bite.|Fel Cones fall from the trees. Grab them before they roll away.|The forest forgives those who make amends. Let the calm come back.",
	[490] = "Fifteen Gnarlpine Fangs. Shayla counts them all.|Ban'ethil Hollow teems with furbolg. Stand your ground.|From the Hollow to Starbreeze and back. The bounty won't wait.|The glade was calm before the corruption. Bring that calm back.",
	[491] = "Three old friends wove this wand. Do your reps for Bethor.|Thule could never let the wand go. Grip it the same way.|From Fenris Keep to the Undercity. The wand is going home.|Old friendship, woven tight. Let it loosen as you breathe.",
	[492] = "Johaan's drink is ready. The mountaineer is not.|The Gallows End cellar is cold. Wait by the prisoner's cell.|Down the tavern stairs, drink in hand. Don't spill a drop.|A subtle hint of the Dark Lady's plan. Let it sink in.",
	[493] = "Renferrel's findings are full of hard work. Match it with reps.|Keep the notes close. The road south is long.|Follow the signs to Tarren Mill. It's a long road on foot.|Hillsbrad is far. Set a calm pace before you set out.",
	[494] = "The raven's cry from the west doth beckon. Answer with reps.|Lesh says be silent. Be silent, and be still.|East to Tarren Mill, with urgency! Lesh insists.|Remember the message word for word. Let your mind go quiet.",
	[496] = "Ten Gray Bear Tongues. Lydon's mood won't improve, but yours might.|Creeper Ichor is rare. Wait for the right creeper to show.|Bears and creepers roam outside Tarren Mill. Go get them.|Lydon hates clean air. Take a deep breath of it anyway.",
	[498] = "Drull and Tog'thar are locked up. Break them out of Durnholde.|Guards pass the cells. Wait in the shadows of Durnholde Keep.|Across the river, into the keep, out again with two friends.|Krusk fought bravely and lost. Plan your way in with care.",
	[499] = "Umpi gets the first taste. Lydon wants to see results.|Hand Umpi the elixir and wait for the face he makes.|Umpi is hiding nearby. Find him before he runs off.|Nothing brightens Lydon's day like a gloomy one. Enjoy the quiet.",
	[516] = "Drudgers and Guardians, six of each. Beren's Peril gets a surprise.|The cave hides in the hills. Wait until you spot it.|Search the hills near the wizards. Beren's Peril is out there.|Turn the tables with a cool head. Allister trusts your wits.",
	[527] = "Hillsbrad's northern farms feed the town. Darthalia wants them shut.|Stand at attention, Darthalia says. Do it.|West to Hillsbrad Fields. The farms are wide and busy.|Varimathras gives orders. Clear your head before you follow them.",
	[528] = "Fifteen peasants hide in the orchards. Darthalia is counting.|Wait among the orchard rows until the peasants show.|The peasants flee south through the fields. After them!|The townsfolk panic. You do the opposite.",
	[529] = "Verringtan's hammer rings for Hillsbrad. Stop the forge.|A shipment of iron is heavy. Keep it steady to Tarren Mill.|Apprentices dash about the smithy. Keep up with them.|Sparks die down when the forge goes cold. Cool down with them.",
	[530] = "Raleigh wants Valdred's hands. Earn the reward.|Valdred hides by the Greymane Wall. Wait for him to show.|South through Silverpine before Valdred slips into Gilneas.|Raleigh can't grieve. Take a quiet breath for him.",
	[531] = "Ol' Sooty is one big bear. Match him.|Vyrin wants it out of the Lodge. Keep your prize outside.|Ol' Sooty roams Loch Modan. Track him down.|Vyrin is upset. Stay calm for the both of you.",
	[532] = "Burnside and five councilmen. Hillsbrad's leaders fall.|The Proclamation burns slowly. Wait until it's gone.|Grab the Town Registry and go before the guards arrive.|Hillsbrad is in disarray. Be the calm one in the room.",
	[538] = "Alterac's books are lost. Stormwind's library needs them back.|A long trip to Southshore. Get ready for it.|Southshore is far from Stormwind. Set off now.|Loremaster Dibbs loves a quiet read. Find his kind of calm.",
	[539] = "Foreman Bonds and his ten miners run the Azureload Mine.|The mine tunnels are narrow. Stay low and wait.|Due south of Hillsbrad to the mine. Get there fast.|Dust settles in the Azureload Mine. Let it settle.",
	[540] = "Five tomes and The Arm of Gri'lek. The ogres won't hand them over.|Ogres sit on Alterac's books. Wait for your chance.|Race through the Ruins of Alterac and grab any book you see.|Old troll lore in a worn leather book. Read the room first.",
	[541] = "Mountaineers, Riflemen, Priests, and Ironhill. Dun Garok falls.|Thoradin's Wall stands firm. So do you, until the siege breaks.|Lay siege to Dun Garok. The dwarves won't let you rest.|The final battle of Hillsbrad. Find your calm before it begins.",
	[546] = "Thirty skulls for Samsa. He's stuck on guard, you're not.|Samsa stands guard all day. Give him a taste of it.|The battle for Hillsbrad is long. Gather skulls as you go.|Samsa is patient. Be patient too; thirty takes a while.",
	[549] = "Ten Rogues, ten Watchmen. The Syndicate pays for its crimes.|Syndicate Watchmen keep watch. Out-wait them.|Durnholde's ruins are big. Sweep them for Syndicate.|Rogues strike from the dark. Stay cool and see them coming.",
	[567] = "Four names on Darthalia's list. Cross them off.|Whitesteed, Wilkes, Hackett, Kalaba. They hide. You wait.|The four are hard to find. Search all of Hillsbrad.|Bounty work takes patience. Take your time.",
	[590] = "Calvin Montague wants a fight. Give him one.|Calvin talks tough. Stand firm until he's done talking.|Calvin is quick on his feet. Be quicker.|He says he owes you nothing. Let it go, then win anyway.",
	[729] = "Golems came up from the dig site. Your reps get you ready for them.|Remtravel stares at old stones. Hold as still as he does.|Head south down the shore, fast. Remtravel may need you.|Be calm like Remtravel. He never even sees the golems.",
	[730] = "The dwarven crew has gone quiet. Darkshore needs a look.|No word in weeks. Wait for a clue in Auberdine.|Off to Auberdine to look for the dig team.|The Explorers' League waits on news. Clear your head and look.",
	[731] = "Remtravel wants a stone brush. Er, a fossil. Dig in.|Stand by Remtravel while he searches. He won't notice the golems.|The prospector wanders. Follow him through the dig.|Remtravel forgets everything. Remember to stay calm.",
	[741] = "The mysterious fossil is full of secrets. Earn the trip with reps.|Grip the fossil tight on the road to Darnassus.|Darkshore to Darnassus by boat and road. Off you go.|Hollee stays behind. Take her calm with you.",
	[742] = "The Ashenvale Hunt calls young adventurers. Answer.|Splintertree Post stands firm north of the Barrens. So can you.|From Thunder Bluff to Ashenvale. The hunt starts with the road.|Ashenvale's wilds are deep and green. Picture them, and breathe.",
	[743] = "Eight Windfury Talons. Ruul is watching your work.|Harpies perch along the mountain edge. Wait for one to swoop.|Southeast to the Windfury nests. Harpies are fast.|Ruul teaches warriors to be patient. Learn it here.",
	[744] = "A headdress needs azure and bronze feathers. Bring them.|Eyahn tans leather straps. Wait while the feathers arrive.|Harpies roost far to the north. Head out after them.|A headdress for Chief Bloodhoof. Soft as a feather, calm as one.",
	[745] = "Tanners, Skinners, Poachers. The Palemane take too much.|Baine has seen many conflicts. Stand as he stands.|South of Bloodhoof and the cave to the west. Cover both.|Words are no longer the answer, Baine says. Silence is, for now.",
	[746] = "Five Prospector's Picks, smashed at a forge. Break them all.|Keep the pick steady on the anvil before it breaks.|Dig site to forge. Grab the picks and go.|Baine says the land teaches the patient. Listen.",
	[747] = "Seven feathers, seven cuts of meat. Camp Narache eats tonight.|Plainstriders spook easy. Wait in the grass.|Plainstriders are fast on Red Cloud Mesa. Be faster.|Grull hunts with a clear mind. Clear yours.",
	[748] = "Paws from wolves, talons from striders. Mull needs them.|The tainted well waits. So must you, a bit longer.|Southwest to the wolves and plainstriders. Go!|The land must offer its aid, says Mull. Be ready to receive it.",
	[749] = "Venture Co. crates at the Ravaged Caravan. Pry them open.|The burned wagons still smoke. Wait for the salvagers to leave.|North shore of Stonebull Lake. Beat the salvagers there.|Morin's torches missed something. Look slowly and find it.",
	[750] = "The children need clothing. Ten cougar pelts will do.|Cougars lurk in the southern hills. Lurk right back.|The hills south of camp are full of cougars. Chase them.|A hunter takes only what the tribe needs. Remember that.",
	[751] = "Venture Co. papers from under the ore. Morin needs them.|Smoke rises in the eastern foothills. Keep the documents close.|Back to Morin near Bloodhoof, papers in hand.|Faint sounds of work in the hills. Listen closely.",
	[752] = "Chief Hawkwind's mother went for water. Go find her.|A humble task starts with patience. Stand ready.|Southeast to the well. She's been gone too long.|Harmony of life, the Chief says. Find yours.",
	[753] = "One water pitcher, full to the brim. The Chief is thirsty.|Keep the pitcher level. Old legs fetched it slower.|Well to Camp Narache. Youthful vitality, she calls it. Show her.|Even a humble task earns respect. Walk it with grace.",
	[754] = "Goblins guard the Winterhoof Water Well. Clear a path.|Plant the totem and keep the ritual going till the well runs clean.|Southeast to the well, past the goblins.|Sacred water, cleansed at last. Feel the ritual settle.",
	[755] = "The Rite of Strength begins with Seer Graytongue.|Three rites await. The first is close.|South into the hills to find the seer's home.|Hawkwind sees greatness in you. Take a quiet look inward.",
	[756] = "Stalker claws and cougar claws make the Thunderhorn totem.|Predators prowl the Mulgore plains. Wait them out.|East for stalkers, west for cougars. Cover the plains.|Mull shapes totems from the plains' own gifts. Give thanks.",
	[757] = "Twelve Bristleback Belts prove your valor to the Chief.|Bristlebacks ambush from the ravine. Hold your ground.|Brambleblade Ravine is to the east. Charge in.|The Rite of Strength asks for bravery. Bravery starts calm.",
	[758] = "Mull made the totem. Your reps carry it to the well.|Plant the totem at Thunderhorn Well and hold till the water clears.|North of the village the well waits. Hooves up, keep going.|The spirits guide the calm. Let the ritual settle over you.",
	[759] = "Eight alpha teeth for the Wildmane Well. Count them out in reps.|An alpha stares you down below Thunder Bluff. Hold your ground.|Alphas prowl the base of the bluff. Stay on their trail.|A wolf pack waits in silence. Match their patience.",
	[760] = "Last well, last totem. Mull wants reps worthy of the Wildmane.|At the Wildmane Well, stay put while the goblin filth washes out.|North of Thunder Bluff, the final well. Don't slow down now.|Clean water flows again. Let your breath flow with it.",
	[761] = "Eight trophy quills. The swoops won't hand them over.|Swoops spook easily. Stay frozen in the grass until one lands.|Quick hooves catch a swoop. Show Harken yours.|Sharp eyes spot the swoop first. Look out over the plains, calm.",
	[763] = "Hawkwind's totem is heavy with carvings. Lift it with pride.|Baine will know these carvings. Keep the totem steady.|Follow the road out of Camp Narache, and do not stray.|Two tests remain. Gather yourself on the road to Bloodhoof.",
	[764] = "Fourteen workers, six supervisors. Send the Venture Co. a message.|Guard the mine mouth. No goblin gets past you.|Northeast of the caravan the goblins dig. Chase them off our land.|Morin says greed makes goblins fast. Be slower, and smarter.",
	[765] = "Fizsprocket drew up the plans. Your reps tear them up.|The supervisor hides in his mine. Wait him out.|Deep in the Venture Co. mine, find the man with the clipboard.|A clipboard tells tales. Settle in before you read it.",
	[766] = "Wolf heart, cougar femur, strider scale, swoop gizzard. Get to work.|Maur's shoulder aches from Mazzranache's bite. Stay firm for him.|Time is short, says Maur. Cross the plains for all four parts.|Mazzranache has red eyes. Face them with a calm mind.",
	[767] = "The Rite of Vision starts with a visit. Warm up for the elders.|Zarlman Two-Moons is the village's spirit guide. Wait on his word.|Off to find Zarlman before the rite can begin.|The land is our holy provider. Feel it under your hooves.",
	[768] = "Twelve pieces of Light Leather. Veren is waiting on your hunt.|Veren sees a gleam in your eye. Keep it there.|Back to the plains for the hunt. Go, young one.|A good hunter waits for the right beast. Be that hunter.",
	[769] = "Four leather, four thread. A kodo bag is built stitch by stitch.|Kodo stand firm on the plains. Stand as firm as they do.|Gather the leather and thread, then hurry back to Thunder Bluff.|A leatherworker's hands are patient. Let yours be patient too.",
	[770] = "Ghost Howl fought the Burning Legion. Honor that scarred hide.|The hide still bears the demon's mark. Grip it and wait.|Someone in Bloodhoof knows this wolf's tale. Go ask around.|A ghost story is best heard quietly. Listen close.",
	[771] = "Two well stones, two ambercorn. Small haul, big vision.|Ambercorn falls beneath the mighty trees. Wait for it to drop.|From well to tree and back to Zarlman. The rite needs both.|The Water of the Seers needs a quiet mind. Start growing one.",
	[772] = "Drink the Water of the Seers. Your vision waits for the brave.|Stay by the tribal fire until the vision takes shape.|The vision moves. Follow it wherever it leads.|The waters work slowly. Let the fire's glow settle you.",
	[773] = "Red Rocks holds the blessing of your ancestors. Earn it.|The Ancestral Spirit speaks only to the patient. Wait for it.|East of Thunder Bluff lie the Red Rocks. Head there now.|You drank the Water of Seers. Now open your mind to the spirits.",
	[775] = "Cairne dwells atop the highest mesa. Earn your way to your chief.|Stand tall before Cairne Bloodhoof. The whole city is watching.|Up the lifts, across the bridges, to the highest mesa.|The city reveres you now. Take in the view from the top.",
	[776] = "Arra'chea is a mighty kodo. Bring Cairne its horn.|A hunter tracks in silence. Wait for Arra'chea to show itself.|Down into Mulgore, on the trail of the great kodo.|Cairne asks for your tracking skills. Read the plains slowly.",
	[780] = "Eight snouts, eight flanks. The young ones want stew.|Battleboars charge. Plant your hooves and take it.|Into Brambleblade Ravine after the boars. Don't let them flee.|The hunting grounds belong to the tribe. Walk them in peace, after.",
	[781] = "The Bristleback plan a siege. Your reps say otherwise.|Those attack plans stay safe till Chief Hawkwind sees them.|Camp Narache must know. Get the plans to the chief, fast.|You found the map. Think over what it means for the camp.",
	[783] = "Northshire needs defenders, not farmers. Show you're one.|Strap your belt on tight and wait for the Marshal's orders.|Marshal McBride is in the abbey. Off you go, recruit.|Peace is thin in Northshire. Find some inside the abbey walls.",
	[784] = "Ten sailors, eight marines, one lieutenant. Tiragarde falls again.|Kul Tiras holds the keep. Hold your line until it breaks.|South to Tiragarde Keep. Benedict won't wait for you.|Gar'Thok asks for honor, not rage. Stay calm before the charge.",
	[785] = "The Darkspear are loyal allies. Pay back that loyalty.|Lar Prowltusk keeps a close watch. Keep one with him.|Sen'jin's western flank is a trek. Find Lar out there.|Thrall's wisdom is quiet. Borrow some for the road.",
	[786] = "Three leaders, three sets of plans. Tear up all of them.|Lower your voice. The Kolkar are just over the ridge.|Slip into Kolkar Crag, burn the plans, and get out.|Lar snuck in last night. Move as softly as he did.",
	[787] = "Throm'ka, recruit. Eitrigg wants the new Horde to be tough.|Eitrigg waited out his exile. You can wait for Gornek.|Report to the Den. Gornek has orders for you.|The Horde is free of the Legion now. Let that settle in.",
	[788] = "Ten mottled boars. Gornek wants some backbone in you.|A boar charges. Brace and let it come.|North of the Den the boars roam. After them!|Kodo can wait. Today the boars teach you patience.",
	[789] = "Ten scorpid tails. Prove your prowess to Gornek.|Watch that stinger. Stay out of reach and ready.|The scorpids swarm to the northwest. Go collect.|Gornek bets you won't need the antidote. Prove him right, calmly.",
	[790] = "Sarkoth nearly took Hana'zua. Your reps settle the score.|Sarkoth's claw closes like a trap. Don't give it an opening.|Up to the plateau to the south. The big scorpid waits.|Hana'zua's honor rests on you. Carry it with care.",
	[791] = "Eight canvas scraps. Furl will make you a bag for your trouble.|Furl watches from the tower. Be as still as the old guard.|Humans and centaurs carry canvas. Go find some.|The signal horn rests. Enjoy the quiet watch with Furl.",
	[792] = "Twelve vile familiars. Zureetha counts on you.|The familiars spill from the cave. Stop them where you stand.|Familiars scatter across the valley. Chase them down.|Zureetha senses a taint. Clear your own head first.",
	[794] = "The medallion hides deep in the coven. Dig in and claim it.|An agent guards the medallion with black magic. Stand firm.|North and west to the coven cave. Down into the dark.|Zureetha's visions see far. Look inward before the coven.",
	[804] = "Hana'zua must endure. Show him how it's done.|Hana'zua can't walk yet. Hold out for him.|Back to the Den with news for Gornek. Hurry.|Hana'zua's heart is steeled. Steel yours the calm way.",
	[805] = "The Burning Blade reached the valley. Gadrin must hear it.|Tell no one of the coven's secrets until Sen'jin.|East out of the valley, then right at the fork. Be swift.|A larger threat comes. Gather your thoughts on the road.",
	[806] = "Fizzle Darkstorm spreads chaos. Your reps spread some back.|Thunder Ridge is full of cultists. Wait for Fizzle to show.|Northwest to Thunder Ridge. Orgnil wants that claw.|A warlock plays with chaos. Answer with a clear mind.",
	[808] = "Zalazane trapped Minshina's spirit. Break the circle.|The circle of power hums. Reach in slow and take the skull.|Across to the largest Echo Isle. Minshina is waiting.|Gadrin hears his brother in dreams. Bring the spirit peace.",
	[809] = "The Demon Seed must be destroyed. Build up for Dreadmist Peak.|Neeru's fears are confirmed. Keep the collar out of sight.|West to Far Watch Post. Ak'Zeloth expects you.|The Legion fell once. Get ready to see it fall again.",
	[810] = "Six shells for Kor'ghan. Your reps crack them one by one.|Be like the scorpid. Hard shell, no give, hold the line.|The scorpids run off. Stay on their tails.|Kor'ghan says watch and learn. Be calm like the sand.",
	[812] = "Rhinag has little time. Get that antidote from Kor'ghan.|Rhinag is holding on out there. So are you.|To Orgrimmar and back. Rhinag is counting on your haste.|The Cleft of Shadow is dim. Find Kor'ghan there, calm and quick.",
	[814] = "Cook Torka wants boar meat. Pull your own weight.|Torka has no time to hunt. Stand in for him out there.|Out to the boars, back to the pot. Razor Hill is hungry.|Torka cooks and cleans all day. Take a quiet moment he never gets.",
	[815] = "Three taillasher eggs for breakfast. Break a few.|Bloodtalons guard their eggs. Wait for your chance.|Southeast to the Echo Isles for eggs. Get movin', says Torka.|Handle the eggs gently. Torka needs them whole.",
	[816] = "Kron went after the crocolisks. Face them for Misha.|The Southfury's banks are wet and wild. Stand watch there.|West to the river. Search the banks for Kron.|Misha fears the worst. Bring her news, and a steady hand.",
	[817] = "Four tiger furs for Vel'rin. The islands to the south hold them.|Tigers wait in the grass. So do you.|Across to the islands south of Sen'jin. The tigers await.|Take only what is needed. Vel'rin lets the tigers thrive.",
	[818] = "Four makrura eyes, eight vials of mucus. Master Vornal waits.|Makrura claws snap shut. Keep your nerve.|Hunt makrura and crawlers up and down the coast of Durotar.|Vornal wants a worthy apprentice. Show him a clear head.",
	[819] = "Chen's keg is empty. Time to raise your spirits.|Read the placard on the keg. Let the words soak in.|Someone must know Chen Stormstout. Go and find out.|May your spirit be raised. Let it rise now.",
	[821] = "Five lion tusks, five kidneys, one horn. Stormstout needs a kick.|Thunder lizards don't give up horns easily. Brace for it.|The ingredients are spread across the Barrens. Cover ground.|Good brew takes patience. So does Brewmaster Drohn.",
	[823] = "Sen'jin has troubles too. Take them to Orgnil.|Orgnil guards Durotar from evil. Stand guard beside him.|North to Razor Hill with news of the Burning Blade.|Put your report in order before you face Orgnil.",
	[825] = "Three gnomish tools lie in the wreck. Dive for them.|Under the waves, hold your breath and search the hull.|Swim out past Tiragarde Keep to Proudmoore's sunken fleet.|The sea drifts through the wreckage. Drift along with it.",
	[826] = "Eight voodoo trolls, eight hexed trolls, then Zalazane.|Zalazane's hexes won't sway you. Stay firm.|To the Echo Isles, the old Darkspear home. End his reign.|These trolls were once Darkspear. Remember that before the fight.",
	[827] = "Searing Collars from the cultists. Margoz wants six.|Skull Rock is dark and hot. Wait in the shadows.|Deep into Skull Rock after the cultists.|Margoz will study the collars. Bring them back in one piece.",
	[828] = "Margoz knows about the Burning Blade. Earn his counsel.|Margoz is wise. Listen longer than you speak.|Northeast, between the coast and Drygulch Ravine. Margoz waits.|Take the shaman's advice to heart, and let it settle.",
	[829] = "One example collar for Neeru Fireblade. Deliver it with care.|The collar hums with demon power. Grip it tight.|Into Orgrimmar and down to the Cleft of Shadow.|Neeru claims his research is harmless. Weigh his words calmly.",
	[830] = "Proudmoore's seal is on it. Do your reps before Razor Hill.|Keep the old letter safe and hold. Gar'Thok can wait a bit.|Razor Hill is down the road. Get that letter there fast.|Turn the old envelope over. Look at the seal with a calm mind.",
	[831] = "Proudmoore's men may land any day. Your reps get you set.|Thrall's hall is busy. Hold at the door till Nazgrel waves.|Humans may land soon. Get the orders to the big city, fast.|Humans can't be trusted. Take a calm breath and think it through.",
	[832] = "The eye still whispers. Show Neeru what you are made of.|The pendant calls for Gazz'uz. Stay quiet and don't answer.|Take the eye to Neeru Fireblade before it speaks again.|Let the voice in the pendant fade. Your mind is your own.",
	[833] = "Eight Bristlebacks at Red Rocks. Drive them off with force.|Stand guard over the graves. The old heroes rest behind you.|The Interlopers scatter over Red Rocks. Chase them down.|Red Rocks is a quiet place. Be quiet with it.",
	[834] = "Five sacks of supplies. Rezlak can't do a thing without them.|A full sack is heavy. Hold it up and don't drop Rezlak's stuff.|Down the big canyon and into the ravine. The harpies won't wait.|Desert winds blow through Razorwind Canyon. Let them pass you by.",
	[835] = "Twelve Savages, eight Storm Witches. Rezlak pays for results.|Hold the ravine so the caravans can pass.|Harpies dive from all sides. Never stop in Drygulch Ravine.|Do it yourself, says Gazlowe. Start with a calm breath.",
	[837] = "Four of each kind of Razormane. Gar'Thok counts them all.|Stand firm by the brambles. The quilboars test your line.|West to the bramble camps. Drive the Razormane out today.|Today Durotar, tomorrow Kalimdor. First, one calm breath.",
	[839] = "No quest here, just you. Make the reps count anyway.|Nothing to find on this empty page. Hold on for the next one.|An empty road with no end. Go anyway.|A blank page, a quiet mind.",
	[840] = "You look pretty strong, says the orc. Prove it with your reps.|Wait at the bridge. Kargal signs when he's ready.|West road, over the bridge, to the outpost. Off you go.|The Barrens are wide. Stand tall at the bridge and look out.",
	[842] = "Sergra wants useful recruits. Show her some useful reps.|Sergra talks a lot. Stand there and take it.|West, then left at the T, then south. The Crossroads wait.|Decide for yourself about Sergra. Think it over, nice and calm.",
	[843] = "Fifteen Excavators, five Foremen. Gann wants his land back.|The blasts shake the ground. Stand firm while Bael Modan rumbles.|Loud machines rip the hills. Race in and shut them down.|Gann wanders alone in quiet. Share his quiet before the fight.",
	[844] = "Seven beaks for Sergra. Your first prey is an easy one.|Plainstriders peck at the food stores. Guard them.|The plainstriders run east. Run faster.|Watch the birds before you strike. A hunter looks first.",
	[845] = "Four hooves for Sergra. Zhevra kick harder than plainstriders.|Zhevra spook at noise. Stay low in the grass.|Zhevra Runners earn the name. Match them step for step.|Your teeth need cutting, says Sergra. Stretch out before the hunt.",
	[846] = "Six vials, six bundles, six samples. The Keep has them all.|Those vials go boom if shaken. Stay very still.|Through the Keep, past the riflemen. Grab the goods and go.|Gann will build the charge. Your part is a steady hand.",
	[848] = "Four spores from the oasis. The apothecaries are waiting.|The mushroom sits by the water. Be as still as it is.|Oasis to oasis in the dry Barrens. The spores won't come to you.|The oasis water gives life. Take in the calm of the pools.",
	[849] = "The flying machine insults Gann's tribe. Blow it sky high.|The fuse is lit. Hold your ground and wait for the boom.|Plant the charge and run for it!|Gann trusts you with the stick. Steady hands, calm heart.",
	[850] = "Barak Kodobane leads the Kolkar. Show him who leads now.|Barak camps by the Forgotten Pools. Wait for your moment.|North to the pools, then back to Regthar. Don't stop.|A calm mind first. Then Barak Kodobane.",
	[851] = "Kill enough centaur and Verog will come. Bring him out.|The alarm is raised. Stand by the tent and wait for Verog.|Verog the Dervish spins in fast. Stay ahead of him.|The Stagnant Oasis is still. Soon Verog won't be.",
	[852] = "Hezrul leads the Kolkar. Break him, break the tribe.|Lushwater Oasis is his home. Hold fast at its edge.|South to Lushwater. Hezrul is fierce and quick.|Hezrul is cunning. Be calmer than he is.",
	[853] = "The spore mix won't last. Earn your pay from Zamah.|Don't spill the spore mix. Keep the jar level and still.|Hurry to Thunder Bluff before the mix goes flat!|A hidden path on Spirit Rise. Look for it with calm eyes.",
	[854] = "Great things are ahead, the seer says. Start with these reps.|The seer saw you coming. Stand and let the vision come true.|East down the road, then north to Thork.|Not so young anymore. Take a slow breath and walk on.",
	[855] = "Fifteen bracers for the heap. The Horde pays well.|Kolkar warriors ride past. Stay put and pick your target.|Kolkar land is wide. Hunt it end to end.|A bounty hunter waits for the right moment. Find yours.",
	[858] = "The boss up top has the key. Go take it from him.|Wizzlecrank sits in a shredder that won't budge. Don't budge either.|Up the derrick to the control room. On the double!|Wizzlecrank panicked. You won't. Slow breath.",
	[860] = "The hunter's path starts in the Barrens. Get ready for it.|The Barrens hold danger for the careless. Stand ready.|East from Bloodhoof, north at the fork. Sergra waits.|Your spirit will grow, the tauren say. Let it.",
	[861] = "Four prowler claws for Melor Stonehoof. Show your skill.|Flatland prowlers are cunning. Lie in wait in the grass.|Hunt the plains of Mulgore. The prowlers won't sit still.|Hunting is a tauren's great honor. Honor it with calm.",
	[862] = "Eight dig rats for Grub's stew. Haw!|Dig rats peek out of holes. Wait for one to pop up.|Down south to Bael Modan. The rats are fast.|Smell the stew. Grub says you'll love it.",
	[863] = "Wizzlecrank is still learning the buttons. Fight off whoever comes.|Guard the shredder. Wizzlecrank needs time with the levers.|The shredder stomps to Ratchet. Stay with it.|Just buttons and a lever or two. Stay calm, it'll work out.",
	[865] = "Five whole raptor horns. Mebok wants them in one piece.|Scytheclaws are smart. Wait until they look away.|South Barrens, then north by Ashenvale. The raptors roam far.|Smart drinks, says Mebok. A smart hunter starts calm.",
	[866] = "Eight root samples. Pull them up one at a time.|Hold the herb gently while you take the root.|Herb to herb across the Barrens. Mebok wants eight.|Oasis water changes the plants. Notice the little things.",
	[867] = "Eight Witchwing talons. Darsok wants a good start.|Darsok snooped around the nests. Now you stay low and watch.|Harpies swoop in the northwest. Don't let them catch you.|Start slow, says Darsok. He means it.",
	[868] = "Twelve eggs from the mounds. The digging claw does the work.|If alerted, they attack. Freeze by the mound.|Field of Giants, mound to mound. Grab and go.|The insects seem smart. Move like you're not there.",
	[869] = "Twelve raptor heads. The guards want their silver back.|A raptor stole silver. Watch them close and wait.|The thieves have claws and quick feet. Chase them all.|What does a raptor want with silver? Think it over.",
	[870] = "Power leaks from below. Tonga needs you ready for anything.|Stand in the Forgotten Pools and feel for the power.|Northwest to the pools and back to Tonga.|The Barrens was lush once. Picture it green again.",
	[871] = "Eight Water Seekers, eight Thornweavers, three Hunters.|Watch the thorny vines. The Razormane dens are close.|Northeast toward Durotar. Den after den.|Thork's scouts still seek the leader. Be patient like them.",
	[872] = "Kreenig leads the raids. His tusk goes to Thork.|Kreenig waits south of the road. So do you.|Through the Geomancers and Defenders to Kreenig.|The caravans will roll in peace soon. Enjoy the quiet first.",
	[873] = "Isha Awak, the Deep Doom. Worthy prey needs a worthy hunter.|Deep in the water, wait. The Deep Doom comes to you.|Swim out past the coast. Isha Awak is out there.|Listen for his heart. To hear it is to know your fate.",
	[874] = "Not even the sea stops a true hunter. Get set for it.|Humans hold the coast. Stay hidden while you look.|Down the coast to find Mahren. Mind the humans.|Mountains, swamps, sea. A hunter stalks any path.",
	[875] = "Six rings from six Witchwing Slayers. A sharp strike.|Spot the rings before you strike. Wait in the Dry Hills.|The Dry Hills are full of Slayers. Hunt them down.|Back for more, Darsok laughs. Clear your head first.",
	[876] = "Serena wants revenge. Give her a fight she won't forget.|Serena rules the nest. Stand your ground when she dives.|Through the nests to Serena. The caravans need this.|Her sister fell to Rexxar. Walk in with a cool mind.",
	[877] = "Dead seeds, a fissure, a test. Tonga wants answers.|Put the seeds in the fissure, then watch. Wait for a sign.|Southeast to the Stagnant Oasis. Seeds in hand.|Watch the dead seeds come alive. Slow and green.",
	[878] = "Mangletooth wants the Bristleback leaders gone. Snort.|Earth power runs deep in the Bristlebacks. Plant your feet.|North to the Bristleback camps. Thirty foes wait.|Both tribes draw strength from the earth. Feel it too.",
	[879] = "Nak, Kuz and Lok Orcbane. Three skulls for Mangletooth.|A caster, a tracker, a warrior. Wait and pick them off.|Far to the south of the Barrens. The trio waits.|Peace from the Razormane is close. Picture the quiet.",
	[880] = "Tonga needs eight snapjaw shells. Get them all.|Snapjaws snap. Wait for the shell to open up.|Lushwater, then Stagnant Oasis. Snapjaws at both.|The water changed these beasts. Stay calm and learn why.",
	[881] = "Whitemist is king of the savannah cats. Take his hide.|Blow the horn, then wait. He comes like mist.|Northeast to the kodo bones. The horn is ready.|Mercy and death, they say. Meet him calm.",
	[882] = "First a zhevra for bait. Then Speartooth himself.|The bait lies under the dead tree. Wait until he smells it.|Take the zhevra to the dead tree near Ratchet. Quick!|Ishamuhale hunts for the joy of it. You hunt with a clear head.",
	[883] = "The Hoof of Lakota'mani. The strength of the great kodo.|The great kodo stomps the ground. Stand firm.|Lakota'mani roams far. Track him across the Barrens.|Feel the weight of the hoof. Take it slow.",
	[884] = "Sparks fly from Owatanka's tailspike. Bring it to Jorn.|Owatanka's spike crackles. Don't flinch.|Thunder lizard on the loose. Stay out of his path.|Let the sparks settle before you touch the spike.",
	[885] = "Washte Pawne's feather stings. Earn it anyway.|Washte Pawne soars high. Wait for him to land.|Chase the great bird across the Barrens.|Carry the feather lightly. It stings if you grip it.",
	[886] = "Tonga may need aid. Show up ready.|The druids sense a strange power. Stand and feel for it.|Out of Bloodhoof and along the road. Don't leave it.|A harsh land lies ahead. Breathe in the last green of Mulgore.",
	[887] = "Twelve Brigands, six Cannoneers. Gazlowe wants them gone.|The cannons boom. Stand firm on the sand.|Go to the pirate camp south of Ratchet. Get them all.|Gazlowe is ticked off. You don't have to be.",
	[888] = "Boots and a lens. Grab them from the pirates with your reps.|Wait by the pirate tents. Gazlowe wants his small lens back.|Get the boots out of camp before the pirates look up.|Pirates nap in the sun. Be as quiet as they are sleepy.",
	[890] = "Gazlowe's ledger is thick. Count reps like Dizzywig counts crates.|Dizzywig checks the books line by line. Wait on him.|Down to the docks with the ledger. The Wharfmaster waits.|Slow and calm, like a clerk who has read every page.",
	[891] = "A captain, two cannoneers, ten medals. Earn them all.|The cannons of Northwatch roar. Stay low behind the wall.|Storm the Hold before Smythe can reload.|Fairmount watches the sea. Watch her back, calm as the tide.",
	[892] = "Bad news weighs a lot. Carry it back to Gazlowe in reps.|Gazlowe will shout. Stand firm while he does.|Back up the road to Ratchet with the ledger.|Pirates took the goods. Let it go, calm as the harbor.",
	[893] = "A dagger, a wand, a shield. Take each from the Razormane.|The war shield is heavy. Keep it up for Tatternack.|Past the Field of Giants, into quilboar land. Don't slow down.|Tatternack studies the blades with care. Study your stance too.",
	[894] = "Venture Co. guards the site. Push on to the console.|Read the manual at the console. Don't twitch a finger.|Far north to the Sludge Fen. Sputtervalve is counting on you.|What is a samophlange? Wonder about it, nice and slow.",
	[895] = "Longshore is a wanted pirate. Your reps bring him in.|The Baron looks out to sea. Wait until he turns his back.|Chase the Baron along the shore. He has no ship to flee on.|A calm hunter finds the Baron. A loud one finds his crew.",
	[896] = "An emerald the size of your fist. Earn your half of it.|Lurk near the Boulder Lode mine until an Overseer walks by.|Enforcers, Overseers, one of them has it. Go find out.|Dizzywig dreams of gold. You dream of green, calm and bright.",
	[897] = "The Harvester does not belong here. Show it the way out.|Its many legs click in the grass. Wait for it to come.|Across the southern Barrens after a thing from nowhere.|Jorn Skyseer sees the natural order. Find your place in it.",
	[898] = "Guards block the way. Clear them for Gilthares.|Gilthares hides behind you. Be the wall he needs.|The break is on. Out of Northwatch and up the coast!|Before the escape, a quiet moment. Then you both go.",
	[899] = "Sixty tusks for Mankrik. He is counting.|Mankrik stands all day and scans the plains. Stand with him.|Bristlebacks are out there. Go get them.|Mankrik's grief runs deep. Find a quiet spot away from it.",
	[900] = "Three valves to shut. Turn them hard.|The Main Control Valve is stiff. Lean on it until it gives.|Fuel, Regulator, Main. Dash from one valve to the next.|Read the dials. Calm hands shut down big machines.",
	[901] = "Tinkerer Sniggles has the key. Make him hand it over.|Sniggles fiddles with gears. Wait until he looks away.|Sniggles is quick on his feet. Be quicker.|One key, one lock. Find the calm before you go get it.",
	[902] = "The samophlange is odd and heavy. Lug it home to Sputtervalve.|The samophlange must not rattle. No one knows what it does.|Ratchet is waiting for a thing nobody can explain.|Wires, tubes and one samophlange. Sort your thoughts like that.",
	[903] = "Seven prowler claws. The tall grass hides them.|Wait low in the tall grass. Let the prowler come.|Hunter or prey? Stay fast and stay the hunter.|Sly like a prowler. Quiet, patient, sharp.",
	[905] = "Sunscale feathers for three nests. Show them no fear.|Stand over the raptor nest. Let the Scytheclaws see you.|Blue nest, yellow nest, red nest. Around the Stagnant Oasis!|The hunt deepens, says Sergra. Let your mind go deep too.",
	[906] = "Lok's skull goes to Thork. Carry the news with pride.|Mangletooth blesses you from his cage. Stay in his light.|Thork should see this. Off to the Crossroads!|Agamaggan's power flows in. Let it settle.",
	[907] = "The ground shakes as they stomp. Shake it back.|One false step and you're under a Thunderhead. Stay put.|Stormsnouts, Stormhides, Thunderheads. Outpace them all.|Three vials of blood for Jorn. First, find your footing.",
	[913] = "Jorn wants its wings. Go and take them.|The thunderhawk is near. Wait for it to land.|Find where it roams. Go now.|The end of your time with Jorn nears. Take it in.",
	[914] = "Cobrahn, Anacondra, Pythas, Serpentis. Four gems, four falls.|Deep in the Wailing Caverns, the Fang waits. So do you.|Through the caverns after four leaders. Nara needs every gem.|Nara wants the Barrens to know peace. Start with your own.",
	[916] = "Ten venom sacs from the webwood spiders. Get to it.|Spiders drop from the ceiling. Stay set and ready.|In and out of Shadowthread Cave before the webs close.|Gilshalan studies spiders calmly. Be his calm student.",
	[917] = "Deep in the nest lies an egg. Earn the right to take it.|Mother spider is near. Freeze by the nest.|Grab the egg and go! The cave is waking up.|Handle the egg gently. Be soft as silk.",
	[918] = "Eight seeds from angry timberlings around Lake Al'Ameth.|Be rooted like a tree. The timberlings will come.|Round the lake after the timberlings. Seeds won't wait.|Denelan grows plants with care. Grow calm like one.",
	[919] = "Twelve sprouts by the lake. Clear them before they grow.|Sprouts tug at their roots. Stand your ground by the water.|Sweep the lake shore fast. Sprouts pop up everywhere.|A quiet walk by the lake. Spot each little sprout.",
	[920] = "Tenaron waits in the highest room. Earn every stair.|Near the top of Aldrassil. Stay there until Tenaron calls.|Up and up the great tree. Don't keep Tenaron waiting.|Long lives, short patience. Stand tall before Tenaron.",
	[921] = "The Crystal Phial needs moonwell water. Fill it with effort.|Hold the phial steady over the moonwell.|To the moonwell north of Aldrassil, then back again.|Moonlight on the water. Let it still your mind.",
	[922] = "One seed for Rellian. Bring your best to Darnassus.|Rellian walks the Cenarian Enclave. Stand where he will pass.|Off to Darnassus with a seed in your pocket.|Some day the seed will bear fruit. Picture it growing.",
	[923] = "Five mossy tumors from the Wellspring timberlings.|Tainted timberlings roam Wellspring Lake. Face them firm.|North to Wellspring Lake. Teldrassil needs you quick.|The source is still unknown. Clear your head and look.",
	[924] = "The Demon Seed must fall. Every step up the Peak counts.|The power stone hums in your hand. Keep it close.|Race the stone's clock up Dreadmist Peak!|At the altar of fire, find a cool, quiet mind.",
	[927] = "Blackmoss the Fetid is gone. His heart still beats.|The heart beats in your pack. Wait and listen.|Take the beating heart to Denalan, fast.|A slow, steady beat, like the moss-twined heart.",
	[928] = "Corithras expects the vessel. Bring it with care.|Stay on the road, says Tenaron. Beasts lurk in the trees.|South from Shadowglen, then west on the cobblestones.|Follow the road to Dolanaar like water finds its way.",
	[929] = "Moonwells run low. Fill the Jade Phial for the druids.|Starbreeze Village is quiet. Be quiet with it.|East to Starbreeze and back to Corithras.|Corithras has more story to tell. Listen with calm ears.",
	[930] = "A big round fruit for Denalan. Earn your keep.|The fruit glows in your hands. Keep it steady.|Home to Lake Al'Ameth with the glowing fruit.|Soft light under the fronds. Soak it in.",
	[931] = "One shimmering frond for Denalan's study.|The frond pulses in the forest light. Don't drop it.|Off to the lake before the frond stops shining.|The frond's glow pulses soft and slow. Match it.",
	[932] = "Lord Melenas plots in Fel Rock. End his plots.|Grell fill the cave. Wait in the dark for your moment.|North to Fel Rock and through his grell guards.|Keep this between you and Tallonkai. Quiet mind, quiet feet.",
	[933] = "Gnarlpine furbolgs guard the Pools. Push them back.|Weapons close, eyes open. The well is near.|Past Darnassus to the Pools of Arlithrien. Move!|The Sentinels watch over the pools. Watch with them.",
	[934] = "The last and strongest moonwell. Give it your best.|Under the boughs of the Oracle Tree, stay put and listen.|Northwest to the Oracle Glade for the final phial.|The first well of all. Drink in the quiet around it.",
	[935] = "All the phials in one vessel. Bring it to the Arch Druid.|Not a drop may spill from the Filled Vessel. Stay level.|Vessel in hand, head for the druid grove.|Teldrassil grew with flaws. Grow slow and sure instead.",
	[937] = "Six Bloodfeather belts. The Sentinels need proof.|Harpies swoop from their nests. Stand firm below.|Nest to nest, pushing the harpies back.|The Oracle Tree wants calm in the glade. Bring it.",
	[938] = "She is hurt. Clear the path for Mist.|Mist rests a moment. Wait by her side.|To the Oracle Tree with a gray sabercat at your heels.|Blue eyes watch you. Move as gently as Mist does.",
	[940] = "The harpies are gone. Now bring the Inscribed Bark home.|The last messenger fell. Stay alert on the way.|The forest will see you safe. Hurry to Darnassus.|A greater calm spreads through the forest. Feel it.",
	[941] = "Dig a spot in Denalan's planter for the tainted heart.|The heart sits in rich soil. Wait and see.|Planter ready, heart in hand. Get it in the ground.|Soil, water, time. Let the tainted heart rest.",
	[942] = "Remtravel's fossil holds a secret. Bring it to Flagongut.|The ship to Menethil rocks on the waves. Find your balance.|Auberdine docks, a ship, then the Deepwater Tavern.|An old fossil, an old power. Think on the past.",
	[943] = "A mottled raptor swallowed the Stone of Relu. Find it.|Raptors prowl the road to Whelgar. Wait for your chance.|Raptor after raptor across the Wetlands.|Flagongut will unlock the fossil. Unlock some quiet first.",
	[944] = "Twilight's Hammer lurks at the Glaive. Look them in the eye.|The scrying bowl must stay calm. So must you.|Search the place where an old lord fell.|Speak to Onu through the bowl. Slow words for an Ancient.",
	[945] = "Cultists surround her. Break the circle.|Therylune is good at hiding. Hide with her a bit longer.|Out of the Glaive, then word to Therysil in Ashenvale.|Her sister is safe. Let the good news sink in.",
	[946] = "Nothing here but you and your reps.|An empty page in the quest log. Fill it with a hold.|No road, no map. Go anyway.|A blank quest. A blank mind. Enjoy it.",
	[947] = "Five Scaber Stalks and a Death Cap. Pick your way in.|Behind Cliffspring Falls, something waits. Stay hidden.|The cave lies behind the falls. Get there fast.|Spray drifts off the falls. Let it pass over you.",
	[948] = "Onu wants your help. Show up ready.|The Ancients are patient. Try to match them.|South to the Grove of the Ancients. It's urgent.|Wise and patient, like an old tree. Be that tree.",
	[949] = "Tear through the Twilight camp for a clue.|A cultist walks by. Stay frozen in the shadows.|Search tent to tent before the cultists come back.|Their plan is dark. Think clear before you make yours.",
	[950] = "The tome's page twists in your hand. Reps keep your mind your own.|The scrawl swims on the page. Hold until the words stand still.|Take the mad page back to Onu before it gets any louder.|One glance nearly knocked you out. Slow air, steady feet.",
	[951] = "Six Mathystra relics. Put a rep behind every find.|The ruins are old and quiet. Hold like a broken stone.|Ruin to ruin across Mathystra. Onu wants those relics soon.|Elves built these stones with care. Match their calm.",
	[952] = "Fandral's message is light. Your reps are not.|Hang on to the hippogryph. It slows for no one.|South of Auberdine, Onu waits. Get Fandral's word there.|Onu is an Ancient. He knows how to wait. Learn from him.",
	[953] = "Two tablets and a crowd of spirits. Reps keep the ghosts back.|Keep your spot at the tablet. Tysha fled. You won't.|Spirits drift through Ameth'Aran. Stay ahead of them.|Old runes, a sad tale. Take it in bit by bit.",
	[954] = "Satyrs and sprites all around. Reps get you to the blue shrine.|Stand in the blue aura. No demon dares come near.|Up the bluff on the west side. The glow is waiting.|The blue light hums softly. Let it slow you down.",
	[955] = "Eight grell earrings for Asterion. Grells don't give them freely.|Asterion has waited ages. Hold for him a little longer.|Sprites dart through the ruins. Chase down the grells.|A ghost's hope rests on you. Calm hands find the trace.",
	[956] = "One satyr holds the Moonstone Seal. Rep till it's yours.|The satyrs guard the seal. Stand your ground.|Hunt the satyrs through Bashal'Aran. Asterion is close to free.|Tears in a ghost's eyes. Go gently with this one.",
	[957] = "A great Highborne made this seal. Break it with reps.|Hold the seal over the blue flame. Let it burn away.|South to Ameth'Aran, the twin ruins. The flame still burns.|Asterion's prison is ending. Breathe out with him.",
	[958] = "Seven Highborne relics, held by ghosts. Pry them loose.|The spirits wield old magic. Stand firm while it crackles.|Down the road to Ameth'Aran. Thundris wants those tools.|The Highborne dabbled and fell. Be wiser, and slower.",
	[959] = "Crates all over the Ratchet docks. Stack up reps like cargo.|Mad Magglish hides in the caverns. Wait him out.|Bigglefuzz chased him to the caves. Finish the chase.|That port aged for ages. Take your time too.",
	[962] = "Ten Serpentbloom in the dark. Zamah wants every stem.|Deep in the Wailing Caverns, wait for the path to clear.|The caverns twist and wind. Push on to the darkest parts.|Rare flowers grow in quiet places. Be quiet too.",
	[963] = "Cerellean can't do it. Your reps will free Anaya.|Anaya drifts near. Stand fast for Cerellean's sake.|Search the ruins for her. Love has waited long enough.|A sad task. Go softly, and bring the pendant home.",
	[965] = "Balthule never came back to Elissa. Reps first, then search.|Balthule watches the tower, still as a tree. Do the same.|Northeast through the forest to the Tower of Althalaxx.|Something is off in the woods. Slow down and listen.",
	[966] = "Four worn parchments, carried by warlocks. Take them.|Don't step into the tower. Hang back like Balthule said.|Warlock to warlock around the tower. The puzzle needs pieces.|Scraps of a plot in your pack. Piece it together calmly.",
	[967] = "Delgren must know now. Put your reps behind the letter.|Grip the letter tight. The Dark Strand grows by the hour.|Far south to Maestra's Post. Be swift, Balthule says.|A long road to Ashenvale. Find a steady breath for it.",
	[968] = "A cursed book for Bonegrip. Lug it all the way to Ironforge.|Keep that book shut tight. Some names are best unread.|Darkshore to Ironforge is a long way. Better get going.|Bonegrip might buy it back. Stay calm while you haggle.",
	[970] = "The Dark Strand camps at Ordil'Aran. Delgren wants their gem.|The soul gem glows with dark power. Don't let it shake you.|Northeast to Ordil'Aran. The cult won't wait around.|Delgren will read the gem's secrets. First, clear your head.",
	[971] = "Blackfathom Deeps hides the Lorgalis Manuscript. Dig in.|Those Who Sleep should stay asleep. Hold, and don't wake them.|Down to the bottom of Blackfathom. Bonegrip won't forget.|Dark water, old elf halls. Move through them with care.",
	[973] = "Ilkrud Magthrull has had his day. Now it's yours.|The Fire Scar Shrine burns hot. Stand firm in the heat.|Southwest to the Fire Scar Shrine. Ilkrud's time has come.|Delgren put Ilkrud off. You can wait for a clear mind.",
	[976] = "Feero hauls supplies to Auberdine. Guard him with all you have.|Foes lurk in Ashenvale. Stand guard over Feero's goods.|Stay at Feero's side all the way through the forest.|Watch the trees for foes. Eyes open, breath easy.",
	[981] = "Athrikus Narassin lies still. Tell Delgren with pride.|The Dark Strand is scattered. Stand tall at Maestra's Post.|Back to Delgren. Good news should not wait.|The cult is beaten. Let the long fight settle.",
	[982] = "Two lockboxes on the sea floor. The crew wants them home.|By the wreck of the Silver Dawning, wait out the murlocs.|Swim hard for the wrecks north of Auberdine.|Deep water, lost captains. Sink down soft and calm.",
	[983] = "Six crawler legs to fix the buzzbox. The crawlers disagree.|Wizbang's buzzbox is on the fritz. Stay put till it hums.|Crawlers skitter on the beach south of Auberdine. Catch up.|Wizbang's gadget needs a gentle touch. So do you.",
	[984] = "Find the furbolg camp. Terenthis needs to know how bad it is.|Crouch at the camp's edge and watch the furbolgs.|Search Darkshore for a furbolg camp. Don't be seen.|A good scout is quiet. See it all, and say nothing yet.",
	[985] = "Eight pathfinders and five windtalkers. The Blackwood fall.|The Blackwood camp is the biggest threat. Hold your ground.|South of Auberdine, the furbolgs roam. Stay after them.|Stealth or a straight fight? Settle your mind and choose.",
	[986] = "Five fine pelts from moonstalker sires. Terenthis needs them.|A moonstalker watches from the brush. Freeze until it steps out.|Down to the Wildbend River, where the big cats roam.|Grimclaw waits for his master. Be patient like him.",
	[990] = "Raene Wolfrunner waits in Astranaar. Set out strong.|Stay close to the road, and stay on track.|Head south on the road. Astranaar is not far.|Ashenvale's trees are old and tall. Walk under them calmly.",
	[991] = "Teronis hunts a gem for a wizard's rod. Go help him.|The shrine in Lake Falathim was overrun. Wait on the shore.|West to the lake at the foot of the mountain. Find Teronis.|A friend has not come back. Search with a clear head.",
	[993] = "The cloak is done. Now go find Volcor.|Grimclaw waits by the road. Wait with him, then wave.|South to the cave. The cloak's magic won't last long.|Pick your moment with the cloak. A calm mind knows when.",
	[994] = "Force it is. Fight Volcor's way down to the road.|Stand in front of Volcor. Furbolgs come from every side.|Out of the cave and down to Grimclaw. Stay close.|You made it out. Let the fight drain away before Auberdine.",
	[995] = "Slip past the furbolgs. Save your strength for the reps.|A furbolg turns your way. Stay frozen in the shadows.|Out of the cave and on to Auberdine. Volcor is faster.|Soft steps, quiet breath. The cave must never know.",
	[997] = "Denalan's rare earth is heavy. Heft it to the lake.|The package came late. Keep a firm grip so it isn't later.|South to Lake Al'Ameth. Denalan's camp is at the east end.|Denalan tends his plants. Grow calm like they do.",
	[1001] = "Three thresher eyes, deep off the coast. Go get them.|The threshers circle below. Stay still in the water.|Out past the beach into deep sea. The threshers are waiting.|Wizbang hiccups. You float calm on the waves.",
	[1002] = "Six moonstalker fangs. Wizbang is too tipsy to help.|Moonstalkers creep near the bridge. Wait for them to pounce.|Up the road north of Auberdine. The cats run fast.|Wizbang slurs his words. You stay clear and calm.",
	[1003] = "Four grizzled scalps from thistle bears. Big bears, big reps.|A thistle bear stands tall. Stand taller, and don't budge.|Far south down the road, near a fence. Wizbang hid it well.|Grizzshled, says Wizbang. Take a calm breath and giggle.",
	[1007] = "The naga tore at Talen's boat. Get his statuette back.|Naga lurk in the surf. Stay low by the ambush site.|North along the coast of Zoram Strand. Find the lost prize.|Talen lost it while he fled. Search with care.",
	[1008] = "Twenty Wrathtail heads. Shindrell wants the naga gone.|The naga come from the sea. Hold the shore against them.|Up and down the Zoram Strand. The Wrathtail keep coming.|A drowned city lies below. Think of it as the waves roll.",
	[1009] = "Ruuzel leads the naga. Take back the Ring of Zoram.|Ruuzel's isle sits at Zoram's edge. Stand firm on its sand.|Out to the northern isle. Ruuzel won't give the ring up.|Kings once wore that ring. Stand tall and calm like one.",
	[1010] = "Five tufts of Bathran's Hair. Orendil is counting on you.|Bathran's Haunt is quiet and grim. Wait among the ruins.|North past Maestra's Post to Bathran's Haunt. Go.|A plant from old ruins, picked with care. Soft hands.",
	[1013] = "Ur's book waits in Shadowfang Keep. Bel'dugur wants it.|The keep is dark and cold. Stand quiet in its halls.|Through Shadowfang Keep, room by room. Find the book.|Ur studied other worlds. Let your mind wander a little.",
	[1014] = "Arugal's spells end today. Put power behind it.|Arugal waits at the top of his keep. Hold before the last fight.|Up through Shadowfang Keep. Arugal can't hide forever.|Silverpine will be free of him. Gather your calm first.",
	[1016] = "Five good bracers from the elementals. Break them free.|Hold up the scroll. Let it read the bracers.|Chase the water elementals down. Velene needs answers.|The scroll glows. Stay calm and wait for a name.",
	[1017] = "Sarilus Foulborne is laughing. Wipe that grin off.|Horde eyes watch the Barrens. Keep low and wait.|Up Dreadmist Peak to Sarilus. Show him the Sentinels.|Velene has had enough of him. Keep your own temper cool.",
	[1020] = "Orendil's vial must reach Pelturas. Carry it with care.|Keep the vial steady. It must not spill.|South, then east to Astranaar. Pelturas is waiting.|A parent waits in Astranaar. Bring calm with you.",
	[1023] = "The murlocs have Teronis' gem. Take it from them.|Teronis fell here. Stand a while by Lake Falathim.|Around Lake Falathim, murloc to murloc. Find that gem.|Teronis' journal is in your pack. Read his last words softly.",
	[1024] = "Keep the gem safe for Shael'dryn. The rod needs it.|The moonwell is still. Be as still as its water.|Follow the road, then turn north at the little rest spot.|A dryad waits by the moonwell. Arrive at peace.",
	[1025] = "Ten totemics, twelve warriors. The Foulweald tribe is big.|Guard the road by the Falfarren River. Travelers need you.|Camp to camp south of the road. The furbolgs won't rest.|Before you hit the camps, get quiet. Then be careful.",
	[1026] = "A corrupt treant has the Wooden Key. Knock it loose.|Treants stand like trees. Stand longer than they do.|Northeast near Felwood, then find the hidden glade.|The treants were once kind. Remember that, gently.",
	[1027] = "The druids of Dor'danil hid the last piece. Find it.|The druids are gone. Stand watch over their camp a while.|Down the road toward the Barrens. Dor'danil lies east.|Shael'dryn can't speak of it. Go there with a quiet heart.",
	[1028] = "Dartol's Rod is whole again. Now give it power.|Place the rod in the shrine. The rest is magic.|Southeast, eyes north. The shrine hides in the hills.|Focus and effort, says Shael'dryn. Start with focus.",
	[1029] = "The rod is finished. Count your reps on the road to Raene.|Grip the new rod and hold. Raene knows what comes next.|Astranaar is not far. Carry the news to Raene at pace.|Raene listens best to a calm voice. Find yours first.",
	[1030] = "The rod gives you a new shape. Test it with reps.|In furbolg form, stay very still. One wrong twitch and they know.|Southeast of Mystral Lake. Trot on in your borrowed fur.|A furbolg shape, a quiet mind. Speak slow to the friendly one.",
	[1033] = "Relara needs that stone. Pay for it in reps.|Stand on the isle like the stone itself. Elune is watching.|Iris Lake is east of Astranaar. Splash out and back fast.|Pelturas prays by the bed. Share his quiet hope.",
	[1034] = "Five handfuls of frosted dust. Your reps fill the pouch.|The ruins sparkle with frost. Hold there, cold and calm.|The Ruins of Stardust lie south. May Elune speed your feet.|Let the frosted dust settle. So should you.",
	[1035] = "The Oracle hoards the moonstones. Take one back with your reps.|Wait by Fallen Sky Lake. The Oracle will show himself.|Southeast to the lake. The Shadethickets won't slow you down.|Moonlight on Fallen Sky Lake. Find its quiet before the fight.",
	[1045] = "Four Bloodtooth guards stand in the way. Knock them down in reps.|Krolg's people must police their own. Stand firm beside him.|Ran Bloodtooth won't wait. Charge through his guards.|Even in furbolg fur, a clear head wins. Gather it now.",
	[1046] = "Ran Bloodtooth's skull and Dartol's rod. Heavy loot, heavy reps.|Show Raene your trophy. Keep it up high for all to see.|Race the news to Astranaar. The whole town should hear it.|The cleansing is done. Bask in it, slow and quiet.",
	[1054] = "The Thistlefur keep growing. Your reps keep up with them.|Raene waits in Astranaar. Stand your ground north of town.|Into the Thistlefur woods and on to their chieftain. Go.|Dal Bloodclaw leads by rage. You lead by calm.",
	[1055] = "The rod is whole in your hands. Put its weight into your reps.|Clutch the finished rod. Shael'dryn will want it steady.|The moonwell calls. Shael'dryn waits for good news.|Moonwell water, still and bright. Match it.",
	[1056] = "The slope to Stonetalon Peak is steep. Pay the toll in reps.|Keeper Albagorm waits at the top. Hang on through the long climb.|Talondeep Path, Cragpool Lake, then up. A long road, so go.|A perilous trip needs a calm start. Take one here.",
	[1057] = "The Bloodfury took the Charred Vale. Your reps push them back out.|Albagorm needs a way in. Hold the pass so the harpies can't close it.|Harpies swoop over the burned hills. Chase them off the ridge.|The Vale was green once. Stand calm and picture it growing back.",
	[1058] = "Thirty courser eyes. Jin'Zil can never have enough, nor can you.|Three little cages wait. Stay put while Jin'Zil stirs the pot.|Sap, whiskers, eyes and a scale. Hurry, the brew is waiting.|Forest magic needs a steady hand. Settle yours.",
	[1059] = "Falfindel can call forest spirits. Earn his help with reps.|The Bloodfuries are down for now. Hold the line till help comes.|Past the Barrens, through Thousand Needles, to Feralas. Run the word.|A wise druid waits at the forest edge. Meet him calm.",
	[1060] = "Serena Bloodfeather is dead. Jin'Zil wants the news. Reps first.|Keep Darsok's letter safe and flat. No creases for Jin'Zil.|Northwest out of the Barrens to Stonetalon. Go, lucky rabbit's foot.|Stonetalon is an interesting place. Arrive with a clear head.",
	[1061] = "The land cried out. Answer it with reps.|The spirits of Stonetalon are listening. Stand where they can hear.|West of the Crossroads, toward Greatwood Vale. Seereth waits.|Listen for the spirits, as Seereth does. Be quiet enough to hear.",
	[1062] = "Fifteen Venture Co. loggers. Speak the language they understand.|Stand between the loggers and the last trees. Don't budge.|Windshear Crag is loud with saws. Chase the noise.|The spirits are blind with rage. You don't have to be.",
	[1063] = "Magatha is old and knows much. Show her some grit in reps.|Elder Rise is high and windy. Stand firm at the top.|Thunder Bluff, then up to Elder Rise. Don't linger.|Magatha speaks slowly. Find her calm before you tell your tale.",
	[1064] = "The Forsaken know a lot. Earn Zamah's trust with reps.|The Pools of Vision are still water. Be just as still.|Down below the Spirit Rise. A quick trip to Zamah.|Look into the Pools of Vision. Let your thoughts go quiet.",
	[1065] = "Zamah's note is for Lydon only. Seal the deal with reps.|The zeppelin sways. Stand firm until Undercity.|Tirisfal, Silverpine, then Hillsbrad. Tarren Mill is far.|A long trip to Lordaeron. Settle in and watch the clouds.",
	[1066] = "Five vials from the Syndicate mages. Take them back with reps.|Durnholde Keep is full of Syndicate. Wait at the wall for your chance.|Southeast to Durnholde. The shadow mages won't see you coming.|Lydon's toxin needs care. So does the way in.",
	[1067] = "Lydon's toxin is ready and Zamah needs it. Reps before the road.|Carry the toxin level. Lydon calls it exciting stuff.|All the way to Thunder Bluff. Don't spill a drop.|A careful hand for a tricky flask. Steady yours.",
	[1068] = "XT:4 and XT:9 fell trees fast. Take them apart faster.|Metal beasts crash through Windshear Crag. Stand and let them come.|Chase the shredders through the crag before more trees fall.|Seereth saw them in a vision. Close your eyes and see them too.",
	[1069] = "Fifteen deepmoss eggs for Booty Bay omelettes. Scoop them in reps.|The spider is near its eggs. Freeze under the tree.|Grab the eggs and dash before the deepmoss spiders notice.|Weak stomach? Stay in Windshear Crag and let it settle.",
	[1070] = "Kaela Shadowspear has gone quiet. Get ready with reps.|Stand at the valley edge like Kaela does. Watch the crag.|To Stonetalon and the valley at Windshear Crag. Go find her.|Wanderlust is a good thing. Let it settle before the road.",
	[1071] = "Ten loggers, ten deforesters. Gaxim needs time to plan.|Keep the goblins at bay while the gnome thinks. Stay put.|The goblins breed like rabbits. Chase them east through the crag.|Gaxim needs quiet to plan. Give him some of yours.",
	[1072] = "NG-5 is the good stuff. Earn it with reps.|Lomac lives in Tinker Town. Stand firm while you ask him.|All the way to Ironforge to find Lomac. Off you go.|Asking a gnome for explosives takes a calm face. Wear one.",
	[1073] = "Four mana potions, two elixirs. Prove your alchemy with reps.|Lomac wants proof of skill. Keep the flask still over the flame.|Stir, bottle, go again. Lomac is waiting, and so is his NG-5.|Alchemy likes a patient hand. Slow down and mix.",
	[1074] = "NG-5 in your pack. Gaxim wants it whole, so do your reps.|Volatile stuff. Keep the flask perfectly level.|Take the NG-5 to Stonetalon. Try not to bounce.|One wrong bump and boom. Stay calm and gentle.",
	[1075] = "Gaxim needs a spell. Do your reps, then go see Collin.|Stand in the mage quarter. Collin will find you.|Stormwind is far. The mage quarter is easy to find.|Gaxim has a plan. Stay calm and hear it out.",
	[1076] = "Dust devils spin hard. Hit back harder with reps.|The dust devil whirls around you. Stand your ground in the wind.|Westfall is windy and wide. Chase the dust devil down.|When the dust settles, so do you.",
	[1077] = "The Scroll of Messaging is done. Take it to Gaxim with reps.|Keep the scroll rolled tight. Collin worked hard on it.|From Stormwind to Stonetalon. Gaxim is waiting.|Collin wants the story later. Remember it in peace.",
	[1078] = "Eight scales from Charred Vale basilisks. Grind them out.|Basilisks stare hard. Stare back and don't blink.|Deep into the Charred Vale. The basilisks won't come to you.|Collin says take your time. For once, you can.",
	[1079] = "Plan Alpha: plans first, boom second. Load up with reps.|Hide by the lumber mill. Wait for the guards to turn.|In the mill, grab the plans, and out before the blast.|Success is not the boom. It is the plans. Keep a cool head.",
	[1080] = "Plan Beta: a distraction, then the letters. Warm up with reps.|Wait in the dark of Windshear Mine. The letters are close.|East end of the crag, into the mine and out alive.|Just get back alive, Gaxim says. Keep your mind clear.",
	[1085] = "A night elf and a gnome as a team. Show Gaxim your reps.|Kaela has fought here a long time. Stand guard with her.|Gaxim is close by. Hurry over and say hi.|Don't judge the gnome yet. Take a calm look first.",
	[1086] = "The Toxic Fogger is ready. Place it, then do your reps.|Wait out of sight at the sky port until it is clear.|Place it, and run. Zamah was very clear.|Search the Venture Co. land with sharp eyes and a calm mind.",
	[1087] = "Four sons, four daughters, four botanists. Braelyn wants them gone.|Braelyn hates this land. Stand by her fire and wait.|The druids of Cenarius roam wide. Hunt them down.|Braelyn talks of the flow of magic. Find your own flow.",
	[1088] = "Ordanus waits atop a great tree. Get ready with reps.|High in Raynewood, grip the branches and wait.|To Ashenvale, to Raynewood, and up the tree. Hurry.|Braelyn sees with magic. You see with calm eyes.",
	[1089] = "Key, caches, hoard. Open them all with reps.|The Talon Den is guarded. Wait in the shadows.|Lantern, key, caches, then the hoard. Move fast through the Den.|A tricky scheme needs a clear head. Think it through slowly.",
	[1090] = "Piznik mines the gold-green ore. Guard him with reps.|Watch the tunnel while Piznik digs. Stand your post.|Patrols come fast. Meet them before they reach Piznik.|Listen for footsteps in the mine. Calm ears hear more.",
	[1092] = "The ore sample goes to Ziz. Earn the trip with reps.|Piznik is cleaning up the mess. Guard the ore for him.|West side of Windshear Crag. Get the ore to Ziz right away.|Piznik hopes for a new job. Share his hope, slow and easy.",
	[1093] = "The Super Reaper 6000 is huge. Your reps should be too.|Gerenzo wants Ziz dead. Stand guard over the little gnome.|Find the operator with the plans. Search the whole crag.|Stealing plans takes a calm hand. Find yours.",
	[1094] = "The sealed envelope holds a lot. Match it with reps.|Keep the envelope sealed tight. No peeking.|Ratchet in the Barrens. Find the little green fellow.|The Super Reaper plans are safe with you. Relax a little.",
	[1095] = "Gerenzo must go. Get ready for it with reps.|Keep the new orders close. The trade princes are watching.|Ziz has a test coming. Race the orders to Stonetalon.|Hunches are best heard in the quiet. Listen to yours.",
	[1096] = "Gerenzo is part gnome, part gears. Take his metal arm with reps.|Up by the water wheel, Gerenzo watches. Wait for your opening.|Fight all the way up above Cragpool Lake. Don't stop now.|The top of the site is quiet. Be quieter than Gerenzo.",
	[1097] = "Grimand makes weapons. Show him you can swing one, in reps.|The weapon shop rings with hammers. Stand firm and wait for Grimand.|Northeast to the Dwarven District. Grimand wants a runner.|Good ties with the dwarves start with a calm hello.",
	[1098] = "Two deathstalkers are missing. Your reps are the rescue plan.|Shadowfang Keep is dark. Wait by the wall and listen.|South to the keep. Find Adamant and Vincent fast.|Dangerous and critical. A clear head first.",
	[1130] = "Melor heard of your deeds. Add a few more reps to them.|Hunter's Rise is high. Stand tall at the top.|Melor calls you to Thunder Bluff. Go now.|A new path waits. Take a calm look at it.",
	[1131] = "Steelsnap rules the hyenas. Take him down with reps.|Hyenas circle in Thousand Needles. Stand firm and wait for Steelsnap.|Steelsnap roams far. Track him through the Needles.|This hunt is not for food or honor. Hunt with a calm heart.",
	[1133] = "Fresh off the boat? Shake off the sea with reps.|Don't say who sent you. Keep that secret tight.|From the Menethil boat all the way to Astranaar. Go.|Shindrell does not know who sent you. Stay calm and don't tell.",
	[1134] = "Twelve venom sacs from the pridewings. Your reps count them out.|Hold low in the grass by Mirkfallon Lake. Pridewings see far.|Pridewings swoop fast. Stay on your feet and chase them down.|Orc spies move quietly. So do you, out by the lake.",
	[1138] = "Six crab chunks for Gubber. Crack shells with your reps.|The reef crawler snaps its claw. Stand your ground and hold.|Crabs scuttle sideways on the shore. Stay after them.|Gubber lists his crab dishes again. Let the list wash over you.",
	[1140] = "Two soulgems, two satyr camps. Break them open with your reps.|The satyr temples are grim. Stay firm while the soul slips free.|Night Run to Satyrnaar is a long way. Stay on the move.|A Highborne soul drifts home at last. Let it go, soft and slow.",
	[1141] = "Six grouper for Gubber. Reel them in with your reps.|Line in the water. Hold until the grouper bites.|Murlocs on the shore! Dodge past them to the good spot.|The Blump family fishes with patience. Wait for the tug.",
	[1143] = "Warlocks guard every floor. Your reps clear the stairs.|Athrikus waits at the top. Keep your nerve on the last step.|Up and up the Tower of Althalaxx. The stairs never end.|Balthule says strike now. First, a calm breath at the tower door.",
	[1144] = "Quilboar block the exit. Your reps push them aside for Willix.|Willix stops to catch his breath. Hold the tunnel while he does.|Easy in, easy out, said Willix. Out is the hard part. Go!|Willix has not seen the sky in ages. Soon. Stay calm for him.",
	[1195] = "The dryads carry the phials. Earn one with your reps.|Hold the phial in the moonwell. Let it fill to the top.|Raynewood Retreat to the Falfarren River. Cover the ground.|The moonwell glows soft and silver. Match its quiet.",
	[1196] = "Don't spill a drop. Your reps are careful ones, for the phial.|The Great Lift creaks down to the Needles. Hang on tight.|Freewind Post is far to the south. The road is long.|Rau Cliffrunner waits on the high rocks. Arrive calm.",
	[1197] = "The Galak guard Splithoof Hold in numbers. Rep through them.|The flame is out, but not for long. Wait, then grab the hoof.|Hoof in hand, and the centaurs are angry. Get out fast!|The moonwell water hisses on the flame. One calm breath, then act.",
	[1198] = "Naga stand between you and Thaelrid. Clear the way.|Thaelrid has held out for weeks. Hold with him a bit longer.|Down into Blackfathom Deeps. The Argent Dawn wants news fast.|The old temple is dark and damp. Listen for the lost scout.",
	[1199] = "Ten Twilight Pendants. Take them from the Hammer one by one.|The cult chants in the dark. Stand firm and give no ground.|Wage war on the Hammer, says Manados. Don't slow down.|The Old Gods whisper in Blackfathom. Tune them out.",
	[1200] = "Kelris feeds Aku'Mai. Your reps end the feast.|Kelris casts from his altar. Brace through his spells.|Thaelrid is weak. Carry his fight deep into the temple.|The Moon Well was sacred once. Honor it with a calm moment.",
	[1221] = "Six Blueleaf Tubers. The gopher sniffs, your reps dig.|Stick out, gopher out. Wait for the sniffing to start.|The snufflenose darts through the Kraul. Try to keep up.|Breathe in like the gopher. Somewhere a tuber waits.",
	[1275] = "Eight brain stems from satyr and naga. Gershala waits.|Naga coil at the water's edge. Keep your spot and wait.|'Tis a long journey, says Gershala. Better get going.|Gershala fears for the blood elves. Think it over, quietly.",
	[1279] = "Three paths. Pick one and put your reps behind it.|Hold at the fork until you choose your path.|One of the three, and then onward. Move along.|Three choices. Let the right one come to you.",
	[1280] = "Hoofprints in the Dustwallow mud. Your reps leave your own.|Stay by the tracks in the marsh and study them.|The centaur trail winds through the swamp. Follow it.|Marsh fog rolls in. Read the hoofprints with a clear head.",
	[1291] = "Deep hoofprints mean heavy centaurs. Match them with reps.|The tracks stop here. Wait and see where they went.|Fresh prints lead on. The centaurs can't be far.|Hooves leave a story in the dirt. Take your time with it.",
	[1292] = "The prints tell of many riders. Count them off with your reps.|Something stirs in the reeds. Freeze and hold.|Down the trail through Dustwallow Marsh. Muddy boots, fast feet.|Bugs hum in the marsh. Let them. Stay easy.",
	[1293] = "Hoofprint after hoofprint. Your reps follow the pattern.|The mud grabs your boots. Don't let it win. Hold.|The last set of tracks. Follow them to the end.|Swamp water drips from the trees. Slow down with it.",
	[1294] = "Not every centaur is a foe. Show good faith with your reps.|Keep an open hand out. See if the centaur takes it.|Word must reach the friendly centaurs. Carry it swiftly.|Listen to the centaur's side of things. Calm ears.",
	[1295] = "A plan needs work. Your reps are the first part.|Hold off on acting until the plan is clear.|The plan is set. Time to put it in motion.|Think through the next step before taking it.",
	[1296] = "Choose the bold path. Your reps back the choice.|Wait for the signal. Keep your place in the marsh.|No more talk in Dustwallow. Get going on the plan.|A good course starts with a clear mind. Find it.",
	[1297] = "The last course of action. Make your reps count.|Stand firm in the marsh. The plan depends on you.|Into the fog, down the path. The plan unfolds.|Look back on your choices, then settle your thoughts.",
	[1298] = "The Warchief needs hard work done. Your reps do it.|Thrall asked for quiet work. Hang back and watch.|Thrall's errand won't wait. Off you go.|Dirty work needs a clean mind. Clear it first.",
	[1299] = "More work for Thrall. Roll up your sleeves for these reps.|Stay in the shadows for the Warchief. Hold there.|The Warchief wants it done fast. Hustle.|No one needs to know. Settle in and stay quiet.",
	[1300] = "Lorn Grim Totem is waiting. Let your reps speak first.|Face Lorn Grim Totem and don't back down.|The Grimtotem are on the move. Go after Lorn.|Before meeting Lorn, find your calm.",
	[1338] = "Stormpike wants a shield from Furen. Earn his coin with reps.|Keep the request safe and flat. Hold it close.|Loch Modan to Stormwind. A long road south.|Furen's forge glows in the dwarven district. Take it in.",
	[1339] = "Stormpike needs a runner. Show him you're the one.|Top of the guard tower. Grip the rail and look out.|Up the northern guard tower, stair after stair.|From the tower top, Loch Modan spreads out below. Look.",
	[1358] = "The zeppelin is loading. Help stow the sample with some reps.|The zeppelin sways over the sea. Hang on until Orgrimmar.|South from Orgrimmar, west into the Barrens. On foot, too.|The Crossroads at last. Hand over the sample and unwind.",
	[1359] = "Zinge wants these samples. Your reps get them to her.|The hearts are toxic. Keep the jar level and steady.|To the Undercity with the samples. Don't dawdle.|The Undercity is dim and cool. Enter calm.",
	[1468] = "Your ward is watching. Show the orphan how it's done.|The whistle blows. Wait while the child comes over.|The orphan can't wait to meet you. Blow the whistle!|Children's Week is about kindness. Share a quiet moment.",
	[1470] = "Three Rattlecage skulls for Venya. Knock them loose.|The skeletons rattle near the old smithy. Stand firm.|Skeletons at the old smithy. Go get those skulls!|Venya says knowing is power. Clear your mind to learn.",
	[1471] = "The voidwalker won't bow easily. Beat it down with reps.|Stay in the circle. The voidwalker tests your will.|The void spills out of the circle. Stay on your toes.|Master the void by mastering yourself. Calm first.",
	[1472] = "Godrick has your bait list. Show him you're ready.|A succubus tempts. You must not bend. Hold.|Into the Temple of the Damned to find Godrick.|A sayaad preys on weak wills. Make yours calm and sure.",
	[1473] = "The Scarlet agent guards Egalin's Grimoire. Take it back.|Hold at the tower's edge. Wait for the agent to turn.|West to the Scarlet tower. The grimoire can't wait.|Egalin summoned the first voidwalker. Read his words calmly.",
	[1474] = "The succubus fights with charm and whip. Answer with reps.|Her charms pull at you. Keep your mind your own.|Pure Hearts on the circle. Here she comes, so move.|Many strong minds fell to her. Yours stays clear.",
	[1476] = "Two names on Carendin's list: Dalin and Corma. Get to work.|Corma waits in the Wetlands for her lost love. Wait too.|From the Greymane Wall to the Wetlands. A long hunt.|Warlock work is dark. Settle your mind before you start.",
	[1478] = "Master Halgar wants you. Show up ready to work.|Wait by the Temple of the Damned. Halgar will see you soon.|Off to the Magic Quarter. Halgar doesn't like to wait.|Be proud, young warlock. Take it in before you go.",
	[1483] = "Ziz needs help. Goblin work is heavy work. Get started.|Venture Company eyes are everywhere. Stay low at the crag.|West to Windshear Crag. Ziz is waiting.|A gnome took Ziz's job. Help him let it go.",
	[1485] = "Six vile familiar heads for Ruzan. Imps are small but mean.|The imps swarm in the cave. Guard the way in.|Into the northeast cave. Those imps are quick.|Ruzan lets you choose your own path. Think on it.",
	[1486] = "Twenty Deviate Hides for Nalpak. That's a lot of beasts.|Deviate beasts lurk in the dark. Wait for them to come.|Through the Wailing Caverns, beast after beast.|Nalpak sees good in these hides. Look for it too.",
	[1487] = "Seven of each kind. Ebru wants the caverns clean.|Dreadfangs in the dark. Stand fast as they close in.|Ravagers, vipers, shamblers, dreadfangs. Chase them all.|Naralex dreamed of forests. Picture them green again.",
	[1489] = "The shells carry a taint. Bring the news to Hamuul.|Hamuul speaks slowly. Wait and hear his counsel.|All the way to Thunder Bluff and up the Elder Rise.|The land dreams and cannot wake. Rest with it for a while.",
	[1490] = "Nara's spirit is fierce. Match it with your reps.|Nara stayed in the dream. Stay put like she did.|Nara's tent is just over yonder. Hurry across.|Hamuul fled the dreaming place. Drift in, then drift out.",
	[1491] = "Six Wailing Essences for Mebok's drinks. Hunt them down.|Ectoplasm oozes near. Wait for the right moment.|Hunt the oozes through the Wailing Caverns.|Mebok's first try failed. No rush on the second.",
	[1492] = "A crate of potions and reagents. Your reps haul it to Ratchet.|The Secure Crate is heavy. Keep it steady.|The caravan left. It's you and the crate on the road to Ratchet.|Dizzywig takes the crate at the dock. Let the sea air settle you.",
	[1498] = "Five Singed Scales. The thunder lizards won't give them up.|Brave their attacks, says Uzzek. Hold like a shield.|Lightning crackles on Thunder Ridge. Stay one step ahead.|A warrior is a shield for the weak. Stand calm and tall.",
	[1499] = "Tell Zureetha about the imps. Show her what you can do.|Zureetha is busy. Wait your turn.|Back to the cave, to find Zureetha.|The imp problem is handled. A reward waits. Relax.",
	[1501] = "Burning Blade warlocks hold the Tablet of Verga. Take it back.|Skull Rock is full of warlocks. Wait at the cave mouth.|East out of Orgrimmar to Skull Rock. Quickly now.|Gan'rul says few warlocks are left. Calm, clear, ready.",
	[1502] = "Thun'grim makes fine weapons. Earn one with your reps.|Thun'grim lives alone on the hilltop. Wait for him to notice.|East of the Crossroads and up the hills to Thun'grim's camp.|A hermit's hilltop is quiet. Enjoy the view.",
	[1503] = "Razormanes took Thun'grim's steel. Your reps take it back.|Be heavy as an iron chest. No quilboar can budge you.|Northwest to the quilboar camps. Grab the box and go.|Thun'grim's eyes are bad. Yours must be calm and sharp.",
	[1504] = "The voidwalker rises from the circle. Show it your reps.|In Neeru's circle, you are the rock. The void blinks first.|Beat the voidwalker down before it wears you out.|Read the glyphs of Verga with a quiet mind.",
	[1505] = "Uzzek trains young warriors. Bring him reps worth seeing.|A veteran stands his ground. Hold yours at Far Watch.|Far Watch Post sits on the border. Head east and don't stop.|Great warriors are great students. Listen, then learn.",
	[1506] = "Gan'rul wants you now. Arrive with a few reps done.|Good news or bad? Hold your nerve in the Cleft of Shadow.|Your schedule just got busy. Down to the Cleft, quick.|The senior warlocks watch. Let your mind go dark and quiet.",
	[1507] = "A sayaad bows only to a strong will. Show yours with reps.|Her charm pulls at weak minds. Hold firm.|Off to find Cazul. The ancient warlock waits.|Think of an object full of love. Then go find it.",
	[1508] = "Cazul is blind but sees plenty. Let him hear your reps.|Zankaja waits for her mate. Wait with her, just as still.|West of the wind rider tower, up the bluffs. Go.|Trust a blind man's words. Close your eyes and listen.",
	[1509] = "Dogran was promoted and proud. Earn some pride of your own.|Zankaja hid her worry from him. Hide yours, too.|The road to the Crossroads is long. Gazrog is at the end.|A week without word. Take a calm breath for Zankaja.",
	[1510] = "Dogran led grunts into a quilboar camp. Match his grit.|The grunts wait for the draught. Hold on with them.|To the Malaka'jin at the foot of Stonetalon. Hurry.|The trolls take their time with a brew. So do you, here.",
	[1511] = "Half now, half tomorrow. Ken'zigla is clear on that.|Keep the flask level. Not a drop spills.|Camp Taurajo is far south. Logmar needs that draught.|Wait a night, says Ken'zigla. Patience is part of the brew.",
	[1512] = "Dogran chose battle over rest. Honor him with your reps.|Keep Dogran's secret, and keep the pendant close.|The Dirt-caked Pendant goes to Gan'rul. Orgrimmar is far.|Dogran wants his mate free of guilt. Let a quiet breath carry that.",
	[1513] = "The succubus tries her charm. Your reps say no.|Pride has sunk many warlocks. Stand firm, not proud.|Win fast, before the succubus gets in your head.|Dogran's Pendant goes home to Zankaja. Let this one end softly.",
	[1515] = "No more grunts to help. It's you against the camp guards.|Crouch by the two huts. Wait for the guards to turn.|Two huts in a quilboar camp. Dogran is inside one.|Quiet steps past the guards. Dogran is close.",
	[1516] = "Two Felstalker Hooves. The earth wants proof of your might.|Your spirit endures like the earth. It does not shift.|The Felstalkers roam north. Chase them down.|Wisdom before proof, says Canaga. Show a bit of it now.",
	[1517] = "The Hidden Path winds on. Earn the sapta with your reps.|At Spirit Rock, drink and wait. Hold until the earth speaks.|Southwest, to the end of the Hidden Path.|A holy place, and no other. Drink, then look around.",
	[1518] = "Small quartz, big heart. Your reps are the same.|The pebble outlasts others. Be the pebble.|Carry the Rough Quartz back to the Valley of Trials.|Be patient. Remain strong. Seek wisdom. Earth asks no more.",
	[1519] = "Two jars of Ritual Salve from the Bristleback shamans.|Ravenfeather sees the earth in you. Stay firm and prove it.|Into the ravine to the east. The Bristlebacks await.|The earth speaks in time. Listen for it.",
	[1520] = "Kodo Rock waits in the east. Arrive ready.|At the shrine, drink the sapta. Then hold for what comes.|East to the shaman shrine with the sapta in hand.|An open mind sees the elements. Open yours.",
	[1521] = "Ravenfeather will craft your totem. Your reps build its base.|The pebble can outlast mountains. Stay put like it does.|Back to Camp Narache with the Rough Quartz.|Respect the earth, and it respects you. Settle in.",
	[1522] = "Fire be witcha, mon. Stoke it up with some reps.|Kranal waits north of the Crossroads. Wait with the same fire.|North of the Crossroads, but not too far. Elves lie beyond.|Earth is yours. Now a flame flickers at the edge of your mind.",
	[1523] = "Destruction and chaos are on the lesson plan. Warm up.|You have shown patience. Show a bit more.|Find Kranal Fiss in the Barrens. Stop before the elf lands.|Fire has a price. Think it over before you pay.",
	[1524] = "The Torch of the Dormant Flame waits to be lit. Earn it.|Grip the torch at the peak. The wind tests your hold.|Up the hidden trail to the highest peak in Durotar.|Look out over the Great Sea from the Shrine of the Dormant Flame.",
	[1525] = "Razormane mystics and Burning Blade cultists. Both drop loot.|The cave above the ravines is dark. Hold at the mouth.|Eastern Barrens, then Razor Hill. Two stops, no rest.|Telf Joolam will brew the sapta. Gather your mind first.",
	[1526] = "The Manifestation grows the longer you wait. Strike fast.|He won't attack until you're ready. Let him see you stand.|The mountaintop burns. Get up there.|Drop the Glowing Ember in the brazier. Watch the torch catch.",
	[1527] = "The flame dances in the wind. Match its heat.|Torch firmly in hand. Don't let the wind take it.|From the peak back to the Barrens, torch held high.|Look out over Durotar one last time before the long walk.",
	[1528] = "Water be in ya future, mon. Earn it.|Islen waits by the coast. So do you, for now.|South along the Southfury River. Look for the big shark!|Fire first, now water. Let the tide in your head roll in.",
	[1529] = "The purity of water is next on the list. Get ready.|Islen fishes by her hut. Wait like a line in the water.|Past Ratchet to the eastern coast. Islen's hut is there.|Patience got you here. Water asks for a little more.",
	[1530] = "Quilboar bother Brine's home. Show them some reps.|Water flows and wears down stone. Be the stone for now.|Deep into Southern Barrens to find Brine.|Water means rebirth. Let that sink in.",
	[1534] = "Ashenvale is far north. Your reps start the trip.|Stand in the lake. Wait for the skin to fill.|West past Lake Mystral to the Ruins of Stardust.|The fountain is a holy place. Be still and look.",
	[1535] = "A simple task: the pond below Brine's hut.|Kneel at the pond. Let the Brown Waterskin fill.|Down to the watering hole and back up to Brine.|See the creatures that drink here. Watch them a while.",
	[1536] = "Tarren Mill is Forsaken land. Arrive ready.|The Red Waterskin fills slow at the well. Wait for it.|A long road to Hillsbrad and the well in Tarren Mill.|A small holy spring in a sad town. Take a quiet moment.",
	[1578] = "Six Copper Axes, six belts. Thorvald's mountaineers need them.|Tongs steady. The copper cools at its own pace.|The troggs keep coming. Keep the forge going.|Thorvald shares his skill with those who help. Listen well.",
	[1579] = "Eight Gaffer Jacks lost at sea. Reel them in.|Line in the water off Auberdine. Wait for the tug.|Wizbang wants his jacks now! Cast and cast again.|Wizbang came for the quiet. Enjoy some of it.",
	[1580] = "Twelve Electropellers somewhere in Darkshore. Fish them out.|Just how lucky are you? Stay put at the lake and find out.|River to lake to stream. Darkshore has lots of water.|Wizbang woke with singed hair. You get a calm shore instead.",
	[1581] = "Six Elixirs of Lion's Strength. Mix like a lion.|Hold the vial level. Minor Defense spills easy.|The shop is booming. Keep the elixirs flowing.|Syral just wants time with her husband. Give them a quiet moment.",
	[1582] = "Five boots, five cloaks, one glove. Lotherias has orders.|Pull the leather tight and hold it there.|Young adventurers need gear, fast. Stitch on.|An advanced technique waits. Clear your head for it.",
	[1598] = "A novice fled with the books. Show Drusilla you are tough enough.|Crouch by the Defias tent. Wait for your moment.|Slip into the Vineyards, grab the tome, get out.|Powers of the Void. Don't get pulled under.",
	[1599] = "Three Feather Charms from the frostmane novices.|Prove your magic and your might. Stand firm in the cave.|Southwest to the frostmane cave. Alamar wants his charms.|Everyone is whispering about the new warlock. Stay cool.",
	[1618] = "Four Heavy Copper Mauls for Redridge. Forge them with reps.|Blackrock orcs press on Redridge. Hold the line with Verner.|Runed belts, heavy mauls, and a long road to Redridge.|Verner Osgood has a trick or two. Stay calm and watch him work.",
	[1638] = "Harry Burlguard is a good teacher. Show him what you've got.|Moves that keep you breathing longer. Hold on for them.|Old Town, the Pig and Whistle. Harry's waiting.|Still young, lots to learn. Clear your head for the lesson.",
	[1639] = "Harry wants to see your moves. Start with some reps.|Bartleby won't let go of that mug. Neither will you.|Past the tavern crowd to the end of the bar.|Walk up calm. Bartleby is about to get cranky.",
	[1640] = "Bartleby wants a fight for his mug. Give him one.|Bartleby is drunk, not weak. Don't give him an inch.|Around the tavern tables you go. Bartleby wobbles after you.|After the brawl, catch your breath. Then ask nicely.",
	[1642] = "Strength in battle counts. So does helping others.|Compassion, patience, bravery. Hold on to all three.|Duthorian Rall waits in Stormwind. Go see him.|Strive to be good in all things. Think on it.",
	[1643] = "Someone in Stormwind needs your kindness. Warm up to help.|Watch the Trade District for a kind face in need.|Search the Trade District street by street.|Pure of heart and motive. Look for it quietly.",
	[1644] = "Ten Linen Cloth for Stephanie. The orphans need clothes.|Stephanie keeps the roof up alone. Hold up your end.|Find the linen, bring it back. Little ones are waiting.|Thank the Light for kind hands. Yours count too.",
	[1646] = "Tiza Battleforge wants paladins strong in heart and arm.|Patience is a paladin's armor. Wear it now.|Through the halls of Ironforge to Tiza.|Aid to others sets you apart. Let that settle in.",
	[1647] = "Someone in Ironforge needs a hand. Be ready to lend it.|Tiza waits in the temple. You wait for a sign of need.|Round the outer ring of Ironforge to find John Turner.|Noble intent rarely shouts. Look close to find it.",
	[1648] = "John needs Ten Linen Cloth to send his shipment home.|John's trip has been slow. Stay with him a while longer.|Gather linen fast. The orphanage in Stormwind needs it.|Clothes for the orphans. A kind deed, calmly done.",
	[1649] = "Valor is like rare ore. Refine it with reps.|A strong alloy can take any blow. Be that alloy.|Duthorian Rall is in Stormwind. Your test begins there.|Never lose faith. Let the Light fill your breath.",
	[1650] = "Daphne is alone and the Defias are close. Get ready.|Jordan is away in Ironforge. Stand guard for him.|Westfall's Longshore runs far. Daphne's house is at the end.|A small house above the ocean. Take in the view, then look sharp.",
	[1651] = "The Defias come in waves. Beat back every one.|We make our stand near the house! Not a step back.|More Defias than before. Keep them off Daphne.|Ask the Light for blessings. Then listen: they're coming.",
	[1652] = "Stilwell's wife is safe. Your reps carry the good news.|Duthorian waits for word. Stay firm until he hears it.|Stormwind is far. Carry her message at a steady clip.|She misses Jordan. Let that quiet hope settle in.",
	[1653] = "Jordan works outside the gates. Match his hammer with your reps.|The cool mountain air bites. Stay put at the Ironforge gates.|The road to Ironforge climbs. Keep those feet going.|Jordan likes the mountain air. Take a long, cool breath of it.",
	[1654] = "Oak, ore, hammer and gem. Jordan's forge waits on your reps.|Grip Jordan's Smithing Hammer like it's yours. Now hold.|From the oak to the Kor Gem, the list is long. Go get it.|Read Jordan's notes calmly. A paladin's weapon starts in the mind.",
	[1656] = "A bundle of furs for Bloodhoof. Lift it high with good reps.|The young brave is resting. Guard his furs for him a while.|Down from Red Cloud Mesa to Bloodhoof Village. Onward!|Innkeeper Kauth's inn is a fine place to rest. Picture it now.",
	[1665] = "Bartleby drained his mug first. Now drain your reps.|Grip Bartleby's mug like a trophy. Don't spill a drop.|Burlguard wants that mug. Hurry before Bartleby refills it.|Bartleby took his time with that drink. Take your time too.",
	[1666] = "Marshal Haggard has spare weapons. Show him reps worth one.|Eastvale Lumber Camp is quiet. Wait there like an old marshal.|From Stormwind to Eastvale. The manor won't come to you.|A retired marshal lives slow. Borrow his calm for a moment.",
	[1667] = "Dead-tooth Jack laughed and ran. Answer him with reps.|Crouch by Jack's camp. Wait for the Defias to look away.|Jack ran off with the badge. Now you chase him south.|It was dark when Jack fooled Haggard. See clearly now.",
	[1678] = "Vejrek is the toughest troll around. Show Muren your mettle.|Vejrek's hut sits below Frostmane Hold. Be ready at the door.|The foothills are cold and steep. Warm up on the way to Vejrek.|Muren teaches new moves after this. First, a calm, clear mind.",
	[1679] = "Muren Stormpike tests all warriors. Make these reps count.|The Hall of Arms likes a proud stance. Take it and keep it.|Across the Military Ward to find Muren. Quick now.|Before Muren's lessons, empty your head of all else.",
	[1680] = "The Great Forge rings. Your reps set the beat.|Tormus eyes you like raw metal. Stay firm on his anvil.|Ironforge is a maze of halls. Find Tormus at the forge.|The forge fire glows low. Let your thoughts cool with it.",
	[1681] = "Umbral ore is heavy. Put your reps in for Master Ironband.|Dark Iron dwarves guard the compound. Keep your ground.|Helm's Bed Lake is far east. Get that load back to Tormus.|Ironband taught with patience. Honor him with a quiet mind.",
	[1682] = "Grey iron weapons on the rack. Earn the right to pick one.|Weigh a grey iron blade in hand. Keep it level.|New weapon, new pace. Show it off around the forge.|Pick your grey iron weapon with care. No rush.",
	[1683] = "Vorlus splashes in the moonwell. Answer him with strong reps.|The path to the moonwell is hidden. Stay alert and wait.|Past Ban'ethil Barrow Den and on. Vorlus won't wait.|The moonwell should be pure. Be as clear as its water.",
	[1684] = "Elanaria trains only the worthy. Bring her solid reps.|The Warrior's Terrace wants a firm stance. Hold it proudly.|Darnassus is a long way up the tree. Keep your feet busy.|A new teacher waits. Arrive calm and ready to learn.",
	[1685] = "Gakin has summoned you. Answer with reps, not excuses.|The Slaughtered Lamb's basement is dark. Wait there quietly.|The messenger searched all day. Don't make Gakin wait too.|Keep the basement a secret. Breathe quiet as a whisper.",
	[1686] = "Eight crates of elunite on the sea floor. Haul them up.|The Shade of Elura guards the deep. Stay down and face her.|Head for the wreck by the Auberdine lighthouse. Hurry!|The captain cursed herself to guard forever. Let the sea calm you.",
	[1688] = "Surena left with a Defias. Your reps catch up to her.|The Brackwell Pumpkin Patch hides her. Wait among the pumpkins.|Gakin wants his choker now. Off to the pumpkin patch!|A bloodstone choker, cold and red. Look into it calmly.",
	[1689] = "A voidwalker answers the choker. Beat it down with reps.|The summoning circle glows. Stand in it and don't budge.|The voidwalker comes at you. Stay light and quick.|Magic flows through the choker. Guide it with a slow breath.",
	[1692] = "Mathiel will craft your elunite weapon. Match his hammer blows.|The case of elunite is heavy. Keep it steady on the way.|Mathiel is just around the building. Hurry over.|A weapon takes shape in Mathiel's fire. Watch it quietly.",
	[1693] = "An elunite blade gleams. Give it a proper welcome.|Your new elunite weapon is light. Keep it raised.|Try your elunite weapon on the Warrior's Terrace today.|Elunite shines like moonlight. Take it in slowly.",
	[1698] = "Yorus promises a grand reward. Earn it with reps.|The Lakeshire Inn is packed. Stay firm at the bar.|Redridge is a long road. Keep going till Lakeshire.|Before any challenge, a quiet sip of air.",
	[1699] = "Heaps of Redridge gnolls stand in the way. Knock them aside.|The Barleybrew Scalder burns. Don't let it knock you over.|Into Rethban Caverns and back before time runs out. Go!|No dying allowed. Find your calm before the gauntlet.",
	[1700] = "Grimand is proud of his skills. Show him yours.|Hand over Furen's notes. Then brace for Grimand's temper.|The Dwarven District is just ahead. Deliver before he cools off.|Grimand hates learning from Furen. Stay kind and easy about it.",
	[1701] = "Fifty of one thing, twelve of another. Furen's list is long.|Fire hardened mail won't come easy. Stay tough like good armor.|Furen sends you far for rare stuff. Get moving.|Rare materials need a patient hunter. Be that hunter now.",
	[1702] = "A cask of Barleybrew Scalder is no light load. Lift it with reps.|Don't let the cask slosh. Keep it level to Stormwind.|Furen owes Yorus a favor. Race the cask to Stormwind.|Furen is the best shieldsmith. Picture your new shield, calm.",
	[1704] = "Klockmort may pull off his own beard. Give him reason to.|Guard Furen's notes close. No gnome gets them but Klockmort.|Off to Ironforge with the notes. Tinker Town awaits.|Klockmort will be thrilled. Stay calm for the both of you.",
	[1705] = "Twenty vials of burning blood. The Nightbane won't give them up.|Roland's Doom mine is dark. Stand fast as the worgen come.|Duskwood's roads are grim. Push on to the mine.|Gutspill has the burning rock. Find a quiet mind before him.",
	[1708] = "Twenty loads of searing coral. Klockmort's toes are twisting.|The coral grows under the waves. Stay down there a bit more.|Down the coast from Menethil Harbor. Hurry, says Klockmort!|The Wetlands tide rolls in and out. Match it.",
	[1710] = "Twenty sunscorched shells. Mathiel wants them all.|Highperch Wyverns circle above. Keep low under the nests.|Highperch is high and wide. Search it from end to end.|The shells break easily. Be gentle and slow.",
	[1715] = "The warlock grumbles about Ironforge. Let your reps grumble too.|Magni keeps watch on you. Look innocent and stay put.|From Ironforge to Stormwind, all for Gakin. Mind the tram.|It burns his blood, not yours. Stay cool on the trip.",
	[1716] = "A sayaad tempts hearts. Your reps say no thanks.|Takar the Seer sees far. Wait before him until he speaks.|The Barrens stretch forever. Keep on to Camp Taurajo.|A demon plays on your will. Guard it with calm.",
	[1717] = "Gakin has more to teach. Show up ready to work.|Linger in Stormwind long enough for Gakin to find you.|Past time for training! Head to the Mage Quarter.|The Mage Quarter hums with magic. Tune in quietly.",
	[1738] = "The heartswood grew where two lovers fell. Honor them with reps.|Ordil'Aran's ruins are old. Wait there as the forest does.|Northwest through Ashenvale to the ruins. Press on.|A tree of undying love. Let its calm reach you.",
	[1739] = "The succubus tempts. Your reps keep your mind your own.|Strong minds fall to succubi. Yours stays in place.|The portal opens in the crypt. Stay quick on your feet.|The heartswood core pulses. Match its slow beat.",
	[1740] = "Three fragments and one large one. Piece the orb together.|Shadowfang Keep's wizard grips his shard. Grip harder.|Blackfathom Deeps, then Shadowfang Keep. Long way, no stopping.|A demon sleeps in the orb. Don't wake it. Stay soft.",
	[1778] = "He's heading home to Stephanie. Send him off with reps.|Tiza Battleforge is busy. Be patient where you are.|Tiza is in Ironforge. Get there before she wonders.|Till next we meet, he says. A kind goodbye, taken slowly.",
	[1779] = "Muiredon fought the Dark Irons. Your reps pick up where he left off.|The Symbol of Life is warm in your hand. Keep it close.|Muiredon is just over there. Bring the Symbol quickly.|Tiza asks for patience. Show her plenty.",
	[1780] = "Gifts for the children are on the way. Reps for their sake.|Duthorian awaits your report. Stand tall before him.|Back through Stormwind to Duthorian Rall. Step lively.|The paladins never turn their backs. Face this moment calmly.",
	[1781] = "Gazin met the Defias near Heroes' Vigil. Your reps are next.|The Symbol of Life asks for focus. Keep it steady.|Gazin rests by the altar. Carry the Symbol to him.|One of the Light's greatest gifts. Focus it in slow breaths.",
	[1782] = "Furen's new armor is heavy. Get used to the weight.|New mail, fire hardened. Stay in it and feel sure.|Show off Furen's armor around the Dwarven District.|Buckle Furen's armor with care. Every strap in place.",
	[1783] = "Narm held off the Dark Irons. Your reps return the favor.|Narm lies near Helm's Bed Lake. Keep the Symbol over him.|South of Helm's Bed Lake, fast. Narm can't wait.|The Symbol of Life calls Narm back. Lend it your calm.",
	[1784] = "One Dark Iron script, and a captain's men in the way.|Watch the Dark Iron captain give orders. Wait for your chance.|Chase down the Dark Iron spies by that small house.|The council needs proof. Think clearly and plan.",
	[1785] = "Tiza's beaming with pride. Give her reason to.|Tiza speaks, and you stay proud and tall. You've earned it.|Narm says get over there pronto. Off you go.|The Scourge and the Dark Irons can wait. Enjoy this.",
	[1786] = "Henze stayed brave for his friend. Be just as brave.|Heroes' Vigil sits in Stone Cairn Lake. Keep watch on the island.|To Stone Cairn Lake in northeastern Elwynn. Henze waits.|Henze was a daft fool, going and being brave. Honor him quietly.",
	[1787] = "Defias rogue wizards hold the papers. Take them.|The island is crawling with Defias. Keep your spot.|Grab the Defias script and hurry to Gazin.|Tell Gazin all is well. First, settle yourself.",
	[1788] = "The script goes to the King's advisors. Your reps got it there.|Duthorian wants to pat you on the back. Wait and let him.|Duthorian waits in Stormwind. Head to him now.|An ally to be proud of. Let that thought sit easy with you.",
	[1806] = "Jordan hammers at the forge. Keep up with him.|Linger by the forge while Jordan works. It won't be long.|Sparks fly from Jordan's forge. Match their speed.|Jordan is a bit envious. Be calm and let him craft.",
	[1818] = "The Dark Lady wants proof of your worth. Here it comes.|Dillinger's post is by the graveyard. Wait there, silent.|West end of Brill. Report to Dillinger, quickly.|Graveyards are quiet. Be quiet with them.",
	[1819] = "Ulag the Cleaver is free at last. Meet him with strong reps.|The seal lifts. Stay ready for Ulag.|Hit the skull stone trigger, then keep clear of the Cleaver!|The mausoleum is still. Gather yourself before Ulag wakes.",
	[1820] = "Coleman Farthing wants revenge. Be the blade he needs.|Gallow's End Tavern is crowded. Stay firm by Coleman.|East across Brill to the tavern. Coleman waits.|Revenge can wait a breath. Take it slowly first.",
	[1821] = "Sword, axe, mace, dagger. Four heirlooms, and the reps to earn them.|Dead Agamands lurk in the crypt. Hold your spot till they pass.|Coleman wants those heirlooms fast. Out of the crypt, go!|The crypt is cold and quiet. Match it before you reach in.",
	[1822] = "Coleman lays out the heirlooms. Pick one and earn it.|An heirloom is yours now. Grip it firm and hold.|A new weapon wants a fight. Get moving, warrior.|Feel the weight of the old family blade. Slow and calm.",
	[1823] = "Ruga Ragetotem calls for warriors. Show him reps worth a trial.|Warriors who answer his call stand firm. Hold at Camp Taurajo.|Camp Taurajo is far south. Keep your legs going.|A trial is coming. Find your calm on the road to Ruga.",
	[1824] = "Five twitching antennae. Get them before they go still.|The bugs crawl close. Stay put and let them come.|The antennae stop twitching soon. Race back to Ruga!|The Field of Giants is wide. Take it in slowly.",
	[1825] = "A smith of renown heard of you. Give him reps to match.|Like armor on a rack, stay put while Thun'grim sizes you up.|East of the Crossroads, a forge waits. Off you go.|Thun'grim has near-blind eyes. Rest yours a while.",
	[1838] = "Fifteen smoky ingots and ten iron bars. Heavy work for your reps.|Hold like a bar of iron cooling on the anvil.|Thun'grim's scroll is long. Run down that list.|Powdered azurite settles slow. So can you.",
	[1839] = "Ula'elek will forge your gauntlets. Bring him reps he can use.|Sen'jin Village waits by the sea. Hold, like a troll on watch.|Off to Durotar. The Darkspear smith awaits.|Sea wind in Sen'jin. Let it slow you down.",
	[1840] = "Orm Stonehoof makes helms for the worthy. Prove it.|Be still as the great totem in Thunder Bluff.|Up the lifts to Thunder Bluff. The pool by the totem waits.|By the pool near the totem, the water is calm. Be like it.",
	[1841] = "Velora still works steel after death. Your reps can keep up.|The trade quarter smells of forge smoke. Hold your ground.|Down into the Undercity. Velora's forge is burning.|Even the dead take their time with good work. So do you.",
	[1842] = "Seven swollen hooves. The satyrs won't hand them over.|Wait in the brush until a satyr strays.|The satyrs dart between the trees. Chase them down.|Ashenvale is pure at heart. Soak it in before the satyrs.",
	[1844] = "The matriarch is mad with pain. End it with strong reps.|The Charred Vale is ash and smoke. Hold until she lands.|The Charred Vale is a long way up. Don't slow down.|Ashen ground, a sad beast. Go in calm and kind.",
	[1845] = "Orm sets the brutal helm on you. Wear it with pride.|The helm is heavy. Wear it tall and don't budge.|New helm, same warrior. Back to the road.|Orm's helm fits well. Take a slow look around Thunder Bluff.",
	[1846] = "Eight sturdy shinbones. If they snap, they don't count.|Grip the shinbone hard. The sturdy ones won't give.|The Wetlands are wet and wide. Slosh after the Dragonmaw.|Velora wants only the best. Pick yours with care.",
	[1848] = "Thun'grim hands over the hauberk. It weighs as much as your reps.|Chain mail sits heavy on you. Bear it and stay.|The hauberk jingles as you move. Let it ring.|The suit is done at last. Let the long quest settle.",
	[1858] = "Gamon is drunk. Your reps are quiet as his snores.|Gamon snores. Not a sound until the key is yours.|Key in hand, satchel open. Get to the Cleft of Shadow.|A good thief breathes soft. Gamon never feels a thing.",
	[1859] = "Therzok heard you like a little sneakery. Show him more.|Lower your voice. Stay in the shadows and hold.|Orgrimmar waits. Slip through the streets to the Cleft.|Quiet now. The Cleft of Shadow likes calm guests.",
	[1860] = "Stormwind needs a mage. Jennea Cannon needs your reps first.|The wizard's sanctum is quiet. Hold like a statue.|Hurry to the mage district. Jennea is waiting.|Mages study in stillness. Take a page from Jennea.",
	[1861] = "One flask of Mirror Lake water. Earn it before you fill it.|Hold the flask under the falls until it fills.|Southwest of the gates to Mirror Lake. Quick now.|Mirror Lake is flat as glass. Let your mind go calm as glass.",
	[1879] = "Bink trusts only a mage. Show her what a mage can do.|Bink won't budge on this. Neither will you. Hold.|Ironforge is big. Weave through it to the Hall of Mysteries.|The Mystic Ward hums softly. Tune in to it.",
	[1880] = "Leper gnomes guard the huts. Get past them with your reps.|Wait in the hut until the leper gnomes wander off.|Bink wants her box back. Get it and run!|So much know-how in one small box. Think on it, slow.",
	[1881] = "Your first task for the Forsaken mages. Start it strong.|The Magic Quarter is full of eyes. Stand firm for Anastasia.|Through the Undercity halls. Anastasia has work.|Green light, cool stone. The Undercity is calm down here.",
	[1882] = "Pluck the snapdragons from the Balnir garden. Put some force in it.|The plague creeps into the soil. Stand your ground in the garden.|Eastern Tirisfal is a long walk. Make it a quick one.|Snapdragons sway in the wind. Sway with them.",
	[1883] = "Un'thuwa feels the magic of Durotar shift. Give it a shove back.|Feel the currents shift in Sen'jin. Hold there.|Durotar's magic is off. Go help Un'thuwa.|Un'thuwa listens to the land. Listen with him.",
	[1884] = "Four ju-ju heaps. Knock each one flat.|Zalazane's warlocks watch the huts. Wait for your chance.|Across to the Echo Isles. Break the heaps and get out.|Once the heaps fall, magic runs right again. Let it.",
	[1885] = "Carkad has taken an interest. Don't let him down.|Those who ignored him are gone. Stay there and wait for him.|Go see Carkad now. You don't want to be late.|The Rogues' Quarter is dim and quiet. Blend in.",
	[1886] = "Astor rides between Silverpine and the Undercity. Catch him.|Wait by the road for Astor Hadren to ride past.|Astor won't wait around. Get after the messenger.|Carkad says know less. So think less. Just breathe.",
	[1898] = "Andron thinks you're the messenger. Play the part.|Keep a straight face while Andron talks. Hold it.|To his shop near the Apothecarium. Look like you belong.|Andron isn't the suspicious type. Stay easy and smile.",
	[1899] = "Astor's Ledger is heavy with secrets. Lift it with your reps.|Clutch the ledger. Hold on until Carkad has it.|Ledger in hand. Back to the Rogues' Quarter.|The bookshelf gave up its secret. Let the moment sink in.",
	[1919] = "The secret war needs mages. Jennea is calling you.|Wait at the sanctum door till Jennea calls.|Your true lessons start now. Hurry to Stormwind.|A window to the unseen world opens. Look in slowly.",
	[1920] = "Hidden beasts in the Blue Recluse. Make them show, then fight.|Box down. Hold on until the beast is caught.|The beasts run all over the inn. Chase them round.|Read the scroll slowly. The unseen things come out.",
	[1921] = "Ten linen and six rift gems. Wynne Larson needs them all.|The Silver Stream Mine is dark. Hold at the crates.|From Loch Modan back to Stormwind. A long road for a robe.|Soft linen for a mage robe. Be just as soft and calm.",
	[1941] = "Your new robe is done. Wear it well, mage.|Wynne checks the fit. Stay put in your robe.|A new robe flaps in the wind. Take it for a spin.|Manaweave feels light. So should you.",
	[1959] = "Magic is stirring in the Undercity. Anastasia wants a mage.|The trouble is close. Guard the Magic Quarter.|The Horde's mages are called. Go find Anastasia.|Feel for the stir in the air. Something here is not right.",
	[1960] = "Magic beasts in Algernon's shop. Show them, beat them, box them.|The scroll is read. Hold till the beasts show up.|Unseen things run between the jars. Keep on them.|The shop smells of herbs. Take it in, nice and slow.",
	[1961] = "Six mana gems from the Dalaran mages. They won't give them up.|The Dalaran mages cast. Hold firm through the spell.|Silverpine is thick with trees. Weave through to the mages.|Josef will sew your robe with care. Take the same care now.",
	[1962] = "The Spellfire Robes are yours. Wear them like you mean it.|Josef pins the hem. Don't twitch.|New robes, old streets. Parade them around the Undercity.|Spellfire on your back, calm in your head.",
	[1963] = "Tazan trades with the pirates by Ratchet. Not for long.|Strike from the shadows. Wait until Tazan turns away.|Ratchet's shore is long. Hunt Tazan down it.|The Shattered Hand works in the dark. Be patient like them.",
	[1978] = "Welcome to the Deathstalkers. Prove they chose well.|Varimathras is watching you. Do not look away.|To the Hall of the Dark Lady. The ledger can't wait.|The Syndicate is found out. Enjoy a quiet win.",
	[1998] = "Fenwick Thatros leads the undead of Silverpine. End that.|Watch the old dock on Lordamere. Thatros will come.|Down to the lake shore, fast. Thatros is there.|Carkad wants it flawless. Aim with care, then act.",
	[1999] = "The Kirin Tor locked it up. Your reps pick it open.|Lockpicks in the lock. Keep your hands dead still.|Ambermill is full of wizards. In, grab, out.|A lock opens for the calm, not the fast.",
	[2038] = "The troggs took Bingles' tools. Take them back, one by one.|Wait on the shore till the troggs look away.|Bingles' gear is all over the island. Go round it.|For Gnomeregan! Or at least for Bingles. Calm first.",
	[2039] = "Bingles might have blown himself up. Go see.|Stay on the shore and watch the Loch for smoke.|Over a week without word. Race to Loch Modan.|Maybe Bingles is fine. Hope, and look calmly.",
	[2040] = "A goblin shredder in the Deadmines. Tear out its power.|The shredder's blades whirl. Hold your ground.|Deep in the Deadmines, the shredder waits. Get down there.|Gnomes will drill with this power. Stay cool till then.",
	[2041] = "Shoni the Shilent leads the dig crew. Show up strong.|Shoni doesn't say much. Wait there with her.|From Ironforge to Stormwind. Shoni is among the dwarves.|Shoni is quiet. Be quiet too.",
	[2078] = "Gelkak's first mate needs to get home. Clear its way.|The first mate is slow. Hold while it catches up.|Lead the robot back to Gelkak. Watch for murlocs.|Key in its head, and it wakes. Take your time too.",
	[2098] = "Three key pieces. Crawlers, a strider and murlocs have them.|Ragin' Crawlers snap at you. Hold, landlubber.|Up and down the shore for the key. Arr, move!|Me ship be sunk, says Gelkak. Take a calm sea breath.",
	[2118] = "A rabid bear won't walk into a trap on its own. Bait it.|Set the trap and wait. The bear will come.|The bear is docile for a short time. Get it home fast.|The light makes the bear calm. Share some of that.",
	[2138] = "Twenty rabid thistle bears. A sad job, but it must be done.|A rabid bear charges. Stand firm.|The sick bears roam the Darkshore woods. Track them all.|Tharnariun hates this task. Think of the forest it saves.",
	[2139] = "The Den Mother is huge. Match her strength.|Her cave near Bashal'Aran is dark. Wait for her to come out.|Northeast to the cave. One last hunt.|Tharnariun hopes this is the last. Let it be.",
	[2158] = "Farley's rates are cheap. Earn a good meal.|Save a seat at the Lion's Pride. Hold it for Farley.|South along the road. You can't miss it.|Rest and relax at the Lion's Pride. Start now.",
	[2159] = "Herbs for Keldamyr. Earn the road south with your reps.|The Shadowglen druids still talk. Hold here till the package is tied.|Down the road to Dolanaar. Don't let the herbs go stale.|Smell the herbs in the package. Slow and easy, like the forest.",
	[2160] = "A crate for Kharanos. Lift your share of the load.|The pass is cold. Stand firm against the wind.|Brave the pass. Tannok waits with a warm hearth.|You made it to the inn. Take that breather.",
	[2161] = "Ukor was too scared. Show his food who the hero is.|Scorpids on the road. Hold your ground, food in hand.|Razor Hill is down the road. Beasts can't catch a moving hero.|Ukor thinks you fear nothing. Let your breath prove him right.",
	[2178] = "Five strider meats for the stew. Earn that recipe.|Striders stand tall on long legs. Be one of them.|Striders race across the shore. Chase them down.|Smell that stew. Alanndarian stirs it nice and slow.",
	[2205] = "Keryn thinks you look like the cheese delivery. Prove him wrong.|Mathias Shaw watches from the shadows. Don't twitch.|Package to the Barracks. Get cracking, fish.|A proper rogue moves quiet. Start with your breath.",
	[2206] = "The Dockmaster's pockets are deep. Dig out that schedule.|Crouch in the dock house shadows. The guard walks past.|Schedule in hand. Leave Jerod's Landing before they notice.|If you're caught, you were never here. Breathe like a ghost.",
	[2218] = "Hogral says your purpose is up the road. Work for it.|The Forlorn Cavern is dark. Wait for your eyes to adjust.|Up the road to Ironforge. Hulfdan won't wait all day.|Another lost soul. Find your purpose one breath at a time.",
	[2238] = "The King mines more gems than ten lifetimes. Take your share.|Onin hides among the lepers. Stay low and blend in.|Off to Gnomeregan. The Hidden Circle wants that report.|Old Stinkbeard must not know. Quiet mind, quiet feet.",
	[2239] = "Steam tanks haul ore past Gnomeregan. You haul the report.|The tank rolls by the post. Freeze until it's gone.|Report in hand, back to Hulfdan. Ironforge is waiting.|Quarry, Kharanos, Gnomeregan. Trace the tank's long route.",
	[2241] = "Jannok's home is full of Syurna paintings. Earn her that rose.|Keep the rose steady. Don't crush Jannok's hopes.|Darnassus is a long way for a flower. Off you go.|Lovestruck Jannok sighs. Sigh with him, then deliver.",
	[2242] = "Sethir the Ancient doomed all who came. Be the one who doesn't.|Sethir sits on his branch. Wait for him to look away.|Grab the clues and flee the Oracle Glade.|Force failed. Talk failed. Try soft steps instead.",
	[2259] = "Not Syurna this time. Erion wants you, so earn it.|Erion waits at the Enclave. So can you.|Make haste through Darnassus. The Enclave is close.|Relief. It's not Syurna. Let that sink in.",
	[2260] = "Stormwind asked for you by name. Show them why.|The trip is long and taxing. Brace for it.|Darnassus to Old Town. Many roads lie between.|A new world awaits. Take it in slowly.",
	[2281] = "Renzik won't lose another rogue. Get up to speed.|Lean on a Lakeshire post like Lucius. Just don't slump.|To Redridge. The docks are full of shady types.|The field is no place for the green. Ease in first.",
	[2282] = "Pick that lock. Lucius wants his token back.|Tension on the lockpick. Steady hands open chests.|Up the hill to Alther's Mill and back to Lucius.|Grace and finesse, like old Lucius. It starts with the breath.",
	[2298] = "Magni's men know your name now. Work fast, leave faster.|Nobody puts the iron on Blackbeard. Or on you.|First gryphon out of Ironforge. Go, go, go.|Phase III is on hold. Your breath doesn't have to be.",
	[2299] = "Hulfdan's been looking all over. Make the trip count.|The king may have irons for you. Stay out of sight.|Ironforge, as soon as you can. Move it.|Not in irons yet. Enjoy that thought.",
	[2300] = "Renzik is Mathias's second. Don't keep him waiting.|Renzik the Shiv likes rogues at attention.|Through Stormwind to Old Town. Quick now, fish.|Old Town is quiet at night. Match its calm.",
	[2359] = "The spiked zombie holds the key. Snatch it.|Those guards aren't human. Stay in the shadows till they pass.|Key in hand, up the tower to the Duskwood Chest.|Read Kearnen's Journal. Slow down and learn the tower.",
	[2360] = "The Defias took an Alliance tower. Time to take it back.|Kearnen hides near the tower. Hide like her.|Westfall is a long way. Head southeast of Sentinel Hill.|A debriefing needs a clear head. Clear it now.",
	[2378] = "The Deathstalkers say you need training. Start now.|Shenthul waits in the Cleft of Shadow. Wait in shadow too.|Journey to Orgrimmar. The Shattered Hand won't come to you.|Stealth and tricks are learned slowly. Begin with quiet.",
	[2379] = "Grit alone won't do it, Shenthul says. Add some work.|Zando'zan tests stealth. Don't let him hear you.|Around the Cleft of Shadow to find Zando'zan.|Master stealth first. Then the next step.",
	[2380] = "Your skills are meager. Shenthul wants more.|Shenthul asked for you by name. Stand proud.|Take the road north. Orgrimmar is close.|All that can and will change. Let it start here.",
	[2381] = "The last five thieves failed. Your reps say you won't.|Parrots on the Tide Razor. Freeze till they look away.|Treasure in hand, off the Tide Razor and up the coast to Ratchet.|Practice in the pirate's den first. Calm hands, quick fingers.",
	[2382] = "Zando'zan has seen too much. Get to work before he says more.|Zando'zan's visions are wild. Stand firm through them.|East of the Crossroads to Ratchet. Go!|Visions of daggers and poison. Clear them from your head.",
	[2383] = "Frang wants words. Show up ready.|Frang waits in the shade outside the Den. Join him there.|Across the Valley of Trials to find Frang.|Read the parchment. Take it in slowly.",
	[2399] = "Teldrassil's fronds sprout slowly. Your reps don't have to.|Stay rooted like a young frond in Teldrassil.|Through Teldrassil's glades, past the fresh green fronds.|Unfold like a new frond in the morning sun.",
	[2438] = "Starbreeze fell to the furbolg. Take back the dreamcatcher.|Search the dresser quietly. Furbolg are close.|To Starbreeze Village and back to Dolanaar.|The dreamcatcher draws from the Emerald Dream. Drift with it.",
	[2458] = "Fire two flares, then salute. Get the order right.|Fizzule attacks strangers. Don't move until he knows you.|North of the Sludge Fen to the Venture Co. tower.|A year of planning rests on you. Be calm and careful.",
	[2459] = "Seven Gnarlpine Mystics. Ferocitas wears the green glow.|Wait for the necklace to glow in the dark. Then strike.|North of Starbreeze, the mystics scatter. Chase them.|The emerald is useless to Ferocitas. Take it back calmly.",
	[2460] = "Watch, learn, repeat. That's the Shattered Hand way.|Hold the salute for Shenthul. Make it perfect.|Shenthul makes you do it again. And again.|The salute tells friend from foe. Learn it with care.",
	[2478] = "Two drones, two patrollers, two lookouts. Then Gallywix.|The poison has weakened the tower. Wait for your moment.|Up the Venture Co. tower, floor by floor, to Gallywix.|Pick Gallywix's lockbox. Soft hands, sharp mind.",
	[2479] = "Zanzil's mixture is in your bag. Get it to Serge.|Keep the sample steady. Don't spill it on the zeppelin.|Undercity, Silverpine, Hillsbrad. Follow the signs to Tarren Mill.|Live long enough and Serge teaches poisons. Patience.",
	[2480] = "Serge is amazed by Zanzil's work. Stay busy while he studies.|Serge is still looking. Stay put.|Tarren Mill feels restless. So are you, while Serge works.|Let the poison lab go quiet around you.",
	[2498] = "The timberlings need help. Get to Denalan.|Denalan found the cause. Stand by for the news.|Lake Al'Ameth needs you. Get going.|The lake is quiet. Soak it in.",
	[2499] = "Oakenscowl spreads rot through the lake. Chop him down.|Oakenscowl's cave is dark. Stand ready at the mouth.|Along the south bank to the cave. Hunt him down.|Lake Al'Ameth will be clean again. Picture it.",
	[2518] = "Lady Sathrah went mad. End her suffering.|Sathrah spins in the moonlight. Wait for her to drop.|North to Wellspring Lake, where Sathrah lurks.|Once pure, now lost. Think of Sathrah as she was.",
	[2519] = "A great creature needs help. Get ready.|Stand before Priestess A'moora and listen.|Southeast to the Temple of the Moon.|The temple is calm. Let it fill you.",
	[2520] = "Sathrah's spinnerets go to the fountain. Honor her.|By the temple fountain, wait while the waters work.|Through the temple to the central fountain.|Lay the great spider to rest. Quiet as moonlight.",
	[2541] = "Gnarlpine shaman carry the charm. Take one.|Oben is trapped in the Emerald Dream. Hold on for him.|Through the Barrow Den, shaman by shaman.|A spirit torn from its home. Picture Oben at peace.",
	[2561] = "Oben asks the hard thing. Face his soulless form.|The deepest part of the Barrow Den. Stand your ground.|Down, down into the Barrow Den to find Oben's form.|Use the charm. Set Oben's spirit free.",
	[2607] = "More news than Mathias expected. Nice work, now more.|Down in the Barracks cellar, Doc Mixilpixil keeps you waiting.|Down the stairs to the cellar. Doc is in.|A strange turn of events. Take a breath before the cellar.",
	[2608] = "Doc cracks jokes. Noarm writes them down. You get to work.|Doc Mixilpixil needs you still. Don't flinch at his jokes.|You look worse than death, Doc says. Prove him wrong.|Settle in while Doc gets his tools ready.",
	[2609] = "Wildflowers, a vial, a tube and thread. Doc wants them all.|Try not to touch anyone. Keep to yourself.|Along the canals to The Finest Thread. Hurry along.|Doc says you need a shower. Take a fresh breath first.",
	[2745] = "Lescovar and Marzon must be dealt with. Prepare.|Tyrion has watched Lescovar for weeks. Watch with him.|To the castle, fast. Tyrion is waiting.|Justice that's not quite legal. Think it through.",
	[2746] = "Three silk, two apples. Tyrion's plan needs them.|Spybot's disguise is almost ready. Wait on Tyrion.|Out to Clara's farm for apples, then back to the city.|Pick the perfect apple. Take your time.",
	[2842] = "The Transpolyporter 6000 needs brave riders. Warm up.|Scooty's roost is busy. Be patient by the pad.|Boat to Booty Bay, then find Scooty. Or run through Dun Morogh.|Fastest way to Gnomeregan, they say. Trust it, calmly.",
	[2843] = "Scooty needs your size and weight. Give him a good reading.|On the pad now. Scooty is still tuning it.|The pad hums and sparks. Don't stop till it's set.|Side effects are not forever. Mostly. Relax.",
	[2904] = "Dark iron dwarves beat Kernobee. Troggs are next.|Guard Kernobee while he finds his feet.|Lead Kernobee to the Clockwerk Run exit. Go!|Kernobee groans awake. Wake up slowly with him.",
	[2922] = "Techbot went bad. Bring its brain home.|Techbot roams in a frenzy. Let it pass, then act.|Grab the core and dash back to Tinkmaster.|Good brain, bad brain. Find the calm in the middle.",
	[2923] = "Techbot broke down. Overspark needs a helper who can do the reps.|Tinker Town is loud. Stay put while Overspark rants about Techbot.|Ironforge is big. Find Tinker Town before Overspark gives up.|Poor Techbot. Take a calm breath for the little bot.",
	[2926] = "Irradiated troggs, one after another. Fill that phial with reps.|Hold the phial steady. The green glow drips in slowly.|Troggs swarm the tunnels of Gnomeregan. Stay on their heels.|Ozzie waits in Kharanos. Calm hands carry a glowing phial.",
	[2927] = "Gnoarn lost his gnomefro to the leak. Do your reps for his hair.|Gnoarn is mad at the troggs. Hold on, and let him vent.|Kharanos is a trek away. Off to find Ozzie Togglevolt.|A city lost, a gnomefro gone. Let the sad news settle.",
	[2928] = "Twenty-four robot guts for Shoni. Pull them loose with your reps.|Bots roam like cattle. Keep your ground and let them come.|The bots run free. Chase them down.|Shoni's drills sit in parts. Rest, then count the guts.",
	[2962] = "Slimes, lurkers and horrors. Squeeze out the green glow in reps.|The fallout wants to fall apart. Keep the heavy phial still.|The glow fades fast. Get it back to Ozzie in time.|It may take a few tries. Calm hands fill the phial.",
	[2983] = "Fire is yours, if you pay for it. Pay in reps.|Real power waits north of the Crossroads. Stay put and earn it.|Head north past the Crossroads. Stop before the elf lands.|Fire starts as a small spark. Let yours glow quietly.",
	[2984] = "Destruction and chaos are lessons too. Start with these reps.|Kranal Fiss tests your patience first. Show him how much you have.|The Barrens are wide and dry. On to Kranal Fiss and his hut.|Before chaos, a quiet mind. Fire listens to those.",
	[2985] = "Water wears down stone, wave after wave. Rep like the tide.|Islen sits at her fishing hut. Be as still as a calm pond.|South of Ratchet, along the coast. Islen is that way.|Water is pure and patient. Let your breath flow like it.",
	[2986] = "Long since your last test. These reps say you are ready.|The Southfury rolls past. Be a rock in the river.|Down the eastern coast of the Barrens you go.|Pure water begins with a clear head. Find it now.",
	[2997] = "Tiza Battleforge trains young paladins. Show her some reps.|The Light asks a lot of ya. Hold, and show her you know it.|Up from Dun Morogh to Ironforge. The Mystic Ward calls.|The Hall of Mysteries is quiet. Match its calm.",
	[2998] = "Duthorian Rall says kind things about you. Earn them, rep after rep.|A test is coming. Stand tall in the Cathedral of Light.|The road to Stormwind is long. Rall has news.|Light fills the cathedral. Let it fill you, bit by bit.",
	[2999] = "Tiza is just upstairs. Earn the climb with your reps.|Wait by the stairs. Tiza will call you when she is ready.|Up the stairs to Tiza Battleforge. No dawdling.|Learn what the Light expects. It starts with a clear mind.",
	[3000] = "Home to Ironforge. Tiza wants to see what Azeroth made of you.|Dwarven paladins are like mountains. Be one for Tiza.|Back across Azeroth to Ironforge. Home is calling.|The Mystic Ward hums with old secrets. Listen close.",
	[3065] = "Frang trains warriors in the shade. Show him your reps.|A warrior's first test: be firm while Frang sizes you up.|Out of the Den and over to Frang. Go, go.|Frang's tablet is plain. Let its words sink in.",
	[3082] = "Jen'shan wants hunters with strong arms. Reps for the bow.|A hunter waits for the beast to step close. Not yet.|Jen'shan is not far. Track her down.|Hunters hear the wind first. Listen to it now.",
	[3083] = "Rwag's code is tricky. Your reps buy time to crack it.|Stay in the shadows until Rwag spots you. Not a twitch.|Cross the Valley of Trials to Rwag. Quick feet.|Secret words need a quiet mind. Clear yours.",
	[3084] = "Shikrik calls. The spirits like a shaman with grit. Reps!|Feel the earth under you. Be as firm as it is.|The spirits stir. Hurry to Shikrik.|Earth, fire, water, air. Let each one pass through you.",
	[3085] = "Ken'jai sits outside the Den. Faith takes work. Do your reps.|In the Light with Ken'jai, let it settle on you.|A tablet from Ken'jai! Off you go to the Den.|A priest starts with a quiet prayer. Say yours now.",
	[3086] = "Mai'ah's glyphs hum with power. Put some into your reps.|Magic needs focus. Keep it fixed on the glyphs.|Near the Den's door, Mai'ah waits. Get over there.|Slowly now. Let the glyphs of Mai'ah find you.",
	[3087] = "The parchment says Jen'shan has work. Reps get you ready.|Wait in the brush like a hunter. The prey is close.|Track Jen'shan through the valley. She won't wait all day.|A hunter reads tracks with care. Read her note that way.",
	[3088] = "Rwag's note is coded. Rogues do their reps where no one sees.|A rogue waits in the dark. Wait there too.|Dart from shadow to shadow until you reach Rwag.|Crack the code with care. A rushed rogue gets caught.",
	[3089] = "The runes carry Shikrik's call. Your reps are the answer.|Be like the stone in the runes. Firm and slow to move.|Carry the note to Shikrik, fast as the wind.|Let the runes speak. Breathe in their old words.",
	[3090] = "Nartok is your new trainer. Dark powers want hard work.|Few trust a warlock. Stand tall and let them stare.|Down into the Den to find Nartok. Mind the shadows.|Dark magic needs a steady mind. Settle yours first.",
	[3091] = "Harutt Thunderhorn wants warriors, not talkers. Get to your reps.|A tauren on the plains does not budge. Nor do you.|Don't take long! Harutt's note sounds urgent.|The wind crosses Camp Narache. Let it cool you as you read.",
	[3092] = "Lanka Farshot aims far. Build arms to match her.|Picture the bow drawn tight. Keep your aim, like Lanka does.|The messenger was in a hurry. Be quick to Lanka.|Red Cloud Mesa stretches wide. Take in the whole view.",
	[3093] = "Meela Dawnstrider calls. The Earth Mother likes strong hands.|Root yourself like the grass of Camp Narache. Meela sees you.|Meela's message came fast. Answer it faster.|Dawn rises over the camp. Greet it with a calm breath.",
	[3094] = "Gart Mistrunner teaches the ways of nature. Nature is not lazy.|Be a tree and let Gart's lesson grow.|Gart's note is green and fresh. Get to him while it is.|Druids listen to leaves. Hear them rustle as you read.",
	[3095] = "Dannal Stern sealed this scroll. A warrior replies in reps.|The Scourge are mindless. You are not. Guard your spot.|Past the graves of Deathknell to Dannal. Hurry now.|Take a quiet moment with the scroll before heading out.",
	[3096] = "David Trias trusts the silent and the strong. Show him both.|Blend into the dark of Deathknell. Wait for your chance.|Slip past the Scourge and find David Trias.|Read the seal. Read the code. Take your time.",
	[3097] = "Dark Cleric Duesten wants a priest with backbone. Earn it.|Be like the church's old stone walls. Unmoved.|To the church in Deathknell! Duesten wants you.|Duesten's scroll bears a dark seal. Open it in quiet.",
	[3098] = "Isabella's magic is sharp. Sharpen yours with reps.|Keep your mind on the glyphs. Don't let it drift.|Isabella wants you at the church. Go now.|Magic follows a calm mind. Let the glyphs guide yours.",
	[3099] = "Maximillion's seal is on it. Demons respect the strong.|The dark powers test those who waver. Don't.|Leave the mindless Scourge behind. Maximillion awaits.|Before dark magic, a still mind. Look the scroll over slowly.",
	[3100] = "Back from the kobold camps? Llane wants more reps from you.|Guard the Abbey gate. Llane is watching.|Across Northshire to Llane Beshere. No other business first.|The Abbey bells ring soft. Take in Llane's letter in peace.",
	[3101] = "Brother Sammuel sealed this in Light. Reply in reps.|A paladin never wavers. Show Brother Sammuel you can't either.|Sammuel is in the Abbey. Don't keep him waiting.|Let the Light fill the Abbey hall and your chest.",
	[3102] = "Jorik hides in the stable. Rogues train where no one looks.|Wait in the hay like Jorik. No one knows you are there.|Behind the Abbey to the stable. Keep to the back paths.|The stable smells of hay and horse. Take it in and relax.",
	[3103] = "Priestess Anetta has a lesson. Show her your will in reps.|Anetta prays for Northshire. Keep watch while she does.|Anetta's letter came first. Kobolds can wait.|The Abbey is a place of peace. Let it be yours for now.",
	[3104] = "Khelden Bremen needs mages with spark. Make some with reps.|Focus like a mage on a spell. Khelden will notice.|Inside Northshire Abbey, Khelden waits. Make haste.|Arcane words need a clear head. Clear yours before Khelden.",
	[3105] = "Drusilla La Salle is by the Abbey. Dark work is hard work.|The Abbey folk stare at warlocks. Stand tall anyway.|Out beside the Abbey you go, to Drusilla.|Drusilla wants a calm warlock. Look her letter over slowly.",
	[3106] = "Thran Khorman wants warriors built like Anvilmar's stone.|Coldridge Valley is cold. Be firm in the snow.|Up to Anvilmar to find Thran. Take a gander on the way.|Snow falls soft on Coldridge. Study the rune in its hush.",
	[3107] = "Bromos Grummner likes a paladin with muscle. Reps, lad.|Light and stone. Be both for Bromos.|Inside Anvilmar, Bromos waits. Off with ya.|The rune glows with Light. Let it warm you in the cold.",
	[3108] = "Thorgas Grimson hunts in the snow. Earn his nod in reps.|Wait like a hunter on the snow. Thorgas taught you well.|Thorgas is in Anvilmar. Follow the tracks home.|Hunters study the snow with care. Study the rune that way.",
	[3109] = "Solm Hargrin trains quiet dwarves. Quiet, but strong. Reps.|Keep to Anvilmar's shadows until Solm finds you.|Solm's rune is a riddle. Get it to him quick.|Coded runes need patience. Give them yours.",
	[3110] = "Branstock Khalder's faith is strong. Match it in reps.|Branstock prays in Anvilmar. Be his quiet guard.|Branstock is inside Anvilmar. Hurry out of the cold.|Warm prayers in a cold valley. Say yours quietly.",
	[3112] = "A memo from Thran: less talk, more reps.|Thran likes warriors who stay put. Be that warrior.|Snowy paths lead to Anvilmar and Thran.|Warriors think before they swing. Look over Thran's memo.",
	[3113] = "Solm's memo is in code. Crack it during your reps.|Hide by the door of Anvilmar. Solm likes a surprise.|Coldridge is small. Solm won't wait long, so hurry.|Decode the memo quietly. Nobody else should see it.",
	[3114] = "Marryk Nurribit has spells to teach. Warm up with reps.|A mage keeps focus. Keep yours on Marryk's glyphs.|Marryk is in Anvilmar, above the valley. Go.|The glyphs twist and swirl. Follow them with your mind.",
	[3115] = "Alamar Grimm has work for you. Warlocks aren't trusted, so prove it.|Watch yerself. Be calm while the dwarves stare.|Past wary dwarves to Alamar Grimm. Don't dawdle.|Your kind ain't trusted here. Keep a cool head.",
	[3116] = "Alyissia trains the warriors of Shadowglen. Reps are her lesson.|Shadowglen's great trees never bend. Match them.|Alyissia has words for you. Across the glen you go.|Moonlight in Shadowglen. Look at the sigil in its glow.",
	[3117] = "Ayanna is atop Aldrassil. Reps for the long way up.|Halfway up Aldrassil, don't look down. Hang on.|Round and round the great tree to Ayanna at the top.|From the top of Aldrassil, all of Shadowglen is calm.",
	[3118] = "Frahun Shadewhisper wants rogues with quick hands. Show them.|Frahun whispers from the shade. Wait there until he does.|Find Frahun before anyone sees the sigil.|A shadow makes no sound. Neither should your breath.",
	[3119] = "Shanda sent a sigil. Answer her call with a strong set of reps.|Read the sigil. Stay where you are until the words sink in.|Aldrassil's ramps wind high. Up you go to find Shanda.|Shanda teaches the Light. Start with a quiet mind.",
	[3120] = "Mardant Strongoak wants a word. Bring him some reps first.|Stand like the tree Aldrassil. Roots down, hold firm.|Shadowglen is waiting. Off to Mardant before the leaves turn.|A druid listens to the wind. Let the Verdant Sigil set your pace.",
	[3221] = "Renferrel asked about wolf hearts. Your reps say you have one.|The Sepulcher is cold and quiet. Stay there with it.|A summons from the apothecary. Along the Silverpine path you go.|Deathstalkers move soft among the pines. Walk with them.",
	[3241] = "Totems on Dreadmist Peak. Grab one per rep for Tonga.|Dreadmist is icky. Hold your nose and your ground.|Up Dreadmist Peak and back with shiny clean totems.|Tonga Runetotem likes things tidy. Tidy your breath too.",
	[3261] = "Jorn Skyseer will guide you next. Show him what you've got.|Camp Taurajo's guards stand tall in the heat. Do the same.|South across the Barrens to Camp Taurajo. A long road.|A seer reads the sky. Look up and take it in.",
	[3281] = "The raptors hid the silver. Dig through their nests, rep after rep.|A raptor sniffs nearby. Hold your spot in the grass until it goes.|The Raptor Grounds go on and on. Don't stop until the silver shines.|Gazrog wants his silver back. Go calm and quiet among the nests.",
	[3301] = "Barrens shells for Mura. Pack them tight and set off.|Keep the shell sample safe. Silverpine is a long way off.|From the Barrens to the Sepulcher. Mura needs that shell.|Mura hopes to bring new life to Silverpine. Give it a calm start.",
	[3361] = "Box, chest, bucket of bolts. Felix wants them all back.|Troll camp ahead. Wait in the snow until the guard turns.|Southwest of Anvilmar and back, arms full of Felix's things.|Felix lost it all to the trolls. Stay calm for him.",
	[3364] = "Hot mornbrew, cold valley. Pump out reps before it cools.|Hold the mug level. Spill it and Nori will hear of it.|The brew is cooling! Race to Anvilmar, northeast, go!|Steam curls off the mornbrew. Breathe it in, then dash.",
	[3365] = "The mug is empty now. Your reps are not.|Durnan is warm to the soul. Stay put and enjoy it.|Back to Nori Pridedrift with the mug, no dawdling.|Brew gone, mug in hand. A slow walk home through the snow.",
	[3366] = "The Nightmare Shard pulses green. Match it with your reps.|Smoke swirls in the shard. Stare back and do not blink.|Get the shard to Ratchet quickly. Its smoke is stirring.|Something dark stirs in the crystal. Stay calm as you look.",
	[3369] = "Strong reps for a heavy shard. Hamuul must see it.|Grip the shard tight. Its nightmare wants out.|Thunder Bluff is far. Get the shard there fast.|Druids walk the Emerald Dream. Clear your mind like one.",
	[3370] = "Mathrengyl Bearwalker must see this shard. Make the trip count.|The nightmare flickers green. Keep your hand steady.|Boat, then road, then Darnassus. The shard must go now.|Under the great tree, the Cenarion Circle breathes easy. Join them.",
	[3376] = "Chief Sharptusk leads the Bristlebacks. Break him.|Brambleblade Ravine bristles with quilboar. Stand your ground.|East into the ravine. The chief's village waits.|Brave Windfeather trusts you. Face the chief with a clear head.",
	[3513] = "A dryad's scroll, tied in silver. Someone must pay for it.|The northern guard tower keeps watch. Keep watch with it.|North to the Ashenvale border, scroll tucked tight.|The silvery ribbon stays tied. Your thoughts can loosen.",
	[3514] = "Rynthariel the Keymaster falls, then the Horde flag goes up.|Plant the flag in the Talon Den. Keep it standing.|Stonetalon Peak is steep. No messenger escapes you.|The dryad schemes. Out-think her before the fight.",
	[3519] = "Iverron is dizzy with poison. Put your reps to his rescue.|Githyiss the Vile bit him. Stay steady while he talks.|Hurry to Dirania Silvershine! Iverron cannot wait.|Iverron's world spins. Keep yours level.",
	[3521] = "Seven mushrooms, four lilies, one ichor. Count them off.|Moonpetal lilies grow by the pools. Crouch low and wait.|Grell, pools, spider cave. Round Shadowglen in a hurry.|Lilies float on still water. Let your breath do the same.",
	[3522] = "Dirania made the antidote. Now it's your turn to work.|The vial must not spill. Steady hands, steady feet.|The antidote won't last! To the cave, fast!|Iverron drinks, and color returns. Share his relief.",
	[3524] = "Greymist murlocs ring the bones. Push through them.|The beached giant lies still. Wait for the murlocs to look away.|Down the sand past Auberdine. The bones won't fetch themselves.|Waves roll up the Darkshore beach. Breathe in time with them.",
	[3681] = "Duthorian Rall trains paladins. Show up ready.|The Cathedral of Light is grand. Stand tall in it.|Stormwind calls its paladins. Take the road now.|The Tomes need study. Quiet the mind before you read.",
	[3741] = "Mean things lurk in the lake. You are not scared.|On the lakebed, stay low and look for a glint.|Paddle hard across Lakeshire's lake. Hilary is waiting.|Fill your lungs, slip under, and search the weeds.",
	[3765] = "Gershala needs a seasoned hand. Prove you are one.|The Stormwind docks are busy. Wait there for your ship.|A long and epic road to Auberdine. Start it now.|Seaside Auberdine is calm. Carry some of that calm there.",
	[3901] = "Twelve Rattlecage Skeletons. Rattle them apart one by one.|Sarvis wants you under pressure. Stay there and take it.|Deathknell's bones clatter all around. Chase them down.|The Forsaken are watching. Show them a clear mind.",
	[3902] = "Six Scavenged Goods from stacks of boxes. Get to work, bag of bones!|The boxes are stacked high. Brace them so they don't tip.|Search Deathknell top to bottom. Hustle, recruit.|New recruits are rising. Rise slow with them.",
	[3903] = "Dirty hands are good hands. Milly needs yours.|Milly's wagon sits by the stable. Stand by it a while.|Around the abbey to the stable. Milly is in trouble.|The abbey bells ring soft. Let them set your mood.",
	[3904] = "Eight crates of grapes. Haul them out of the vineyard.|A crate in your arms, Defias nearby. Keep it level.|In and out of the vineyards before the guards trample it all.|Grapes on the vine, sun on the leaves. Take your time.",
	[3905] = "Brother Neals likes his wine. Earn a taste.|The bell tower sways a little. Stay steady at the top.|Bell tower stairs, round and round, manifest in hand.|Fresh grapes for Northshire. Brother Neals will be glad.",
	[3911] = "Ten Essence of the Elements. Pry each from a golem.|Dark Iron golems march past. Wait in the shadows.|Turn Blackrock Depths upside down. Search it all.|Deep under the mountain, the forges hum. Find your calm there.",
	[3921] = "A broken samophlange. Muscle it up to Wenikee.|Undermine is curious. Keep the samophlange in one piece.|Past Mor'shan Rampart, samophlange in tow.|Wenikee is clever and curious. Be curious too.",
	[3922] = "Fifteen Nugget Slugs from the tool buckets. Scoop them up.|Venture Co. guards stand by the Sludge Fen. Wait them out.|Bucket to bucket through the Sludge Fen.|Wenikee needs the right slugs. Look close and pick with care.",
	[3923] = "Its gauges read an all-time low. Yours should not.|The Broken and Battered Samophlange rattles. Keep it steady.|Off to Orgrimmar and Nogg's Machine Shop.|More dials would make it worse. Less is more. Let go a little.",
	[3924] = "Boss Copperplug hoards the manual. Take it, page by page.|Boulder Lode Mine is dark. Wait for Copperplug to show.|Chase down every page holder in the mine.|Rilli wasn't trusted. You will read what he never could.",
	[4021] = "Kolkar come from the west. Cut them down until Krom'zar shows.|Hold the bunkers. Krom'zar's banner is coming.|Wave after wave of Kolkar. Don't let up.|Regthar is counting on you. Face the warlord calm.",
	[4161] = "Small spider legs, seven only. No more, no less.|The kaldorei take only what they need. Wait for the right one.|Spiders scuttle through the woods. After them.|Children of the stars live in balance. Find yours.",
	[4402] = "Cactus Apples, ten of them. Mind the spines.|The Valley of Trials bakes. Stand in the heat and bear it.|Cactus to cactus across the hot valley.|Galgar wipes his brow. You wipe yours and breathe.",
	[4495] = "Iverron is hours late. Spiders are not. Be ready.|By the cave, peer into the dark. Wait for a sign of him.|Race to the spider cave up north. Find Iverron!|A friend is worried. Stay calm and look around.",
	[4541] = "No task written yet. Do your reps anyway, hero.|Nothing here but quiet. Keep your place in it.|An empty page, an open road. Off you go.|No orders. Just you and a calm moment.",
	[4641] = "Kaltunk laughs at dragon stranglers. Start small.|You are of age for the Horde. Stand proud.|West to the Den. Gornek has work for you.|Glory for the Warchief can wait. First, find your feet.",
	[4681] = "The Skeletal Sea Turtle lies near a sunken ship. Dive and grab.|Underwater, stay low by the wreck and look.|Swim hard west of Auberdine to the turtle.|Drift down past the sunken ship. Easy, no rush.",
	[4722] = "Murlocs picked at the turtle. Grab what's left and go.|Murlocs camp by the shell. Sit tight until they wander.|Turtle sample in hand, back up the beach to Auberdine.|An old turtle rests on the sand. Rest beside it for a breath.",
	[4723] = "A giant thresher on Mist's Edge. Its bones are heavy.|How did murlocs bring down this beast? Stay and wonder.|Mist's Edge to Auberdine, bones rattling in your pack.|Fog rolls in off the Mist's Edge. Move soft as it does.",
	[4725] = "A carriage strapped to a turtle shell. Pry the box loose.|Strange marks on the box. Study them without a twitch.|Unknown beings drove this turtle ashore. Hurry to Gwennyth.|Trace the strange marks with your eyes. Slow and easy.",
	[4727] = "Even the Greymist murlocs shy from this turtle. Not you.|Something scares the murlocs here. Stay put and find out.|Northern beaches to Auberdine with a Temple sample.|The northern sand is empty and quiet. Enjoy it.",
	[4728] = "Someone left a wheelbarrow here. Put it to use.|Kneel by the giant with the old tools and work with care.|Beach to Auberdine with the bones. Pick up the pace.|Someone studied this beast before you. Think of their quiet work.",
	[4730] = "These murlocs outclass Auberdine's. Meet them rep for rep.|A strong murloc band guards the bones. Wait for your chance.|Half a sea giant, a band of murlocs, and a long run back.|The sea gives, the sea takes. Watch the tide roll.",
	[4731] = "Powerful Greymist murlocs crowd the carriage. Force your way in.|The carriage leans off the shell. Brace it while you search.|Grab the Strangely Marked Box and dash for Auberdine.|Who drove this turtle ashore? Ponder it in the quiet.",
	[4732] = "The turtle is picked nearly clean. Scrape what's left.|Greymist murlocs lurk. Freeze until they turn their backs.|Along the Darkshore coast and back, sample in hand.|Gwennyth will study it well. Settle yourself for the walk.",
	[4733] = "A thresher several times too large. Heave its bones free.|The rocky inlet is slick. Plant your feet and stay.|Twilight Shore to Auberdine. Mind the rocks.|Twilight on the shore. Let the day wind down in you.",
	[4740] = "Murkdeep sank two ships. Sink him instead.|Guard the huts, does he? Stand firm against him.|Splash through to the murloc huts. Murkdeep is there.|Glynda Nal'Shea lost a Sentinel. Face Murkdeep with a cool head.",
	[4761] = "Thundris wants the furbolg news. Bring it with a strong set of reps.|The elder of Auberdine is thinking. Hold on while he does.|Auberdine is small. Get to Thundris before the news goes stale.|Share what you saw at the furbolg camp. Slowly, like an elder.",
	[4762] = "The Cliffspring runs foul. Your reps carry the tube up the river.|Keep the sample tube level under the bridge. Hold it right there.|North along the Cliffspring, past the bridge, to the pool. Go.|Water falls, the pool settles. Let the sample fill in its own time.",
	[4763] = "Fruit, nut, grain, moonwell water. Then the satyr gets your reps.|Set the bowl by the bonfire and wait for the satyr to show.|Moonwell to camp to bonfire. The satyr corruptor won't wait.|The furbolgs eat and turn calm again. Find that calm too.",
	[4811] = "Moonkin gather at the red crystal. Glynda wants reps, not rumors.|Stand at the foot of the eastern mountains. Hold and look for red.|East of Auberdine the moonkin roam. Cover ground, find the crystal.|Look up at the mountain wall. Calm eyes spot a red glow.",
	[4812] = "Fill the tube at the moonwell. Your reps get it to the crystal.|Pour it over the red crystal, then hold. Felwood is watching.|Moonwell, then east again to the crystal. Glynda said be careful.|Moonwater runs down the crystal. Let it flow, and flow with it.",
	[4813] = "Bone in the crystal, and a jawbone. Tell Glynda after your reps.|Not even strong magic can break that crystal. Be as solid as it.|Back to Auberdine with strange news. Glynda will want it fast.|The crystal kept its secret. Keep your mind calm on the way home.",
	[4905] = "Centaur assassins close in on Kanati. Your reps stand in the way.|Hold your ground by Kanati Greycloud. The centaurs come to you.|Circle Kanati and watch for centaur blades. No rest.|Assassins move quietly. Listen closer than they do.",
	[4921] = "Mankrik's wife held off three Bristlebacks. Match her with reps.|Mankrik waits in the Crossroads. Hold on as long as he has.|Search the Barrens off the Gold Road. She is out there somewhere.|Mankrik is full of rage. Be the calm one on this search.",
	[5041] = "Razormane camps hide Crossroads crates. Your reps haul them home.|A supply crate is heavy. Hold it up and don't drop the goods.|Camp to camp through Razormane land. Thork needs those crates.|The quilboar grew fat on stolen supplies. Stay light and loose.",
	[5052] = "Mangletooth wants blood shards. Reps win Agamaggan's gift.|Quilboar grip those shards as totems. Grip your hold tighter.|More shards, more blessings. Keep hunting the Bristlebacks.|Mangletooth snorts and waits. Let the magic of Agamaggan settle.",
	[5061] = "The Pendant of the Sea Lion is yours. Show Mathrengyl your reps.|A sea lion rests on the rocks. Hold like one before Darnassus.|Mathrengyl waits in Darnassus. Take the pendant home.|Become one with the water. Let the stretch roll like a wave.",
	[5101] = "Six sheep. Benny said ten. Do the reps and don't argue.|Stand firm. The sheep look harmless, but Benny insists.|Benny joked about running. The joke's on you. Go.|Even a test quest needs a calm hunter. The sheep suspect nothing.",
	[5261] = "Wolves crowd Northshire. Eagan needs a hunter who can do reps.|Eagan is round the side of the abbey. Wait for his word.|To the left of the abbey, quick. The wolves are not waiting.|Northshire is green and quiet, wolves aside. Take it in.",
	[5321] = "Kerlonian keeps nodding off. Your reps keep the road safe.|He's asleep again. Hold your spot and reach for the horn.|South along the road to Maestra's Post. Kerlonian drifts along.|Kerlonian yawns again. Stay calm, and don't nod off too.",
	[5441] = "Five peons snore. Your reps wake them up one by one.|Creep up on a napping peon. Hold... then the blackjack.|Thazz'ril wants work done. Out-work the peons in the valley.|The peons nap by the trees. Loosen up like one, but stay awake.",
	[5481] = "Gordo has big hands. You have reps. Three gloom weeds, please.|Gloom weed grows by the road. Stay low and pick it clean.|Weeds by the road, then Brill graveyard. Master Holland waits.|Gordo not good at picking. Show him slow, careful hands.",
	[5482] = "Ten doom weeds by the mass grave. Pull them with your reps.|Gnolls roam near the gravesite. Hold low and let them pass.|North of Brill to the grave field. Hurry, as Holland said.|Gordo picked the wrong weeds. Take care and pick the right ones.",
	[5541] = "Wendigo scared off the courier. Your reps bring the ammo home.|An ammo crate is no light thing. Hold it up for Rumbleshot.|Past the Grizzled Den, then down the road to Anvilmar. Go.|Rumbleshot's riflemen steady their aim. Steady yours.",
	[5545] = "Eight bundles of wood for Raelen. Lift your reps like timber.|Wolves and bears lurk. Hold the bundle and stay out of sight.|Raelen has a deadline. Get the wood to Eastvale fast.|The wood is cut. Breathe in the smell of Eastvale pine.",
	[5621] = "Shaya waits south of Dolanaar. Your reps bring Elune's grace.|Keep close to Shaya while your spells take hold. Then Fortitude.|South of Dolanaar, find Shaya, then return to Laurna. Go.|Elune's gift passes through calm hands. Keep yours calm.",
	[5622] = "Laurna Morninglight has robes for you. Your reps help earn them.|Finish your work in Shadowglen first. Hold on a little longer.|From Shadowglen down the road to Dolanaar. Laurna waits.|The ways of Elune start with quiet. Start there.",
	[5623] = "Priestess Josetta has lessons waiting. Your reps are lesson one.|Wrap up your Northshire tasks. Hold, then head for Goldshire.|Down the road from Northshire to Goldshire and Josetta.|The Light teaches patience before it teaches spells.",
	[5624] = "Guard Roberts is down by the lake. Your reps bring the Light.|Roberts waits by the lake. Stay beside him while the Light works.|East of Goldshire to the lake, then over to Josetta.|First robes are near. Let the Light settle before you cast.",
	[5625] = "Mountaineer Dolf is south of Kharanos. Maxan wants reps and results.|Snow and cold. Stay firm beside Dolf while the spell lands.|Out of Kharanos, south through the snow. Find Dolf.|Maxan skipped the test. Show him a calm priest anyway.",
	[5626] = "Maxan Anvol has your first robes. Bring your reps to Kharanos.|Finish up here first. Hold tight, then the tunnel.|Through the tunnel to Kharanos. Maxan Anvol is expecting you.|The path of the Light is long. Take a slow look down it.",
	[5627] = "The Stars of Elune shine for priests. Shine with your reps.|Stars stay in their place all night. Stay in yours.|Stars wheel across Teldrassil's sky. Move with them.|Look up at the stars of Elune and let the night settle.",
	[5628] = "You traveled far so young. Alathea will want to see that grit.|Don't dally too long. But hold here first, then Darnassus.|The Temple of the Moon calls, and it sounded urgent.|A long way from home. Picture the temple and its quiet halls.",
	[5629] = "The elders think you're ready. Show them with your reps.|Take some time for yourself, the elders said. Hold that thought.|Darnassus calls. Alathea at the Temple of the Moon awaits.|May Elune be with you. Let her light settle over you.",
	[5630] = "Made of tougher stuff, the dwarf said. Rep like you believe it.|This cold land won't move you. Hold against the chill.|Leave the snow behind and head for Darnassus.|Think of home, warm and green, and Alathea's temple.",
	[5631] = "A priestess searched far for you. Your reps are the reply.|The Light be with you. Hold it close on the road to Darnassus.|Seek out Priestess Alathea. The road home is long.|The halls are quiet here. Carry that quiet home.",
	[5633] = "A blessing on you and your kind. Pay it back with reps.|It did sound important. Stay put until you learn more.|From these great halls to the Temple of the Moon.|Alathea waits in the temple. Arrive with a clear mind.",
	[5634] = "High Priest Rohan asked for you. Reps first, then Ironforge.|The Hall of Mysteries is deep in stone. Be as firm as it.|Ironforge, as soon as you can. The priest was clear.|Rohan will tell you more. Go to him with open ears.",
	[5635] = "Your leaders are watching. Give them reps worth watching.|You have proven yourself. Now stay firm a bit longer.|Off to the Hall of Mysteries. Rohan has more to teach.|Good luck, and may the Light be with you. Let it in.",
	[5636] = "Elune blesses you, and the Light guides you. Reps do the rest.|Your people need you. Hold steady, then go to Rohan.|Don't linger here. The Hall of Mysteries is calling.|Such notice is a good sign. Breathe it in and move on.",
	[5637] = "Really good or really bad? Rohan wants you. Bring reps.|The High Priest asked for you himself. Stand tall until you go.|Don't waste time around here. Rohan wants you now.|Probably good news. Let the worry drain out on the way.",
	[5639] = "A desperate prayer needs a firm answer. Reps give it.|Prayer asks you to stay put. So stay put.|A prayer answered in a hurry. Get going.|Say a quiet prayer and let the Light fill the room.",
	[5640] = "Faith in Elune, faith in the Light. Both count your reps.|Finish your business in Darnassus. Hold here until it's done.|From Darnassus all the way to Rohan in Stormwind.|Praise be to Elune and your Light. Let both settle in you.",
	[5641] = "Chastise is a stern lesson. Answer it with stern reps.|A priest of the Light takes a scolding without a flinch.|Chastise the wicked, then keep after them.|Even a stern priest needs a gentle pause.",
	[5642] = "Messengers rushed through for troll priests. Rush your reps too.|Don't dally in Thunder Bluff. Hold here, then head home.|Orgrimmar's Valley of Spirits, fast as you can.|Ur'kyo waits in the Valley of Spirits. Arrive with a clear head.",
	[5643] = "Your tribe's rites of passage start now. Meet them with reps.|The time is upon you. Stand firm as a totem.|Return to Orgrimmar and find Ur'kyo. No stopping.|What Ur'kyo teaches may matter later. Make room for it.",
	[5644] = "Aelthalyste knows things only she can teach. Reps first.|No spoilers from the old priest. Hold on and find out.|Down to the War Quarter of the Undercity.|True power, the old priest says. Let it sink in slowly.",
	[5645] = "Make haste, strong friend. Rohan counts on those reps.|Your next test comes fast. Brace for it.|To Ironforge and the Mystic Ward, where Rohan stands.|May the Light go with you. Let it walk beside you.",
	[5646] = "Aelthalyste sends her people to learn. Your reps are the lesson.|She be ready to teach you. Hold until you be ready too.|Return to the Undercity, mon. Do not wait long.|Learn the ways of your people. Start with a slow breath.",
	[5647] = "Your race is strong, the elf says. Rohan wants to see it.|Don't keep Rohan waiting. Just hold this first.|Word came from Ironforge. Head for the Mystic Ward.|As the sun sets, feel sure you are on the right path.",
	[5648] = "Grunt Kor'ja fought Proudmoore's troops. Honor her with reps.|Kor'ja needs the blessing of the ancestors. Stay by her side.|South of Razor Hill, then over to Tai'jin. Go, mon.|The ancestors listen when you're quiet. Be quiet for them.",
	[5649] = "Tai'jin teaches the old troll ways. Rep for the tribe.|Old ways die hard. Hold to them, in secret if you must.|Off to Razor Hill. Tai'jin knows your history.|Some traditions stay secret. Keep this one calm and low.",
	[5650] = "Deathguard Kel held off the gnolls. Your reps help him stand.|North of the cemetery, Kel waits. Hold your place by him.|Past the cemetery to Kel, then over to Beryl in Brill.|Before the dark, the light. Let both pass through you.",
	[5651] = "The Forsaken learned the hard way. So do your reps.|The Darkness is your home. Settle into it and stay.|To Brill, where Dark Cleric Beryl waits.|Light and dark, used with care. Find the balance between them.",
	[5652] = "A Hex of Weakness for your foes. None for your reps.|The hex drains your foe. You stay firm.|Cast the hex and keep your foe chasing you.|Troll hex magic wants a steady mind. Bring one.",
	[5653] = "Ur'kyo thinks you're ready. Your reps say he's right.|Word came to wait for you. Now you wait a bit longer.|To Orgrimmar and the Valley of Spirits. Find Ur'kyo.|Your culture's old practices call. Answer them slowly.",
	[5654] = "Ur'kyo waits in the Valley of Spirits. Earn your place in the circle.|The circle does not open for the restless. Stand firm for Ur'kyo.|Orgrimmar is a long road. Your feet carry you to Ur'kyo.|Old ways start quiet. Let the Valley of Spirits settle you.",
	[5655] = "A troll came all this way to fetch you. Make the trip worth it.|Stop wandering. Stay put like a priest who listens.|Home is calling, and Ur'kyo does not like to wait.|The greatest of your priests wants a word. Arrive calm.",
	[5656] = "Power that is not arcane. Show the Forsaken what that looks like.|An undying heart points you home. Stand there and take it in.|From here to the Valley of Spirits, no dawdling.|Priests of all cultures wander. This one heads home at ease.",
	[5657] = "Ur'kyo begs you home. Pay him back in reps.|The path you travel pauses here. Hold it before the next step.|The great Horde city is far. Your feet know the way.|Home. Just the word. Let it slow you down.",
	[5658] = "Aelthalyste teaches the Touch. Your reps pay the fee.|A lesson in weakness needs a strong stance. Stay there.|The War Quarter is busy. Don't let the crowd slow you.|The Undercity is dim and cool. Let its hush sink in.",
	[5659] = "Aelthalyste hates excuses. Give her reps instead.|No tardiness allowed. Stand ready at her door.|As soon as possible, she said. Off to the War Quarter.|Before her lesson, gather your power quietly.",
	[5660] = "Things only your mistress can teach. Get ready for them.|The zeppelin sways. Stay steady on the deck.|As fast as a zeppelin can carry you, and then faster.|Far from home and under open sky. Soak it up, then go.",
	[5661] = "Bloodhoof Village is no place for a Forsaken. Work your way out.|The head priestess calls. Stand tall while the word sinks in.|Mulgore to the Undercity. That is a lot of ground.|The troll helps kindly. Take a slow moment to thank him.",
	[5662] = "Abilities that set you apart. Start setting yourself apart.|Lordaeron's old stones never budge. Neither do you.|Back to the city once called Lordaeron, on quick feet.|The troll offers his respect. Take it with an easy breath.",
	[5663] = "The younger of the order train hard. Prove you count among them.|Faithful ones wait without fuss. Be faithful.|Deep in the Undercity, the War Quarter calls. Get down there.|Count yourself among the faithful, and let the dark go quiet.",
	[5672] = "Elune gives gifts to those who work. Put in the work.|Moonlight falls still on the temple. Match it.|Race the moon across Darnassus.|Elune's Grace is soft as moonlight. Move like it.",
	[5673] = "Priestess Alathea will test you. Warm up with reps.|The Temple of the Moon waits in silence. Share it.|Home to Teldrassil, trainer to trainer, no rest.|Elune teaches calm minds. Be still as a pond at night.",
	[5674] = "A wonderful day for training. Alathea wants you ready.|Only night elves learn this. Stand like one of them.|Finish your business here, then off to the temple.|She tests before she teaches. Let your mind go clear.",
	[5675] = "Time's a wastin'. Get those reps done, lass or lad.|Alathea's message says she'll wait. You can wait too.|Head out whenever you can. Now looks good.|Good luck, says the dwarf. Take a moment to gather it.",
	[5676] = "Arcane Feedback bites back. Push harder than it does.|Magic hums in the air. Stay firm while it buzzes.|Stormwind's streets are long. Cover them.|Feedback fades when the mind is quiet. Quiet it.",
	[5677] = "Separate yourself from the rest. Laurena will notice.|The Cathedral of Light has stood for ages. Stand with it.|Back to Stormwind with your own kind. Move it.|No offense meant, says the dwarf. Let it roll off you gently.",
	[5678] = "Your race and mine are allies. Show Laurena what an ally can do.|Distrust runs deep here. Stay put until it passes.|Stormwind calls you back. The road will not walk itself.|Coy words, open road. Let the worry go before Laurena.",
	[5679] = "Dark Sacrifice asks a price. Your reps cover it.|Shadows gather close. Do not budge while they do.|Outrun your own shadow for a while.|Give the dark a slow breath, and take one back.",
	[5680] = "Shadowguard wraps you in darkness. Build it up.|A shield of shadow must not waver. Neither should you.|Shadows swirl around you. Stay ahead of them.|Let the shadows circle slowly, like a calm guard.",
	[5713] = "Marosh and his trackers come. Answer them for Aynasha.|Aynasha needs time for her antidote. Hold your ground.|Furbolgs rush in from all sides. Meet every one.|Aynasha steadies her bow. Steady yourself beside her.",
	[5722] = "Maur Grimtotem never made it out. Search harder than he could.|The Chasm is dark. Wait for your eyes to find the body.|Lava tunnels twist on and on. Keep searching them.|Magatha wants answers. Look slowly, miss nothing.",
	[5723] = "Eight troggs, eight shaman. Magatha wants them gone.|Troggs climb up from below. Block the tunnel.|Ragefire Chasm is hot and long. Charge through it.|Diplomats fell here. Honor them with a quiet moment.",
	[5724] = "The satchel is heavy with secrets. Lug it to Rahauro.|Maur held that satchel tight. Grip it just as hard.|Out of the tunnels, all the way to Thunder Bluff.|The satchel is safe now. Let the Chasm's heat fade.",
	[5725] = "Spells of Shadow and Incantations from the Nether. Take both.|The Searing Blade guards its books. Do not give way.|Grab the books and dash for the Undercity.|The Dark Lady only borrows. Slip away as if nothing happened.",
	[5726] = "Skull Rock is full of Burning Blade. Thrall wants an insignia.|Thrall plays his hand slowly. Stay still and wait for yours.|East of Orgrimmar to Skull Rock. Off you go.|Find the head of the beast. Clear your mind before you look.",
	[5727] = "Neeru thinks you are one of his. Play the part well.|Keep a straight face in the Cleft of Shadow. Do not crack.|The Cleft of Shadow and back to Thrall, nice and quick.|A good spy never looks nervous. Calm face for Neeru.",
	[5728] = "Bazzalan and Jergosh lead the Searing Blade. Not for long.|Neeru must not know it was you. Stay hidden in the dark.|Through Ragefire Chasm to both leaders. No stops.|A satyr and a warlock. Face them with a clear head.",
	[5729] = "Neeru needs new leaders. Look like one.|Do not be too overt. Stand quiet near Neeru.|Back to the Cleft again. You know the way by now.|Earn his trust with patience. Calm and easy.",
	[5730] = "You are one of Neeru's lieutenants now. Thrall must hear it.|Thrall will call on you soon. Be ready when he does.|From Neeru to Thrall, carrying news fast.|The Council schemes elsewhere. Rest your mind before the next plot.",
	[5761] = "Taragaman the Hungerer is huge. Hit back harder.|The Felguard swings. Brace and do not give.|Down into Ragefire to find the Hungerer. Hurry.|His heart goes to Neeru. Keep yours calm for the fight.",
	[5805] = "A gift waits in Northshire. Earn it before Merissa hands it over.|A little companion is coming. Wait for it right there.|Across Northshire Valley to Merissa Stilwell.|Welcome to the world. Look around the abbey slowly.",
	[5841] = "Yori Crackhelm has a gift. Snow does not stop a dwarf.|Coldridge snow piles high. Do not let it tip you.|Trudge through the snow to Yori. It keeps you warm.|Snowflakes drift in Coldridge. Drift with them.",
	[5842] = "Orenthil Whisperwind has a little friend for you. Get to work.|Shadowglen is quiet as a leaf. Be that leaf.|Under the great trees to Orenthil, light on your feet.|Soft wind in Shadowglen. Let it whisper you calm.",
	[5843] = "The Valley of Trials tests all. Pass this one for Magga.|The sun beats down on the valley. Stand in it.|Across the dusty valley to Magga.|A small friend for the long road. Welcome it slowly.",
	[5844] = "Vorn Skyseer holds your gift. Show him tauren grit.|The plains wind blows at Camp Narache. Do not sway.|Over the grass of Camp Narache to Vorn.|Vorn reads the sky. Look up and let it go wide.",
	[5847] = "Freshly risen in Deathknell. Claire has a gift. Earn it.|The graves of Deathknell lie still. So do you.|Claire waits across Deathknell. Rattle on over.|Night falls grey on Deathknell. A calm start to a new life.",
	[5921] = "Staghelm and Remulos argue. You just train.|The teleport pulls at you. Stay firm while the world spins.|Off to Moonglade to find Dendrite Starblaze.|Moonglade offers solace. Take some.",
	[5922] = "Tauren and night elf alike train in Moonglade. Join them.|Remulos keeps watch. Keep watch beside him.|From the landing spot to Nighthaven, no lingering.|Druids rest deep in Moonglade. Sink into that peace.",
	[5923] = "Mathrengyl Bearwalker will train you. Show him you are ready.|Your training begins a new life. Wait at the starting line.|Up through Darnassus to the Cenarion Enclave.|Mathrengyl is wise. Listen before you go.",
	[5924] = "The Arch Druid's own helper wants you. Impress him.|Staghelm's great tree stands firm. Be its trunk.|Staghelm's tree is tall. Head up without a break.|The Enclave is green and hushed. Take in the leaves.",
	[5925] = "Sage and august, they call Mathrengyl. Earn his nod.|Excuse me, friend. Wait right there for the news.|All of Darnassus lies between you and him. Go.|Your druid path takes on a new life. Grow into it slowly.",
	[5926] = "Turak Runetotem will train you himself. Show him your best.|Turak is patient. Be patient like him.|Up the Elder Rise to Turak's tent.|The Elder Rise wind is gentle. Let it pass through you.",
	[5927] = "The Cenarion Circle's tent waits. Walk in ready to work.|Thunder Bluff sits high on its mesa. Be as solid as the rock.|Cross the rope bridges to the Elder Rise.|A wise teacher waits. Arrive with an open mind.",
	[5928] = "Turak wants to train you. Give him something to train.|Wait by the tent flap until Turak looks up.|From the lifts to the Elder Rise, no rest.|The plains roll below Thunder Bluff. Look out and breathe deep.",
	[5929] = "The Great Bear Spirit shows the nature of the bear. Be the bear.|The Bear Spirit weighs you up. Stand under its gaze.|Across northwest Moonglade to the Bear Spirit's home.|Bears know when to rest. Learn that from the Spirit.",
	[5930] = "A bear never skips its work. Neither do you.|A bear stands its ground. Stand yours before the Spirit.|Pad through Moonglade's woods to find the Spirit.|The Spirit is wise and noble. Sit with its lessons.",
	[5931] = "Mathrengyl walks in balance. Bring him a well-trained druid.|A protector of balance must be steady. Find your balance.|Moonglade to Darnassus. The road is yours.|We shall meet again, says the Spirit. Carry its calm home.",
	[5932] = "The tauren are young in the ways of Cenarius. Catch up.|Balance is the lesson. Keep yours as you wait.|Back to Thunder Bluff, hooves pounding.|Part ways with the Spirit gently. Turak waits.",
	[6001] = "Lunaclaw guards the Moonkin Stone. Show it the strength of body.|Lunaclaw hits hard. Do not give an inch.|The moonkin caves east of Auberdine. Charge in.|Strength of heart comes first. Settle yours before the dust falls.",
	[6002] = "Lunaclaw rises from the Lunardust. Meet it head on.|The Moonkin Stone near Taurajo never moves. Match it.|West of Taurajo, where the Barrens meet Mulgore. Go.|Moonkin are strange beasts. Face this one with a quiet heart.",
	[6061] = "Plainstriders kick hard. Your reps show Yaw you can too.|Keep the Taming Rod steady. The plainstrider must come to you.|Plainstriders never stop moving across the plains. Neither do you.|Calm hands, calm bird. Yaw Sharpmane taught you that much.",
	[6062] = "A dire mottled boar charges again and again. Your reps answer it.|Stand your ground as the boar charges. Thotar is watching this hold.|The boar won't sit still, so you won't either. Stay on its heels.|Thotar says taming takes will. Gather yours in the quiet.",
	[6063] = "Webwood lurkers spin fast. Your reps spin faster.|A lurker waits in its web for prey. Wait just like it.|Webs everywhere near Dolanaar. Don't stop, and none catch you.|Nature is stronger than you, Dazalar says. Listen to it, calm and low.",
	[6064] = "Crag boars are big and stubborn. So are these reps.|Grif wants that boar tame. Stay put till it stops snorting.|A crag boar is quicker than it looks. Stay ahead of those tusks.|Grif would rather talk about his Shrapnel Blaster. You find calm.",
	[6065] = "A young hunter earns a pet. The earning starts with reps.|Yaw Sharpmane waits in Bloodhoof Village. So can you, for this hold.|Bloodhoof Village is just ahead. Your beast is out there somewhere.|A hunter's path starts with a quiet mind. Find yours.",
	[6066] = "Yaw wants skilled hands. Show him the first of many reps.|The trainer sizes you up. Stand tall and don't budge.|Off to Bloodhoof. A pet of your own waits at the end of the trail.|Picture your future companion. Let the thought settle, nice and slow.",
	[6067] = "Beasts respect strength. Bank some reps before you see Yaw.|Hunters wait in tall grass for their prey. Hold like one.|The road to Yaw Sharpmane is open. Your future pet won't wait.|Earth below, sky above. Every hunter starts from here.",
	[6068] = "Thotar only trains the tough. Your reps say you are.|Razor Hill's trainer keeps you waiting. Hold until he's ready.|Razor Hill is close. Get going, a pet is on the line.|Before meeting Thotar, clear your head like a hunter at dawn.",
	[6069] = "Handling a beast takes grit. Thotar will count these reps.|A beast tests your will first. Hold, and let it test you.|Dust flies on the road to Razor Hill. Stay on it.|A pet mirrors its master. Be the calm one.",
	[6070] = "The path to a pet has many steps. Your reps are the first ones.|Stand guard outside Razor Hill until Thotar is ready.|Thotar has the taming rod. Don't let him hand it to someone else.|Hunter first, beast second. Settle the hunter.",
	[6071] = "Dazalar trains only the able. Let your reps speak for you.|Under Dolanaar's trees, a hunter waits in silence. Join them.|The trail to Dolanaar winds through the woods. Follow it fast.|Leaves drift down in Dolanaar. Let your mind drift with them.",
	[6072] = "Dazalar asks for skill. Hand him a stack of reps as proof.|Be as still as an owl on a branch. Dazalar likes patience.|Go find Dazalar. The woods of Dolanaar are wide and green.|A good hunter hears the forest. Go quiet and listen.",
	[6073] = "Trainers remember strong starts. Give Dazalar these reps.|Wait at the edge of Dolanaar. Hold until Dazalar waves you in.|Dazalar is waiting in Dolanaar. Hurry, young hunter.|Soft steps, soft breath. The forest trusts a quiet hunter.",
	[6074] = "Grif Wildheart likes hard workers. These reps should do it.|Stand firm at the gates of Kharanos until Grif looks up.|Kharanos isn't far. Off you go, a pet is waiting.|Grif talks a lot. Save your calm for when he's done.",
	[6075] = "The dwarf trainer wants skill. Stack up reps for Kharanos.|Wait like a hunter at a den. Grif's lesson starts soon.|Grif Wildheart is ready now. Hurry to Kharanos.|A new pet is coming. Let your thoughts go quiet and wait for it.",
	[6076] = "Taming starts with tough hands. Grif counts your reps.|Plant your boots in Kharanos. Hold till Grif's done talking.|Long road, big reward. Make for Kharanos.|A good hunter is patient. Settle in before you meet Grif.",
	[6081] = "Ormak Grimshot trains pets. These reps train you.|Wait by the Hall of the Brave. Hold until Ormak sees you.|Orgrimmar is a long way. Your new pet trots right behind you.|Ormak is a revered hunter. Meet him calm and clear-headed.",
	[6082] = "The armored scorpid strikes quick. Strike back with your reps.|A scorpid waits, tail up. Hold just as sure.|Scorpids skitter across the dry land. Stay on their trail.|Be like the scorpid: sure and calm before the strike.",
	[6083] = "Surf crawlers pinch. Pinch back with reps near the Echo Isles.|Waves crash around you. Let the crawler come to you.|Waves off Sen'jin roll in fast. Stay ahead of them.|Let the tide set the pace. The spirited crab will calm down too.",
	[6084] = "Snow leopards are swift fighters. Match their power in reps.|A snow leopard waits before it pounces. Wait with it.|These cats are agile and swift. Can you keep up?|Graceful cat, graceful hunter. Move like Grif's snow leopard.",
	[6085] = "Reps for the ice claw bear, a beast of brute strength.|The bear stands tall and firm. So do you.|Ice claw bears roam east of Kharanos. Chase one down.|Even a big bear has a quiet side. Find yours.",
	[6086] = "Belia will teach your pet tricks. You bring the reps.|The Hall of Arms is busy. Hold your place in line for Belia.|Get goin' to Ironforge! Belia won't find you out here.|Belia is a friendly sort. Meet her with an easy smile.",
	[6087] = "Swift and fearless, the prairie stalker. Be both in these reps.|Wolf and hunter wait as one. Hold with your new pack.|Prairie stalkers never tire on the plains. Stay with them.|You and your pet must work as one. Find that shared calm.",
	[6088] = "The swoop hits sharp and fast. Hit your reps the same way.|The swoop rides the wind high above. Hold as steady as its wings.|Watch the sky and chase its shadow. The swoop won't land for you.|The sky is wide and calm. Let the Earthmother slow you down.",
	[6089] = "Holt has bested the fiercest beasts. Show him your reps.|Hunter Rise sits high over Thunder Bluff. Hold firm up there.|Thunder Bluff is a long trek. Holt only meets the worthy.|Holt's ties to the Earthmother are strong. Borrow a little peace.",
	[6101] = "Nightsabers strike from shadow. Your reps come out of nowhere too.|A nightsaber stalker waits in the dark. Out-wait it.|Nightsabers prowl to the south. Track one down.|Nature is always changing. Change pace, and slow right down.",
	[6102] = "A mighty owl needs a mighty master. Prove it in reps.|Perch like the screecher on its branch. Not a feather moves.|The owl soars west of Dolanaar. Follow it across the woods.|Owls see all from high up. Be wise, and be quiet.",
	[6103] = "Jocaste may seem stern. Win her over with solid reps.|Respect Jocaste and she'll respect you. Stand tall in the Enclave.|Make haste to Darnassus. Jocaste is expecting you.|The Cenarion Enclave is a peaceful place. Match its quiet mood.",
	[6121] = "Druid lessons start hard. Dendrite Starblaze expects your reps.|Nighthaven is calm. Wait there for Dendrite's lesson.|Moonglade is far. The lesson begins when you arrive.|Cenarius gave druids a gift. Take it in quietly.",
	[6122] = "Naga live near Cliffspring Falls. These reps keep them wary.|Hold the sampler under the falls until it's full.|Fill the sampler, then hurry it to Auberdine.|Cliffspring water flows clear at the cave mouth. Flow with it.",
	[6123] = "Five earthroot and twelve lunar fungus. Your reps fill the bag.|Moonkin are grumpy in the caves. Stay put till they pass.|Caves east of Auberdine, then back again. Stay quick.|Lunar fungus glows softly in the dark. Glow just as softly.",
	[6124] = "Ten deer across Darkshore wait for salve. Get the reps in.|Deer spook easily. Freeze until this one lets you close.|From Cliffspring River to Ashenvale's edge. That's a lot of deer.|Soft hands, gentle voice. The deer of Darkshore will trust you.",
	[6125] = "Mathrengyl Bearwalker has a spell ready. Reps now, magic later.|The student understands the lesson. Hold on to it.|Back to Darnassus! Mathrengyl is waiting in the Enclave.|Remember what others endure. Carry that thought, quiet and kind.",
	[6126] = "Before a gift from Cenarius comes hard work. Here are the reps.|Moonglade is quiet. Stay just as quiet in this hold.|Your path to Nighthaven lies ahead. Go, young druid.|Poison is a lesson too. Let the thought sink in slowly.",
	[6127] = "Dreadmist Peak is tall. Your reps carry you to the top.|At the top pool, keep the sampler level. The Burning Blade is near.|Up the peak and back to the Crossroads. Don't stop for the Blade.|Airy peaks and quiet pools. Let Dreadmist Peak settle you.",
	[6128] = "Kodo horns are heavy. Haul five back to Tonga with your reps.|A kodo won't budge. Neither will you.|Kodos wander the northern Barrens. Track them down.|Earthroot grows slow and deep. Take your time like it does.",
	[6129] = "Ten gazelles in the northern Barrens. Put in the reps for them.|Gazelles bolt at any sound. Stay frozen until one steps near.|Gazelles dart north of the road. Chase down all ten.|Tonga sends his thanks. Let that warm thought settle you.",
	[6130] = "Turak Runetotem has a new spell for you. The reps come first.|Elder Rise is a place of patience. Show some here.|Head for Thunder Bluff. Turak's lesson won't teach itself.|Farewell for now, young druid. Let the lesson rest in you.",
	[6181] = "Lewis needs armor for Sentinel Hill. Your reps start the order.|Grip Lewis' note tight. Thor is just down the hill.|Down the hill to Thor! The note is urgent.|One note, one gryphon master. Easy errand, easy mind.",
	[6261] = "Osric packed that crate full. Your reps will get it moving.|Guard the crate in the trade district crowds.|Fighters in Westfall need their gear. Get to Dungar, fast.|Crate in hand, gryphon ahead. Calm steps to Dungar.",
	[6281] = "A gryphon ride costs a small fee. These reps cost you more.|Hold on tight. Gryphons fly fast to Stormwind.|Old Town is busy. Weave through it to Osric's shop.|Enjoy the flight. Westfall looks calm from up high.",
	[6282] = "Seven of each Bloodfury kind. Twenty-eight harpies in all.|Harpies dive from the cliffs. Hold your ground, Maggran is counting.|Bloodfury wings beat fast in Stonetalon. Beat them faster.|Roguefeathers love an ambush. Stay calm and watch the sky.",
	[6283] = "Their queen is Bloodfury Ripper. Your reps end her reign.|Her flock circles the western hills. Stand fast and wait for her.|The Charred Vale is wide. Hunt her through the western hills.|She will not be easy. Settle your mind before the hills.",
	[6284] = "Maggran wants Besseleth's Fang. Your reps pay the bounty.|Webs everywhere in Sishir Canyon. Don't twitch, or she feels it.|Eight legs chase you through the canyon. Outpace them.|Enter her webbed lair slow and quiet. Besseleth feels every step.",
	[6285] = "Fresh equipment for Sentinel Hill. The reps are your delivery fee.|Gryphon in the air, crate in your lap. Hold it steady.|Land at Sentinel Hill and bring that crate straight to Lewis.|Gryphons always fly home. Take that lesson in slowly.",
	[6301] = "Ten Gaea Seeds hide at the water's edge. Your reps find them.|Wait at Mirkfallon Lake's edge. The seeds show themselves in time.|North of Sun Rock to Mirkfallon Lake. Off you go.|Seeds grow slowly with the Earthmother's blessing. So can you.",
	[6321] = "The Deathguards need weapons. Your reps fill the order.|Tuck Podrig's order away safe. The Scourge lurk nearby.|Take the order to Karos Razok before the Scourge show up.|The woods are dark and full of Scourge. Keep your head clear.",
	[6322] = "Gordon's crate is heavy with weapons. Your reps haul it.|Brace the crate in the Undercity crowd. Michael Garrett is near.|Crate in hand, hurry to the Undercity bat master.|The Undercity is gloomy and quiet. Borrow its calm.",
	[6323] = "Gordon Wendham needs Podrig's order. Reps while the bat flies.|Grip the bat tight on the flight to the Undercity.|The Trade Quarter is busy. Find Gordon Wendham fast.|Bat wings beat slow in the dark. Match their beat.",
	[6324] = "The Sepulcher's weapons are finally here. Reps for the Deathguards.|Clutch the crate as the bat drops toward the Sepulcher.|Land at the Sepulcher and rush the crate to Podrig.|Bats always fly home to the Undercity. Rest your mind on the ride.",
	[6341] = "Fish bones and scales. Not heavy, but Nessa wants it done right.|Keep the box level. Nessa's scales must not spill.|Down the dock to Vesprystus. The hippogryph is waiting.|Big fish, calm water. Think like Rut'theran's fishermen.",
	[6342] = "Earn your hippogryph ride with these reps.|Grip the reins tight. Auberdine is a long way down.|Wings beat fast over the sea. Match them.|Up in the clouds, the wind is soft. Let it carry you.",
	[6343] = "Laird thinks the world tree changes the fish. Prove it on you.|Wait on the dock for the ferry. It always comes.|Ferry or hippogryph, Nessa wants her letter soon.|Teldrassil rises from the sea. Look up and take it in.",
	[6344] = "Nessa needs a hand. Give her a few good reps first.|The portal hums west of the gardens. Hold here until it opens.|The portal is west of the Temple Gardens. Hurry there.|Rut'theran is calm by the sea. Let that calm come to you.",
	[6361] = "Hides from the Barrens stack up. Lift them for Ahanu.|Hold the bundle close. Devrak is just up the road.|The Crossroads are hot and dusty. Get those hides moving.|Barrens wind in the grass. Let your breath move like it.",
	[6362] = "Wind riders fly hard. Your reps pay the fare to the Bluff.|Hang on to the wind rider. Do not let go.|Ahanu waits at the base of the tower. Get there fast.|Thunder Bluff sits high on the mesas. Look out and rest.",
	[6363] = "Ahanu's leather goods are packed. Heave them up to Tal.|By the tower, Tal calls a wind rider. Wait tall.|Thunder Bluff lifts go up and up. Race to Tal.|Soft leather, soft winds. Take it slow with Tal.",
	[6364] = "Jahan wants his goods to sell. Earn his coin with reps.|The wind rider dips low. Brace, and stay put.|Down at the Crossroads, Jahan is at his stall. Hurry.|Crossroads to Bluff and back. The loop is closed. Rest easy.",
	[6365] = "Zargh's best cuts are heavy. Lift them for Gryshka.|Keep the meat off the dirt. Devrak will not wait long.|Meat goes bad in the sun. Move it to Devrak now.|Smell the meat and think of the inn. Slow in, slow out.",
	[6381] = "Ten Gaea seeds, ten mounds. Push them into the dirt.|Harpies circle the Charred Vale. Stay low by the mound.|Mound to mound across the burnt vale. Plant them all.|The land is scarred, but seeds wait. Grow slow like them.",
	[6382] = "Bigger game waits in Ashenvale. Show Senani you are ready.|The forest edge looks back at you. Let it.|North from the Barrens to Splintertree Post. A long road.|A hunter enters the wild quietly. Go in like one.",
	[6383] = "Senani has a hunt for you. Warm up for the big game.|Wait by Senani's fire at Splintertree. The hunt will come.|Ashenvale trees go on and on. Pace through them.|The forest listens. Make no sound at all.",
	[6384] = "Coins paid. Now pay the wind rider in reps.|The Skytower comes into view. Grip tight until you land.|Skytower to the Valley of Strength. Gryshka is waiting.|Orgrimmar smoke drifts past. Let your breath drift too.",
	[6385] = "Gryshka wrote her thanks. Carry it to Doras with reps.|Wait by Doras while he calls a wind rider down.|Up the Skytower to Doras. Up, up, up.|A kind letter, gently held. Be as calm as its words.",
	[6386] = "Zargh will want his letter. Give him reps to match the thanks.|Doras's wind rider banks hard. Stay firm in the saddle.|Land at Devrak, then dash to Zargh. Don't stop.|Back where you began. Let the Barrens settle you.",
	[6387] = "Brock's best students earned picks. Earn yours the same way.|Hold Brock's list steady. Those names matter.|Thorgrum's gryphons are up the hill. Get the list there.|Loch Modan's lake is still. Be the lake.",
	[6388] = "A sack of honorary picks. Heavy iron for Gryth Thurden.|Keep the picks from clanking while Gryth gets a gryphon.|Across Ironforge to the gryphon master. Picks in tow.|Young miners will swing these. Picture their proud faces.",
	[6391] = "Golnir makes picks in the Great Forge. Strike like a smith.|Gryphon wings wide. Stay low on its back until Ironforge.|Deep Mountain Mining Guild. Through the forge halls, fast.|Ironforge is warm and loud. Find the quiet inside it.",
	[6392] = "Brock's students wait for their picks. Don't let them down.|Brace on the gryphon as it drops over Thelsamar.|Thorgrum to Brock's door, straight through town.|The picks are home. Thelsamar can rest, and so can you.",
	[6393] = "Tsunaman wants ten Incendrites. Put out ten fires.|Be cold water before the flames of Charred Vale.|Fire spirits dart through the vale. Chase them down.|Neptulon's tide rolls in slow. Breathe with the waves.",
	[6394] = "Beasts guard the pick. Clear them out of the way.|The pick glows by the waterfalls. Wait for the beasts to pass.|In and out of the Burning Blade Coven. Be quick.|Water falls in the dark cave. Listen and be calm.",
	[6395] = "Samuel roams by the road. Beat him, then give Marla her wish.|Wait at Marla's grave. Let the moment be.|Ruined camp to graveyard, with Samuel's remains.|Two names on one grave at last. A quiet end.",
	[6401] = "Kaya lives! Put some joy in your reps.|Tammra will cry happy tears. Stay strong for her.|Run west to Sun Rock with the good news!|Good news. Let it sink in slowly.",
	[6421] = "Ten Resonite crystals. Chip them loose from the kobolds' cave.|Deep in the ravine, a kobold candle flickers. Stay hidden.|How deep does the cave go? Find out.|Something hums under the mountain. Listen closely.",
	[6442] = "Twenty Wrathtail naga. Throw them back to the deep.|The tide pulls hard. Stand firm on the Strand.|Along the Zoram Strand after the naga.|Old Zoram sleeps under the sea. Let it sleep.",
	[6461] = "Ten creepers, seven spitters. The trolls are keeping count.|Webs everywhere. Don't twitch, or the Deepmoss feel it.|Spiders skitter north through Stonetalon. Stay on them.|Malaka'Jin sleeps easy tonight, thanks to you. Ease down too.",
	[6462] = "Eight troll charms in eight chests. Pry them open.|A furbolg walks past Thistlefur Hold. Freeze.|Through Thistlefur Village and deep into the cave.|The lost kin wait in the afterlife. Honor them with calm.",
	[6481] = "Smash the Resonite cask. Goggeroc wakes up weak. Hit hard.|Goggeroc is solid stone. Be stone right back.|The Earthen stirs. Don't give him time to wake fully.|Mor'rogal's magic is in the crystal. Focus like a shaman.",
	[6482] = "Ruul is weak from hunger. Lend him your strength.|Guard Ruul while the furbolgs rush in.|Get Ruul out and east to his sister Yama. Go!|Ruul is free and Yama is near. Take a calm breath.",
	[6503] = "Nine outrunners from Silverwing. Stop them all.|Crouch in the ferns. The outrunners come this way.|Outrunners are fast. Be faster through the forest.|Sneak as quietly as they do. Softer, even.",
	[6523] = "Grimtotem chase Kaya. Show them what you've got.|Put yourself between Kaya and harm.|To Camp Aparaje, quick, before they see she's gone.|Kaya knows her way from here. Let your guard down a bit.",
	[6541] = "The Horde needs recruits for Ashenvale. Sign up with reps.|On his tower, Kadrak stands tall. Match him.|North through the Barrens to the watch tower.|A new front awaits. Get your head clear first.",
	[6542] = "Kadrak wants new fighters for Zoram Strand. Show your worth.|Look north from the tower. Ashenvale waits beyond it.|Stonetalon to the northern Barrens is a long trek. Move.|Before the war, a quiet moment on the road.",
	[6543] = "Three reports, three scouts. Deliver them all.|The outrider reads slowly. Wait while he does.|Zoram'gar, Splintertree, then out east near Azshara. Run!|Kadrak gets his news. The runner can rest a while.",
	[6544] = "Torek's raiders charge Silverwing. Swing with them.|Sentinels hold the gate. Hold longer.|Run in with Torek. Don't fall back.|Duriel Moonfire falls. Now tell Ertog, calmly.",
	[6548] = "Eight ruffians, six mercenaries. For Makaba's village.|The Grimtotem camp is just west. Wait for your moment.|Cut through the Grimtotem ranks. No rest.|Makaba lost much. Carry his anger, but lightly.",
	[6561] = "Kelris feeds Aku'Mai. Cut off the supply.|Deep water, dark cult. Stay steady in the Deeps.|Past the naga, past the cultists, to Kelris.|An old temple of Elune. Find its lost calm.",
	[6562] = "Je'neu needs help. Build up for the long road.|Windshear Crag winds blow hard. Don't budge.|Far west to Zoram Strand. Don't slow down.|Forces there won't like you. Go in cool.",
	[6563] = "Twenty sapphires on the cave walls. Pry them free.|Naga harvest crystals nearby. Keep low.|Tunnel to tunnel, grab the sapphires first.|Blue light glows in the rock. Watch it pulse.",
	[6564] = "A damp note full of bad plans. Get it to Je'neu.|Read the scrawl again. Old Gods? Stay firm.|The cult has plans. Race them to Zoram'gar.|The ink runs. The plot is clear. Think it through.",
	[6565] = "Lorgus Jett wants the Old Gods back. Say no, with force.|Lorgus hides in the Deeps. Wait for him.|Find Lorgus before his plan is done.|Je'neu is too weak to go. Be his calm hand.",
	[6629] = "Grundig led the raid. Six brutes stand guard. Take them.|Grundig's brutes stand at Grimtotem Post. Stand firmer.|Up the path west to Grimtotem Post. Charge!|Makaba will be grateful forever. Take that in.",
	[6641] = "Vorsha the Lasher rises in anger. Answer her.|Guard Muglash by the brazier. The naga are coming.|Put out the brazier, then face the hydra. Fast!|The island falls quiet after Vorsha. Soak it in.",
	[6661] = "Five Deeprun rats. Monty wants them alive, arrr.|Play the flute and wait. The rats will come.|Lead the rats back to Monty. They follow your tune.|A soft flute tune down the tunnel. Match its beat.",
	[6662] = "A crate of rats for Nipsy. Heave ho, matey!|Keep inside the tram, or be peglegged for life.|Get a move on before these rats go bad!|The tram rumbles under the sea. Enjoy the ride.",
	[6721] = "A pet of your own awaits. Earn it.|A beast is watching you. Stay calm and let it look.|Ironforge to Dolanaar is far. Off you go.|Dazalar knows beasts. Be as quiet as a tamer.",
	[6722] = "Kharanos is cold. Warm up before the trip to Dazalar.|Snow falls on Kharanos. Stand firm in it.|Dun Morogh snow to Dolanaar woods. Long road.|Think of the pet you'll have someday. Smile.",
	[6843] = "Da Foo gives no orders. Do your reps anyway.|Wait here. The quest might yet speak.|No map, no goal. Just move.|An empty quest log. Enjoy the silence.",
	[6921] = "The Twilight's Hammer took the ruins. Take them back.|The fathom stone sits in the water. Stay put and search.|Swim through the Moonshrine Ruins to the stone.|Old ruins, still water. Look and let go.",
	[6922] = "The Baron left a strange globe. Carry it to Je'neu.|Nothing can crack the globe. Be just as hard.|Out of the water, back to Zoram'gar.|Foul water sloshes in the globe. Watch it swirl.",
	[6962] = "Five cookies for the old man. Count them out with your reps.|Greatfather Winter waits for his milk. Hold on, it is coming.|Cookies to Orgrimmar before the milk gets warm. Go, go!|He has worked all day. Share a quiet breath with the old man.",
	[6964] = "Sagorne keeps the old tales. Earn a seat by his fire with reps.|Snow sleeps on the land. Be as still as the winter ground.|Up to the Valley of Wisdom, far from all the gift shopping.|The Feast is a time of rest. Let the snow settle in you.",
	[6981] = "The green shard feels heavy. Lift your share of it to Ratchet.|Smoke swirls in the shard. Hold and stare into it.|From the Caverns to Ratchet. The shard won't go there alone.|Something about the shard is wrong. Stay calm and look deep.",
	[7022] = "Greatfather Winter keeps a nice list. Get on it with your reps.|Wait in line by Smokywood Pastures. The old man is busy.|Through the snowy halls of Ironforge to say hello.|Think of what you hope to get this year. Wish for it slowly.",
	[7023] = "Greatfather Winter keeps a list. Put your reps on the nice side.|The line to see Greatfather Winter is long. Stay put and wait.|Ironforge is cold at Winter Veil. Stay on the go to keep warm.|Snow drifts past the Great Forge. Think of your wish, nice and calm.",
	[7025] = "Five Gingerbread Cookies for the Greatfather. Earn them with reps.|Steady hands, or that Ice Cold Milk ends up on the floor.|The Greatfather is hungry. Hurry those cookies across Ironforge.|Let the milk settle. Nobody rushes a Winter Veil snack.",
	[7062] = "Karnik has old books to lift. Help the Explorers League out.|History is slow. Stay put while Karnik finds the right page.|Off to the Explorers League. Leave the red suit behind.|The land rests under snow. Rest with it for a while.",
	[7069] = "No quest here, but the work still counts.|This page is empty. Fill it by holding your ground.|Nothing to chase here. Go anyway.|A blank page. Enjoy the quiet.",
	[7383] = "The Oracle Glade is far. Fill the Amethyst Phial with hard work.|Keep the phial steady while the moonwell fills it.|Northwest to the Oracle Glade, then back to Dolanaar.|Under the Oracle Tree, the water is calm. Be calm too.",
	[7681] = "Your pet is hungry. Earn its supper.|Your pet sits and waits for food. Wait with it.|Hurry to the food bag before your pet eats your boots.|A fed pet is a happy pet. Take a calm moment together.",
	[7682] = "Hungry paws wait. Your pet watches you work for its dinner.|Hold out the food and wait. A good pet eats from a calm hand.|Around the camp your pet sniffs for food. Match its pace.|Fed and happy, your pet sighs. Settle down beside it.",
	[7791] = "Sixty wool cloth for Stormwind. Stack it up.|The wool pile is tall. Stand firm so it doesn't tip.|Bolt after bolt of wool across the Trade District.|Soft wool, soft breath. Stormwind thanks you.",
	[7792] = "Darnassus needs sixty wool. Pull your weight in cloth.|The sentinels count the wool slowly. Wait it out.|Up the tree paths of Darnassus with a sack of wool.|Moonlight on the Temple Gardens. Let the wool pile rest.",
	[7802] = "Into the dwarves' stores: sixty wool. Heave!|Ironforge takes its time counting. Stand by the pile.|Round the Great Forge with wool on your back.|The forge hums warm. A soft wool moment for you.",
	[7807] = "The gnomes want wool too. Sixty more, if you please.|Keep the wool bundle steady. Gnomes hate a mess.|Tinker Town is a long way down. Hurry the wool along.|Wool is warm and quiet. Borrow some of both.",
	[7810] = "Short John Mithril only talks to fighters. Show him.|Stand at the edge of the Gurubashi Arena and wait for the chest.|Through the jungle to the arena. Pirates don't wait.|A master of the arena is calm before the bell.",
	[7813] = "Undercity wants sixty wool. The dead get cold too.|Stand in the damp halls while the clerks count.|Down the lift and along the canals with your wool.|Even the Undercity has quiet corners. Find one.",
	[7820] = "Tauren are big folk. Sixty wool barely covers one.|Wind on the bluffs tugs at the wool. Don't let it go.|Across the rope bridges of Thunder Bluff with a full load.|The plains roll below the bluffs. Breathe with the wind.",
	[7826] = "For Orgrimmar, sixty wool. The Horde asks, you deliver.|Stand in the Valley of Strength with the wool. Don't budge.|Dust and heat in Orgrimmar. The wool must still arrive.|Hot sun, soft wool. A calm spot in a loud city.",
	[7833] = "Darkspear trolls need wool, mon. Sixty bundles.|Keep the wool dry in the Cleft of Shadow. Nobody touches it.|Up and down the ramps of Orgrimmar. The wool keeps coming.|Wool piled high, work nearly done. A quiet breath in Orgrimmar.",
	[7869] = "A test quest with no story. Make up your own foe and beat it.|Nothing happens here yet. Wait for the world to be finished.|This road was never built. Cross it anyway.|An empty quest log. Enjoy the quiet while it lasts.",
	[7870] = "Test quest two, also empty. The game makers left you the work.|Someone forgot to write this one. Stand guard over the blank page.|No map, no goal, no giver. Wander the empty space with speed.|Blank page, blank mind. Let this odd corner of the world rest.",
	[7904] = "The Faire has one item for you. Earn it.|The Faire tent is quiet today. Wait for the show.|Rides, games, lights. Hurry past them all.|Darkmoon Faire at night. Take in the glow.",
	[7905] = "Free prize tickets wait. Gelvas Grimgate likes a hard worker.|Hold that voucher tight. Goldshire is a long way off.|From Ironforge to Goldshire. The Faire won't stay forever.|Carnival music drifts over Elwynn Forest. Enjoy it.",
	[7908] = "More to being arena master? Earn the answer with reps.|The pirate sizes you up. Don't blink.|Stranglethorn is hot and wide. Cross it to the arena.|Out in the jungle, the arena roars. Stay cool inside.",
	[7926] = "A free ticket voucher is worth some sweat. Earn your prizes.|Gelvas is busy. Stand by the tent with your voucher.|Out of Orgrimmar and on to Mulgore. The Faire awaits!|Tents glow near Thunder Bluff. Stroll in, calm and happy.",
	[7961] = "Rabbits everywhere. Keep up with them, if you can.|Wait by the burrow. A rabbit always pops out.|Rabbits hop fast. Chase them across Northshire.|Jon LeCraft is upset. Calm him, and yourself.",
	[7962] = "Three LeCrafty pelts. Jon says this is important.|Stay low in the grass. The rabbits have not seen you.|LeCrafty Rabbits bolt. Go after them.|Soft pelts, soft grass. A gentle moment in the valley.",
	[8193] = "Forty fish to land. Work that line.|Line in the water. Wait for the bite.|The best spots are far apart. Rush between them.|The water is flat and calm. Match it.",
	[8230] = "Collin is testing. Give him something to count.|Collin checks his notes. Stay right there.|Test quest, real effort. Get going.|Nothing to fight. Let the quiet be enough.",
	[8247] = "An empty quest still wants work.|No foes, no loot. Just stand your ground.|Nowhere to go, and plenty of room to go there.|Empty sky, empty map. Let your mind go empty too.",
	[8248] = "A quest with no name. Make it count.|The log is blank. Stay as quiet as it.|No goal in sight. Move anyway.|Nothing asks for you here. Sink into the calm.",
	[8266] = "Ribbons are won in Warsong Gulch. Earn yours.|Guard the flag room. Nobody gets past.|Grab the flag and race for home.|Before the gates open, a calm, quiet moment.",
	[8268] = "A ribbon for the brave. Pay for it in reps.|Stand on the flag. Do not let go.|Across the Gulch and back. The foe is right behind.|The Gulch is still for now. Be still too.",
	[8274] = "Five murlocs, and something shiny. Fair deal.|Murlocs gurgle by the shore. Wait for them to come.|Mrglglgl! Chase the murlocs along the beach.|The sea laps at the sand. Let the murloc noise fade.",
	[8290] = "Push back the Horde. Silverwing Hold needs you.|Defend Silverwing Hold. Stand where Farsong put you.|Through the tunnel and into the fight for the Gulch.|The forest feels each tree cut. Stand with it, calm.",
	[8295] = "Cut down the Silverwing Sentinels for Shatterskull.|Hold the Warsong camp. The elves will come.|Charge out of the Horde gate. Kalimdor waits.|Let the pride swell, then settle. The next fight comes soon.",
	[8311] = "Four sweets from four spots. Jesper is counting on you.|The innkeeper wants a trick. Stay in pose till you get candy.|Stormwind, Ironforge, Darnassus. Candy won't collect itself.|Jesper can't go out this year. Go gently for him.",
	[8312] = "Marzipan, gumdrop, nougat, mint. Spoops wants them all.|Do the trick, then freeze. The innkeeper is watching.|Orgrimmar to Undercity to Thunder Bluff. What a candy trip!|Candy that turns you into things. Picture a funny one.",
	[8459] = "The log says Log. The work says work.|Description: you, standing firm.|A quest with no words needs no map. Just go.|Blank words, blank mind. Rest in it.",
	[8492] = "Copper bars for Stonebrow, twenty in a stack.|Stonebrow counts slow. Keep the bars steady.|Down to the Military Ward with a sack of copper.|Copper glows warm by the forge. Soak in it.",
	[8494] = "Iron bars, Fancypants. Carnes wants a whole mess of them.|Iron is heavy. Plant yourself while Carnes signs for it.|A load of iron to haul across Ironforge.|After the loud forge, a quiet moment by the iron pile.",
	[8499] = "Steam tanks need thorium. Twenty bars for Dame Twinbraid.|Stand firm like a steam tank set to fly to Silithus.|Bars to the Military Ward before the tanks take off.|Thorium sleeps deep in stone. Rest like it.",
	[8503] = "Draxlegauge wants A LOT of kelp. Twenty to start.|Kelp sways in the deep. Be the rock it clings to.|Wet kelp, long walk. Get it to Draxlegauge.|Sway like kelp in the sea. Easy and soft.",
	[8505] = "Master Nightsong wants twenty purple lotus. Pick them all.|Nightsong looks at every petal. Wait while he does.|Lotus grows far and wide. Cover the ground.|Smell the purple lotus. Let it calm your mind.",
	[8509] = "Arthas' Tears, twenty of them. Germaine doesn't ask why.|Orders are orders. Stand at attention for Germaine.|Out into the world for Arthas' Tears, then back fast.|A sad name for a pretty flower. A soft moment for it.",
	[8511] = "Ten light leather for Bonnie. The Stoneflayers work hard.|Bonnie tans the hides. Stay still while she works.|Out after the skins, back to Bonnie with the stack.|Soft leather, soft sigh. Bonnie nods at you.",
	[8513] = "Ten medium leather for Private Porter. He tracks them all.|Porter writes it all down. Wait until he's done.|From whatever source, get that leather to Porter.|Porter would sure like a hand. First, a calm moment.",
	[8515] = "A ton of thick leather! Marta means it.|Marta bounces with joy. You stay put for her.|Do yah, do yah? Marta wants that stack fast!|Marta is so excited. Someone has to be calm here.",
	[8517] = "Linen bandages, twenty for Silversky. Wrap them tight.|Silversky guards the stacks. Guard them with her.|Bandages to the Military Ward before the war starts.|Linen is soft and light. Let the work feel light too.",
	[8520] = "Twenty silk bandages for Nurse Stonefield. Roll them up in reps.|Stonefield counts the silk. Stay put until the pile is done.|Ironforge halls are long. Carry the silk to the Military Ward.|Silk is soft work. Let the Ward's quiet hum settle you.",
	[8522] = "Moonshade wants twenty runecloth rolls. Wind them up with reps.|Keeper Moonshade waits by the crates. Hold like a night elf guard.|Loom, cut, wrap, again. Runecloth does not roll itself.|Think of family and friends, as Moonshade asks. Then let go slowly.",
	[8524] = "Slicky wants twenty albacore, cooked. Reel in your reps.|Line in the water. The Rainbow Fin bites when you stay put.|Catch, clean, cook, and back to Slicky. The grill stays hot.|Watch the float bob on calm water. Rainbow Fin take their time.",
	[8526] = "Twenty roast raptor for Sarah, who does not even like meat.|Sarah holds her nose by the stack. You hold your spot.|Raptors are fast. Keep up with them, then with the fire.|Her dad called this a learning trip. Learn to breathe through it.",
	[8528] = "Swiftriver says prep work wins wars. Twenty yellowtail of reps.|Huntress Swiftriver never rushes a cast. Wait out the bite.|Spotted yellowtail swim fast. Your line has to go faster.|It stores well and smells mild. A calm fish for a calm spell.",
	[8530] = "Fifty singed corestones. Stronghammer's smiths want every one.|The Molten Core is hot. Stand firm while the raid loots.|Thirty-nine friends and a lava river. Keep up with the raid.|Back at the airfield, cool mountain air after the Core's heat.",
	[8532] = "Bars, not ore, says Cromwell. Smelt twenty with your reps.|The forge takes its time. Stay by it until the copper runs.|Mine, smelt, and haul the bars to the Valley of Spirits.|Copper cools slowly in the mold. Match its pace.",
	[8542] = "Maug can't count that high. Give him twenty tin bars anyway.|Maug would rather hammer armor. Brace like the anvil instead.|The Warchief calls it prepare. Maug calls it more tin, faster.|Grunt Maug is learning to prepare. Show him how, nice and calm.",
	[8545] = "T'kelah still be needin' more. Twenty mithril bars, mon.|Mithril veins run deep. Stand strong while the pick bites.|Mine it up, smelt it down, bring it to T'kelah quick.|Mithril gleams in the dark. Find that shine slowly, mon.",
	[8549] = "Twenty Peacebloom for the war. Pick one with each rep.|Hold low in the grass. Peacebloom hides from those in a rush.|The war needs potions. Get those herbs back to Orgrimmar, fast.|Proudfeather waits in the Valley of Spirits. Find her calm.",
	[8580] = "Pele'keiki no know why they need it. He know you bring twenty.|Firebloom goes boom, maybe. Stay steady near it, mon.|The Horde thinkin' they need lots. Rush the fields hot.|Firebloom glows in the heat. Stay cool as the petals sway.",
	[8582] = "Jezel needs a great many lotus. Twenty for now. Start picking.|Stay by the lotus patch until Jezel has all she needs.|Lotus hides in far fields. Out you go, and back to Jezel.|Jezel tests each flower with care. Take the same care.",
	[8588] = "Sharpen your knife. Ten heavy leather for Skinner Jamani.|A skinner keeps a firm grip. Hold yours on the blade.|Tarps, armor, and more. Jamani wants the bundle soon, mon.|Knife sharp, hand steady. Jamani's work starts calm.",
	[8590] = "Ten thick hides for Sergeant Umala. The Horde remembers.|Umala's war plans are in full swing. You stay firm.|Thick leather walks on four legs. Chase it down.|Honor and thanks wait in Orgrimmar. Take a calm moment first.",
	[8600] = "Serratus says pressure matters more than edge. Show him ten.|The fit of the knife in your palm. Keep that grip firm.|Rugged leather roams far. Serratus will not wait, no?|Even a dull blade cuts with calm pressure. Be the calm.",
	[8604] = "Longrunner packs kits for soldiers. Twenty wool bandages, please.|A soldier in the field waits on these kits. Stay firm for them.|Longrunner lives up to the name. Match that speed to Orgrimmar.|Wool is soft and warm. Wrap up the day nice and slow.",
	[8607] = "By whatever means, says Lady Callow. Twenty mageweave rolls.|Fresh would be nice. Callow waits, and so do you.|Whatever means, she said. That means lots of cloth, fast.|Lady Callow does not ask twice. Answer her with a quiet mind.",
	[8609] = "Horde and Alliance on the same side. Twenty runecloth for Clayhoof.|Stoneguard Clayhoof stands like stone. So can you.|The silithid will not wait. Get those bandages moving.|Both sides working as one. Strange times. Take them calmly.",
	[8611] = "Rawtar needs twenty wolf steaks. Hunt the wolves, then the grill.|Rawtar stands in the sun all day. Hold your ground like him.|Wolves are quick. Be quicker, then cook what you caught.|Salt the steaks slowly. Rawtar is not here for a tan.",
	[8613] = "A ton of yellowtail, Lin'do says. Twenty will do for now.|Nice day for fishin', mon. Let the line sit and wait.|Cast, reel, cook, again. Lin'do be countin' on you.|Sun on the water, a lazy float. Lin'do's kind of day.",
	[8615] = "Sharpclaw wants twenty baked salmon. Soldiers must eat.|Salmon leap upstream. Stay in the river and wait for them.|Catch the salmon, bake them, and hurry back to Sharpclaw.|Baked slow, keeps well. Sharpclaw likes a patient cook.",
	[8617] = "Fifty corestones for General Zog. He is less kind than the Warchief.|Zog does not forgive. Brace in the Core's heat.|Gather your guild and storm the Molten Core. Zog is watching.|The lazy days are gone, says Zog. Take one last calm look.",
	[8619] = "Morndeep waits far below. Honor him with your reps.|Deep under the mountain, Morndeep sits calm. Join him.|Morndeep lives far down. A long road to pay respects.|Lunar light reaches even Morndeep. Let it find you too.",
	[8635] = "Splitrock by name. Show the elder you can split rock too.|Be the rock Splitrock sits on. Firm and quiet.|Splitrock is a long trek away. Off you go.|The Lunar Festival brings you to Splitrock. Greet him with calm.",
	[8636] = "Rumblerock's name shakes the ground. Make your reps rumble too.|The rumble stops when you brace. Rumblerock nods.|Rumble along the road to Rumblerock. The festival waits.|Under the moon, even Rumblerock goes quiet. Your turn.",
	[8642] = "Silvervein's blessing is worth its weight in silver. Earn it.|Stand like a silver vein in stone. Silvervein approves.|Silvervein is out in the hills. Head there and pay respects.|Moonlight turns everything silver. Silvervein likes a calm guest.",
	[8643] = "Highpeak lives up high. Your reps are the steps to the top.|Top of the peak, wind in your face. Highpeak stays put.|Up and up to Highpeak. The mountain has no shortcuts.|From Highpeak's perch, the whole land lies still. Look out.",
	[8644] = "Stonefort guards his fort of stone. Knock with your reps.|Walls of stone do not budge. Neither does Stonefort, or you.|Stonefort is far from any feast. Hurry to find him.|A fort is built stone by stone. Settle in, block by block.",
	[8645] = "Obsidian is hard and sharp. Your reps must be the same.|Black glass sets hard and still. Obsidian waits like that.|The road to Obsidian is long. Lunar lanterns light the way.|Smooth as black glass, Obsidian's calm. Borrow a little.",
	[8646] = "Hammershout wants loud reps. Ring them out like a hammer.|Between hammer blows comes a pause. Hammershout holds it.|Hammershout shouts for company. Answer him in a hurry.|Even Hammershout lowers his voice for the Lunar Festival.",
	[8647] = "Bellowrage bellows. Let your reps bellow back.|Bellowrage's rage is loud. Your calm stance is louder.|Follow the bellowing to find the elder. Don't lose it.|Rage fades under the moon. Bellowrage knows the trick.",
	[8648] = "Darkcore dwells in the dark. Light it up with your reps.|Darkcore waits in shadow, patient. Wait with him.|Dark roads lead to Darkcore. Lantern high, go quick.|In the dark, the moon's light matters more. Darkcore agrees.",
	[8649] = "Stormbrow frowns like thunder. Earn a smile with reps.|A storm gathers over Stormbrow's brow. Weather it.|Race the storm clouds to Stormbrow's side.|After the storm, Stormbrow's brow clears. So does yours.",
	[8650] = "Snowcrown wears a crown of snow. Earn a nod from the old elder.|Be a snowdrift. Snowcrown has seen many winters.|Snow slows everyone but you. Push on to Snowcrown.|Snowflakes fall slowly. Snowcrown's words fall the same way.",
	[8651] = "Ironband is bound in iron. Show him some iron of your own.|An iron band does not bend. Live up to Ironband's name.|Ironband is waiting. Lanterns lit, road ahead, go.|Iron cools and settles. Let Ironband's calm sink in.",
	[8652] = "Graveborn rose from the grave. Rise to meet him with reps.|Graveborn is still as a tombstone. Match him.|Past the graves to Graveborn. Don't let the chill catch up.|Graveborn has all the time in the world. Borrow some.",
	[8653] = "Goldwell's blessing shines like gold. Earn the shine.|Wait by the well of gold. Goldwell will not rush you.|Gold waits at the end of the road. Goldwell too.|Draw calm from Goldwell like water from a well.",
	[8654] = "Primestone is the oldest stone of all. Give it your prime reps.|Primestone has not moved in ages. Try a little of that.|Primestone waits far off. The road goes on; so do you.|Old as stone and twice as calm. Primestone shows the way.",
	[8670] = "Runetotem carves runes in wood. Carve out your reps.|A totem stands tall and still. So does Runetotem, so do you.|Follow the totems to Runetotem's side.|Runes speak softly. Listen to Runetotem the same way.",
	[8671] = "Ragetotem's rage lives in your reps now.|The totem does not rage. It stands. Learn from Ragetotem.|Rage the whole way to Ragetotem. He will like that.|Ragetotem's rage cools under the Lunar moon. Cool with it.",
	[8672] = "Stonespire towers high. Stack your reps like his spire.|A spire of stone never leans. Neither does Stonespire.|Spot the spire on the skyline and head for Stonespire.|Stonespire gazes out from on high. Gaze out with him.",
	[8673] = "Bloodhoof comes from a proud line. Make your reps proud too.|Hooves planted, Bloodhoof does not stir. Plant yours.|Hoofbeats all the way to Bloodhoof. Thunder on.|Bloodhoof's people honor the earth. Rest with it a moment.",
	[8674] = "Winterhoof has seen cold years. Bring warm reps.|Winter comes slow and stays long. So does Winterhoof.|Winter winds push back. Push on to Winterhoof.|A frosty breath, then a slow one. Winterhoof smiles.",
	[8675] = "Skychaser reaches for the sky. Reach with your reps.|Skychaser watches the stars all night. Watch with him.|Chase the sky like Skychaser. It never gets away.|Look up. Skychaser sees the whole festival sky from here.",
	[8676] = "Wildmane's mane is wild. Your reps can be wild too.|Wind in the mane, Wildmane stays firm. Do the same.|Go wild on the road to Wildmane. The festival is calling.|Even a wild mane settles in calm air. Wildmane knows.",
	[8677] = "Darkhorn lowers his horns. Meet them with your reps.|Horns set, Darkhorn is ready. Be ready too.|Darkhorn is a long way out. Horns up, onward.|Lunar light on dark horns. Darkhorn takes it in slowly.",
	[8678] = "Proudhorn wants something to be proud of. Give it reps.|Head high, horns proud. Proudhorn has not blinked yet.|Proudhorn waits at road's end. Make him proud of the trip.|Pride can be quiet. Proudhorn shows how.",
	[8679] = "A Grimtotem elder is a grim sight. Your reps earn his respect.|Grimtotem glares. Stare back and do not budge.|Grimtotem ground is not friendly. Be quick about it.|Even Grimtotem pauses for the Lunar Festival. Pause too.",
	[8680] = "Windtotem hears the wind. Let him hear your reps.|The wind blows. The totem stays. Windtotem nods at you.|Ride the wind to Windtotem. It blows your way today.|Wind in, wind out. Windtotem breathes with the sky.",
	[8681] = "Thunderhorn's name booms. Boom out your reps.|Thunder rolls past Thunderhorn. He stands through it all.|Chase the thunder to Thunderhorn before the rain.|After thunder, a hush. Thunderhorn loves that part.",
	[8682] = "Skyseer has a lunar coin for you. Your reps pay for it.|Stand under the moon like Skyseer does. The coin can wait.|The road to Skyseer is long. Your feet know the way.|Skyseer reads the sky. Look up, and let your breath go out.",
	[8683] = "Dawnstrider greets each dawn. Your reps greet this one.|Wait for first light, as Dawnstrider does. No moving yet.|Stride like Dawnstrider, from dark to dawn, with no stop.|The sun comes up slow over Dawnstrider. Let your breath rise too.",
	[8684] = "Dreamseer dreams of heroes. Give her a real one to see.|Dreamseer sits in a dream. Stay put and do not wake her.|Chase the dream to Dreamseer's side. It won't wait for you.|Close your eyes. Dreamseer says the best trips start inside.",
	[8685] = "Mistwalker hides in fog. Your reps burn the mist away.|The mist is thick. Hold your spot till Mistwalker comes into view.|Push through the fog. Mistwalker is out there somewhere.|Walk in the mist like Mistwalker: soft, slow and calm.",
	[8686] = "High Mountain lives up high. Reps are the steps up.|Stand firm like the peak where High Mountain waits.|Up the slope to High Mountain. The air gets thin. Go on.|At the top, High Mountain looks out. Stretch out and look too.",
	[8688] = "Windrun loves a strong gust. Make your reps the gust.|The wind pushes. Stay rooted till Windrun nods.|Race with the wind to Windrun. Let it carry you.|Windrun hears the wind. Breathe in, breathe out, and listen.",
	[8713] = "Starsong sings to the stars. Your reps keep the beat.|Starsong's song is long. Don't leave till the last note.|A star falls. Race it to Starsong before it lands.|A soft tune from Starsong. Stretch to it, slow.",
	[8714] = "Moonstrike strikes like moonlight, sharp and bright. Be that sharp.|Hold the pose until the moon strikes midnight for Moonstrike.|Moonstrike waits past many hills. Your feet must not quit.|Under the moon, Moonstrike is calm. Be calm with him.",
	[8715] = "Bladeleaf's leaves cut clean. Reps should too.|A leaf in no wind. Bladeleaf knows that kind of stillness.|Leaves blow past on the path to Bladeleaf. Chase them.|Bladeleaf bends like a young tree. Bend along.",
	[8716] = "Starglade tends a glade of stars. Your reps light one more.|The glade is quiet. Starglade asks you to stay that way.|Cross the dark wood to Starglade. The stars show the way.|Lie back in Starglade's glade and count stars in your head.",
	[8717] = "Moonwarden guards the moonlight. Show him a guard's work.|A warden stands watch. Share the watch with Moonwarden.|Moonwarden's post is far out. Get there before the moon sets.|Moonwarden watches the night with soft eyes. Soften yours.",
	[8718] = "Bladeswift strikes fast. Your reps can't lag behind.|Swift blades need a still hand. Bladeswift will check yours.|Swift is the name. Swift is the pace. Go find Bladeswift.|Even Bladeswift slows down at the festival. Slow down too.",
	[8719] = "Bladesing's blade sings. Give it a chorus of reps.|The song needs a long note. Hold it for Bladesing.|Bladesing hums a fast tune. Your feet dance to it.|A quiet blade tells no tales. Bladesing likes it that way.",
	[8720] = "Skygleam shines bright. Reps put a gleam on you as well.|Bright and still, like the gleam over Skygleam.|A gleam in the sky marks Skygleam. Head for it fast.|Skygleam sees the sky change. Watch it change, nice and slow.",
	[8721] = "Starweave weaves the stars together. Weave your reps as tight.|One loose thread and the weave falls. Starweave needs you firm.|Weave through the crowd to Starweave. No stopping.|Starweave's threads stretch long and thin. So do you.",
	[8722] = "Meadowrun likes a busy meadow. Make it buzz.|Tall grass does not twitch. Be the grass by Meadowrun.|It's in the name. Cross the meadow to Meadowrun.|Wildflowers sway at Meadowrun's feet. Sway with them.",
	[8723] = "Nightwind blows cold tonight. Reps warm you up.|The night wind howls. Nightwind stands firm. You too.|Beat the night to Nightwind. The dark comes fast.|Nightwind breathes with the dark. Long in, long out.",
	[8724] = "Morningdew wakes early. Your reps are the rooster.|Dew sits on the leaf till the sun comes. Sit tight for Morningdew.|Get to Morningdew before the dew dries.|Fresh dew, cool air. Morningdew starts slow. Start slow.",
	[8725] = "Riversong hears the river. Let the reps splash.|A stone in the river stays put. Be that stone for Riversong.|Follow the river down to Riversong. It never stops. Nor do you.|The river bends and flows. Riversong asks you to do the same.",
	[8726] = "Brightspear keeps a spear keen. Keep the reps keen.|A spear held level does not shake. Brightspear is watching.|Brightspear's spear points the way. Go that way, fast.|Lower the spear. Brightspear says the festival is for peace.",
	[8727] = "Farwhisper tells of old deeds. Add a new deed in reps.|Lean in close. Farwhisper speaks soft, so stay still.|Far is in the name. Far is where you're going.|Hear Farwhisper's whisper over the wind. Breathe quiet.",
	[8744] = "Layers of paper to get through. Reps rip them off.|Don't tear the paper yet. The best part is the wait.|The bow is tight and the tape is thick. Work at it.|Peel back the paper slow. A careful gift wants care.",
	[8767] = "Something rattles inside. Rattle off some reps.|No more shaking. Keep the gift still and guess.|Give the gift a good shake. Then another. Then more.|Gently now. Whatever's inside likes it calm.",
	[8792] = "Warlord Gorchuk wants the Horde ready. Prove you are.|Gorchuk's camp is busy. Stand your ground in the Valley of Spirits.|The Horde needs you! Hurry to the Valley of Spirits.|War is coming to Ahn'Qiraj. Take a calm breath first.",
	[8793] = "Collectors want supplies. Gorchuk wants your reps on the pile.|Wait by Gorchuk. He has a long list to read.|Orgrimmar's streets are packed. Weave through to Gorchuk.|Before the war, a quiet moment in the Valley of Spirits.",
	[8794] = "For the Horde! Pile up reps like war goods.|Stand at attention. Warlord Gorchuk is looking you over.|The war effort can't wait. Neither can your feet.|Spirits drift through their valley. Drift with them for a bit.",
	[8795] = "Field Marshal Snowfall needs strong hands. Lend yours.|Snowfall likes soldiers who stay still in line.|To the Military Ward! The Alliance won't wait.|Ahn'Qiraj is far off. For now, a calm breath in Ironforge.",
	[8796] = "Crates of war goods stack high. Stack reps higher.|Keep your post in the Military Ward. Snowfall is near.|Snowfall's call rings through Ironforge. Answer it on the double.|The forges glow warm. Loosen up before you meet Snowfall.",
	[8797] = "For the Alliance! Snowfall keeps the tally.|The line at Snowfall's desk is long. Be patient in it.|Past the forges, past the guards, straight to Snowfall.|The Military Ward hums. Find a quiet spot in it.",
	[8803] = "A festive gift waits under the tree. Earn it first.|The gift sits under the tree. Sit with it a while.|Snow on the ground, a gift ahead. Hurry over.|Lights on the tree, snow outside. Take in the calm.",
	[8827] = "Presents with your name on them! Earn every one.|Greatfather Winter hands out gifts one by one. Your turn is coming.|To Ironforge, fast! The tree is full of gifts.|Snow falls on Smokywood Pastures. Watch it drift down.",
	[8860] = "Smokywood Supplies are heavy. Lug them over in reps.|Keep the supplies steady. Allison needs the party food whole.|Fireworks tonight! Get the food to the Gilded Rose first.|Free drinks, fireworks, and a new year. Soak it all in.",
	[8862] = "Five of Elune's Candles. Light a wick with every rep you do.|A candle flame stays steady in still air. Be the still air.|Elune's Candles pop and fly. Keep up with them.|Candlelight for Elune. Soft light, soft breath.",
	[8866] = "Bronzebeard likes solid dwarf work. Reps built like Ironforge.|Be as still as Ironforge stone. Bronzebeard would approve.|Down the long halls of Ironforge to Bronzebeard, quick.|Bronzebeard strokes his beard and thinks. Take your time too.",
	[8867] = "Eight rockets, two clusters. Fire off the reps like fuses.|Light the fuse, then wait for the bang.|Launcher to launcher, rocket after rocket, no rest.|Watch the sparks fade over the festival. Ahh.",
	[8870] = "The Harbinger in the Mystic Ward has news. Reps buy a seat.|Step into the circle of moonlight and stay there.|Find the moonlit circle in Ironforge. It's festival time!|Moonlight in a stone city. Let it wash over you.",
	[8871] = "The Cenarion Circle invites you. Your reps are the reply.|The Harbinger stands in the Park's moonlight. Stand beside her.|Across Stormwind to the Park District, quick as you can.|Trees and moonlight in the Park. A good place to unwind.",
	[8872] = "Enclave druids like a hard worker. Show them one.|The blessed circle glows. Stay inside its light.|Up the paths of Darnassus to the Enclave. Don't dawdle.|Darnassus is calm under the moon. Match its calm.",
	[8897] = "Heldric can't leave the gate. Your reps carry his words.|Heldric keeps watch at the gate. Keep watch with him a bit.|Get the note to Colara before Heldric loses his nerve.|A note from the heart. Walk it over with care.",
	[8898] = "He rewrote this letter again and again. Your reps top that.|The mail is full. You are the mail now. Stand ready.|The mail is too slow. Take the letter to Colara on foot.|Smooth out the creases. Colara deserves a neat letter.",
	[8899] = "So many years, and no words. Let reps do the talking.|Some other suitor waits. Don't budge from your spot.|No time to spare. Rush the letter before a rival does.|The letter is spotless. Keep your breath just as clean.",
	[8900] = "They laughed at him. Reps make sure the letter lands.|Elenia waits by the Undercity bank. Wait with her.|Down into the Undercity with the note. Don't stop.|Sad hearts need soft steps. Walk the note in gently.",
	[8901] = "Mulgore to the Undercity is a long haul. Load up.|Stay still. Let Elenia read it and say yes.|From Mulgore to the Undercity, the letter must fly.|Love is new for him. Share a calm breath for his nerves.",
	[8902] = "Old love, new letter. Give it all you've got.|He is too nervous to go. Stand in for him.|Years have passed. Don't let more pass. Go to Elenia.|The past is past. Let your breath go, like his old worries.",
	[8903] = "Aristan Mottar thinks love is a threat. Reps say otherwise.|The guard stands still. So do you, till he hands over the card.|Go find a guard. Go fast. Mottar is cross.|Love is in the air in Stormwind. Take a deep breath of it.",
	[8973] = "Three odd things to hand in. Reps are the fourth.|Three items, one bag. Keep the bag steady.|Gather all three before the season ends.|Lay out all three and look them over, nice and easy.",
	[9065] = "Two Kobold Vermin. Small foes, big reps.|The vermin squeak and scurry. Wait for them to come close.|Kobold Vermin scurry off. Chase them down.|Only two vermin, punk. No need to rush.",
	[9247] = "The Argent Dawn calls once more. Answer loud.|The call sounds. Stand ready for the Keeper of the Rolls.|Light's Hope Chapel is far in the Eastern Plaguelands. Set off now.|Light's Hope glows in a dead land. Find that glow within.",
	[9260] = "Three Dim Necrotic Stones from the Scourge. Work for them.|The runic circles glow. Stand at the edge and watch them.|Scourge at Stormwind's door! Clear the way to the circles.|Study the runes with a clear head. Stormwind needs answers.",
	[9261] = "Three stones from the Scourge camp by Ironforge. Dig in.|Snow and runes outside Ironforge. Wait by a circle and study it.|Undead at the gates. Go get them.|Cold air, glowing runes. Keep a calm mind as you look.",
	[9262] = "Three stones from the Scourge at Darnassus. Earn them with your reps.|The runic circles glow outside the gates. Hold and watch them pulse.|The undead camp sits on the elves' doorstep. Chase them off it.|Study the glowing circles with a calm mind. What do they mean?",
	[9263] = "The Scourge camp near Orgrimmar needs thinning. Your reps do it.|Stand firm outside Orgrimmar's gates. No undead get past this hold.|Dim stones, three of them. Race through the camp to claim them.|A Necropolis floats above. Look up, breathe, and read the runes.",
	[9265] = "Undead against undead outside the Undercity. Put reps into the fray.|The glowing circle hums under your feet. Hold your spot on it.|Weave through the Scourge. They're slow. You're not.|Quiet as the Undercity sewers. Let the runic glow tell its tale.",
	[9292] = "The crystal still pulses. Match its beat with your reps.|Grip the cracked crystal tight. Lieutenant Orrin waits at the gate.|The abomination fell. Now hurry its crystal to Stormwind.|A cracked crystal, a slow pulse. Settle your breath to match it.",
	[9322] = "Four blue fires across Kalimdor. Stoke them with your reps.|Winterspring is chilly. Hold near the blue flame and soak up the heat.|Azshara, Silithus, Un'Goro, Winterspring. That's a long road. Go.|Watch the blue fire dance at Un'Goro's gate. Let it calm you.",
	[9323] = "Four far fires in the east. Feed each one with reps.|The blue flame by Blackrock Spire burns hot. Stand your ground by it.|The Dark Portal road is far. The Flamekeeper wants you back soon.|Up on the Hinterlands cliffs, the fire burns quiet. So can you.",
	[9367] = "Stormwind, Ironforge, Darnassus. Stoke their fires with reps.|Warm your hands at the Ironforge fire. Stay put until they glow.|Three capitals, three bonfires. The tram won't wait. Hurry.|Midsummer is here. Stand by the flame and let the warmth sink in.",
	[9368] = "Orgrimmar's blaze must be the hottest. Fuel it with reps.|Up on Thunder Bluff the wind bites. Hold by the bonfire.|Orgrimmar, Thunder Bluff, the Undercity. The zeppelins are waiting.|Even the Undercity's bonfire has a gentle glow. Take it in.",
	[9388] = "Green fires go out fast. Reps keep the Barrens flame alive.|Stand guard by the Silverwing bridge. Watch the green fire.|Ratchet, Darkshore, Ashenvale, Stonetalon. The road runs on.|Emerald flames by the Master's Glaive. Sit with them a while.",
	[9389] = "Four green fires need tending. Put your reps into Westfall's flame.|On the cliff above the Westfall lighthouse, stand tall and firm.|Dun Modr to Pyrewood. Green fires won't tend themselves.|By the ruined tower in Hillsbrad, the green fire flickers softly.",
	[9411] = "Bandages don't roll themselves. Wrap up some reps.|Keep the linen tight on the spool. Hold until it sets.|Fresh bandages for the front line. Run them over.|Soak the cloth, fold it neat, and take your time.",
	[9412] = "Crystal flakes to crush for the lozenge. Grind out your reps.|Let the crystal lozenge melt. Hold on until it's gone.|The flakes chill fast. Stir quick before they freeze.|A cool crystal flake on the tongue. Breathe in the frost.",
	[9413] = "Crack the crystal, shape the lozenge. Reps get it done.|Frost creeps along the crystal. Stay frozen with it.|Winterspring cold, crystal flakes in hand. Stomp to stay warm.|Cool air, clear crystal. Let each breath feel crisp.",
	[9414] = "Roll the cloth, cut the strip. Reps for the bandage pile.|Pin the bandage down and hold it in place.|The bandage crate is empty. Dash back with more linen.|Fold the soft linen slowly. Neat folds, calm hands.",
	[9415] = "Bluewall wants recruits who can take it. Show him with reps.|The desert sun beats down. Hold out and don't dry out.|Hive'Zora is far across the sand. Get going, recruit.|Sand in your boots, heat on your back. Find a calm spot first.",
	[9416] = "Kirika needs fresh bodies for the desert. Prove you last with reps.|The dwarves gain ground daily. Hold yours at Hive'Regal.|No one will train you here. Find the General on your own.|Desert winds blow hot. Take a breath before the General's orders.",
	[9419] = "Silithyst is heavy loot. Lug it back with your reps.|Guard the Silithyst Extractor. The Horde wants it too.|Grab the silithyst and race to the Extractor before the Horde does.|The Horde got here first. Plan your path with a clear head.",
	[9422] = "Every set of hands counts. Lend yours to these reps.|The Alliance is closing in. Hold the Extractor for the Horde.|It's a race for the crystals. Beat the Alliance to the Extractor.|Heat and dust all around. Stay calm and keep the crystal safe.",
	[60863] = "This quest was never used. Your reps give it a purpose.|A quest no one ever took. Hold your spot in the empty log.|No quest giver, no map marker. Go anyway.|An empty page in the quest log. Enjoy the quiet.",
	[60864] = "Nobody ever wrote this quest. Fill it with reps.|Blank quest, blank sky. Hold on and wait for a story.|No foes and no map. Just go and go.|Nothing to do here. Let the calm settle in.",
	[60865] = "A lost quest from the vault. Dust it off with reps.|The quest giver never came. Wait for them in your hold.|Lost quests make for a fast trip. Off you go.|Silence in the quest log. Soak it up.",
	[60866] = "Nobody finished this quest. You can finish these reps.|This one sat on a shelf for years. Sit tight like it did.|A quest with no road. Pick one and move.|No words on the scroll. Fill the space with calm air.",
	[60868] = "Unused quest, unused strength. Spend some on reps.|No one to talk to here. Stay put and listen to the quiet.|The quest map is blank. Roam it at speed.|A quest made of nothing. Rest easy inside it.",
	[63769] = "The holidays are coming. Count your reps like gifts.|Wait for the feast to start. Hold until the bells ring.|The fair is in town. Go, go, go, and do not stop.|Candles lit, snow falling. A calm night for a stretch.",
	[65593] = "Carendin wants two hearts from far lands. Your reps come first.|Silverpine and Ratchet lie worlds apart. Hold that thought.|Ambermill, then Ratchet. A long trip for a warlock's lure.|Two lovers far apart who long for each other. A quiet, sad tale.",
	[65597] = "The incubus fights back. Answer it with reps.|Don't fall for its charm. Hold firm in the circle.|The demon breaks loose. Stay on it until it yields.|Carendin's circle waits below. Clear your mind before the call.",
	[65601] = "Magar misses his mate Krilge. Lend your reps to his cause.|Gan'rul is blind but sure. Hold on and trust his lead.|East from the Cleft of Shadow, down the main drag. Find Magar.|Magar longs for Krilge. Listen to his story with care.",
	[65602] = "An old figurine in an Ashenvale house. Earn the trip with reps.|Thousands of years old, the carving waits. Hold as it has.|North to Ashenvale, west past Maestra's Post. The house is near.|A keepsake of old love among the trees. Handle it gently.",
	[65603] = "Fail, and your soul is forfeit. Make the reps count.|The sayaad sees the ruse. Brace in the crypt and hold.|Down into the crypts under the Slaughtered Lamb. The gate opens.|Gakin says draw on all you've learned. Gather it now.",
	[65604] = "Krilge's scarf lures the incubus. Now beat it down with reps.|Neeru's tent, the circle, a furious demon. Hold your ground.|The incubus won't go quietly. Outlast it.|Ready your magic in Neeru's tent. One breath, then summon.",
	[65610] = "Bog beasts overran Fallen Sky Lake. Your reps clear the way.|Krilge met Magar here. Hold at the lake edge and search.|Off to Ashenvale to look for Krilge. No time to lose.|Fallen Sky Lake was their quiet place. Take in the still water.",
	[76156] = "Five Seaforium charges to pinch. Steal a rep for each.|A Venture guard looks your way. Freeze and smile.|Grab the charges and slip out of the mine fast.|Boarton sees a hidden talent. Find it in the quiet of the shadows.",
	[76160] = "Crush the Windfury Cones with the Mortar and Pestle. Grind away.|Harpies nest above. Wait under the tree until they look away.|Eight cones lie under the harpy nests. Grab them and go.|Poison is a slow art. Take it one cone at a time.",
	[76240] = "One smallfish, a set of daggers. Clean cuts, many reps.|Boarton watches you work. Keep the blade steady.|Catch a smallfish or buy one. Then hurry back to Thunder Bluff.|Don't think too hard. Do what comes to you, says Boarton.",
	[78124] = "Old Nar'thalas notes, page by page. Turn them with your reps.|The almanac is old and thin. Hold it still so no page tears.|The scholars ran their halls all day. Run with them.|Read slow. The old elves wrote for a calm mind.",
	[78127] = "The Dalaran Digest has many chapters. Match them with reps.|Mages wrote long notes. Stay put and finish the page.|Carry the Digest across town. The library awaits.|A mage's book is best read slowly. Let the words sink in.",
	[78132] = "A dragonslayer's helm is heavy. Earn the right to wear it with reps.|Stand tall under the helm. Hold, as if a dragon is watching.|Dragons do not wait. Chase down that helm before one finds you.|Set the helm down. Let the quiet before the dragon settle in.",
	[78133] = "The Dragonslayer's Shield takes a hit. So do your reps.|Raise the shield and brace for dragon fire.|Shield in hand, dash for cover.|Behind the shield, the flames can't reach you. Rest a beat.",
	[78134] = "A Dragonslayer's Lance is long and heavy. Your reps can take it.|Keep the lance level. The dragon charges soon.|Lance up, charge in. The dragon is waiting.|Aim the lance true. Calm eyes find the weak spot.",
	[78142] = "Bewitchments and Glamours holds tricks. Your reps hold more.|A glamour lasts only while you stay in place.|The spells in this book fade fast. Race to the library.|Read the charms softly, the way a witch would.",
	[78143] = "The Dreamers hid their secrets well. Dig them out with reps.|Stay in the dream a little longer.|Wake up and dash. The Dreamers' book must be returned.|Secrets of the Dreamers. Drift like a sleeper in green fields.",
	[78145] = "The Arcanic Systems Manual has many steps. Work through your reps.|Hold the manual flat. The diagrams are tiny.|Gears spin in the manual. Spin up your pace to match.|Follow the manual's lines of arcane power, one by one.",
	[78146] = "The Goaz Scrolls are rolled tight. Unroll them with reps.|Pin the old scrolls flat before they curl back.|Scrolls in your pack, head for the library at a clip.|Old ink on the Goaz Scrolls. Take in each mark.",
	[78147] = "Crimes Against Anatomy is a strange read. Shake it off with reps.|Keep a straight face while you read this one.|Get that creepy book off your hands, and fast.|Some books are best closed. Take a calm moment after.",
	[78148] = "The Sorcerer-Kings carved runes in stone. Carve your reps.|Old runes glow on the page. Hold while they fade.|The runes of the Sorcerer-Kings want out. Hurry them home.|Trace the old runes with your eyes. Take it slow.",
	[78149] = "Fury of the Land speaks of storms. Stir one up with reps.|Stand like a mountain in the Fury of the Land.|The land rumbles. Move with it.|Feel the earth under your feet, patient and wide.",
	[78150] = "A true Friend of the Library earns it. Reps for the librarian.|Stay a while in the library. The books like company.|Book returns on time, every time. Hustle.|Quiet halls, full shelves. The library's calm is yours.",
	[78261] = "Shadowfang Keep, alone. C pays well for the reps it takes.|Keep a low profile at the courtyard gate. Wait for your chance.|Veenix in Stonetalon, then the keep, then Pyrewood. Move.|No backup on this job. Just you and a quiet mind.",
	[78307] = "The horn is back. C's payment is coming. Earn it with reps.|Wait by the dead drop near Pyrewood. C will send word.|Slip away from the dead drop before anyone sees.|Job done. Let the rogue in you unwind.",
	[79007] = "Not all that burns is lost. Your reps prove it.|Hold the charred note up to the embers. Read it again.|Find the twin land, find the place. Off to the Field of Giants.|Embers darken around you. Think on the riddle.",
	[79008] = "A burnt note, a cold fire. Put some heat back in with your reps.|Up to the light with the charred note. Words creep out.|Find the twin land. Your feet know the way before you do.|Not all that burns is lost. Sit with the embers a while.",
	[79090] = "Warsong Outriders fall one by one. Your reps push them back.|The battle still rages. Hold the Moonwell.|Outriders ride fast. Match them across Ashenvale.|Felore Moonray waits by the well. Bring her a calm mind.",
	[79091] = "The unabridged life of Antonidas. Heavy book. Lift it with reps.|Antonidas has a lot to say. Keep his book open for the hold.|Rush the big book back to the library shelf.|Turn the pages slow. A great mage lived here.",
	[79092] = "Theocritus wrote it all down. Your reps fill a page too.|Steady with the journal. The ink is still wet.|Notes fly loose from the journal. Chase them down.|Read like a mage at work: slow, calm, sharp.",
	[79093] = "Rumi wrote a lot for such a small gnome. Match him in reps.|The Collected Works weigh more than Rumi. Keep them up.|Gnomes dash about all day. Dash like one.|One page of Rumi, one quiet breath.",
	[79094] = "Ta'zo teaches in lessons. This one is a rep lesson.|A good student sits quiet for Ta'zo. Hold.|Class is out. Race to the library with Ta'zo's book.|Ta'zo says a calm mind learns best. Be that mind.",
	[79095] = "Mix, stir, pour. The apothecary has reps too.|Level vial, no spills. The apothecary is watching.|The primer bubbles with odd ideas. Stir up some speed.|Deep thoughts on odd brews. Think them through slow.",
	[79097] = "Baxtan loves a big blast. Make your reps go boom.|Fire bites, says Baxtan. Hold it back.|Fire spell gone wrong! Out of the way, fast.|Even Baxtan cools down after a blast. Your turn.",
	[79192] = "Two couriers, two accidents. Count your reps and count the clues.|The note is torn and shaky. Keep your grip firm while you read.|A cozy spot waits in the mountains. Don't let the trail go cold.|Apothecary accidents? Take a calm breath and think it through.",
	[79362] = "Grant's mace is stuck in a skeleton. Rep until it's free.|Grant's shield is heavy. Keep it high for the hold.|Raven Hill Cemetery is crawling. Weave through the bones.|Grant Valor still fights. Give his spirit some peace.",
	[79363] = "Seven Night Blades, two Enchanters. Silvia wants them gone.|Silvia guarded homes. Guard Addle's Stead like she did.|Night Blades dart through the farm. Stay on them.|Silvia's spirit visits the farms at dusk. Walk with her.",
	[79535] = "Basilisks turn folk to stone. Your reps say not today.|Pretend the basilisk got you. Stay stone for a hold.|Don't meet its eyes. Just go!|Should you fear stone? Slow down and think it over.",
	[79536] = "The library knows your name now. Earn it with reps.|Stand tall among the shelves, Greater Friend.|Shelves and shelves of books. Lap the library.|Quiet, please. This is a library.",
	[79947] = "Stone-cold truth: rock does not lift itself. Reps do.|Be the stone. Cold, calm, hard to move.|Geomancers shake the ground. Shake it back.|Feel the ground under you. It has been here a long time.",
	[79948] = "Class one: shields up. Rep until the spell sticks.|Your ward is up. Nothing gets through today.|Dodge the practice bolts. Class is on.|A good shield starts with a calm mind. Lesson one.",
	[79949] = "Myth after myth falls. Knock down a few more with reps.|Stuck in a web of lies? Wait it out until it breaks.|Legends run fast. Truth runs faster.|Pick the lies apart one thread at a time.",
	[79950] = "Demons and you. Mostly you, if you do your reps.|A demon stares you down. Don't blink.|Imps are quick. Be quicker.|Demons feed on panic. Stay calm and give them nothing.",
	[79951] = "Mummies are slow. Your reps are not.|Wrapped up tight like a mummy. Hold it.|A mummy shuffles after you. Stay ahead.|Gross undead need a calm reader. Turn the page.",
	[79952] = "Murlocs only say one word. Say it with your reps. Rwl!|Murlocs gurgle all around. Don't give an inch.|RwlRwlRwl! The whole murloc camp is after you.|Learn the murloc tongue. It starts with a calm gurgle.",
	[79974] = "Dig the bag out of the soil. The reps do the digging.|The waterfall pours on. Hold as long as it does.|A stash for fleeing in a hurry. Flee like you mean it.|The mountain was carved by falling water. Let time pass.",
	[79975] = "The Eagle and Fist need a loyal arm. Rep for the old wall.|This barricade has seen better days. Stand like it still holds.|Water spray, great view. Climb the dam before it's gone.|From here you call the shots. Take in the view first.",
	[79976] = "You just missed them. Do the reps while the trail is warm.|A sleeping bag unrolls onto your feet. Freeze. Don't trip.|The author went back underground. Chase the last clue.|Last words, or one more clue? Sit with it on Thoradin's Wall.",
	[79980] = "A hundred paces north. Make your reps count like steps.|The cliff is steep. Cling on and mind your ankles.|Scramble down the cliffside. The stash won't wait forever.|Find your feet on the rocks. Slow is safe on a steep drop.",
	[81947] = "Red magic, hard work. Pour your reps into the spell.|Keep the red glyph lit. Let it glow.|The spell pulls hard. Match its pull.|Old red spells need a quiet mind. Read with care.",
	[81949] = "Tidesages pulled the sea itself. Pull your reps like tides.|A Kul Tiras dock takes the storm. Be that dock.|The tide comes in fast. Beat it to shore.|In with the tide, out with the tide.",
	[81952] = "Please, thank you, please again. Manners take reps.|A proper guest waits for the host. No fidgets.|Late for dinner! Rush, but mind your manners.|Good manners start calm. Sip your tea.",
	[81953] = "Stonewrought Dam took a lot of work. Stack your reps.|Hold like the dam holds back the lake.|The builders never stop. Stone after stone.|Plan the wall before you build it. Think.",
	[81954] = "Every sting in the book, and you still read on. Reps.|A snake is near. Make no sound.|Scorpids behind you! Go!|Travel far, step light, watch for fangs.",
	[81955] = "Gears turn, gears click. Your reps keep the engine going.|Firm, like a bolt screwed tight. That's the hold.|The clockwork is wound up. Tick, tick, tick!|A mind of metal still needs oil. Ease into it.",
	[81956] = "Conjure water, conjure bread. Conjure some reps.|The conjured bread is almost done. Hold the spell open.|The codex flips its own pages. Try to keep up.|Draw the rune slow. Rushed runes fizzle.",
	[84395] = "The potatoes rose from the grave. Put them back down with reps.|Something stirs in the potato patch. Wait for it.|Undead potatoes roll fast. Stay out of reach.|It's just a potato. Calm down, it's fine.",
	[84396] = "Magma or lava? Argue it out in reps.|The rock is hot. Stay on your spot anyway.|The floor is lava. Or magma. Either way, move!|Down below it's magma. Up top, lava. Let that settle.",
	[84397] = "Ashenvale, Darkshore, Winterspring. A rep for each land.|Wind off the coast tugs the map. Pin it flat.|Northern Kalimdor is huge. Cover some ground.|Close your eyes. Picture the forests of the north.",
	[84398] = "The Light shines on hard work. Give it your reps.|Bask in the Light. Let it shine down.|Carry the Light fast to a dark place.|A prayer to the Light, calm and quiet.",
	[84399] = "Light the fuse. Rep before it goes off.|The fuse is lit. Hold... hold...|It's going to blow! Get clear!|After the boom, the dust settles. So do you.",
	[84400] = "The knight trains for the lady. Train your reps with him.|Guard the lady's door, like a true knight.|The knight rides to his lady. Stay at his side.|A love story, told slow. Let it play out.",
	[84401] = "Undead menace or not, your reps make the case.|Plague carts are rolling. Hold the line.|A ghoul is fast, not misunderstood. Outpace it.|Think it over. Menace? Yes. Menace.",
	[84402] = "Raise the dead? Raise your reps first.|Lesson one: keep the skull from moving. Hold.|Your first skeleton got loose. Catch it!|Dark lessons need a clear head. Breathe in the dust.",
	[86574] = "Wyverns stole the bundles for their nests. Take all six back.|Pridewings circle overhead. Wait for your chance.|Faralia's inn is far up the peak. Get the goods there.|A courier fell here. A quiet moment for them.",
	[86576] = "Fifteen sunstones, and the harpies won't give them up.|Harpies love shiny things. Stay dull and quiet.|Across the Charred Vale, harpy to harpy.|Mor'rogal waits up on the hill. Climb to him calm.",
	[86585] = "Raise the banner of Ironforge. Headsplitter will come.|The standard stays high. Let the trogg see it.|Headsplitter charges. Meet it head on.|A mountaineer fell here. Stand quiet for her.",
	[86613] = "The dwarves left six tools behind. Rep them home.|The troggs are near. Wait in the dark.|Grab the tools and get out before the troggs return.|Magmar will be glad. Dust off each tool with care.",
	[86614] = "Hooks, spools, and one silver clip. Rep through the junk.|K.D. is out there somewhere. Keep the clip safe.|Find K.D. somewhere around the Loch. Off you go.|The clip shines under the rust. Some things last.",
	[86667] = "Scoop snow at South Gate Pass. Fill that jar with reps.|The snow wants out. Grip that jar tight.|Get the snow to Norric before it melts!|Norric's magic is odd. Don't ask. Just breathe.",
	[86758] = "Give Daggerfang a friendly hello. And by hello, a rep.|Daggerfang lurks at the lake edge. Let it come to you.|Scramble out quick, like Marek did!|Marek lost a knife, not a hand. Lucky. Take that in.",
	[86776] = "Ten bronze bars for Morhan. Smelt, pour, repeat.|Tongs over the fire. Don't drop the bronze.|Stoke the forge. Morhan needs more bronze.|Thelsamar is quiet at night. The forge still glows.",
	[86784] = "Dry branches, six of them. Eleanor would want more.|A basket full of wood. Not one stick falls.|Firewood to the western hills. Eleanor is cold.|Sit by Eleanor's fire and listen to it crackle.",
	[87288] = "Aldria wants six pelts. The nightsabers don't agree.|A nightsaber waits in the grass. So do you.|Nightsabers are fast. Don't let them catch you.|Dolanaar is small and friendly. Be friendly back.",
	[87760] = "The Beastmistress rules the threshers. Take her rod.|By the Ruins of Mathystra, you wait. She will surface.|Dive in after the naga. Swim hard.|The threshers should be free. Think of the open sea.",
	[90902] = "Five Deathguard wait for the Light. Work it back up.|The Light stings now. Stay in it.|The Light is rusty. Push through it.|Old skills come back slow. Let the Light find you.",
	[91208] = "The scared paladin needs a firm hand. Offer it in reps.|Hands open, feet still. Scared folk bolt at a sudden move.|Into the hills west of the chapel. Don't let him get far.|Speak soft. The lost one listens to calm.",
	[91209] = "Shari Stilwell will ask what you learned. Show her in reps.|Forsaken eyes follow a paladin on the road. Show them you are calm.|East out of Deathknell, down the road to Brill.|Tirisfal is gray and quiet. Let the road settle your mind.",
	[91282] = "Bandarion Keep was built stone by stone. Add your reps to it.|The keep sits on the bluffs, firm in the wind. Be the keep.|Past the Solliden Farmstead, up to Northface Rock. On you go.|New order, new home. Take a breath at the gate.",
	[91285] = "Eight attackers, eight seers. Knock back the Vile Fin.|The gate holds while you do. Murlocs hate a closed door.|Bluffs to the east, lake to the west. The Vile Fin are everywhere.|Seers chant by the lake. Out-quiet them before you strike.",
	[91294] = "Hilda the Breaker likes a firm grip. Greet her with reps.|Danitha Morr sizes up new faces. Stand tall while she looks.|Four people to meet, all over the keep. Make the rounds.|It isn't much yet, but it's home. Let that sink in.",
	[91316] = "Twelve pieces of lumber, up from a root cellar. Lift them out.|Brace the old beam while the keep gets its patch.|Down to Shadowvale and back, arms full of wood.|The cellar is dark and dusty. Slow down and look around.",
	[91317] = "Drudges, zealots, then Gelhardt. Strike hard for the Forsaken.|The tarnished charge. Meet them with your guard up.|Shadowvale is full of foes. Stay on the attack.|Old hate drives the tarnished. Let yours go before you fight.",
	[91723] = "Fewer geomancers, fewer surges. Hamish thanks your reps.|Hamish needs his tools still. So stand like one of them.|Kobold magic sparks at Jasperlode Mine. Get there.|The needle must settle. Let your breath settle with it.",
	[91724] = "Six Defias wizards at Stone Cairn Lake. Break their spells.|By the Nether! Keep steady till the dials stop shaking.|Round Stone Cairn Lake after those bandit spell-casters.|Hamish is close to done. Calm air helps the last reading.",
	[91725] = "Five lost packs in gnoll camps. Snatch them back.|Keep low near the campfire. Gnolls sniff out the jumpy.|Blixie fled fast. Now you run the same path the other way.|Think of Blixie, spared from mopping up after sheep spells.",
	[91732] = "Old miners swung these picks hard. Earn the right to carry them.|Deep in Jasperlode, the tunnel creaks. Brace and wait.|Four tools, deep in the mine. Down the shafts you go.|Hagar will melt them down. Good steel takes its time.",
	[91733] = "Axe, saw, toolbox. Fish them out of the river.|Stand in the stream and let the cold current pass.|Murlocs and wolves by the bank. Stay ahead of both.|Follow the river's slow bend. It knows where things went.",
	[91738] = "One shiny apple from Elwynn. Earn it with your reps.|Hold out the apple. Someone in Elwynn is eager for it.|Off through Elwynn Forest for the ripest apple. Don't slow down.|A quiet orchard, a red apple, and calm forest air all around.",
	[91740] = "Croaky ruled the roads. Merell Ross will want proof.|The Ridgepoint guards stare at the head. Stand proud.|Ridgepoint Tower is uphill. A murloc head rides along.|The roads are safe now. Enjoy the quiet.",
	[91741] = "A kobold tried to eat this book. Chew through your reps instead.|The chewed book is falling apart. Carry it level.|Rush it to the abbey before more gets eaten.|Brother Paxton loves his books. Be gentle as a turned page.",
	[91743] = "Pry eight stolen books out of kobold paws.|Guard the stack you saved. Kobolds want seconds.|Kobolds scurry off with the pages. Chase them down.|Paxton's library, back on the shelf, spine by spine.",
	[91745] = "Kelsey Fargo swings a pick all day. Match her.|By the Echo Ridge Mine, wait and listen for kobolds.|Out to Echo Ridge. Kelsey has news of the kobolds.|Mining starts with a calm look at the rock.",
	[91746] = "Elmpaw fell to you. Helene Peltskinner will want the tale.|Hold up the trophy so all of Goldshire can see.|Carry the trophy along the road to Goldshire.|Good hunts end in good stories. Tell it slow.",
	[91751] = "Seven rough pelts for Helene. Earn them wolf by wolf.|Wolves circle in Elwynn. Stay set as they close in.|Wolf tracks cross the forest. Follow them far.|Skinning takes a steady hand and a calm mind.",
	[91752] = "Picture for Narf! Not anymore. That sack is going home.|The kobolds deep in the mine are meaner. Stand your ground.|To the back of the mine, where Narf hoards his books.|Bring a friend, take a breath. Narf is waiting.",
	[91753] = "Three bits of glowing dust from kobold wax dolls. Get them.|Steady with the wax doll. Its magic leaks out slow.|Geomancers carry wax dolls. Chase them through the mine.|Kitta says kobolds learn by doing. So do you.",
	[91758] = "Somewhere out there, a kobold hauls a sack of books. Get ready.|Tordrin Sternblade waits by the stable. Hear him out.|Behind the abbey, by the stable, the hunter waits.|Hunters wait before they track. Learn that first.",
	[91772] = "Six sets of tracks. Read them all, then find Dughan.|Shhh. Stay by the tracks and make no sound.|The tracks lead out of Northshire. Follow them to Goldshire.|Soft steps, quiet breath. Kobolds have big ears.",
	[91775] = "Lost books, and one on elementals. Take them all back.|Fargodeep's depths are dangerous. Hold the tunnel with friends.|Deep into Fargodeep Mine, before a kobold reads the wrong page.|Tuck each book in the bag. Gentle hands, calm head.",
	[91777] = "The kobold master guards the last two books. Take them.|If the master calls up something big, stand firm.|Paxton's list has two books left. Into Jasperlode!|Every book home at last. Paxton can finally rest easy.",
	[91858] = "Earthen Ring guests went missing. Prove your worth to the Horde.|The Horde is watching, paladin. Give them nothing to doubt.|South to The Sepulcher. Trevan Rol is waiting for you.|Lost guests, big stakes. Think clear before you set out.",
	[91859] = "A tauren and a high elf? Trevan bets his pinky on it.|Baldren guards the town gate. Keep him company while he talks.|Across The Sepulcher to the entrance. Baldren saw something.|An elf with a tauren. Turn the puzzle over slowly.",
	[91860] = "Brave or stupid? Take on the gnolls of Fenris Isle.|Watch the pyre from the shore. Count the gnolls first.|Fenris Isle lies east. A lost cause worth the trip.|Baldren says it isn't worth it. Weigh that, then go anyway.",
	[91861] = "Only one body found. The elf may still live. Push on.|Stop in the dark hall and listen for a voice.|Deeper and deeper into Fenris Keep.|Hope is a small thing. Carry it quietly inside the keep.",
	[91862] = "Rot Hide gnolls hold the key. Lumina waits in her cage.|Guard the cage while Lumina counts the gnolls.|Beat the gnolls near the cage, grab the key, and get out.|Lumina will tell the rest once you are safe. Wait for it.",
	[91920] = "Renferrel wants three murloc eyes. Lordamere's shore has plenty.|Renferrel stares at you. Don't blink first.|Along the lake shore, murloc to murloc.|Hearts, hearts, hearts. Bring eyes, and hope he likes change.",
	[91921] = "The potion holds six whole hearts. Put yours in too.|Quinn needs every drop. Don't tip the vial.|North to the Ivar Patch before the potion goes flat.|No more paperwork, please. Slip out quietly.",
	[92109] = "Vials, Silverleaf, Peacebloom. Five of each for the kid.|Bees buzz on the Peacebloom. Let them pass first.|Herbs are spread across Westfall. The kid is counting on you.|Someday this kid will be a real alchemist. Smell the flowers.",
	[92110] = "Gross? Yes. Three murloc eyes for the barn in Moonbrook.|Murloc eyes in a jar look back at you. Don't flinch.|Murlocs gurgle on the Westfall coast. Pay them a visit.|Slow mixing turned the potion red. Take your time too.",
	[92124] = "Daniel talks trade skills. Count books instead.|Daniel will prattle. Stand there and steer him back.|Across the library to Daniel. Don't let him start.|Take stock, like Daniel should. How many books are gone?",
	[92401] = "Edward went to the graveyard and never came back. Find out why.|There are things in the ruins. Wait at the gate and brace.|Search the Ruins of Lordaeron for Edward.|Edward's wife waits for news. Carry her worry gently.",
	[92415] = "This torn letter speaks of a lost child. Take it to the matron.|The letter barely made it this far. Don't crumple it.|From the ruins all the way to Stormwind City.|Some words are heavy. Read them, then breathe.",
	[92421] = "Twenty-five limbs for Morbin Lightbane. Grim work. For Lordaeron!|The scourge roam in great numbers. Hold the line.|The ruins are big and the sack is light. Fill it.|Garek Bandarion would be proud. Remember him quietly.",
	[92422] = "Rath'mael calls up fog. Strike through it.|Fog hides the scourge. Stay set until Rath'mael shows.|Through the Lordamere Overlook, into the unholy fog.|Summon your allies, clear your head. Then drive him out.",
	[92454] = "Dalia Windbreeze has a gift for you. Earn it.|Dalia is finding your little friend. Wait right there.|Off to Thendal Grove with the voucher in hand.|Your little companion is here. Adventure starts small.",
	[92460] = "You come of age once. Start strong for Rorian.|Nerves and excitement. Stand in both and wait your turn.|West to the greatfather tree. Rorian is waiting.|Ailee smiles kindly. Smile back, and breathe in the grove.",
	[92461] = "The vuldren grew too many. Eight fewer sets the balance.|Balance is the whole point. Find yours and stay there.|Young vuldren roam the east grove. After them.|All creatures share the grove. Keep the harmony inside you.",
	[92462] = "Swat eight pesky cirrusflies out of the air.|The swarm buzzes past. Stay put and let it come to you.|The swarm grows at the far end of the grove. Get over there.|The swarm buzzes. You don't. Be the calm one.",
	[92463] = "The Cirrusfly Queen hides by the hive. Put her down.|Her soldiers are big and mean. Wait for an opening.|Past the soldiers, through the forest, to the queen.|One less problem after this. Picture it done first.",
	[92464] = "The wind sprites are upset. Show Yala you're ready.|The wind pushes at the stones. Don't let it move you.|Northeast to the standing stones. Yala is there.|Wind sprites copy your mood. Give them a calm one.",
	[92465] = "Seven converts, six winds. Send the Al'Aketh a clear message.|Roiling winds push hard. Don't give an inch.|Converts and winds all over the grove. Go after them.|The sprites were calm once. Help them find it again.",
	[92466] = "Drive off the Al'Aketh at the stones. Bring back a signet.|Earth asks for a strong will. Show it with a hold.|The cult gathers at the eastern stones. Get moving.|Your first trial starts here. Be sure of your resolve.",
	[92467] = "The Rise of Spirits is up the pass. Earn the view.|Drink the Earth Sapta. Be still as the stones around you.|Up the pass to the northeast. No stopping on the climb.|A sacred place, a sacred drink. See what you need to see.",
	[92468] = "Small quartz, strong heart. Size does not matter.|Be patient. Remain strong. The earth outlasts all.|Back down to Windshaper Boro with the Rough Quartz.|Seek wisdom, the earth says. Respect it back.",
	[92469] = "The cult is here. Rorian will not be pleased. Tell him.|Face Rorian and give him the bad news straight.|Hurry to the Village with word of the Al'Aketh.|Bad news goes down better when told calmly.",
	[92470] = "Thin the den by eight. Then Urs'anah. Rep them down.|Urs'anah waits in the cave. Hold your ground when she comes.|South to the caves, fast. The den will not thin itself.|Aetheen is watching. Show her a calm hand before the den.",
	[92471] = "Aetheen has a test. Warm up with reps first.|A leader of Zephras is looking your way. Stand tall.|The grove is small. Get to Aetheen fast.|Big island, big trials. Take a calm breath first.",
	[92472] = "The cult threatens Shen'dar. Aonda needs you ready. Reps now.|Tell Aonda who sent you. Hold that name in your head.|South to Shen'dar Village. The road is long, so go.|The Windlord's zealots are loud. Be the quiet one.",
	[92473] = "Six scrawny claws. Six scrawny ursera. Get to your reps.|A boy nearly met an ursera here. Guard the elder tree.|Hungry ursera roam the den. Keep them on the run.|Even a scrawny ursera has claws. Stay calm and watch.",
	[92474] = "Up the watchtower steps you go. Count them as reps.|On the ledge. Wait for the wind. Rorian has no idea.|Float forward on the air. Land right before Rorian.|Walk on air. Soft and light, like a leaf in the wind.",
	[92479] = "Tordrin Stemblade sealed this letter. Earn the read in reps.|Keep still in the Abbey and read the letter through.|Back from the kobold camps and off again to Tordrin.|Break the seal. Read slow. The Abbey can wait.",
	[92480] = "The cultist dropped orders. Your reps carry them to Shen'dar.|A spy hides in Shen'dar. Keep the orders close and wait.|Shen'dar must hear of Falaath. Off you go, and quick.|Spies watch the road. Walk it calm, like you know nothing.",
	[92481] = "Warm the mind for Dorii. Reps first, crystal after.|The Glowing Recall Crystal hums. Stay put till it ends.|Dorii is just behind you. A short dash to class.|Let the crystal glow. Let your mind go quiet with it.",
	[92482] = "Tai'ree trains hunters. Reps are the first lesson.|A hunter waits in the grass. Hold like Tai'ree taught.|Tai'ree is near the center of the village. Go find her.|Read the note slowly. A hunter sees every mark.",
	[92483] = "Akeri Duskblade likes quiet work. Do your reps soft.|Shady folk wait in the dark. Wait with them.|Up to the watchtower. Quick feet, no sound.|Read the note. Then fade into the shade.",
	[92484] = "Boro's crystal calls. Your reps answer.|The crystal hums. Stay firm like a standing stone.|Boro waits near the center. Blow through town like wind.|The elements speak soft. Let the wind fill you with Boro.",
	[92485] = "Silverwind can teach you much. Start the learning in reps.|Roots deep, branches high. Be the great tree.|Down to the ground floor of the tree. Silverwind waits.|Heed his words. Grow slow, like the tree above you.",
	[92514] = "Two folks to greet in Shen'dar. Get your reps in between.|Feel the static on your skin? Hold it in.|Illaya first, then the inn. Shen'dar is a busy town.|Coriella runs the inn. Picture a soft bed and rest easy.",
	[92515] = "Ten Prideclaw pelts. The hills get quieter with your reps.|Prideclaws creep near the village. Guard the border.|The Shen'dar Highlands are thick with cats. Chase them off.|A prideclaw stalks slow. Match its calm, then strike.",
	[92516] = "Eight youths, six guards, one matriarch. Reps for the lot.|Wings beat all around the nest. Stand your ground.|Hippogryphs dive at the road. Outrun their shadows.|Watch the matriarch glide. Move as smooth as her wings.",
	[92517] = "Badwind Bennic and ten bandits. The cave waits on your reps.|Behind the waterfall, the bandits hide. Wait for your moment.|Through the falls and into the cave. Don't let Bennic flee.|The waterfall roars. Be the calm under the noise.",
	[92528] = "A good recruit works hard. Reps keep your cover in Falaath.|Keep to the square like a true believer. Stay out of the way.|Wander Falaath Village. Look busy. Hear everything.|Skip the inn. Keep your face calm and your ears open.",
	[92529] = "Wear the Mark of Akir well. A recruit does reps.|Missionary Jasaan waits by the gate. Be there like you belong.|On to Falaath Village. Don't lose the mark on the way.|Look humble. Let the wind think you are one of its own.",
	[92532] = "Blademaster Ren wants you. Bring reps to the tower.|Ren is in the tower. Be firm like her blade.|Read the note, then off to the tower. Ren does not wait.|A calm mind cuts clean. Ren will test that.",
	[92544] = "Brutes, neophytes, then Malduko. Count them all off.|Cloudcrush is a real monster. Plant your feet and face him.|Travelers are leaving the grove. Beat the thugs to the road.|The temple ruins are old and still. Let that stillness in.",
	[92550] = "Strike first. Six stormcallers fall to your reps.|Living Lightning crackles. Brace in the storm.|Back to Falaath, fast. Hit them before they hit Shen'dar.|Cyclas has guards. Wait for the gap, then go for him.",
	[92551] = "Stolen packs, ten of them. Lift them back one by one.|Full packs are heavy. Keep them up and don't drop one.|Grab the packs and go. The cult is all around.|Look in every corner of Falaath. Food, stones, all of it.",
	[92553] = "Three eggs and eight strider cuts. The village is hungry.|A strider will walk by soon. Be ready in the grass.|Striders are fast. Chase them over the highlands.|Eggs break easy. Soft hands, calm mind.",
	[92579] = "Valanaar must get ready for a fight. So should you. Reps.|Hold Aonda's letter tight. Valennia needs every word.|To the far southeast edge of the island. Long road. Go.|Shen'dar is safe for now. Let that sink in.",
	[92595] = "Illaya sees skysight in you. She'd like to see reps too.|Stay put while Illaya speaks of the Windshapers.|Winds never stop. Neither does a child of the winds.|Illaya smiles warmly. Let her calm become yours.",
	[92596] = "Rathiril feels arcane power in you. Let it out as reps.|Take the seat Rathiril offers. Do not stir.|Arcane power hums around you. Let it spill out.|Rathiril talks of old magic. Listen and let it sink in.",
	[92597] = "The ley line pulses under the stones. Pulse along in reps.|At the stones, draw the ley line in and keep it.|Northeast to the standing stones. The ley line is waking.|Arcane power rises through the ground. Let it fill you.",
	[92598] = "Skysight is a gift. Pay the spirits back in reps.|At the convergence, stay put and let the spirits come.|The standing stones are close. Get there while the sky is clear.|Close your eyes and see the sky. Wisdom drifts in.",
	[92640] = "Windshapers, High Order, peacekeepers. Reps for all of them.|Valennia has a plan for the Shrine. Stay firm while she shares it.|Recruit both orders. Back and forth across Valanaar.|Two old rivals must work as one. Find the calm to ask them.",
	[92642] = "Four cult menders, eight brawlers. Knock the count down.|Her people can't hold much longer. You hold for them.|Down the hill into the Gustberry Lowlands. Break their line.|They sent just one. Make that one count, calm and sure.",
	[92643] = "The turncoat wants safety. Reps say you can give it.|It might be a trap. Wait by the house and watch.|Northwest into the highlands. Quiet feet, quick pace.|Go in soft. A secret this big needs a quiet hand.",
	[92644] = "The turncoat fell. His crystal still glows. Reps, then go.|Hold the cracked crystal close. It may still matter.|To Talanaanis Shadowsong in Valanaar. The glow is fading.|A plan went wrong. Take a calm moment before the news.",
	[92645] = "Belguilos the Breaker. Break her first with your reps.|She was a peacekeeper once. Be firm like one now.|To the villa at the hill's base. The Breaker is waiting.|They say she was always off. Be the steady one.",
	[92646] = "Lorthuna fled up the spires. Your reps follow her.|Through the portal, you may be on your own. Brace yourself.|Ayessa and Elaadrin went ahead. Catch up to them.|The Rohashi Spires loom high. Look down once, then ahead.",
	[92679] = "Alvarion came for fighters. Let your reps say you are one.|Alvarion winces as he talks. Stay and hear him out.|West of Valanaar to the orchard. Aamelia is waiting.|A farm needs saving. Think it over, then walk west.",
	[92682] = "Work for your meals: ten stormapples, five bandits.|The bandits think they are sneaky. Wait for one to show.|Tree to tree across the orchard. Apples in, bandits out.|Ripe stormapples bruise easy. Go gentle.",
	[92683] = "Five piles of dust. Your swatter has work to do.|Wait for the flutterfly to shake its rump. Dust incoming.|Some flutterflies take offense. Be ready to dash off.|Big bugs, soft wings. Move as light as they float.",
	[92684] = "Seven tenderloins for a hot meal. Earn every bite.|One kick puts you down. Brace and watch their legs.|Galestriders raid the orchard. Chase them through the fields.|Bigger and angrier than the highland kind. Stay cool.",
	[92685] = "Catch the bandit camp off guard. Seven masks to bring back.|The hills have eyes. Lie low until they look away.|Up the hills north of the orchard. Hit them first.|Even the odds with a clear head before the camp.",
	[92693] = "Last chance to walk away. Answer with reps instead.|Heads held high. Hold with Aamelia and don't give ground.|Follow Aamelia out to face the bandit leader.|Whatever happens, happens. Make peace with it first.",
	[92698] = "Function error, says the construct. Your reps work fine.|Stay close to the construct and listen to it hum.|The words repeat and repeat. So can you, all the way to Aamelia.|What is my purpose? A fair thing to wonder, quietly.",
	[92699] = "Elaadrin leads the High Order. Arrive with reps done.|Windshapers pass by. Give them a wide berth and stay put.|To the lodge on the far southeast side of Valanaar.|No fights in the streets. Stay cool as you pass the Windshapers.",
	[92700] = "Reps before you greet the Grand Skyseer.|The High Order keeps its distance. Keep yours and stand tall.|The lodge sits near the center of Valanaar. Head in.|Faction fights are banned here. Carry peace to the lodge.",
	[92701] = "The peacekeepers must fight now. Warm them up with your reps.|Keep Aonda's pages sealed. Valennia reads them first.|Across the island to Valanaar. The cult grows fast.|You will always have friends in Shen'dar. Carry that along.",
	[92703] = "Alvarion needs a windshaper. Earn the news with your reps.|Aamelia has a secret. Hold it close and say nothing yet.|Valanaar is a long road. Carry the news there on foot.|Tell Alvarion calmly. Some news can wait for later.",
	[92706] = "Bruuz eats small boats. Your reps say you are no small boat.|Bruuz circles the dock. Wait for the fin to break the water.|Into the water after the fin. Don't let Bruuz turn.|Sharks smell panic. Float calm like a log on the tide.",
	[92708] = "The wind spirits are missing. Ayessa needs help. Show her reps.|Ayessa has a plan. Stay and listen to all of it.|Save the island? That is a lot of ground to cover.|Surprising finds, Ayessa says. Clear your head for them.",
	[92709] = "Elaadrin sees a highborne in you. The reps should match.|Elaadrin speaks of Zephras and beyond. Stay put for it.|Beyond Zephras sounds far. Start moving now.|Clear as the sky above. Let your mind match it.",
	[92727] = "Fillion went looking for wind magic. Reps while you look for him.|Pause on the road and look close. Something happened here.|West from Valanaar along the road. Fillion is out there.|Seek knowledge, the High Order says. Seek Fillion first.",
	[92741] = "Iaadaria wants eight shriekling talons. Reps will get them.|Shadowgale Forest is dark. Wait for the shriek, then strike.|Into the woods. Hunt the shrieklings down.|Many shrieklings, many talons. Stay calm in the dark.",
	[92742] = "Two wells, two samples. Fill the kit with your reps.|Keep the sample kit level. Spill it and you start over.|Jansen Stead to Molsen Farm is a long road. Get going.|Look down the well. Wait for the water to settle.",
	[92744] = "Seven murlocs, seven gills. Alba wants them all.|The murlocs gurgle on the shore. Stay put and wait.|Murlocs are quick on wet sand. Chase them down the coast.|Sea air, soft waves. Take it in before the murlocs spot you.",
	[92745] = "Four kobolds, six gnolls. Swing like a miner, but harder.|Jangolode Mine is dark and tight. Brace in the tunnel.|North mine, west quarry. The miners won't stop, so neither do you.|Candles flicker in the mine. Be as soft as their light.",
	[92747] = "Eight crates of odd supplies. Moonbrook won't miss them.|A Defias guard walks past. Freeze in the shadows.|Moonbrook is full of eyes. Grab the goods and go.|Quiet steps through Moonbrook. Calm and slow, like a spy.",
	[92748] = "Stormwind needs an engineer. Warm up for the long road.|Wait at the Dwarven District gate. Someone will wave you in.|Westfall to Stormwind. The road won't walk itself.|Smell the forge smoke of the Dwarven District. Settle in.",
	[92749] = "Ten sticks of Coarse Dynamite. Sprite counts them all.|Dynamite in both hands. Don't shake.|Hunt down ten sticks before Sprite gets bored.|Handle the powder with calm hands. Sprite likes her limbs.",
	[92750] = "SI:7 sizes you up. Give them something to count.|Stand in the shadows of SI:7. They see you anyway.|Down to Stormwind Intelligence. Quick, before Sprite changes her mind.|Spies speak softly. Match their calm.",
	[92751] = "A prototype detonator. Lift it with care and pride.|Don't press the button. Keep the kit steady.|Carry the kit to Sprite before SI:7 wants it back.|Say nothing to the elf. Keep your secret with a slow breath.",
	[92752] = "A bomb for Alba. Heavy and ready to go.|Careful with that detonator. Not a twitch.|Back to Westfall with a bomb. Don't trip.|Easy on the bumps. The bomb is watching.",
	[92753] = "Plant the charges by the forge. The Deadmines will shake.|Hide by the great forge. Wait for the guards to pass.|Charges placed. Now get out of the Deadmines, fast.|Deep in the mine, the forge roars. Stay calm beside it.",
	[92819] = "Weeks of work, one button. Make it count.|Finger on the switch. Wait for Alba's nod.|Feel the ground roar under Moonbrook. Don't stop now.|The forge is gone. Westfall can rest easy, and so can you.",
	[92834] = "Ten cultists, ten charms. Belathaan is owed that much.|The Shrine of Akir is close. Hold your ground.|Gustberry Fields to the Shrine. Chase every cultist.|Anger makes bad swings. Cool it before you go.",
	[92840] = "Six windstone formations. Read them all with the Index.|The Index Esoteria hums. Keep it still while it reads.|Windshapers guard the stones. Move from one to the next.|Feel the wind at the Overlook Standing Stones. Let it pass.",
	[92849] = "Fillion is heavy for a scholar. Lift him out.|Shrieklings nearby. Hold Fillion tight and stay low.|Out of the cave with Fillion on your back. Go!|Find Fillion first. Look slowly around the cave.",
	[92850] = "The Shriekling Matriarch nests near Valanaar. Not for long.|Her shriek fills the den. Don't let it move you.|Back into the Shriekling Den. Take the head, then head home.|Quiet your mind before the den. She hears everything.",
	[92860] = "The High Order stands with Valanaar. Show Valennia that strength.|Stand tall before Valennia. The High Order is behind you.|The cult is gearing up. Carry the news fast.|A promise of support. Speak it calm and clear.",
	[92871] = "The Windshapers pledge their might. Put yours in too.|Valennia's peacekeepers stand firm. Stand with them.|Rumors of cult moves. Get the word to Valennia.|Like the wind, the Windshapers go where needed. Drift with it.",
	[92880] = "Yorna's report is in your pack. A hero's load.|The watchtower is stable now. So are you.|Valanaar waits for good news. Let your feet fly.|May the four winds bless you. Let them cool you on the road.",
	[92881] = "The cult wants the anchor pylons. Get ready to stop them.|High Elder Shadowsong takes his time. Wait on his word.|A promising lead. Hurry to Shadowsong.|Think of the watchtowers. Let the clues settle.",
	[92909] = "Ozwin needs parts. Take them from the harvesters.|Ozwin hides in the stable. Stay put with him a bit.|The harvesters chase fast. Chase them faster.|Pick the springs out with a calm hand.",
	[92910] = "A shiny harvester part. Lift it up for Ozwin.|Keep the assembly still. It might still twitch.|Rush the part to Saldean's Farm.|Look it over slowly. What makes these things tick?",
	[92911] = "Eight springs, four parts, one scope. Ozwin wants your reps now.|A golem swings its big arm. Stand firm and let it miss.|The fields of Saldean's Farm are full of golems. Do not slow down.|Ozwin works with calm hands. Take a slow breath, just like him.",
	[92947] = "Guardians, Spiritcallers, Blademasters. Seven of each fall.|The front line holds the shrine gate. Hold with them.|Round the flank and up the steps to Hyusaa!|Before the charge, one calm breath. Winds guide you.",
	[93036] = "Sania wants new followers. Look keen and eager.|Smile at Sania. Don't let your face give you away.|Get close to the cult, fast, before the peace breaks.|A spy stays easy and calm. Play the new face in town.",
	[93065] = "Last chance to get ready. Make it count before the march.|The Peacekeepers wait on the eastern road. Stand in line.|Out to the Gustberry Lowlands. The army moves soon.|One last check-in. Settle your nerves by the road.",
	[93089] = "Zephras says thanks. Go out with a bang.|Stand with Elaadrin. The trip to Dalaran awaits.|A new world waits. Get ready to leave Zephras Isle.|Look back at Zephras one more time. Take it all in.",
	[93090] = "The Earthen Ring calls. Show Ayessa you're ready.|Ayessa waits by the shore. Stay near her.|Pack up. The Windshapers leave the island soon.|Winds be with you. Let one last island breeze pass by.",
	[93159] = "The hermit is rusty at talking. You are not rusty at this.|He shifts about. You stay still and patient.|Keep the talk going. He hasn't had a chat in ages.|How is your day going? Pause and really think about it.",
	[93160] = "Eight acorns off the forest floor. Scoop them up.|A raptor-bird stalks past. Don't be its lunch.|Acorn to acorn across Shadowgale Forest. Stay ahead of the birds.|The hermit promised something tasty. Think of that, nice and slow.",
	[93165] = "The Nightclaw pays for proof. Ten cultists, ten debts.|Wait in Shadowgale's shade for the next cultist.|Forest, shrine, lowlands. The cult is everywhere. So are you.|Earn the Nightclaw's trust with calm, sure moves.",
	[93172] = "Ten Wind Hollows trapped in a sad song. Set them free.|Their song is so sad. Stay and listen a while.|Race from hollow to hollow in the old ruins.|Let the hollows' song fade into a soft sigh.",
	[93173] = "A rusty gadget from a Wind Hollow. Lift it for the hermit.|Grip the gadget. Rust flakes, but it holds.|The hermit in Shadowgale will be thrilled. Hurry over.|Turn the gadget over slowly. What could it be?",
	[93317] = "Six crawlers, six bits of meat. The season is short.|Windsong Crawlers snap. Stay firm on the shore.|Along the lake and down the rivers. The window is closing.|Windsong Lake is calm. Match it before the crabs get mean.",
	[93318] = "Danarii wants Vulgara's head. Earn the bounty.|Winged terror above. Stay low until she lands.|Up the hilltop southwest of Shen'dar. Don't slow down.|Approach with caution, says the poster. Take your time.",
	[93319] = "Knock bandit heads. Ten windstones come back.|The bandit cave is north. Wait at the mouth.|Chase the bandits through the highlands.|Steady hands take back what was stolen.",
	[93320] = "The watchtower is under attack. Bring all you have.|The defenders are holding on. Hold on with them.|Go now! The east tower needs you.|Clear your head on the way. Yorana needs calm help.",
	[93461] = "A new face in Shen'dar Village. Make a strong first mark.|Wait in the main lodge for Rathiril Sunlance.|Lodge, then inn. Get around the village.|Coriella's inn is warm. Rest by the fire.",
	[93552] = "Fifteen windstone clusters. Break them loose.|Raw windstone hums with wind. Hold firm as you pry.|Stone to stone around Thendal Grove.|Feel the old wind in the stones. It is fading slowly.",
	[93735] = "A damaged construct in Valanaar. Get to work.|The artisan may need a hand. Stand by.|West end of the city. Go see what's wrong.|Gifts of the wind spirits still hum here. Listen.",
	[93736] = "Scatter the hollows and gather what's left.|Shadowgale is haunted. Don't let the hollows spook you.|Dash through the dark woods. The hollows drift away.|Why did the spirits leave? Let the question drift.",
	[93737] = "Lightning, gyrozephyr, core. Riaani wants all three.|Riaani has his head in the construct. Wait for him.|Cave, lake, bandit camp. It's a busy trip.|Listen to Riaani. A novice learns by being calm.",
	[93738] = "Brightwish took the parts. Ayessa must know.|The High Order is too bold. Stand firm against them.|Ayessa needs this news. Don't dawdle.|Too bold by a mile. Be the calm one instead.",
	[93739] = "Vol'jin, Cairne, Sylvanas. Three leaders to impress.|Stand proud in Grommash Hold. Nazgrel is watching.|Orgrimmar, Thunder Bluff, Undercity. A long trip.|Each city has its own ways. Take them in slowly.",
	[93740] = "Ten charms from the Al'Aketh. Windshapers do not forget.|The Gustberry Lowlands are quiet. Too quiet. Stay ready.|North into the lowlands. Hunt the cult.|Grief first, then the fight. Let it settle.",
	[93746] = "Send Belathaan home with a few bruises.|Block the road to the Shrine of Akir. He must pass you.|Catch Belathaan on the north road before he gets away.|Put fear in his heart, not in yours.",
	[93791] = "Time for a spell focus of your own. Prove you're ready.|Belann has made staves for ages. Wait your turn.|Off to Valanaar. An old tradition awaits.|A young mage grows calm before the craft begins.",
	[93797] = "A large bough from the oldest trees. Haul it back.|The branch still holds the wind. Grip it firm.|South of Falaath Village to the wind shrine. Off you go.|Old trees sway by the wind shrine. Sway with them.",
	[93835] = "High Priestess Lorthuna waits in the spires. End her plans.|Through the portal, then brace for Lorthuna's storm.|Up to the Rohashi Spires! Elaadrin can't wait.|You are on your own now. Gather your nerve.",
	[93836] = "Al'Akir can see Zephras now. Be ready for him.|The wards are down. Don't waver while Shadowsong listens.|Hurry to Valanaar. Shadowsong must know.|We will save our home. Say it softly and mean it.",
	[93926] = "Tell Vaaniel to pull back. Lives matter more than towers.|The tower is under attack. Stay firm until Vaaniel hears you.|Southwest to the watchtower. Hurry!|Clear orders need a calm voice. Find yours.",
	[93927] = "The note asks for one last deed. Do your reps for the fallen guard.|Raani's feather is light. Keep it safe and do not let it fall.|The note points the way. Go now, while the trail is warm.|Read the note again. Let the calm come before you act.",
	[93928] = "A mouse wants a cookie. Earn it with your reps, see?|The mouse waits for his cookie. You wait with him. Nyeah.|Off to find a cookie. The mouse will not ask twice.|Cookie first, milk next. Take it easy, like a well-fed mouse.",
	[93948] = "A ring for Talaanis. Carry the bad news with strong reps.|The signet sits heavy in your pack. Stay firm, like his good name.|Valanaar is not far. Get the ring to the High Elder.|Sad news for a good man. Find the right words on the way.",
	[93949] = "Eight bugs to squash. Count them off with your reps.|The bugs are listening. Stay quiet and give them nothing.|Skyhoppers hop fast. You have to be faster.|Quiet now. Any bug could be a spy for the cult.",
	[93951] = "Eight soft feathers. Pick them up one by one.|A hippogryph is watching its nest. Do not move.|The hippogryph spots you. Grab the feathers and go!|Down feathers drift slow. Be as soft as they are.",
	[93958] = "The sanctum went quiet. Get ready with a few reps.|Too quiet in here. Keep your guard up and wait.|Valennia's forces are inside somewhere. Find them fast.|Step soft into the shrine. Listen for Valennia.",
	[93963] = "Three leaders, three cities. Your reps say hello to all of them.|King Magni likes a firm stance. Show him yours.|Stormwind, Ironforge, Darnassus. Quite the trip. Get going.|Tyrande's temple is calm. Take a bit of that calm home.",
	[94003] = "Zaal holds a shield he does not deserve. Take it back.|The Bulwark guards a worthy wielder. Stand firm and be one.|Up to the Shrine of Akir. Zaal will not wait for you.|The last Skybreaker is counting on you. Stand tall for the line.",
	[94004] = "The buyer wants ogre strength in a bottle. Show them yours.|Hold the vials steady. Spilled elixir pays nothing.|The delivery spot is marked. Get the elixirs there.|Mix with care. Even ogres wait for the brew to settle.",
	[94006] = "Urs'endris waits by the falls. Show him the bear in you.|A bear sits still by the water. Be that bear.|Northeast, to the falls! The spirit's land is falling away.|Hear the falls. Let the great spirit's calm reach you.",
	[94007] = "A pet of your own is close. Get ready for it.|Wait at the port for Quel'ana. Pets need patience.|Off to Valanaar! Your new friend is out there.|Calm hands. Calm heart. Beasts can tell.",
	[94013] = "The Vuldren Alpha is strong. Match it before you tame it.|Keep the Taming Rod up. Don't let the Alpha break free.|Off to the Gustberry Lowlands. The Alpha won't come to you.|Calm the beast by first calming you.",
	[94049] = "Quel'dora trains beasts. Show him you can train too.|Beasts learn to wait. So should their master.|Find Quel'dora in Valanaar. Quick now.|A good trainer is patient. Take a slow, calm pause.",
	[94050] = "Your pet will learn tricks. You learn some reps first.|Sit, stay. Your pet will learn it. Show it how.|Go with the winds to Quel'dora. She is waiting.|Go with the winds, young one. Slow and easy.",
	[94212] = "Wise folk count well. Count your reps for the Elixir of Wisdom.|A wise mind waits. Let the elixir cool.|The writ says where. Wisdom says go now.|Take in the smell of the brew. Let your mind go clear.",
	[94213] = "Mages run dry. Your reps fill the potion rack.|Keep the flask level. Mana spills are hard to clean.|A thirsty mage waits at the mark. Hurry with the potions.|Blue swirls in the glass. Watch it and let your thoughts slow.",
	[94214] = "Shadow magic is coming for the buyer. Brew hard for them.|Dark potion, firm hand. Wait for the shadows to settle.|Shadows move fast. So does a good courier.|Dim the lamps and let the dark brew rest.",
	[94215] = "Free Action means no one can pin you down. Prove it.|Funny, a Free Action Potion and you stuck in place.|Nothing slows you with this brew. Go, go, go.|Loose and free, like the potion says. Let it all go.",
	[94216] = "Quick hands make this brew. Show quick reps too.|Agility is also balance. Stay put like a cat on a fence.|Light on your feet. The buyer wants it fast.|Soft and quick, like a thief at night. Start soft.",
	[94217] = "Trolls never quit. Neither should your reps.|Hold on like a troll who just won't go down.|A troll could go all day. Try to match one.|Troll's Blood takes time to brew. Give it that time.",
	[94218] = "Tough skin in a bottle. Build your own with these reps.|Defense is all about standing your ground. Stand.|Deliver the Elixirs of Defense before the buyer needs them.|Guard up, mind calm. A good fighter knows both.",
	[94219] = "Someone plans a deep dive. Stir the brew with your reps.|Hold like you're under the waves. The draught will help.|Rush the draughts to the drop-off. Stay dry this time.|In through the nose, out slow. Practice before the dive.",
	[94220] = "Hammer the blade, set the pearl. Reps make the dagger.|Keep the pearl in place while the glue sets.|A fancy dagger for a fancy buyer. Get it there.|Pearls come from the calm deep sea. Find that calm.",
	[94221] = "Gold is soft. Work it into a rod with steady reps.|The rod must cool straight. Stay as still as it does.|A Golden Rod won't deliver itself. Take it to the mark.|A shiny rod, a quiet shop. Enjoy the glow.",
	[94222] = "It's a hammer. You know what to do. Reps!|Hold the hammer high. Watch the colors shift.|The buyer wants the shiny hammer now. Move it.|Colors swirl on the head of the hammer. Let them calm you.",
	[94223] = "Tap, tap, tap. Shape the Silver Skeleton Key.|A key must fit just right. Stay steady while you file it.|Some lock out there is waiting. Rush the key over.|Turn the key slowly in your mind. Click.",
	[94224] = "A heavy mace needs a heavy hitter. Get into those reps.|Bronze takes heat. Stay at the forge and take it too.|Two maces, both heavy. Haul them to the mark anyway.|Let the forge fire die down. Rest with it.",
	[94225] = "Rough bronze, rough work. Your reps shape the leggings.|Brace like a guard in new bronze leggings.|The leggings clank as you go. Let them clank.|Smooth the rough edges. Slow strokes of the file.",
	[94226] = "Green iron is tough to bend. Bend it with your reps.|Gauntlets on, fists shut. Wait for the metal to set.|The gauntlets go to the buyer. Off you go.|The green shine on the iron. Look at it and slow down.",
	[94227] = "It's big, it's bronze, it's a knife. Earn it.|The blade cools in the water. Steady until the hiss stops.|Deliver the knives. Big ones, so move with care but fast.|Sharpen with long, even strokes. No rush.",
	[94228] = "Iron boots need a smith who never quits. Rep on.|New boots, planted on the floor. Stay put and break them in.|Test the Green Iron Boots. March them to the buyer.|Iron boots are heavy. Take a calm moment before the walk.",
	[94229] = "Fit the lens, fit the screws. Reps build the spyglass.|Look through the spyglass. Keep it very steady.|The buyer wants to see far. Get the spyglass there first.|Far hills, blue sky, one small lens. Take in the view.",
	[94230] = "Build the sheep. Do not drop the sheep. Reps!|The sheep is ticking. Stay very, very still.|The sheep is loose. Go after it before it goes boom.|Wires in, fuse set. Calm hands make safe sheep.",
	[94231] = "Fit the barrel, fit the stock. Your reps make the rifle.|Aim the Moonsight Rifle. Wait for the clear shot.|Night falls soon. Rush the rifles to the hunter.|Moonlight on the scope. Quiet, like a hunter at night.",
	[94232] = "Recombobulate! Nobody knows what it means. Just do reps.|The gadget hums. Wait to see if it works.|It's a gnome gadget. Hurry before it breaks.|Unscramble your mind, like the Recombobulator would.",
	[94233] = "Rogues need practice. So do you. Reps.|The pins must line up. Stay steady and wait for the click.|A young rogue wants to train. Rush the locks over.|Lock picks need soft hands. Loosen up.",
	[94234] = "Tiny lenses, big work. Put your reps into the goggles.|Goggles on. The world goes dark. Stay put.|Shadow Goggles make the sun dim. Go out and test them.|Dark lenses, quiet mind. Enjoy the gloom.",
	[94235] = "Tinker until it works. Gnomes call that reps.|Point the remote at a beast. Wait. Did it work?|The remote sparks! Take it to the buyer before it acts up.|Gnomes rarely slow down. You can. Take a calm pause.",
	[94236] = "Pack the powder tight. Big bombs take big work.|Fuse is lit. Nobody move.|Big bombs, short fuse. Get them to the buyer now!|Easy with the powder. Calm hands, no boom.",
	[94237] = "Two hundred shots to cast. Your reps set the pace.|The hot metal sets in the mold. Wait with it.|A hunter needs ammo. Haul the shot over.|One shot, then the next. A calm rhythm at the mold.",
	[94238] = "Stitch the ball tight. Kids will kick it hard.|Keep the leather taut while the stitches set.|Someone wants to play ball. Get it there fast.|Thread in, thread out. Slow, easy stitches.",
	[94239] = "Cut, stitch, cut, stitch. Fine pants take fine reps.|Keep the leather flat while the dye dries.|New pants for the buyer. Go and drop them off.|Soft leather, careful thread. No need to rush.",
	[94240] = "An herbalist needs gloves. Stitch them with your reps.|Gloves on. Stay put like a patch of Peacebloom.|Deliver the gloves before the herb season ends.|Smell the herbs. Kingsblood, Peacebloom, calm.",
	[94241] = "Dark leather is thick. Work it with firm reps.|Try on the tunic. Stand tall and see if it fits.|The buyer is cold. Rush the tunic over.|Oil the dark leather with slow, soft strokes.",
	[94242] = "Gloves for a thief. Make them quiet and quick.|A pilferer waits in the dark. So do you.|Slip off with the gloves. Nobody saw a thing.|Soft gloves, soft steps. Take it slow, like a thief.",
	[94243] = "A heavy quiver holds lots of arrows. Stitch it strong.|Brace like an archer with a full quiver.|The hunter is out of arrows. Get the quiver there!|Draw a slow breath, like an archer before the shot.",
	[94244] = "Tough pads for tough fighters. Build them with reps.|Try on the pads. Stand firm and see if they sit right.|Two sets of pads, one buyer. Take them over.|Relax and let the leather settle into shape.",
	[94245] = "Barbaric Gloves demand barbaric reps. Grr.|A barbarian stands his ground. Try it in these gloves.|A wild buyer wants wild gloves. Go, go!|Even a barbarian needs a calm moment. Take one.",
	[94246] = "Red whelp scales are tough. Stitch them with firm reps.|The whelp scales are warm. Keep your grip on them.|Deliver the red gloves. They still feel like fire.|Little whelps nap after a meal. Take a sleepy pause.",
	[94247] = "Mages hate hard work. Do the reps for them.|A wizard stands tall in a new robe. Try it.|The robe must reach the wizard. Off to the mark.|Soft cloth, slow stitch. Let your mind drift like a mage.",
	[94248] = "Blue Overalls, stitch after stitch. Count your reps like seams.|Pin the cloth flat and hold. Crooked overalls sell for less.|The buyer waits at the map mark. Get those overalls there fast.|Smooth the blue cloth with calm hands before you fold it.",
	[94249] = "Silk is thin, so the needle goes in and out. Match it in reps.|A hood must sit just right. Hold like the fitting dummy.|Azure silk flutters as you race to the drop point.|Soft as silk. Let the calm run through you like thread.",
	[94250] = "Pack it tight. Load up on reps like bags of silk.|Hold the seam shut while the last knot sets.|A small pack, a long road. The customer wants it today.|Empty bag, empty mind. Fill both slowly.",
	[94251] = "Phoenix Pants must rise from the ashes. So must your reps.|Hold like a phoenix on its perch, quiet before the flame.|These pants are hot stuff. Don't stop until they're handed off.|Wings fold, fire dims. Let the phoenix rest a while.",
	[94252] = "Tough soles need tough reps. Red Woolen Boots, coming up.|Hold firm, like a new boot that has not been worn in.|Someone needs warm feet. Get those boots to them quick.|Wool is soft and slow to dry. Take your time, too.",
	[94253] = "Each color takes its own thread. Keep the reps coming.|Hold proud and tall. A kilt this bright deserves it.|A kilt swings best on the move. Off you go.|Red, gold, green. Let each color settle into place.",
	[94254] = "A greater robe for a greater adept. Earn it with reps.|The adept sits quiet in study. Hold as they do.|The adept's class starts soon. Rush that robe over.|Robes are for quiet minds. Find yours.",
	[94255] = "Spider silk is strong. Weave in reps as tight as a web.|Hold like a spider waiting in the middle of its web.|Quiet slippers, busy feet. Scurry to the drop point.|Soft as a web in the wind. Sway, then settle.",
	[94256] = "Frost bites hard. Stir up heat with your reps.|Frozen in place? Good. Hold until the potion thaws.|Cold hands, warm feet. Race the chill to the buyer.|Breathe out a frosty cloud. Watch it fade.",
	[94257] = "Unseen reps still count. Nobody will know but you.|Hold so still that no one knows you are there.|No one sees you rush. That's the point of the potion.|Fade out slow and quiet, like the potion's mist.",
	[94258] = "Stone skin needs stone arms. Grind out the reps.|Stoneshield means you do not budge. Stand like a wall.|Stone is heavy. Move fast anyway. The buyer waits.|Be the rock. Calm, cool and slow.",
	[94259] = "Roots grow deep with reps. Brew the Nature potion.|Hold like an old oak in a storm.|The wild calls. Answer it at speed, potion in hand.|Leaves drift down. Let your thoughts drift, too.",
	[94260] = "Cats pounce again and again. Your reps can too.|A cat watches a mouse hole for a long while. Hold like that.|Night eyes, quick paws. Dash through the dark to the buyer.|Lazy like a cat in the sun. Let the dark draught settle.",
	[94261] = "Rage in a bottle. Pour it into your reps.|All that rage, locked in. Hold it back.|Warriors are waiting for their rage. Don't make them angry.|Rage cools slowly. Let it drain away.",
	[94262] = "Mages drink these by the case. Stack reps to match.|Hold while the blue glow fills the flask.|A mage runs low on mana. Run it over, now.|Mana flows in calm, blue waves. So does your breath.",
	[94263] = "Fire is fierce. Fight back with reps.|Hold near the flames and do not blink.|Hot potion, hot feet. Rush it before it cools.|Watch the candle flame sway. Match it, soft and slow.",
	[94264] = "Dark oil, sharp blades. Quiet, steady reps.|Hold in the shadows. Let them hide you.|Slip through the dark with the oil tucked away.|Shadows grow long at dusk. Let the day go dim.",
	[94265] = "Goblin fuel goes boom. So should your reps.|Hold steady. Rocket fuel hates a shaky hand.|Blast off! Goblins don't wait, and neither do you.|Before the launch, a calm countdown.",
	[94266] = "Agility in a bottle. Quick, sharp reps to earn it.|Quick feet need a still center. Hold it.|Nimble feet! Dance the elixir to its buyer.|Light as a feather, loose as a leaf.",
	[94267] = "Wildvine grows fast. Grow your rep count with it.|Hold tight, like a vine wrapped round a trunk.|Vines creep, but you don't. Rush it over.|A vine climbs slowly toward the sun. Rise with it.",
	[94268] = "Clang! Steel bends only for firm reps.|Hold the helm to the anvil while it cools.|The forge roars. Work the bellows and don't slow.|Hot steel sinks into cool water. Hiss, then calm.",
	[94269] = "Mithril is tough. Wear it down with reps.|Inlay needs a firm grip. Hold the cylinder true.|Tap, tap, tap on the cylinder. Keep the beat going.|Trace the inlaid lines with calm eyes.",
	[94270] = "Link by link, the chain grows. So do your reps.|A weapon chain holds the blade fast. Hold as firm.|Chains rattle as you rush them to the buyer.|Let the links hang loose and quiet.",
	[94271] = "Fancy shoulders, heavy metal. Show them with reps.|Hold proud. Ornate mithril is made to be seen.|Shiny armor, quick delivery. Off to the map mark.|Polish the swirls slowly till they shine.",
	[94272] = "A glittering axe needs a sharp edge. Grind reps to hone it.|Hold the axe up to the light. Let it glitter.|Sparks fly from the grindstone. Don't let them stop.|Blue gleam, calm mind. Admire your work.",
	[94273] = "Moonsteel sings when struck. Make it sing with reps.|Hold the broadsword level under the moon.|Forge by night while the moon is up. Hurry!|Moonlight is cool and quiet. Soak it in.",
	[94274] = "Scale by golden scale, the coif takes shape. Rep on.|Hold the coif steady while you rivet the scales.|Gold shines brighter on the move. Rush it along.|Let the golden scales lie flat and calm.",
	[94275] = "Scrape, scrape. Sharp edges come from solid reps.|Hold the blade at the right angle on the stone.|Stone to steel, fast and even. No breaks.|A good edge is never rushed. Slow down.",
	[94276] = "A wicked blade for a wicked buyer. Forge it with reps.|Hold the blade out. Admire the wicked shine.|Deliver fast. Nobody keeps a wicked buyer waiting.|Even a wicked blade rests in its sheath.",
	[94277] = "Truesilver shines true. Earn the shine with reps.|A rod must stay straight. Be that rod and hold.|The buyer wants their rod now. Make haste!|Pure silver, pure calm. Let the forge go quiet.",
	[94278] = "Gauntlets make a fist of gold. Show them with reps.|Gold gauntlets, iron grip. Hold on.|Fingers of gold, feet of fire. Go go go!|Gloves off. Rest now. The gold can wait.",
	[94279] = "Heavy axe, heavy work. Pile on the reps.|Heavy mithril never shakes. Hold just like it.|Lug that heavy axe to the buyer. Fast!|Rest the axe by the forge. Let your arms go loose.",
	[94280] = "Wind up the dragonling. Crank out the reps.|Hold the gears in place while the bolts set.|A metal dragon waits for its wings. Hurry with the parts.|Tiny gears turn slowly. Tick, tock, calm.",
	[94281] = "The dummy can take hits. Can you give reps?|Be the dummy. Stand there and hold.|The dummy never tires. Try to keep up.|Even the dummy gets to rest. So do you.",
	[94282] = "Fine work needs sharp eyes. Sharp reps, too.|Look through the lens. Hold. Small work needs care.|Pop in the monocle and rush to the buyer.|Close one eye. Then the other. Rest.",
	[94283] = "Pack the land mine with powder. Pack in the reps.|Don't step on it! Hold where you are.|Tiptoe fast past the mines to the map mark.|Careful hands. Slow breath. Nothing goes boom.",
	[94284] = "Ultra goggles for ultra reps.|Stare through the goggles. Hold and scan the dark.|Night vision on. Hurry through the gloom.|Take the goggles off. Let your eyes rest in the dark.",
	[94285] = "Unstable? Not your reps. Make them firm.|One wrong twitch and it goes off. Hold and stay put.|Get it there before it pops! Go!|Calm hands keep the trigger quiet.",
	[94286] = "Flash! Bang! Quick bright reps.|Hold your eyes shut and wait for the flash to fade.|Blinded foes stumble about. You stay on your feet.|After the flash, dark and quiet again.",
	[94287] = "Sparks fly at the bench. Build the goggles with reps.|Hold your gaze on the flames. The goggles have you.|The forge is hot. So are your feet. Deliver!|Watch the embers glow and fade.",
	[94288] = "Mithril shards, big bang. Load the reps.|Hold the fuse away from the fire.|The fuse is lit! Better hurry.|No sparks here. Just slow, careful work.",
	[94289] = "Tweak, twist, tweak. Small reps add up.|Tiny parts, tiny moves. Better yet, hold.|Whirr! The gyro never stops. Neither do you.|Adjust, then wait. Fine work is slow work.",
	[94290] = "Bolts, nuts, springs. Fix it with reps.|Hold the wrench tight while the bolt turns.|Something broke! Rush the repair kit over.|Lay out the tools in neat rows. Calm work.",
	[94291] = "Dark Iron is dense. Pack it full with reps.|Hold the bomb far from the forge. Very far.|Dark Iron goes boom. Leave the area fast!|Cool dark iron, cool mind.",
	[94292] = "Tan the leather. Toss in some reps.|Hold the hat in place. It fits best that way.|A comfy hat for a busy head. Bring it quick.|Put on the hat. Sit back. Relax.",
	[94293] = "A guardian stands up to all. Stand up to reps.|A guardian holds the line. Hold yours.|Cape flying behind you, race to the buyer.|Wrap up in the cloak. Feel safe and still.",
	[94294] = "Bracers brace the wrists. Brace for reps.|Dusk falls slow. Hold until the last light.|Beat the sunset to the buyer!|Dusk is soft and gray. Let it calm you.",
	[94295] = "Wild leather is tough to tame. Tame it with reps.|Hold firm, like a wild beast about to pounce.|Run wild! The helmet must get there.|Even wild things rest at night.",
	[94296] = "Wide shoulders need wild reps.|Brace the load and hold. Wild leather can take it.|Across the wilds with the shoulders packed.|Let the wild leather soften in the quiet.",
	[94297] = "Quick draw, quick reps. Fill the quiver.|Draw back and hold. Wait for the shot.|Quick feet, like quick arrows. Fly to the buyer.|Aim slowly. Breathe. Let the arrow go.",
	[94298] = "Swift Boots need tough seams. Your reps pull the thread tight.|Let the glue set on the Swift Boots. Hold until the soles stick.|The buyer wants boots that fly. Show them how fast feet should go.|Lace the Swift Boots slow and neat. A calm hand makes quick shoes.",
	[94299] = "Nightscape leather is thick. Work it soft with steady reps.|Pin the Nightscape Shoulders flat. Stay put, like the night.|Dusk is near and the order waits. Get those shoulders on the road.|Night falls quiet over the tanning rack. Match its calm.",
	[94300] = "Carve the Big Voodoo Mask a big grin. Put reps into the leather.|Wear the mask and don't blink. Voodoo likes a still face.|The mask wants to dance. Don't let the drums stop.|Behind the Big Voodoo Mask, the troll spirits wait in silence.",
	[94301] = "Big robe, big stitches. A rep for all those wild patterns.|Keep the Big Voodoo Robe on the frame till the dye dries.|Voodoo drums beat fast. Keep up with them to the drop-off.|Fold the Big Voodoo Robe with care. Troll cloth hates a rush.",
	[94302] = "Turtle scales are hard. Rivet them on with firm reps.|Brace like a turtle in its shell. Nothing gets through.|Turtles are slow. The customer is not. Hurry that breastplate over.|Think of a turtle on a warm beach. No rush at all.",
	[94303] = "Stuff the Ammo Pouch full. Your reps are the shot going in.|Keep the thick leather tight while the stitches settle.|A hunter waits with an empty pouch. Get moving, quick feet.|Snap the ammo pouch shut, softly. A hunter hears every sound.",
	[94304] = "Mageweave bags carry a lot. Stack up reps to match.|Keep the Mageweave tight on the loom. Hold it there.|The loom clacks on and on. Keep your feet in time with it.|Soft purple cloth, slow hands. The bag comes out neat.",
	[94305] = "Shadoweave Gloves, finger by finger. Stitch the dark cloth with reps.|Shadows don't twitch. Stay dark and quiet as the gloves.|Shadow cloth slips away if you pause. Chase it down.|Slip on the Shadoweave Gloves. Let the dark cool you off.",
	[94306] = "Crimson silk is fine thread. Strong reps, gentle seams.|The red dye is still wet. Stay where you are till it sets.|Silk spools spin fast. Spin your feet up to match.|Smooth the Crimson Silk Robe flat. Soft as a summer wind.",
	[94307] = "A long robe means long seams. Sew the Shadoweave with your reps.|Stand like a dark mage in a doorway. Say nothing. Stay.|Night market, tight deadline. Race the robe across town.|Shadoweave drinks the light. Sink into the quiet with it.",
	[94308] = "Sew the pouch, then add the magic. Reps first, sparkle later.|The spell on the pouch is new. Keep it steady so it stays.|Magic fades if the pouch sits too long. Hurry it along.|Feel the soft glow of the pouch. Let it settle in your palms.",
	[94309] = "Stars on a belt! Sew them on bright with your reps.|Stay put under the night sky like the stars on the Star Belt.|Shooting stars never slow down. Be one of them.|Count the stars on the belt as you go. Slow and bright.",
	[94310] = "Black thread, black cloth, black vest. Sew it with power.|The vest must dry flat and dark. Don't move a thread.|A mage wants the vest by dusk. Feet fast, cloth folded.|Dark cloth, quiet room. Let the vest and you both rest easy.",
	[94311] = "Red Mageweave Pants take long seams. Pull the needle hard.|Pants on the rack, pins in place. You stay in place too.|Bright red pants get noticed. Get them out the door quick.|Fold the red cloth in soft layers. No creases, no fuss.",
	[94312] = "A Martial Shirt for a fighter. Show it how fighters train.|Take the martial stance the shirt was made for. Firm.|The fighter wants the shirt before the bout. Go, go, go.|Orange like a slow sunrise. Calm, like the monk who wears it.",
	[94313] = "Bandits need masks too. Earn the coin with honest reps.|Bandits wait in the bushes. Wait with them, not a peep.|Deliver the mask and get away before the guards ask questions.|A mask of white cloth. Quiet face, quiet mind.",
	[94314] = "Cindercloth is woven near fire. Stoke it with your reps.|Stand close to the forge heat. Don't back off from the flames.|Hot robe! Keep it going before it scorches your pack.|Embers cool to soft grey. Let the heat drift away.",
	[94315] = "Earthen silk is tough as stone. Your reps give it shape.|Be like the earth. Heavy, calm, and going nowhere.|Dirt roads lead to the buyer. Pound the ground all the way.|Earth tones, soft silk. Sink low and feel the ground.",
	[94316] = "Demons fear this potion. Grind the herbs with firm hands.|The brew must not tip. Stand guard over the Demonslaying flask.|A demon hunter is waiting. Rush the potion to the front.|Stir the pot slow. Demons hate a patient alchemist.",
	[94317] = "Crush the herbs for Dreamless Sleep. Hard work before bedtime.|Dreamless Sleep is still as a pond. Be the pond.|Stay awake! Don't sip this one before the drop-off.|Yawn, sigh, sink. Dreamless Sleep is almost ready.",
	[94318] = "Fire flowers don't crush themselves. Put your reps into the bowl.|The flask is hot. Keep your grip and don't let it drop.|Someone is heading into the flames. Get them this potion fast.|Watch the red brew bubble down to a calm glow.",
	[94319] = "Demons hide, but not from this draught. Mix it with strong reps.|Sip, then look. Stay put while the hidden demons show.|A warlock needs this draught now. Don't stop till it's there.|Let the draught settle. Hidden things show up to a calm eye.",
	[94320] = "Gift of Arthas is a cold brew. Grind the herbs like you mean it.|Cold creeps from the flask. Stand firm in the chill.|The Scourge are near. Get the Gift of Arthas out the door.|Frost on the glass. Slow down like the winter air.",
	[94321] = "Every dragon color in one flask. Pour power into the mix.|Dragon fire in all colors. Brace and don't budge.|A raid waits on this flask. Dash it to them.|Colors swirl in the flask. Watch them blend, soft and slow.",
	[94322] = "Nothing can touch the one who drinks this. Brew it with grit.|For a short while, nothing hits you. Stand like it's true.|This potion is needed before the big fight. Off you go.|Shimmer like the potion's glow. Easy, light, untouched.",
	[94323] = "A strong brew for a big job. Work the pestle hard.|Keep the flask level while the potion glows. No spills.|Fresh brews work best. Get it there while it glows.|Green light swirls in the glass. Let it slow, and you with it.",
	[94324] = "Firewater bites back. Crank the still with strong reps.|Don't flinch at the fumes. Stay close to the still.|Ogres want their Firewater now. Don't make them wait.|Drip, drip, drip. Firewater takes its sweet time.",
	[94325] = "Radiant Circlet on the anvil. Ring it round with hammer reps.|Keep the hot circlet in the tongs until it cools.|The circlet glows bright. Keep the forge fires roaring.|The circlet shines like a sunrise. Warm and calm.",
	[94326] = "Hit the Radiant Belt hard. It glows more with each blow.|Keep the belt in the cold water. Let it hiss and set.|Pump the forge bellows. The belt wants more heat.|A bright belt, a soft glow. Let the forge light warm you.",
	[94327] = "Orcs hit hard, so the leggings must too. Pound the plates.|Stand like an orc guard at the gate. Lok'tar! Stay there.|War drums sound. Get the leggings to the front lines.|Even orcs rest by the fire after the forge work.",
	[94328] = "Tap out the Mithril Spurs. Small parts, big swings.|Sit tall in the saddle as if the spurs were yours.|Spurs are for speed. Gallop that order across the land.|A good rider stays soft in the saddle. Loose and easy.",
	[94329] = "Imperial Plate is heavy work. Beat the chest into shape.|Plate armor stands tall on its rack. Stand tall with it.|Big plate, short deadline. Hustle it over.|Polish the Imperial Plate Chest slowly. Shine it like a mirror.",
	[94330] = "Darkrune Gauntlets for a strong grip. Shape the fingers with blows.|Runes glow while they set. Clench tight and wait for the fade.|Dark runes hum with power. Match their buzz.|Trace the dark runes on the gauntlets, line after slow line.",
	[94331] = "Huge axe, huge work. Beat the thorium thin along the edge.|Thorium is heavy. Keep that axe head up and steady.|Stoke the forge white hot. Thorium won't bend for less.|Hone the edge with long, slow strokes. Sharp takes time.",
	[94332] = "Arcanite is tough to shape. Tap out the key's teeth.|Keep the key in the lock and wait for the click.|A locked chest won't wait. Get the key to its owner.|Turn the Skeleton Key slowly. Click. All locks open.",
	[94333] = "A small blade, a big job. Grind the Ebon Shiv to a fine point.|A rogue waits in the shadows. Be that rogue.|Slip through the alleys and drop off the shiv unseen.|Soft steps, a dark blade, a quiet alley. Rogue calm.",
	[94334] = "The Target Dummy takes hits for a living. Give it some.|Stand like the dummy. Let them swing, you don't move.|Wind up the Target Dummy. It wants you to keep busy.|Even a dummy gets a break. Oil the gears and relax.",
	[94335] = "Grind the Green Lens smooth. Glass takes steady work.|Look through the lens and don't wobble. Focus.|Green glass, blue sky, fast feet. Deliver it bright.|Everything looks calm through a Green Lens. Take a look.",
	[94336] = "Wind the Mechanical Toad's key. Crank it tight.|The toad sits on its lily pad and waits. So do you.|Ribbit! The toad is loose. Chase it down.|A toad on a warm log, blinking slow. Be that toad.",
	[94337] = "Tighten the bolts on the Alarm-O-Bot. Gnomes like it snug.|The Alarm-O-Bot is watching. Don't set it off.|BEEP BEEP! The alarm is going off. Move!|Shh. Turn the Alarm-O-Bot down, and let the room go quiet.",
	[94338] = "Crank the goblin battery. More sparks, more zap.|Clamp the cables on and stay put. Zzzt.|Buzzing with goblin power? Use it up before it fizzles.|The cables cool off. Let the zap drain out.",
	[94339] = "Bolt by bolt, the Repair Bot comes together.|Stand by while the Repair Bot fixes the gear. No rushing it.|A broken sword can't wait. Get the Repair Bot there.|Whirr, click, done. The Repair Bot works calm. So can you.",
	[94340] = "Wind the Truesilver coils tight. Loop after loop.|Power flows through the Transformer. Grip it and wait.|The Transformer hums fast. Keep up with the current.|Truesilver shines soft. Let the hum fade out.",
	[94341] = "Screw the Sniper Scope on tight. Good aim needs a steady mount.|Look down the scope. Don't let the crosshair drift.|A hunter waits to take aim. Get the scope there quick.|Sniper calm. Wait, watch, and let the moment come.",
	[94342] = "Build the Mechanical Yeti a sturdy frame. Big furry bolts.|The mechanical yeti is calm and quiet. Stay calm beside it.|The yeti's gears spin fast. Match them.|This yeti is the gentle kind. Be gentle, too.",
	[94343] = "Wicked leather is tough. Put some force into the stitches.|Pin the Wicked Leather Pants down. Keep them flat.|Wicked pants for a wicked buyer. Rush them out.|Oil the leather slow and smooth. Wicked looks good soft.",
	[94344] = "Gordok ogres are big. Build the suit big with big reps.|In the Ogre Suit, stand tall and look dumb. Easy.|Ogre Suit on? Get past the guards before they look close.|Ogres nap a lot. Take a lazy break like a Gordok.",
	[94345] = "Volcanic leather, hot to work. Keep your needle driving.|Lava heat rolls off the breastplate. Brave it and stay.|Lava is flowing! Get that breastplate out fast.|Lava cools into black stone. Cool down with it.",
	[94346] = "Carve the runes into the headband. Press hard, cut deep.|Wear the headband and focus. The runes need a still mind.|Runes spark on the leather. Keep the magic flowing.|Runic lines curve and loop. Follow them slow.",
	[94347] = "One pair of Wicked Leather Bracers. Stitch them tight with your reps.|Hold the hide flat. One bad stitch and the pair is lost.|The buyer waits at the map mark. Get the bracers there fast.|Slow hands make good leather. Take your time.",
	[94348] = "Chimeric hide is tough. Your reps work it into a vest.|Keep the leather flat while the vest takes shape.|The buyer waits where your map is marked. Get going.|Smooth the Chimeric hide, slow and calm.",
	[94349] = "Scorpid plates are hard. Your reps bend them into a helm.|Rivets need a firm grip. Hold the helm until they set.|Helm in your pack, buyer far away. Don't stop now.|Scorpids wait, calm and still, before they strike. Try it.",
	[94350] = "Runes on leather need a firm hand. Reps make it firm.|Grip the bracers tight so the runes stay in a line.|Bracers packed, map marked. The road starts here.|Trace the runes softly. Rushing smears the ink.",
	[94351] = "Frostsaber hide is thick. The needle needs your reps to get in.|Stand firm like a Frostsaber in deep snow.|New Frostsaber Boots? Test them all the way to the buyer.|Soft paws, soft steps. Move like the big cat.",
	[94352] = "Wizardweave fights the needle. Beat it with your reps.|Pull the cloth taut and hold. Wizardweave slips away.|This turban is for a wizard who hates to wait. Hurry.|Wrap the turban slowly. Magic cloth likes a calm hand.",
	[94353] = "So many pockets to sew. Your reps fill the Runecloth Bag.|Keep the bag open while the buyer checks the seams.|The bag is done. Carry it to the mark with no stops.|Fold the Runecloth neat. Calm hands make tidy seams.",
	[94354] = "Two boots, lots of seams. Reps pull them tight.|Pin the sole down. The thread needs time to set.|Runecloth Boots want a long road. Give them one.|Measure twice, cut once. No rush with the Runecloth.",
	[94355] = "Sharp cuts make a sharp Tuxedo Jacket. Reps do the cutting.|Like a butler in his best tuxedo, stand tall.|The party starts soon. Get that jacket to the door!|Fine lapels ask for grace. Give them some.",
	[94356] = "Felcloth glows green. Your reps keep it in line.|Felcloth squirms like it is alive. Pin it down.|The boots are done. Take them to the buyer. Go!|Fel magic is wild. Meet it with a calm mind.",
	[94357] = "The druids asked for a Cenarion Herb Bag. Reps sew it up.|Druids wait by the herb patch. Wait with them and hold.|Herbs wilt fast. Rush the bag to the druid who asked.|Cenarion work is quiet work. Let the forest calm you.",
	[94358] = "Shadoweave is dark and stubborn. Reps win it over.|Behind a Shadoweave Mask, no one sees you blink. Hold.|Someone wants this mask fast. Don't make them wait.|Shadows drift soft and slow. Drift with them.",
	[94359] = "Ghostweave is thin as mist. Your reps give it weight.|Ghostweave floats off if you let go. So don't.|Is the buyer a ghost? Chase them to the mark.|Light as a spirit, calm as a grave. Weave slow.",
	[94360] = "A Soul Pouch for a warlock. Reps sew the dark seams shut.|Soul shards rattle inside. Hold the pouch shut.|Warlocks don't wait kindly. Get that pouch to them.|Souls whisper in the pouch. Let them. Stay calm.",
	[94369] = "Al'Akir may strike. Your reps show Zephras can stand.|The wards are down. Hold firm while the Windlord watches.|Carry the warning to High Elder Shadowsong. Fast.|Wind howls over Zephras. Find the calm inside the storm.",
	[94373] = "Frostmane trolls wear bear pendants. Two of them are yours.|Stout as the stone under your boots, says Teo. Prove it.|South to the troll cave, and back to Anvilmar.|The mountain is patient. Stand like the mountain.",
	[94374] = "The hidden path climbs high. Your reps carry you up.|Sapta in hand. Hold until you reach the Spirit Stone.|Up the mountain path to the Spirit Stone. Keep climbing.|Drink the Earth Sapta and see what the earth shows.",
	[94375] = "Small quartz, big heart. Reps make you just as tough.|Be patient, be strong. The earth asks both. Hold.|Rush the Rough Quartz back to Teo in Anvilmar.|Even the smallest pebble outlasts the rest. Be that pebble.",
	[94411] = "Six High Order Apprentices. Send them all packing.|The standing stones are sacred. Hold the ground by them.|Chase the apprentices away from the stones.|Drive them off, but keep your spirit clear.",
	[94413] = "The ley line draws Windshapers. Send six of them off.|Guard the ley line. It glows while you hold.|Southwest into the forest. The Windshapers won't wait.|Feel the ley line hum under your feet.",
	[94414] = "The anchor pylons bind the isle. Reps bind you to it.|Borrow Halaan's gift and hold your gaze on the pylon.|The pylon's magic flickers. Match its restless beat.|Look far across the isle. Let the view slow you down.",
	[94427] = "Grace takes work. Put some reps into it.|Hold on to your grace, even among the Forsaken.|Down to the Trade Quarter. Tanis is waiting.|Good for good's sake. Let that thought sit a while.",
	[94434] = "Ten Linen Cloth for Tanis. Stack them up.|Wrap her up tight so she stays in one piece.|His wife is falling apart. Hurry with that cloth!|Fold the linen soft and neat. She needs it.",
	[94435] = "Tanis calls you a friend. Reps earn the name.|Hold on to his thanks. Carry it back to Danitha.|Back to Bandarion Keep with good news.|A small kindness. Let it settle in.",
	[94436] = "Show the Forsaken what a true paladin can do.|Clutch the Symbol. The Light burns, but you stay.|Downstairs, quick. Billmuth has come for help.|The Light stings the Forsaken. Stay calm through it.",
	[94438] = "Falgan stayed to hold them off. Give him your reps.|Falgan held the line alone. Now it's your turn.|Billmuth fled toward Brill. You head back to the Vale.|Raise the Symbol of Life. Quiet now. Falgan is close.",
	[94440] = "Beat the Scarlets. Grab their plans.|Wait in the Vale. A Scarlet with a bag will come.|Plans in hand. Get them to Billmuth at Tyr's Watch.|An ambush needs a cool head. Plan like one.",
	[94441] = "The Deathguard will hear of this. Earn the story.|Tyr's Watch did good work today. Stand proud.|Take Billmuth's thanks up to Danitha Morr.|Dark Lady watch over you. Rest in that thought.",
	[94449] = "Fire asks a price. Pay it in reps.|Chaos waits for you. Stand your ground first.|Far east into the mountains. Bruegs is up there.|Before the fire, one last quiet moment.",
	[94465] = "The Dormant Flame is a long climb. Reps get you there.|The torch is cold. Hold it. It will burn soon enough.|Past the Valley of Kings to Loch Modan. Onward.|The torch sleeps. So does the fire in you, for now.",
	[94466] = "Tunnel rats, then troggs. Fight for the tar and the pouch.|Hold in the kobold tunnels until a Geomancer shows up.|North caves, then south hills. Off you go.|Dangerous work, says Braldir. Go in with a clear head.",
	[94467] = "Strike fast! The fire spirit grows while you wait.|He won't strike till you do. Stare him down.|The spirit waits on the peak. Get up there.|Set the Glowing Ember in the brazier. Watch it catch.",
	[94468] = "Proud work, this Torch of Eternal Flame. Earn it.|Wind whips the flame. Shield it and hold.|Down the path, back to Dun Morogh. Torch burning.|Watch the flame dance over Loch Modan.",
	[94484] = "The druids went quiet. Your reps will break the silence.|The silence is heavy. Hold up under it.|Northeast through Shadowgale Forest to Elegael.|Listen to the quiet woods. Something is wrong.",
	[94485] = "Eight clumps of Lady's Tear. Pick them from the trees.|Sticky moss, sticky hands. Stay put till it lets go.|Be swift, says Elegael. Tree to tree, moss to moss.|Find the moss at the roots. Slow eyes find more.",
	[94486] = "Twenty feathers from angry Shrieklings. Earn them.|Shriekling talons are big. Stand firm and don't back down.|The Shrieklings are wild today. Dodge those talons!|Soft feathers for soft wraps. Handle them gently.",
	[94487] = "Al'Aketh cultists wear Bloodied Heirlooms. Take ten.|The cultists struck with no warning. Stand ready.|The Stormchasers flee through Shadowgale. After them!|Elegael spits in anger. You stay cool.",
	[94488] = "Haalien turned on his kin. Make him pay for it.|Haalien smells you coming. Hold your ground.|Hunt the traitor druid through the cultist camp.|Face Haalien with a clear mind, not a hot head.",
	[94489] = "Seven druids in the den. A poultice for each one.|Stay by each druid until the wrap holds.|Across the clearing to the Nightfang Den. Quick!|Search the den for Jorel Windsinger. Look with care.",
	[94490] = "The missive is torn, but the news is big. Carry it.|Keep the ripped note safe. It holds the cult's plans.|Bring the note back to Elegael before it's lost.|Read the torn lines slowly. What does the cult want?",
	[94491] = "A spy hides in Valanaar. Your reps will find them.|Hard news to carry. Hold it together for Lotheluum.|Elegael can't make the trip. You can. Go swiftly.|Remember the druids who are gone. A quiet moment for them.",
	[94493] = "No help is coming. Your reps will have to do.|Elegael pales. Stand steady for both of you.|Time is short. Get back to Elegael, now.|Elegael sighs, then looks brave. Do the same.",
	[94494] = "Water wears down stone. So do your reps.|Wait at the lake's edge like still water.|Along the lake to Norric's burrow hut.|Purity starts with a calm mind. Start there.",
	[94495] = "Hervdana's cave hides under the falls. Reps get you there.|Pure water is still water. Be pure water.|Don't let the river outrun you. Off to the Wetlands!|Rebirth comes slow, like water through rock.",
	[94497] = "Fill the brown skin where the falls crash down.|Hold the waterskin under the falls until it's full.|Mind the marsh. Out to the falls and back.|Where fresh water meets salt, watch it mix.",
	[94499] = "Big, twisted murlocs guard Stonewatch Falls. Don't flinch.|Fill the red skin while the murlocs aren't looking.|To Redridge and back. Hervdana wants that sample.|Magic, venom or worse? Watch the water for signs.",
	[94500] = "Ashenvale is far. Your reps earn the trip.|The forest has eyes that don't blink. Neither do you.|Menethil, the boat, Auberdine, Ashenvale. Long road.|Astranaar's lake is old and pure. Rest your eyes on it.",
	[94501] = "One last task from Norric. Reps get you ready.|Level vial, steady hands. Not one drop spilled.|Loch Modan again. Norric has one more task.|Purest water, calmest hands. Carry it gently.",
	[94502] = "The pond's corruption fights back. Beat it, take its bracers.|Place the bracers on the shrine. Wait for the spirit.|Out to Moonbrook, where Stendel's Pond has gone foul.|The spirits went silent. Be silent with them.",
	[94503] = "The corrupt spirits fall apart. You are still standing.|Mist fades into silence. Stay where you are.|Light bursts over the pond. Go to the water spirit.|The hiss dies down. Listen for the spirit's voice.",
	[94505] = "Water is life. Bring the Shard of Water home.|The Shard of Water hums with life. Hold it close.|Westfall to Loch Modan. Norric waits with the totem.|Understand water is life. Let that sink in.",
	[94559] = "A turncoat waits northwest of Valanaar. Earn his trust with reps.|The turncoat won't come out until you hold your spot in the dark.|Get to the house in the highlands before the cult does.|It may be a trap. Stay quiet and calm, like a shadow at the door.",
	[94568] = "The turncoat's secrets died with him. Your reps must say the rest.|Talaanis speaks with the crystal. Stand by and do not stir.|Desperate times are next. Warm up while the talk goes on.|Listen close to Talaanis. A quiet mind hears the crystal best.",
	[94638] = "Ur'endra lost herself to madness. Meet her strength with yours.|Her cave is dark. Stand firm at the mouth and wait for her.|Off to the bluffs west of here. Ur'endra will not wait.|It lays heavy on his heart. Let your breath be gentle for her.",
	[94773] = "The Light asks for work, not words. Show it here.|In the Light, stay put and let it settle on you.|Eyes are on you now. Give them something to see.|A priest's grace starts with a quiet mind. Find yours.",
	[94774] = "Laurena has heard of you. Give her reps worth the talk.|The Cathedral of Light is patient. Be still as its stone.|Stormwind is far. Go as soon as possible, they said.|May the Light be with you. Let it in with a long breath.",
	[94775] = "An elf says a priest came looking. Show why he did.|Like a statue in the elf temple, let the news sink in.|Don't linger in Darnassus. Your people need you home.|Take the elf's blessing in, then set off.",
	[94776] = "Somethin' really good or really bad. Your reps decide which.|The High Priestess wants you personally. Stand tall for it.|Don't waste time 'round here. Stormwind is a long road.|Guessin' it's good news. Settle in and let the worry go.",
	[94778] = "Proof that you are worthy, Laurena asks. Hand it over in reps.|The heart of the Cathedral is quiet. Stay put there.|Don't waste time finding the way. Stormwind calls now.|Give her my regards, the priest says. Bring them in a quiet breath.",
	[94779] = "Faith in Elune, faith in the Light. Both need hard work.|Moonlight falls on Darnassus. Let your faith rest in it.|Finish your business in Darnassus, then go find your teacher.|New gifts come with faith. Take a slow breath and wait for yours.",
	[94792] = "Rockhide Boars are stubborn. Show the Taming Rod who's boss.|The boar charges, then stops. Wait it out until it trusts you.|Chase the boar through the forest. Don't let it lose you.|Respect nature's balance. Be gentle, and the boar comes near.",
	[94793] = "Isaac Chan is a lifelong woodsman. Show him your work.|A pet learns to stay. Teach it by staying yourself.|Off to Goldshire with your new friend at your heels.|Go with the winds, young hunter. Let them carry your breath.",
	[94817] = "A flash to confound foes. Your reps charge it up.|Glow bright and stay put. Let the flash gather in you.|Blink, and the foe is lost. Keep them guessing.|Before the flash, darkness. Let your mind go dark and quiet too.",
	[94818] = "A priest with a backup plan never falls. Build yours here.|Plans take time. Wait here until yours is ready.|When plans fail, run. Practice that part now.|Think it through, calm and clear. Then think it again.",
	[94819] = "Mims has a test for you. Show her what you've got.|The Mystic Ward is still as stone. Match it.|Make haste to Ironforge, clever friend. The test draws near.|Your race has its own rites. Breathe in, and get ready for yours.",
	[94821] = "A priest searched far to find you. Make the trip worth it.|The Hall of Mysteries waits. So do you, right here.|Back to Ironforge as soon as possible. Off you go.|The Light be with you, young one. Let it settle before the road.",
	[94822] = "Your superiors say you've proven yourself. Prove it once more.|Until Mims guides you, stand fast in the Hall.|Ironforge is deep in the snowy hills. Get moving.|Good luck, they said. Luck likes a calm priest.",
	[94823] = "An elf passes on the word: Mims wants you. Work for it.|Elune bless you. Stay in that blessing a while.|Your people need you. Don't spend long among the elves.|It seems you've done well. Let that thought sink in gently.",
	[94824] = "Really good or really bad? Earn the good kind.|Mims commands you to come. Stand ready for her word.|Head there as soon as you can, the dwarf says. Go on.|You've done well for yourself, it seems. Rest easy on that.",
	[94825] = "The priest's mood seemed good. Good news deserves good reps.|No need to worry, the elf says. Stand firm and trust it.|Don't take too long reaching the Hall of Mysteries.|Elune be with you. A soft breath, and you're on your way.",
	[94826] = "New skills come to those with faith. Put them to work.|Darnassus can keep you a little longer. Your teacher will wait.|Business in Darnassus done? Then off to your teacher.|Knowledge serves, the elf says. So does a quiet moment.",
	[94863] = "Gray Forest Wolves are fierce. Be fiercer.|The wolf watches you. Stare back and do not blink first.|Wolves run in packs. Run with them until one follows you.|With care, the wolf will trust you. Stay soft and quiet.",
	[94864] = "The Young Forest Bear is the mightiest yet. Match it.|A bear sniffs you out. Stand like a tree and let it decide.|Through Elwynn to find the bear. Don't stop till you do.|Earn the trust of the bear. Slow breaths calm a big beast.",
	[94896] = "Eight lost belongings in Ban'aethal. Bring back every one.|The village falls into the sky. Grip what you found, tight.|Shadowgale Forest is dangerous. Get in, get out, fast.|The refugees wait with hope. Carry their things with care.",
	[94897] = "Resaan went back for supplies. Go back for him.|In the ruins, you find him. Stay a while beside Resaan.|A week gone already. Hurry to the ruins of Ban'aethal.|Bring his heirloom home gently. Some things need a soft touch.",
	[94898] = "Ten Wind Hollows attack the fleeing. Answer them rep for rep.|The wind spirits howl at you. Plant your feet and take it.|Wind spirits are fast. Stay on their trail across the forest.|When the Hollows are gone, the air goes still. Be that air.",
	[94901] = "Gustjumper frogs never tire. Neither do your reps.|Wait by the pond. A Gustjumper lands when all is quiet.|The frogs bounce off on the wind. Go after them.|Cup a Gustjumper gently. Frogs like a calm hand.",
	[94902] = "The vineyard hangs heavy. Count your reps in grapes.|The best bunch is up high. Stay under it until it's yours.|Vine after vine through the Valanaar vineyard. On to the next.|Grapes bruise easily. Take them soft and slow.",
	[94911] = "Turak Runetotem will teach you. Show him you're worth it.|Thunder Bluff stands high and still. Stand like its cliffs.|Thunder Bluff is a long way off. Travel with the wind's blessing.|Much promise in the druid arts. Let it grow quiet, like roots.",
	[94912] = "The Cenarion Circle is ancient. Show it a young druid's grit.|Sheldras Moontree waits in Stormwind. Wait, rooted like a tree.|Go now. You have much to learn and a city to reach.|To save your home, first learn to be still in nature.",
	[94913] = "Remulos keeps watch over Moonglade. Give him something to watch.|Druids sleep long in Moonglade. Hold like one who sleeps a season.|The spell takes you there. The walk to Nighthaven is on you.|Moonglade offers comfort. Let a breath of it in.",
	[94914] = "Dendrite Starblaze has a path for you. Take the first steps.|The sacred lands wait. Be quiet as the glade at night.|Cast the spell and go. Nighthaven's village is waiting.|Your first lesson on Azeroth begins in the calm of Moonglade.",
	[94946] = "The cult changed Elaadrin's plans. Your reps change theirs.|The skycutter lifts off. Grip the rail until Dalaran appears.|Down to the dock outside the lodge. The skycutter won't wait.|Clouds slide past the ship. Watch them go and breathe easy.",
	[94947] = "Bolvar Fordragon rules Stormwind. Greet him with your best.|Before the regent lord in Stormwind Keep, stand tall and still.|A big world down here. Go out and start exploring it.|Step through the Skyborne Portal calm and ready for Stormwind.",
	[94978] = "Show the Windsong Crawler you are strong. Your reps earn its trust.|The crawler sniffs the rod. Hold your ground and let it come.|The crawler runs to the lake. Stay on its tail.|Calm hands by the water. A wild beast trusts a quiet hunter.",
	[94979] = "Galestriders respect strength. Show it in your reps.|Stand firm in the Gustberry Lowlands. Let the Galestrider test you.|The Galestrider runs like the wind. Don't let it leave you behind.|Quel'ana says trust starts calm. Wait low in the tall grass.",
	[95034] = "A worgen came for Lumina. Banon stood in its path. Honor him.|Lumina tells what came next. Stay and hear it all.|Banon was bitten, and they limped back. The gnolls were close.|Scary tales need a calm listener. Be one for Lumina.",
	[95036] = "Fire-Eye won't stay dead. Gather what the new blade needs.|Trevan reads his list. Wait while he names what he needs.|Silverpine is full of worgen. Keep ahead of them.|A special weapon starts with a clear head. Get yours ready.",
	[95041] = "Seven archive cards lost near Gnomeregan. Dig out each.|Grandma Quikswitch's chili recipe is down there. Stay low and search.|The snow outside Gnomeregan is deep. Plow on through it.|It's a long shot, Jemma says. Stay calm and look close.",
	[95065] = "Gray is down to his last bait. Three Nightcrawlers, coming up.|Gray casts his line and waits. Wait right along with him.|West of the Trade District, along the canals. Catherine has bait.|What a view from the harbor. Take it in, like old Gray does.",
	[95111] = "Ott's blades surprised the Undercity smiths. Surprise him back.|Hand Ott the materials and wait for his answer.|Tarren Mill is a long road. Take the fine materials there.|Give an unknown smith his chance. Kind deeds start quiet.",
	[95125] = "Clang goes the hammer on the blade. Keep time with Ott.|Stand back, Ott says. Stay out of the sparks.|The forge roars. Match its heat while Ott works.|Watch the metal glow and cool. Breathe with the forge.",
	[95126] = "The Moonsilver Blade is heavy with purpose. Carry it proud.|The Masterwork is in hand. Keep it steady for Trevan.|From Tarren Mill to Silverpine. Ott's thanks go with you.|Honor goes with you, says Ott. Let it settle in.",
	[95140] = "Old Fire-Eye is the biggest worgen of all. Bring him down.|Near the gates of Gilneas, Fire-Eye hunts. Be ready.|Fire-Eye roams a wide land south of here. Track him.|The Moonsilver Blade must not fail. Nor your nerve. Steady now.",
	[95161] = "Jeremy's letter must reach Duskwood. Earn the long road.|Avette needs another pair of hands. Lend yours, still and sure.|Duskwood is dark and far. Get the letter there.|Tell little Jeremy they're all thinking of him. Think of him too.",
	[95189] = "Few relics survived Lordaeron. Lady Dena Kennedy wants this one.|The weathered crest is fragile. Keep it safe and steady.|Ruins to Stormwind City, the crest rides with you.|A fallen kingdom's mark in your hands. Give it a quiet moment.",
	[95195] = "Marcus Jonathan wants ten old insignias. Search the ruins.|Each medal was a soldier. Stand at attention for them.|Through the Ruins of Lordaeron, medal after medal.|Families will get these back. Think of them, gently.",
	[95204] = "Oran Snakewrithe wants the crest. Don't make him wait.|In the Undercity, the crest feels heavy. Keep it level.|Wind through the ruins and down to the Undercity.|Lordaeron is gone, but its crest remains. Honor it calmly.",
	[95212] = "Six pristine pelts from the fiercest leopards. Go get them.|Lie in wait in the snow until a leopard shows.|It's biting cold up east. Stay warm by staying on the go.|The rams need saddles for Alterac. Picture the ride, calm and sure.",
	[95213] = "DANGER, says the keg. Hurry it to the quarry anyway.|Carry the empty keg steady. Troggs might want it back.|A sinking feeling. Get to Gol'Bolar Quarry fast.|Troggs with blasting powder. Keep a cool head about it.",
	[95214] = "Sixteen kegs of powder in trogg hands. Take them back.|The troggs play with fire. Stay steady near the powder.|East of the quarry, trogg after trogg. Get that powder.|Magni's throne room is safe while you stay calm. Easy does it.",
	[95216] = "Witherfang bites through dead flesh. Make your reps bite back.|Wait near the web. Witherfang must not see you shake.|Its venom is fast. Be faster in the ruins above.|Griffs wants a sample, not a fool. Calm hands for the vial.",
	[95217] = "Twelve copper bars for Frast. Stack them up in reps.|The anvil does not budge. Be the anvil.|The supply cart is late. Go fetch it yourself, fast.|Frast cools the metal slow. Cool down like the steel.",
	[95250] = "The Baron has a big head. Your reps will bring it in.|Truman keeps his post. Hold yours as long as he does.|The war rages in the ruins. Charge in after the Grand Marshal.|Truman thinks you won't last. Prove him wrong with a clear mind.",
	[95314] = "The ruins of Shadowvale hide the elixir. Dig it out with your reps.|Hold. The Whispering Forest is talking. Let it pass you by.|Shadowvale lies deep in the woods. Don't stop until Brill is far.|Carolai Anise pays well for quiet hands. Keep yours calm.",
	[95328] = "The residue squirms. Your reps keep the lid shut.|Jar level, lid on. Lankester wants it all.|Down to the War Quarter before the goo gets out.|It still squirms. Stay easy all the way to Undercity.",
	[95349] = "The skycutter needs a crew. Pull your weight with reps.|The ship lifts off. Brace until Mulgore comes into view.|The dock is just outside the lodge. Don't miss the ship.|Banu-Alah. Watch Valanaar fade behind the clouds.",
	[95350] = "Thrall meets many heroes. Show up with a few reps done.|The wind rider dips and turns. Grip tight to Orgrimmar.|Thunder Bluff to Orgrimmar. The winds guide you east.|The Valley of Wisdom earns its name. Arrive with a clear head.",
	[95494] = "Six lion hides. Start with the big ones, like he said.|The Matriarch watches from the grass. Don't move first.|Lions rule the Barrens. Run them down.|A good hunter waits in the tall grass. Be that hunter.",
	[95495] = "Up the ridge with the bundle. He can't, so you will.|The hillside is steep. Stay firm with the hides on your back.|Climb to the hermit's ridge above the Dry Hills.|His looks may alarm you. He's no threat. Breathe easy.",
	[95507] = "Eight traps to check. Reset them fast.|Something moves near the trap. Wait and watch.|Vrang's traps are spread over the valley. Go check them all.|Wild things roam here. Eyes open, breath low.",
	[95508] = "Kul Tiras marines up the ridge. Meet them head on.|By Walton's side. The ridge is yours to hold.|Terry Longdrink's men charge the hill. Don't let up.|Walton is still telling his story. Listen close until the fight.",
	[95621] = "Kul Tiran soldiers at the wreck. Clear them out.|Lie low above the caravan. Watch what they search for.|South to the wrecked caravan. Find out why they came.|A rifle scope needs a calm eye. Look slow, see it all.",
	[95771] = "A taste of darkness in Elwynn. Push it back.|The dark creeps over the forest. Don't give it an inch.|Shadows spread fast in Elwynn. Stay ahead of them.|Even Elwynn has dark corners. Find the light within you.",
	[95774] = "Four adornments of polished bone. Win them back for Olgra.|Mankrik builds her memorial. Stand guard while he works.|The Razormane Raiders flee. Chase them down for Mankrik.|Her name is Olgra. Take a quiet moment for her.",
	[95803] = "Gelhardt's head is heavy. Carry it with pride.|Sylvanas stares. Stand tall before the Dark Lady.|Take the head to the Undercity. The Dark Lady waits.|She mistrusts you. Keep your face calm and your words few.",
	[95805] = "The incense smokes. Push on to the shrine.|Incense up and dry. Not a drop of water.|The incense burns fast. Race to the shrine in the hills.|Sun and moon, An'she and Mu'sha. Give them a quiet thanks.",
	[95816] = "Sign here. And here. And here too.|The form is long. Wait in line for Elaine Compton.|Take the form to Redridge before the ink dries.|Read the small print. Stay cool. It is only a form.",
	[95819] = "One form, many boxes. Tick them all for Jornah.|Jornah is busy. Wait in the dust for your turn.|Carry your signed form across the Barrens to Jornah.|Your signs will hang all over Azeroth. Smile at that.",
	[95883] = "The undead of Beren's Peril hold a Tortured Soul. Take it.|The altar waits. Stay firm among the restless dead.|Try every undead in the ruins until one gives it up.|The note says all is ready. Ready yourself too.",
	[95884] = "The note is torn. Find the stone anyway.|Stop. Read the note again. The stone is near.|Beren's Peril is big. The stone is out there.|Look around slow. Old stones hide in plain sight.",
	[95885] = "You gave the blood. Now fight what comes out.|Dread washes over you. Stand your ground at the stone.|The Tortured Soul is free. So is the thing that held it.|A willing gift. Take a breath before you give it.",
	[95981] = "Eight wizards, eight watchers. Cut the relic road.|Watch the roads near Ambermill. Let no one pass.|Patrol the roads of Silverpine for Allister.|The Kirin Tor feel magic stir. Stay quiet as the woods.",
	[95998] = "Sam's campfire needs wood. Earn your seat by it.|Sit by the fire. Stay there till the rest kicks in.|Fortune and glory wait. First, get to the fire.|Get comfy near Sam's fire. Let the warmth sink in.",
	[95999] = "Gar'im burns towns. Your reps put out the fire.|His Shadowcasters guard the valley. Wait for your moment.|Into Render's Valley. Gar'im will not wait.|Magistrate Solomon wants proof. Bring a steady hand, and the staff.",
	[96031] = "Stitch the hides tight. A tent must not leak.|Hold the leather taut while Gretta checks your seams.|Twenty points of skill. Then off to Gretta in Ironforge.|Picture the tent: cool when hot, dry when wet.",
	[96044] = "Hammer to twenty. Tognus waits in Kharanos.|Blades on the wheel. Leave them there until they shine.|The forge is hot. Work it until your skill reads twenty.|A sharp blade starts with a calm smith.",
	[96045] = "Alchemy to twenty. Grind herbs and count your reps like vials.|Hold the flask steady while the mix settles. No spills for Vosur.|Spellcasters will come running to your Mana Well. Beat them there.|Stir slowly and watch the potion turn blue. Calm hands brew best.",
	[96046] = "Strike the rock for Yarr. A Lodestone needs good ore.|Brace in the tunnel. The rock won't give up easy.|Vein to vein across Dun Morogh. Twenty skill to go.|Good honest work. Let the dust settle.",
	[96047] = "Roll the linen tight. Thamner Pol likes a neat kit.|Press the bandage down. Thamner is watching.|Stitch cloth after cloth until your skill reads twenty.|Steady hands pack the best kit in Kharanos.",
	[96050] = "Reel them in at Iceflow Lake. Paxton counts your catch.|Line in the water. Wait for the bite.|Cast, reel, cast again. Twenty skill by the lake.|A Fish Bowl brings joy. So does a quiet lake.",
	[96055] = "Pick the flowers, fill the pack. Reyna needs them.|Wait by the herb. Don't crush the petals.|Field to field, flower to flower. On to twenty.|Smell the Incense Candle before you make it.",
	[96056] = "Hides for a Camp Chair. Balthus wants plenty.|Knife steady on the hide, nice and slow.|Beast after beast in the wilds. Skin them all.|Take a load off, like the chair will let you soon.",
	[96057] = "Needle in, needle out. The banner won't sew itself.|Cloth flat on the table for Uthrar Threx.|Bolt after bolt of cloth. Twenty skill for a banner.|Your banner flies high over the camp. See it now.",
	[96058] = "Bits, bots and bombs. Build them up for Bronk.|Steady on the wire. One slip and it goes boom.|Tinker fast. The Reagent Bot won't wait in Kharanos.|Count the gears. A quiet mind builds a better bot.",
	[96059] = "Rune after rune. Thonys wants a lute that sings.|The rod rests on the lute until the magic takes.|Magic on everything. Twenty skill, then off to Thonys.|Hum a tune. Your lute will learn it soon.",
	[96101] = "Raan's campfire wants fuel. Bring some.|Stay by Raan's fire. The rest will come.|Restless souls roam far. Make it back to camp.|Raan's fire does the work. You just sit and breathe.",
	[96102] = "Snang wants tight seams. Pull every stitch firm.|Hold the banner pole straight in Orgrimmar's wind.|Sew until you hit twenty, then find Snang.|A banner lifts the whole camp. Let it lift you too.",
	[96130] = "Chakuyak hunts travelers. Now she's the hunted.|She moves from tree to tree. Wait for her.|Chase her west of Stonebull Lake.|Other hunters seek her too. Breathe, and team up.",
	[96137] = "Ten young, seven grown. The worg must answer to Ira.|Ira kept these woods safe. Stand where she stood.|The Black Ravagers roam Duskwood. Go after them.|Ira's ghost still walks here. Let her rest.",
	[96138] = "Eight warriors, four taskmasters. Merrick's road is yours.|Guard the road near Raven Hill as Merrick did.|South of town the ogres roam. Drive them off.|Merrick's spirit wanders. Give it some peace.",
	[96139] = "Turn over every stone in Raven Hill.|Pause at the graves. These folk earned it.|Comb Raven Hill from end to end.|Remember the heroes. Sirra wants them known.",
	[96204] = "Lumina wants these creatures to pay. Help her.|Guard Lumina's back in Fenris Keep.|Out of Fenris Keep! Lumina leads the way.|Free at last. Let the wind carry you out.",
	[96243] = "Anvilmar was forged by hammer and fire. Earn your way in.|Feet on the stone. Let the earth hold you.|To Coldridge Valley and Teo Hammerstorm.|The elements prickle in your skin. Feel them.",
	[96390] = "Ten Dark Iron spies. Nip them in the bud.|Spies hide at Ironband's. Stay out of sight.|East to Ironband's Compound. Catch them all.|A spy thinks no one sees. Prove him wrong.",
	[96391] = "The map shows tunnels under Ironforge. Get it to Farsen.|The wind whispers. Stay put and hear the voice.|Farsen needs this map now. Don't dawdle.|Jagged runes, strange tunnels. Look close.",
	[96392] = "Farsen shows you the threat. It is bigger than you'd think.|Look through Farsen's farsight. Don't blink.|The Dark Iron move fast. So does your eye.|Let the magic carry your sight across Dun Morogh.",
	[96393] = "Durgen Dirgehammer leads them. Take him down.|The lower vaults are deep. Hold the line.|Push down through the Hall of Thanes.|Magni will hear Farsen's regards. Think of his face.",
	[96394] = "Fifteen apparitions, ten souls. Put them back down.|The tombs rattle. Stand your ground.|The dead are light sleepers. Wake up faster.|The vaults grow quiet again. Help them.",
	[96395] = "Faldrim's grudge is old. Your will is newer.|The Thane will not rest. Be the one who waits him out.|Help... him... rest. Move fast, the grudge won't wait.|The Thane must let go of his grudge. So can you.",
	[96403] = "Eight heirlooms. Grab them before the thief does.|Mole machines rumble. Stay low.|Loot, er, heirlooms, all over the vaults. Grab them.|Catalogued and returned, he swears. Sure he will.",
	[96408] = "Someone lit a fire above Gol'Bolar Quarry. Reps first, then the climb.|Wait low behind a rock. Who sits by that fire?|The hillside is high and the snow is deep. Up you go.|Calm as a mountaineer at dawn, you look down on the quarry.",
	[96604] = "Brakk says rest is earned. Earn it with reps by his fire.|Settle by Brakk's fire and hold. Boosted Rest will come.|Warm up before you settle. Brakk's fire can wait a bit.|Brakk's campfire crackles. Let the warm air fill you up.",
	[96605] = "Kaga Wildhoof has chores before rest. Do your reps, then sit.|Kaga's fire is low and warm. Hold your spot beside it.|Gather sticks for Kaga's fire at a good clip.|Out in the wilds with Kaga. Slow down and watch the flames.",
	[96606] = "Lyreena teaches the wilds. Lesson one is reps.|Lyreena says let the rest sink in. Hold there.|Restless souls can't settle yet. Use up the itch first.|Stars above Lyreena's camp. Easy air, slow thoughts.",
	[96607] = "Eleanor Shackleton kept camp through hard nights. Reps for her.|Eleanor's campfire needs a watcher. Hold your place.|Fetch more wood for Eleanor's fire. The night is cold.|Smoke drifts from Eleanor's fire. Drift with it.",
	[96608] = "Eric Brighthammer swings logs like hammers. Your reps next.|Plant yourself by Eric's fire like a dwarf in snow. Hold.|Snow near Kharanos. Stay warm until Eric's fire catches.|Eric's fire hums. Let the Dun Morogh cold melt away.",
	[96626] = "Tomas in Goldshire needs a cook with strong arms. Reps now.|Keep the pan over the flame while Tomas watches.|Goldshire smells of stew. Hurry to Tomas before it's gone.|Tomas says a good cook waits. Let the pot simmer, and you too.",
	[96627] = "A new face near Goldshire. Warm up with reps before you meet Sam.|Watch Sam Sarsparilla from the road a while first.|Down the road to Goldshire. Sam won't wait all day.|Sam camps under open sky. Take a moment to enjoy it.",
	[96628] = "The Supply Bundle is heavy. Reps make it lighter.|Snow all around. Keep the Supply Bundle off the ground.|Past Kharanos with Eric's supplies. Don't let your feet freeze.|Set the bundle down at last. Eric gives you a nod.",
	[96629] = "Gremlock Pilsnor stirs a big pot. Match him with reps.|Steady the kettle for Gremlock. Don't spill a drop.|Kharanos is cold. Keep warm on the way to Gremlock.|Gremlock's kitchen smells of spice. Take it in slowly.",
	[96630] = "The journal is full of camping fun. Reps on the way to Dolanaar.|Clutch the journal close. Someone's life is in those pages.|Through the woods to Lyreena, journal in hand.|Flip slowly through the journal. The camp stories are nice.",
	[96634] = "Zarrin in Dolanaar wants a cook who works. Reps to prove it.|Zarrin's roast turns slowly. Stay steady like the spit.|Dolanaar's paths wind through trees. Off to Zarrin, quick.|Zarrin says good food starts with a calm cook. Be one.",
	[96638] = "Raan Wildwind left Thendal Grove for glory. Show him your reps.|The road southwest is long. Hold here before you set out.|Out of Thendal Grove and on to Shen'dar Village.|Raan's camp is quiet. Look around and learn what you can.",
	[96646] = "Zerril Softbreeze teaches soft food and hard work. Reps first.|Raise the ladle for Zerril. The soup is almost done.|Shen'dar Village is waiting. Get to Zerril's fire fast.|Soft as the breeze in Zerril's name. Let your breath go easy.",
	[96652] = "A plain journal, a long way to Razor Hill. Reps for the road.|Brakk wants to read it. Shield the journal from the wind.|Across red Durotar dirt to Brakk's camp.|Someone found camping fun enough to write about. Think on it.",
	[96655] = "Cook Torka feeds all of Razor Hill. Pitch in with reps.|The grill in Razor Hill is hot. Stand your ground by it.|Durotar sun, dusty road. Hurry to Cook Torka.|Torka's stew bubbles away. Let yours settle too.",
	[96656] = "The Scarlet Crusade is out there. Reps keep you ready.|Stop by the road and watch Eleanor's camp for a while.|Brill is down the road. Go see what Eleanor is up to.|Eleanor's camp is a strange sight in Tirisfal. Take it in.",
	[96658] = "William Pickman cooks in Brill. Chop up some reps for him.|Brill's kitchen is gloomy but warm. Hold a while.|Rain in Brill again. Get to William's kitchen quick.|Take in the smell of William Pickman's pot, nice and slow.",
	[96659] = "Kaga once helped out. Now your reps pay her back.|The supplies are bulky. Grip them tight across Mulgore.|Long road to Bloodhoof Village. The supplies ride on your back.|Kaga takes the bundle with a smile. A debt is paid.",
	[96661] = "Pyall Silentstride knows the foods of the plains. Reps earn a lesson.|Silent as Pyall's step. Hold without a sound.|The grass of Mulgore rolls on. On to Bloodhoof Village.|Pyall cooks in quiet. Match that quiet with your breath.",
	[96735] = "Toast!? Nobody explains. Do your reps anyway.|Hold up that toast. Or whatever this is.|Something about toast. Go with it, fast.|A quiet moment for the mystery of toast.",
	[96821] = "Six Creepers, six Lurkers. Clear the road with reps.|Spiders wait in their webs. You can wait longer.|Eight legs each, and you still outpace them to Razor Hill.|Brush off the cobwebs. Gar'thok will be glad to hear it.",
	[96822] = "A battleaxe, a bow, a shield. Heavy relics, strong reps.|Crouch behind the Raider's Shield as Tiragarde's guards pass.|Grab the relics and get out of the keep's shadow.|Turroc will honor the fallen. A quiet thought for them.",
	[96825] = "Eight prickly pears for Cook Torka. Earn them with your reps.|Hold low by the cactus. The quilboars have not seen you yet.|Past the quilboar camps and back to Razor Hill. Go, go, go.|Spines on the fruit, spines on the boars. Slow hands win here.",
	[96873] = "Three pendants, three glowing bits. Pa'zula counts your reps.|Don't put the pendant on. Hold it away while the spell fades.|Zalazane's trolls drop pendants. Chase them across Echo Isles.|Pull the magic out slowly. Hands calm, mind clear.",
	[96874] = "Five spines, five stones. Ug'thok wants a mighty axe. Reps!|Press the spine to the grinding stone until it's sharp.|Thunder Ridge beasts don't give up spines easily. Go get them.|Saru laughed. Stay calm; the axe will prove Ug'thok right.",
	[96875] = "Rough lizard hide is thick. Reps to cut through it.|Stretch the hide on the frame and keep it flat for Kamari.|Thunder Ridge lizards roam wide. Keep up with them.|Orgrimmar grows roof by roof. Picture your hides up there.",
	[96876] = "Ukor's pack is stuffed full. Earn the load with reps.|Grip the pack by the flap. Ukor's name is stitched there.|Southern Durotar is dusty. Get the pack back to Ukor.|A lost pack found. Ukor will be pleased. Relax a moment.",
	[96877] = "Halikor fell. The hoof is huge. Reps to lift the proof.|Lift the enormous hoof for all Orgrimmar to see.|Haul Halikor's Hoof up the road to Orgrimmar.|The mighty lizard is gone. Let the win sink in.",
	[96895] = "Scourge cultists near the city. Your reps get you ready for them.|Wait by the gate. The Argent Dawn will come to you.|Head southeast to the city gate. The cultists are close.|Forsaken or not, the Argent Dawn looks calm. Match them.",
	[96896] = "Garek Bandarion wielded the Light. Reps in his honor.|Danitha and Leonid talk. Hold and listen.|Bandarion Keep bustles with paladins. Stay on your toes.|Old friends lost to Naxxramas. Listen with a quiet heart.",
	[96897] = "Eight Neophytes, eight Enforcers. The Cult gets your reps.|The cultists chant. Stand firm and wait for your chance.|Chase the Cult of the Damned out of Tirisfal.|Tirisfal has seen enough. A calm moment before the fight.",
	[96898] = "Twelve Necrotic Crystal shards. Reps to match the haul.|Careful with the shard. Hold it out, away from you.|Shards lie all over. Grab them before the cult can.|Naxxramas broke here once. Walk the field with calm eyes.",
	[96899] = "Leonid waits at Bandarion Keep. Arrive with your reps done.|The Argent Dawn watches over this land. Hold watch too.|Northwest to the keep. The paladins expect you.|The cult is dealt with. A good deed. Let it settle.",
	[97003] = "Chol'aruk is five quilboars big. Your reps must be bigger.|Deep in the Thorn Hill cave. Hold until the Ravener shows.|Blood and thunder! Charge into the lair.|Gur'ak said prepare well. This is that part.",
	[97005] = "They say it swallows orcs whole. Reps say you won't be one.|The cave on Thorn Hill is dark. Hold your nerve.|Bring allies and hurry to the plateau. Bainham waits.|For those Bainham lost, a quiet moment before the beast.",
	[97220] = "Short on dockhands today. Your reps fill the gap.|The Gatehouse Shipment is a surprise. Hold on to it tight.|Through the Trade District to the cheese shop. Chop chop.|Elaine knows these boxes well. Hand it over nice and calm.",
	[97222] = "Only a flight of stairs, they say. Your reps say otherwise.|Balance the crate on the top step. Don't drop the cheese.|Up the stairs in Trias' shop, crate and all.|Set the crate by the door. The guard will come for it.",
	[97223] = "The Bloodtalon Matriarch has killed many. Reps before you face her.|Her eggs are close. Stay low and wait for her to turn.|Raptors are fast. Be faster across the isles.|Hatchlings raised as friends one day. Think of that, softly.",
	[97225] = "Eight idols for the loa. Earn their favor with reps.|Cradle the idol gently. The loa are watching.|Idols lie all over the big isle. Find them all.|Master Gadrin speaks to the loa. Listen for them too.",
	[97234] = "Old tomes weigh a lot. Reps before the library trip.|Keep the wrapped books steady. No torn pages.|The library is across Stormwind. Snacks wait after.|Deep meanings of old legends. Think on one as you go.",
	[97236] = "Githyiss was big. The fang is proof. Reps for the win.|That fang is sharp. Stay steady and mind your fingers.|Take the fang to Aldrassil, quick as a spider.|Someone in Aldrassil loves spiders. Share the find calmly.",
	[97237] = "Four books, heavy ones. Reps first, then the shelves.|The librarian keeps an eye on you. Stay put and look.|Up and down the rows. Find all four books.|Quiet rows of books. Be quiet too, and read the titles.",
	[97242] = "Two cattails, four speargrass. Cut them with power.|The cuttings must stay dry. Stay steady above the water.|Around the water flows and back to Kor'geld. Quick now.|Whuut is too proud to ask. Take a calm breath for him.",
	[97243] = "The Torch of Dormant Flame waits to wake. Reps stoke it.|Hold the torch high. Olariaan will know it on sight.|West of Valanaar, along the island edge. Hurry.|Listen to the spirits of fire, wind, earth and water.",
	[97244] = "Faladiel betrayed the Windshapers. Answer with reps.|The skypriest walks his farm. Wait for the right moment.|Northeast past Valanaar to the farm. Faladiel waits.|The ritual needs a steady mind. Find it now.",
	[97245] = "Rap on the stump. Kuramaa comes. Rep hard.|The spirit shrugs off magic. Stand firm and trust the flame.|The stump sits atop a highland hill. Get up there.|Kuramaa's mask is old wood. Be as calm as a tree.",
	[97246] = "Migi skips lunch. You won't skip your reps.|Wait at Borstan's Firepit while the lunch is packed.|Off to Borstan's. Migi's games won't last forever.|A worried parent asks for help. Take it on with a kind heart.",
	[97249] = "Sweetglazed hog belly for Migi. Reps to earn a bite.|Guard Migi's lunch. No bites for you.|Behind Grommash Hold, Migi plays. Get there fast.|The smell of glazed bits drifts by. Enjoy it, then let go.",
	[97250] = "Two soldiers and one more topple our landmarks. Reps for them.|Hold the Barrens border. This land is ours.|Down to the Dustwallow edge. Kill first, ask later.|Did the Horde burn the tavern? Think on it after.",
	[97253] = "Scattered gears won't pick themselves up. Your reps will.|Pirates stroll past the scrap pile. Stay low and hold till they go.|Grab a part, dodge a scimitar, grab another. Ratchet is waiting.|Wrenix likes your odds. Calm breaths make them even better.",
	[97257] = "Olariaan calls the spirits. Your reps feed the flame.|Torch up. The fire spirits must see it.|The flame fades fast in Skywall. Get it to Valanaar.|A calm mind for the ritual. Let the brazier glow.",
	[97263] = "Eldrun's box says urgent. Your reps say you got it.|Eldrun's box came from Aerie Peak. Don't drop it now.|Urgent means go. Ironforge halls are long.|Read the label twice. Then take a calm breath.",
	[97275] = "Yelmak wants Whuut to learn the basics. So do you.|Yelmak's potion stays flat in your hands.|Whuut is in a rush. Go find him fast.|Good brews take time. Slow down like Yelmak.",
	[97277] = "Snow leopard on the loose. Meet it with your reps.|Wait in the hills. The big cat will show.|It moves in a blur. Stay on its tracks.|Quiet as a cat. Find Gozwin's log in the snow.",
	[97279] = "Six old swords lie in the dirt. Pick them up.|Grip that old blade tight. Kzan is watching.|Boars roam the Valley of Trials. Grab and go.|Show Kzan a calm recruit, not a failed one.",
	[97281] = "The orb hums in your hand. Bring your reps to Rezlak.|The orb sparks. Not a twitch from you.|Drygulch Ravine is that way. Off you go.|Dark mist swirls in the orb. Let your mind go calm.",
	[97282] = "Five lizard parts. Five zaps of work.|The lizards buzz with power. Pick your moment.|Race down the gorge. The lizards are quick.|Rezlak says be ready. Get calm, then seize it.",
	[97286] = "The mage books open for those who do the work.|Stand at the door. The books will open.|Many halls, many books. Find your way in.|A mage reads slow and thinks clear.",
	[97288] = "The head fell off again. Your reps stay on.|This head likes to roll. Firm grip.|Faranell waits in the Undercity. Take the head.|The ruins are quiet now. Take a moment.",
	[97289] = "Othmar was a Grand Marshal once. Now he is a head.|Set the head down. Do not attach it yet.|Next room over. The body waits.|Faranell says wait. Patience, then.",
	[97290] = "Othmar says be gone. Stay and do your work.|Othmar glares at you. Stare back.|Back to Faranell with the news.|Othmar won't help. Let it go for now.",
	[97291] = "A skullcap, some weed, some poison. Three stops.|Toxic Skullcap goes at arm's length. Far from your nose.|Trade Quarter to Rogues' Quarter. Get going.|Take the Blisterweed. The Alliestars owe Faranell.",
	[97292] = "Feed the serum in. Othmar will learn to serve.|Do not drop it. Faranell can't get a new helper.|Get the serum to the pipes before it hisses out.|Steady hands on the Hissing Serum.",
	[97326] = "Eight smooth rocks for Thra. Lift with care.|A boulder in your arms. Thra wants it here.|Behind Grommash Hold is a long walk with rocks.|Soon they get a seat. Rest a moment like them.",
	[97485] = "Herbs, cedar, thread and flint. Buy them all.|At the edge of Hunter's Rise, the wind picks its time.|Up and down the rises of Thunder Bluff you go.|Let the incense drift on the wind. An'she watches.",
	[97538] = "Thirty mirkweed pods. Tah needs lots of red.|Wade in and reach for the pods. Mirkfallon Lake is cold.|Long road to the Stonetalon Mountains. Young hooves, go.|The lake is round and still. Be like it.",
	[97558] = "Duskbats, darkhounds, murlocs. Shelene wants it all.|The darkhounds prowl. Stand your ground.|From bat caves to the murloc shore. Move.|Take it slow. Tirisfal fog hides a lot.",
	[97891] = "Alessandro can't run. That's your job now.|One shake and the Unstable Potion blows. So don't.|Cross the slime canal. The clock is ticking.|The Apothecarium is close. Calm hands deliver.",
	[97894] = "Borgus says a Steelhand is a fair deal. Be one.|The ship comes to the southern dock. Be there.|Off to Auberdine to find Gorbold.|Sea air on the ship. Let the waves rock you.",
	[97899] = "Skill twenty in alchemy. Stir your way there.|Up with the vial. Whuut wants a look.|Potions bubble in Orgrimmar. Get to Whuut.|A Mana Well needs a calm brewer.",
	[97900] = "Strike the anvil. Dwukk knows the sound of skill.|Tongs on hot steel. Don't let go.|Razor Hill is close. Run to Dwukk.|A sharp blade starts with a calm hand.",
	[97901] = "Jhag wants proof of skill. Put the work in.|Rod over the dust. Let it glow.|Get to Jhag. A lute waits.|Play a soft tune on the Enchanted Lute in your head.",
	[97902] = "Bolts, bots and bombs. Mukdrak wants proof.|Wrench still. One slip and boom.|A tinker waits in Razor Hill. Go see Mukdrak.|Check the wires twice. Calm engineers keep their eyebrows.",
	[97903] = "Roll the bandages. Rawrk counts them.|Wrap it snug. Rawrk will check.|Rawrk is in Razor Hill. Bring your kit.|Calm hands make good bandages.",
	[97904] = "Cast and reel. Lau'Tiki is counting your catch.|Line in the water. Wait for the bite.|Down to Sen'jin Village. Lau'Tiki has a fish bowl plan.|Watch the bobber float. Nothing to rush.",
	[97905] = "Flowers won't pick themselves. Jandi knows.|A bee sits on the Peacebloom. Let it leave first.|No dilly-dallying. Jandi is in Orgrimmar.|Smell the Incense Candle before it's made.",
	[97906] = "Stitch the hide. Karolek wants a tent.|Pull the leather tight and don't budge.|Karolek is in Orgrimmar. Bring your hides.|A tent for rain and sun. Rest easy under it.",
	[97907] = "Chip the rock. Krunn hears it from Razor Hill.|Stay in the tunnel. The ore vein is right here.|Down the mine and back up to Krunn.|The Lodestone hums. Let it settle you.",
	[97908] = "Hides pile up. Thuwd likes a tall stack.|Knife steady on the hide.|Orgrimmar's Thuwd has a chair plan. Go get it.|A comfy chair is coming. Take a load off.",
	[97914] = "Thundris wants Auberdine known. Carry his word.|Salt spray on the deck. Thundris' letter stays dry.|Stormwind is across the sea. Find Baros.|Old ruins, a humble town. Think on Auberdine.",
	[97915] = "Mallory wants a real alchemist. Earn it in reps.|The brew must settle. So must you.|Elwynn Forest calls. Mallory has a recipe.|Mix it slow. A good Mana Well starts here.",
	[97916] = "Smith Argus counts every blow. Make them good.|Blade to the wheel. Watch it shine.|The forge is hot. Keep that fire going.|Let the metal cool. Then look it over.",
	[97917] = "Betty Quin shares her lute trick with hard workers.|Magic dust in your palm. No spills.|Across Stormwind to Betty Quin.|Camp music soon. Rest your mind before the trail.",
	[97918] = "Tighten the gears. Sprite Jumpsprocket is picky.|Steady on the fuse. Not yet.|Your Reagent Bot won't build itself. Hurry up.|Think like a bot. Clear and calm.",
	[97919] = "Linen and more linen. Michelle Belle needs rolls.|Pin the cloth in place and wait.|Goldshire is down the road. Michelle Belle is there.|A camp kit can save a friend. Take a quiet moment.",
	[97920] = "Lee Brown pulls fish all day. Your turn.|The bobber dips. Not yet. Not yet.|Grab your pole and head for Lee Brown.|A happy fish in a bowl. A happy you by the lake.",
	[97921] = "Pomeroy likes a full herb bag. Fill it.|Pomeroy says roots come out slow. Grip and wait.|Elwynn Forest has herbs all over. Go find them.|Candle smoke drifts up. Let it lift your spirits.",
	[97922] = "Adele Fielder cuts hides with care. Match her skill.|Tent pole up while Adele ties it.|Adele is close by in Goldshire. Bring hides.|Rain taps on the tent. Nice and dry inside.",
	[97923] = "Crack the copper. Gelman Stonehand is waiting.|Pick braced on the stone. The crack is coming.|Stormwind has Gelman. Get down to his shop.|Good honest work. Rest the pick and look around.",
	[97924] = "Helene Peltskinner knows good pelts. Bring yours.|Lay the pelt on the frame. Keep it flat.|Pelts wait in the wilds. Then Helene in Goldshire.|Sink into your camp chair in your mind.",
	[97925] = "Needle in, needle out. Eldrin wants a banner.|Banner high over camp.|Eastvale Logging Camp is a hike. Get to Eldrin.|The banner waves in the wind. Calm and proud.",
	[97926] = "Baros has little to give. Give it your all.|It's not the answer Thundris wants. Bring it anyway.|Back to Darkshore with the reply.|Stormwind's coin is thin. Make do, and stay calm.",
	[97927] = "Grind the herbs. Kray is watching your work.|The flask is full to the top. Don't spill it.|Thunder Bluff is up high. Kray waits at the top.|Casters will line up for your Mana Well. Get ready.",
	[97928] = "Thrag Stonehoof pounds steel. Pound yours.|Bar on the anvil. Keep it there.|Warriors and rogues are lining up. Get that wheel done.|Honing takes patience. Thrag has lots of it.",
	[97929] = "Rune after rune. Mot will like what he sees.|Let the glow build. Mot says wait.|Dusty trails ahead. Mot will get you ready.|A lute by the fire. Hum along, nice and slow.",
	[97930] = "Twizwick hides in a Venture mine. Earn a visit.|The gizmo buzzes in your grip. Stay with it.|Out to the mine in Mulgore to find Twizwick.|Plan the bot in your head, bit by bit.",
	[97931] = "Vira Younghoof wants neat work. Show her.|Vira likes a kit that stays shut. Clamp it.|Bloodhoof Village is waiting. Head for Vira.|Soft grass, soft cloth. Easy does it.",
	[97932] = "Uthan Stillwater reels them in, slow and sure.|Be like Uthan. Still as the water.|Pole in hand, out to Uthan in Bloodhoof.|Ripples fade. Let your thoughts fade too.",
	[97933] = "Komin Winterhoof gathers by the armload. Do the same.|Komin needs the herb bundle steady.|Mulgore fields are wide. Cover them.|A quiet field, a sweet herb. Stay in the moment.",
	[97934] = "Chaw Stronghide wants skill twenty. Stitch your reps like tent seams.|A good tent stands firm in the rain. So do you, for this hold.|Bloodhoof Village is waiting. Keep that leather moving.|Picture the tent up, the rain outside, and you dry within.",
	[97935] = "Brek Stonehoof wants skill twenty. Crack the rock with your reps.|The Lodestone sits heavy and sure. Be the stone in this hold.|Ore veins hide all over Mulgore. Go find the next one.|Thunder Bluff's winds blow high. Let them fill you and pass.",
	[97936] = "Hides don't skin themselves. Put your rep into the knife.|Yonn Deepcut is watching. Hold the hide flat and let the blade work.|Beasts roam Mulgore. Chase down more hides before dark.|Think of the Camp Chair. Soft hide, a slow sit, a calm mind.",
	[97937] = "Vhan sews banners. Your reps are the thread that holds it.|A banner in still air hangs straight. Hang in there with it.|Needle in, needle out. Vhan's banner needs a fast hand.|Picture your banner rising over camp, calm and proud.",
	[97938] = "Cyndra Kindwhisper counts vials. Fill your reps like she fills them.|A brew needs time to settle. Let this hold settle too.|Herbs in, flask out. Dolanaar's alchemist never slows down.|A Mana Well is still water. Let your breath be the same.",
	[97939] = "Elisa Steelhand hits the anvil hard. Your reps ring just as loud.|Steel cools slowly in the trough. Wait with it until it hardens.|Auberdine's forge roars. Feed it air and keep it hot.|A blade is only as calm as the hand behind it.",
	[97940] = "Alanna Raveneye tunes the Enchanted Lute. Pluck out your reps.|A good note hangs in the air. Hold yours as long.|The lute plays a quick song in the Oracle Glade. Match it.|Soft strings, soft glade. Let the song settle you.",
	[97941] = "Jenna Lemkenilli turns bolts. Turn out your reps like a Reagent Bot.|A bot on standby does not twitch. Go on standby for this hold.|Gears spin, springs pop. Your Reagent Bot is warming up.|Even Jenna stops to check her plans. Breathe and look them over.",
	[97942] = "Byancie rolls linen into bandages. Roll out your reps.|Keep the bandage tight until Byancie says it's done.|Someone in camp needs a kit. Get there fast.|A steady hand ties the best knot. Find yours now.",
	[97943] = "Astaia wants skill twenty. Reel in your reps like trout.|The bobber sits on the lake. Don't move until it dips.|A fish is on the line! Don't let it slip away.|The Fish Bowl glows by the fire. Watch the fish drift and relax.",
	[97944] = "Malorne Bladeleaf needs flowers. Pick a rep for each one.|Peacebloom grows slowly. Let this hold grow with it.|Silverleaf on the hill, Earthroot by the stream. Go gather.|Light the Incense Candle in your mind. Smell the smoke drift.",
	[97946] = "Nadyia Maneweaver needs thick leather. Tan it in reps.|Tent poles don't sway in the wind. Neither do you.|The road to Darnassus is long. Hides won't carry themselves.|Under your tent, rain taps softly. Listen and let go.",
	[97948] = "Kurdram Stonehammer wants copper. Your reps chip it free.|Brace the tunnel beam. Kurdram needs it to stay up.|Copper veins dot Darkshore. Off to the next one.|Deep in the mine, the dust settles. So do you.",
	[97949] = "Radnaal Maneweaver trades in hides. Pay him in reps.|The nightsaber is close. Freeze until it passes.|Teldrassil's beasts are quick. Keep up with them.|A comfy Camp Chair waits. Think of sinking into it.",
	[97950] = "Trianna counts stitches. Count your reps along with her.|Pull the thread tight and hold. Trianna's banner must not sag.|Trianna's needle flies across the cloth. Fly with it.|Linen and lamplight in Darnassus. Let the calm sink in.",
	[97951] = "Carolai Anise grinds herbs. Grind out your reps in Brill.|Don't budge until the brew in Carolai's flask turns blue.|Brill's potion shop is busy. Fetch, stir, fetch again.|The Mana Well gleams. Taste the calm it brings.",
	[97952] = "Basil Frye has iron to shape. Strike it with your reps.|Grip the tongs over the forge. Basil won't let you drop them.|The Undercity forges never cool. Keep the bellows going.|Sparks fade in the dark. Let your thoughts fade with them.",
	[97953] = "Vance Undergloom wants skill twenty. Your reps are the magic dust.|The rod glows. Hold it there until the rune takes.|The Enchanted Lute plays a lively jig. Don't miss a beat.|A slow tune from the lute. Let it drift you away.",
	[97954] = "Graham Van Talen needs a Reagent Bot. Crank out the reps.|One wrong twitch and it all goes boom. Graham says wait.|Bits, bots and bombs. Graham needs them all, and fast.|Count the gears. Slow the ticking. Graham likes a calm engineer.",
	[97955] = "Nurse Neela has linen to fold. Fold it into reps.|Press the bandage and keep it there. Nurse Neela is watching.|Brill's streets need kits. Nurse Neela sends you off.|Nurse Neela's hands never shake. Find that calm in you.",
	[97956] = "Clyde Kellen wants skill twenty. Pull your reps from the lake.|Line out, rod up. Clyde says the big ones like patience.|It's a big one! Reel fast before it breaks the line.|Brill's pond is quiet at dusk. Watch the ripples fade.",
	[97957] = "Faruza needs Mageroyal by the bunch. Pluck your reps.|Earthroot clings to the soil. Cling to this hold just as hard.|Tirisfal is full of herbs. Out you go, basket in hand.|The Incense Candle burns low. Breathe in its sweet smoke.",
	[97958] = "Shelene Rhobart wants soft leather. Your reps pound it smooth.|Stake the tent down tight. Tirisfal winds are strong.|The road to Undercity is long. Shelene's tent won't sew itself.|Rain on the tent roof. Nothing to do but listen.",
	[97959] = "Brom Killian wants tin. Knock it loose, then more.|The tunnel creaks. Stand firm until Brom gives the all-clear.|More ore down the next shaft. Brom won't wait.|A Lodestone hums near the fire. Let its low hum fill you.",
	[97960] = "Rand Rhobart needs hides for the Camp Chair. Bring them in reps.|Wait by the wolf den. Rand says the pack comes to you.|Tirisfal's wolves roam wide. Chase down the next hide.|Rand says take a load off. The chair is almost built.",
	[97961] = "Bowen Brisboise sews the Horde's banner. Sew your reps into it.|Hold the banner high while Bowen checks the hem.|From Deathknell to Brill, Bowen's cart rolls on. Stay with it.|A banner flaps once, then falls quiet. Let it settle.",
	[97963] = "Nyassa Swiftdraught mixes fast. Mix up your reps just as fast.|The draught must steep. Stay right there with it.|Swiftdraught by name, swift by nature. Go, go, go.|Spellcasters sip at the Mana Well. Take a slow sip of air.",
	[97964] = "Aedi Thriceforged forges each blade with care. Your reps get the same.|Keep the blade on the Sharpening Wheel. Aedi wants a true edge.|Warriors and rogues line up at Shen'dar. Turn that wheel!|A sharp edge takes a calm mind. Aedi has both.",
	[97965] = "Naleeia Tattermend packs kits by the stack. Stack up your reps.|Keep that knot tight. Naleeia is almost done tying.|Word from the camp: someone needs a kit. Off to Shen'dar!|Naleeia hums while she wraps linen. Hum along, slow and low.",
	[97967] = "Fenn Fairweather wants skill twenty. Hook your reps from the shallows.|Fair weather, flat water. Fenn says wait for the tug.|The fish is fighting! Fenn cheers you on from the dock.|Fish circle the Fish Bowl. Follow them round with your eyes.",
	[97968] = "Syriel Nightrain wants skill twenty. Your reps fill her herb pouch.|Night rain falls on Valanaar. Stay with it until it stops.|Herbs sprout all over Valanaar. Get them before the boars do.|Candle lit, herbs drying. Syriel's hut smells of calm.",
	[97969] = "Indari Sunseam cuts leather strips. Cut out your reps the same way.|Stretch the hide on the frame and wait. Indari says it must dry.|Sun is up in Shen'dar. Fetch hides before it sets.|A tent in the shade, a cool breeze. Sink into it.",
	[97970] = "Messana Crestwind wants skill twenty. Pick away at those reps.|Brace against the rock face. Messana says the vein is close.|Ore gleams up the crest. Head for it, Messana is waiting.|The Lodestone's pull is slow and sure. Let it draw you in.",
	[97971] = "Mendalass Tattermend needs clean hides. Your reps earn them.|Keep the knife still over the hide. Mendalass likes neat work.|Stags dash through the woods near Shen'dar. After them!|A Camp Chair by the fire. Lean back, just in your mind.",
	[97972] = "Taleen Shimmerthread wants skill twenty. Weave in your reps.|The loom stops. Keep the thread tight while Taleen checks it.|Shimmerthread flies through cloth. Taleen's banner grows fast.|A banner shines in the moonlight. Look up and let it lift you.",
	[97973] = "Taleen's banner needs more thread. Spin the rep count up.|Pin the banner corner down. Taleen isn't done yet.|Spirits are low at camp. Rush that banner to the fire.|The banner is done. Look at it, and let the calm come.",
	[97977] = "Four Gnarlpine Totems. Tarindrella wants each one found.|Grell lurk near the camps. Wait in the brush till they pass.|The totems lie scattered along the glen. Search fast.|Read the old carvings slowly. The furbolg story is in there.",
	[97979] = "Elune's Light guides your strikes. Make your reps hit true.|Shadowmeld means not a flicker. The moon hides you now.|Out from the shadows, into the light, and back again.|Bask in Mother Moon's glow. Nestle into Teldrassil's branches.",
	[98013] = "The naga want war. Your reps bring it right to them.|Stand firm in the ruins. The naga will not get past you.|Naga swarm the old city. Stay on them as you head northeast.|Arbal speaks softly of what they once were. Rest in the Grove.",
	[98021] = "Gryan Stoutmantle needs help. Show up with reps to spare.|Westfall's people wait on you. Hold out till you reach them.|South to Westfall, road after road. Sentinel Hill ahead.|A new land, small troubles. Take it in before you head south.",
	[98024] = "Thork at the Crossroads wants proof of your worth. Here it is.|The Barrens sun beats down. Stand up to it with this hold.|Southwest across the vast Barrens. The Crossroads calls.|Go with honor. Wide plains and a dry wind await.",
	[98025] = "Jai'vhanel slashes with sword-sharp feathers. Strike back harder.|Swordfeather perches above Ameth'Aran. Wait her out.|The mad owl hunts the road to Auberdine. Get after her.|One jet black feather is all Glynda needs. Calm aim, clean hunt.",
	[98028] = "Baron Marinous fell hard. Your reps show how you did it.|Keep the globe level. The cloud inside must not stir.|Far south to the Grove of the Ancients. Onu awaits.|Turn the globe and peer inside. The cloud swirls, then clears.",
	[98042] = "Twilight Thugs guard the Peerless Eye. Your reps pry it loose.|A cold voice fills your head at the Master's Glaive. Do not yield.|Grab the eye and take it to Auberdine. Someone will want it.|They have failed, says the voice. Let it drift past you.",
	[98046] = "Fandral is cross. Your reps don't care what he thinks.|Fandral's glare is cold. Take it without a blink.|South to the Temple of the Moon. Lariia takes the phial.|Out of his sight at last. Let Fandral's words fall away.",
	[98065] = "Moonwell water for Tyrande. Your reps carry it up the stairs.|Not a drop of sacred water may spill. Hold on tight.|Tyrande is right above. Up the temple steps you go.|The High Priestess is firm, but kind. Meet her with a calm heart.",
	[98067] = "Four Sentinel Owls, four posts. Dalia counts on your reps.|An owl on its perch sees all. Watch the city like one.|Bank, inn, gate, and the Hold depths. Darnassus is big.|Pray to Elune like the sentinels do. Quiet mind, sharp eyes.",
	[98072] = "Crimson whelps, crocs of the sky. Scales are earned the hard way.|Orcs in the hills. Stay low and wait for a clear path.|East along the Green Belt. The whelps flap, you chase.|Pristine scales need a clean fight. Go in calm.",
	[98093] = "Seven Stormhide, seven Hecklefang. Sulhasa is counting from her tree.|Sulhasa waits up her tree. Wait with her while the hyenas circle.|Clear the golden road so Sulhasa can make it to Camp Taurajo.|The weather is lovely again. Once the field is clear, enjoy it.",
	[98094] = "Deathstalker Masoj needs these orders. Your reps seal them.|Masoj waits on high ground above Nethander Stead. Be as patient.|South from Tarren Mill toward Dun Garok. The orders must arrive.|Spies stay quiet. Slip past like a shadow in the hills.",
	[98095] = "Vials on three peaks. Your reps carry them up.|Uncork the vial and hold. The bats need the scent to settle.|Dun Garok, Dunholde, the Headland. Hills all the way round.|On the ridge above Hillsbrad, wait for the wind to carry it.",
	[98189] = "The Blind Princess never made it. Your reps finish her job.|Keep the Menethil Statuette steady. It is too fine to drop.|Captain Stoutfist waits just behind you. Short trip, quick feet.|A beautiful thing in your hands. Let the calm of it settle in.",
	[98190] = "The Dragonmaw want this statuette. Your reps say no.|A calm harbor in a nasty storm. Hold like Menethil Keep.|Straight to Stormwind. Skip the chain of command and go.|Bolvar will know where it belongs. Walk in with a quiet mind.",
	[98191] = "King Terenas hated fuss. Do your reps with no fuss at all.|The Light gathers in the statuette. Stand firm while it glows.|Cathedral Square is in the center. Cross the city at a steady clip.|Inside the Cathedral of Light, even the air is quiet. Match it.",
	[98197] = "Thirty bars of Khaz Modan Iron. Your reps haul them home.|Six beams of timber on your back. Stand under the load.|Down the docks and back. The old Horde left plenty behind.|Valstag will build walls with this. Set it all down, nice and calm.",
	[98219] = "Farren could use the lesson. Your reps can teach it.|The boat from Menethil rocks. Stand firm on the deck.|Southshore is a long way from Stormwind. Get going.|His father was a friend. Go to Farren with a patient heart.",
	[98240] = "A crate of whelps for Howin Kindfeather. Lift with care, they bite.|The Crimson Crate wiggles. Keep it level so the whelps stay put.|East past Whelgar's Excavation Site. The road is all yours.|One last favor, promised. Let the whelps nap on the way.",
	[98247] = "Torn label, full crate. Couriers get paid for their trouble.|The crude map is smudged. Stand and make sense of it.|Redridge roads lead to Three Corners. Off you go.|Couriers get paid for time. Take yours and settle in.",
	[98248] = "Durotar Supply wants its crates back. Earn that pay.|Due west of the Crossroads, the map says. Stand and find it.|The Barrens are wide and flat. Cross them to the outpost.|The dry wind of the Barrens. Let it slow you down a bit.",
	[98251] = "Six stags, six bears. Va'xug wants the forest thinned.|An Ashenvale Bear rears up. Stand your ground and stare back.|Circle half the forest? Va'xug did. Now you do it.|Va'xug is angry enough for both of you. Be the calm one.",
	[98282] = "Thelgen Rock spiders guard their glands. Earn one the hard way.|The gland must not burst. Hold it gentle and firm.|Far southeast to Thelgen Rock, then back before it spills.|Caitlin needs it whole. Soft hands, soft steps.",
	[98284] = "Twenty points of enchanting. Your reps add the spark.|An Enchanted Lute takes a steady hand. Hold the rune.|Off to Shen'dar Village for Nasalanna's lesson.|Around the camp, the lute plays soft. Rest in the tune.",
	[98285] = "Engineering to twenty. Bolts, gears, and your reps.|The Strange Hermit's gadget needs one part held in place.|Shadowgale Forest is wild. Find the Strange Hermit.|A good engineer thinks before the spark. Think a while.",
	[98286] = "Raise enchanting to twenty. The rods won't charge themselves.|Glowing dust in your palm. Keep it there, don't spill.|The old dusty trail calls. Head for Nasalanna Windsinger.|Camp is set, the fire is low. Let the magic hum.",
	[98298] = "Six Worgen Bits for Dalar. The Greymane Wall is full of worgen.|The worgen watch from the Greymane Wall. Don't blink first.|South to the wall. A direct approach, Dalar says.|Arugal's Curse barely lasts. Your calm lasts longer.",
	[98299] = "Ten refugees at the Greymane Wall. Dalar wants the curse held back.|Stand between the curse and the wall. Don't get bit.|Silverpine is thick with fog. Reach the wall before Arugal does.|Dalar studies. You wait by the wall, quiet and ready.",
	[98319] = "Wendigos fill the Grizzled Den. Clear a path to Cornelius.|Wait in the dark till the wendigo pass.|Cornelius charged in head first. Follow him, just smarter.|Brave, but stupid, Gretchen says. Be brave, not stupid.",
	[98321] = "Eight Flintfire Shipments dropped in the den. Pick them up.|A crate of ore in your arms. Tongus needs it whole.|The miners ran. You go in. Grizzled Den, to the west.|Hands dirty, heart light. Tongus likes a worker like that.",
	[98322] = "Whitebeard is late. Do the legwork for him.|Whitebeard's reports stack up. Stand by for news.|Just west of Kharanos. Gretchen should be there.|The snow of Dun Morogh falls soft. Walk into it calmly.",
	[98323] = "The cave is lost, the report says. Whitebeard won't like it.|Gretchen won't leave her spot till the mountain is safe. Nor you.|Back to Kharanos with bad news. Better get it there fast.|A sad note for Cornelius. Carry it gently.",
	[98326] = "Frosthowl stole a sack of fish. Take it back the hard way.|A frozen lake, a man, a fishing line. Be as patient as Paxton.|Deep into the Grizzled Den to find the loudmouth.|Frosthowl roars and the fish scatter. You wait him out.",
	[98340] = "Dendrite Starblaze has sent for you. Show him you are ready.|Moonglade's magic pulls. Stand in it until it takes you.|Your druid training moves on. So do you.|Next step, young druid. Nighthaven is quiet as a cat.",
	[98341] = "The windborne cat spirit of Zephras waits. Prove your worth.|South of the twin bridges, the Avatar watches. Meet its gaze.|Past the twin bridges, into the south of Moonglade.|Your homeland's cat has a different shape. Learn it slowly.",
	[98342] = "Fang, Claw and Silent Shadow. Three relics for three tests.|Angry spirits pass close by. Freeze in the shadows.|In and out of the Barrow Den before the spirits notice.|Cunning, stealth, and a fierce heart if cornered. Find all three.",
	[98362] = "Turak Runetotem found a worthy pupil. Show him why.|The Great Cat Spirit sees you. Stand tall for it.|Thunder Bluff calls. Up to the Elder Rise.|Part ways with the spirit. It will meet you again.",
	[98372] = "An unfortunate end, but the work still counts.|Some stories end quietly. Stay with this one.|Nothing left here. On to the next road.|A sad close to a tale. Let it go gently.",
	[98386] = "Twelve Greater Tarantulas at Alther's Mill. Oslow is counting.|The eggs are ready to hatch. Stand guard and let none move.|The mill is east. The bridge deadline is close.|Alther owes Oslow. You owe no one. Settle in.",
	[98387] = "Battleworn Axes, ten of them. Take them off the Blackrock orcs.|A long war, Marris says. Outlast the orcs.|South of Stonewatch Keep, raid camp after camp.|Empty bellies, empty hands. The orcs wait. So can you.",
	[98389] = "Forsaken wrapped in web, six of them. Tear them loose.|The spiders of Night's Web Hollow watch. Wait them out.|Night's Web Hollow is northwest. Get there fast.|Aramis says death can't stop the Light. Let it glow in you.",
	[98391] = "Sister Aquinne needs help. Show her what you can do.|Mother Moon is patient. Be patient too.|To Darnassus. Sister Aquinne is ready for you.|Moonlight on the temple. Let it quiet your thoughts.",
	[98392] = "Harpy leaders wear the amulets. Pull all three from the nests.|The taint runs through the leather. Look close and don't look away.|West to the harpy nests. Their leaders won't wait.|Arynia has a hunch. Sit with it while the proof comes.",
	[98393] = "Moonglade calls again. Answer with some work.|The spell to Moonglade is almost done. Keep your place.|Leave soon, your teacher says. So go.|Nighthaven's lanterns glow. Walk in without a rush.",
	[98394] = "A wise and cunning spirit sits on the hill. Be worth its time.|Above the bridge, the Great Cat Spirit sits still. Copy it.|South through Moonglade to the hill by the bridge.|Druids all seek this wisdom. Now it's your turn.",
	[98396] = "Relic of the Fang. Relic of the Claw. Take both, and the third.|The statue's stealth is short. Stay hidden while it lasts.|The Barrow Den is just east. Slip in fast.|A cat waits in the dark. Be that cat.",
	[98397] = "Mathrengyl Bearwalker found a good pupil. Prove him right.|Heed his lessons. The cat shape is close now.|Home to Darnassus and the Cenarion Enclave.|When the time is right, you'll meet again. Until then, rest.",
	[98398] = "The Oracle Tree shed its bark. It has a task in mind.|Bark in hand. Stand and listen for the message.|Nearby, just a short walk to the fallen bark.|Old trees speak slowly. Listen the same way.",
	[98403] = "Befouled Webwoods first, eight of them. Then Xethorr.|Xethorr the Wicked lurks in the Cleft. Don't give ground.|Northwest into the Cleft, through a nest of twisted spiders.|Fel moss stinks of the satyr's plans. Clear your head first.",
	[98404] = "The Avatar of Saeyleenan wants three relics. Earn them.|Spirits pace the Barrow Den. Stay unseen in the dark.|Past the statue, into the den, and out with the relics.|A trial of these lands. Move like wind through grass.",
	[98405] = "The Great Bear Spirit taught you. Now the cat will.|Cats wait in the grass before they pounce. Try it.|Down to southern Moonglade. The spirit is on the hill.|Cat shape starts with a cat mind. Soft and sharp.",
	[98407] = "Five Spiked Collars. The gnolls respect strength, so show some.|Gnolls camp near Lakeshire. Hold the line so they don't come closer.|Into the hills after the thrashers. Feldon wants those collars.|Put the fear of the Alliance in them, then calm your own.",
	[98423] = "A peace between Bronzebeard and Wildhammer. Heavy stone, too.|Old tablet, old clans. Keep it steady on the way.|To Ironforge. Magni will want this at once.|After the War of the Three Hammers came peace. Find some.",
	[98424] = "More pages in the Venture Co. Mine. Dig them out.|Worn papers. Hold them flat and read the plans.|Through the mine and back to Morin Cloudstalker.|Folded in a breast pocket. Some secrets are small.",
	[98427] = "The shredder fells forests. Stop it cold with a group.|Not a single tree more. Stand like the old glades.|Northeast into the mine. The Clearcutter is running.|Where the young ones take first steps. Keep it green.",
	[98430] = "Perith was to be the gnolls' feast. Change the menu.|Palemane Rock is loud. Keep Perith close and wait for a gap.|Out of Palemane Rock, then on to Cairne in Thunder Bluff.|Longwalkers keep secrets. Stay calm, and keep his.",
	[98435] = "Thunderhorn's progress, on paper. Deliver the good news.|The lifts rise slowly to the center of Thunder Bluff. Ride it out.|Cross the bridges to the Elder Rise and find Hamuul.|The elders listen well. Speak to Hamuul at an easy pace.",
	[98447] = "The Valor ghosts still walk. Their weapons may wake the truth.|Raven Hill is cold at night. Stand among the graves and look.|Raven Hill again, with the Valor weapons in hand.|A whole family lost at once. Let the quiet tell you why.",
	[98459] = "Half-fish Tom has a gift for Bart. It's not a kind one.|The boat's second stop is Menethil. Stand on deck till then.|Off to Menethil Harbor to find the captain of a stuck ship.|He cheats at poker, Tom says. Keep a straight face.",
	[98461] = "Hollee's note for Tarrel. Carry it and her hopes.|The boat from Auberdine sways. Keep the note dry.|From Darkshore across the sea to the Wetlands.|Hollee sighs. You don't need to. Just deliver it.",
	[98512] = "Al'Aketh Assassins, ten in all, by the house. Take them out.|Get low and keep quiet, the scout says. Do just that.|Up the hill to the house, before they finish their work.|Someone is watching your back. You can rest your mind.",
	[98517] = "The call of fire comes. Answer it with heat of your own.|The spirits have spoken of you. Stand and listen.|Skycutter from Skywatcher Plateau, home to Zephras Isle.|Fire starts as a small flame. Start small, young Skyborne.",
	[98545] = "Glix Xizzix will pay. Make the trip worth his coin.|Keep Leonid's seal safe. Stand firm past the guards.|Down into the Undercity. The Dark Lady's halls are long.|A neutral friend stays calm. Be that friend for Leonid.",
	[98574] = "Branstock wants a priest with grit. Show him some.|Read the memo by the fires of Anvilmar and do not stir.|Anvilmar is just inside. Go find Branstock at a steady clip.|Let the Light settle in as you read Branstock's words.",
	[98575] = "Nartok wants to see what you can do. Reps first, fel later.|The tablet hums with dark words. Stay with it and read it all.|Off to the Den. Nartok does not like to wait.|Warlocks read slowly. Take in the tablet one line at a time.",
	[98576] = "Mai'ah likes a sharp mind. Rep work sharpens the will.|Glyphs glow on the parchment. Stay put until they fade.|The Den's entrance is near. Mai'ah stands there.|Mages breathe with the arcane. Let the glyphs guide you.",
	[98581] = "Teo carves runes with a heavy hand. Match his force.|The rune is set in stone. Be the stone for Teo.|Warm up the cold halls of Anvilmar on the way to Teo.|The Wildhammer carve with care. Read the rune the same way.",
	[98601] = "Aramis Hammerhand will test your arm. Show him the Light's might.|Step away to read the scroll, and stand firm in the Light.|To the church in Deathknell. The Scourge are still about.|The scroll reeks of the Light. Take it in, calm and slow.",
	[98731] = "The Cat Spirit blessed your claws. Put them to work.|A cat waits in the shadows. Wait like one, then go to Dendrite.|Back to Dendrite, light on your paws.|Let the blessing sink in, soft as a cat at rest.",
	[98738] = "Zephras winds lift you. Lift something back.|The shadows hide you. Stay there until the wind shifts.|Let the winds guide your steps back to Dendrite.|Zephras will be here when you return. Breathe in its sky.",
	[98739] = "Foes will fall to your claws. Test them now.|Hide in the tall grass like the great cat. Wait for your chance.|Dendrite has more to teach. Pad over to him with haste.|The Cat Spirit's blessing is quiet. Let it fill you.",
	[98977] = "Mossheart has seen many moons. Honor the Elder with effort.|Stand before Mossheart as still as an old tree.|The festival lanterns glow. Hurry to pay your respects.|Mossheart speaks slowly. Match the Elder's quiet way.",
	[98983] = "Frostleaf gives coins to those who earn them. Earn one.|Frost clings to the Elder's leaves. Stay just as frozen.|Lunar Festival lights to chase. Frostleaf is at the end.|A cold night, a warm Elder. Let the moon calm you.",
	[99046] = "Eralya is still in training. Show her what training looks like.|Watch the road to the Oracle Glade. Something is not right.|The runner is late. Take the western road to find her.|Elune guide you. Listen to the forest for a sign of Eralya.",
	[99047] = "Harpies everywhere, and Eralya fading. Work fast.|Eralya holds on. Hold on with her until help comes.|Dolanaar is far and Eralya is weak. Hurry to Byancie.|Stay calm for Eralya. Panic won't help her now.",
	[99048] = "Heglan's reports stopped. Put your worry into the work.|The Shattered Hand watch from far off. Watch Tiragarde like them.|North of Tiragarde Keep, fast. The reports are late.|Quiet feet, quiet mind. Heglan would want it that way.",
	[99049] = "A wreck holds three clues. Turn over every stone.|Study the torn ground. The attackers left marks.|Search the fight site end to end. Orgnil wants proof.|Take in the scene. Whatever hit Heglan did not get away clean.",
	[99050] = "Byancie needs six dewy lasher fronds. Pick them one by one.|Stand at Lake Al'Ameth's edge until the fronds show.|Lake, spring, town. Byancie needs it all, and fast.|Teldrassil gives when asked kindly. Take only what you need.",
	[99051] = "Nine spinefins for Orgnil. Naga don't give them freely.|Wait at the edge of the naga camp. Strike when they turn.|The naga scouts flee to the shore. Chase them down.|Before the camp, a still mind. The snakes will not see you.",
	[99052] = "A young sea giant is still a giant. Match his size.|The sea giant swings. Brace against the tide and stay.|Along the north coast, the giant wades. Stay on his heels.|Gather friends and a deep breath before the giant.",
	[99053] = "Furbolgs block the barrow. Clear the way for Lynessa.|Guard Lynessa in the dark. The furbolg are close.|Up from the barrow into the light. Lynessa follows.|Under the earth is no place for kaldorei. Find calm anyway.",
	[99073] = "The salve is ready. Carry Dolanaar's hope in your arms.|Keep the salve steady. Not a drop may spill.|Eralya lies on the Oracle road. Haste is worth it.|Byancie's hope goes with you. Carry it gently.",
	[99079] = "The Longwalkers serve the High Chieftain. Serve Mulgore now.|Scan the eastern edge for a headband and feathered staff.|East of Bloodhoof, to the edge of Mulgore. Find Malah.|Malah is three days gone. Walk softly and listen.",
	[99080] = "Six Galak, four Outrunners, and Herak. Not a blade of grass for them.|Guard the path to the Barrens. None may slip past you.|Outrunners are quick. Be quicker across the plains.|Baine's calm is a warrior's calm. Wear it into the camp.",
	[99081] = "Malah fell with her report in hand. Her words are yours now.|Pause for the Longwalker. She kept her post to the end.|Brave Wildrunner must hear this. To Bloodhoof, fast.|Hard news. Take a breath before you give it.",
	[99082] = "Cairne led the charge with Thrall. Lead one of your own.|Cairne sees bravery. Stand tall before him.|Northwest to Thunder Bluff, then up the lift.|Cairne's rise is high and the wind is soft. Be at peace there.",
	[99101] = "The centaur are back. Baine needs warriors who are ready.|Malah's report is tight in your grip. Don't let go.|No time to waste! Baine is in the center of town.|Steady voice, clear words. Baine must hear it all.",
	[99108] = "Tang Stonehoof wants three wins. Sharpen your horns.|In the arena, all are equal. Stand your ground.|Stay light on your feet. The novices hit hard.|Tang says sword or bow does not matter. A calm mind does.",
	[99123] = "Pal'juh's magic ran dry. Lend the troll your might.|Hide with Pal'juh in the crag until the Kolkar pass.|Out of Kolkar Crag with Pal'juh! Master Vornal is waiting.|In the shadows, even your breath must be quiet.",
	[99127] = "Seven traps in Crystal Lake. Haul up each one.|Wait in the cold water by Lee's traps. Something is off.|Swim from trap to trap across Crystal Lake.|Not a single minnow. Look close and stay calm.",
	[99128] = "Eleven murlocs, sharp teeth. Be sharper.|Murloc teeth snap at the shore. Keep them back.|Round the lake to the murloc side. They won't sit still.|Mrgglll. Ignore the noise and find your quiet.",
	[99129] = "Murlocs keep taking Jason's fish. Put that grudge into your reps.|Remy likes to talk. Stay put and hear out his murloc plans.|Off to find Remy before the murlocs grab another fish.|Remy hates murlocs too. Take a calm breath and let him vent.",
	[99130] = "Eighteen duskweed petals. Pull them from the fields.|Wait in the farm rows. Duskweed hides in plain sight.|Farm to farm across Elwynn for murloc bait.|A win-win, truly a win-win. Say it calmly, like Remy.",
	[99131] = "Fewer murlocs soon. That calls for a round of rep work.|Remember Remy's rundown. Mathers will want all of it.|Jason Mathers needs the good news. Go.|Fewer murlocs, more fish. Let that thought settle.",
	[99134] = "Five Deathguards to motivate. Zygand keeps a ledger.|Zygand watches. Don't be the next name in the ledger.|Swiftly now. The lazy Deathguards are spread out.|Discipline starts with calm. Zygand would approve. Maybe.",
	[99141] = "Dillinger, Kristof, Gordo. Three reports, no excuses.|Zygand's patience ran out. Yours must not.|Graveyard, waystation, Stillwater Pond. Zygand wants them now.|The Dark Lady wants perfect work. Slow down and get it right.",
	[99142] = "Holland wants five tomb weeds for his glorious destiny.|The Scourge are drawn to the weed. Stay put till they pass.|East to Balnir Farmstead. Holland hates slow help.|Curious weeds, curious Scourge. Watch them calmly.",
	[99143] = "Rummage for six bits of shiny junk.|Murlocs love shiny things. Wait until they look away.|In and out of the murloc camp with the loot.|Think like a fish. What would you bite?",
	[99144] = "The Crusaders hate Bareth. Answer them for him.|Bareth steadies himself. Stay at his side.|Flee Crusader's Outpost. Shari Stilwell is in Brill.|Bareth seeks calm in the Light. Seek it with him.",
	[99145] = "A Winter Veil gift! Earn the ribbon first.|No peeking at the gift. Wait for it.|Snow falls and bells ring. Race to the tree.|Winter Veil is a cozy time. Take it in.",
	[99152] = "Hilda wants six glowing bones. Call it a crash course.|Hilda's trainees watch. Show them how it's done.|Down into the cellars below Shadowvale. Go!|Glowing bones, dark cellars. Stay calm below.",
	[99153] = "The crystal raises the dead. Break its hold.|Something hums beneath Shadowvale. Listen until you hear it.|Search the tunnels before this gets out of hand.|Ephram's best guess leads below. Trust it and look close.",
	[99156] = "Riptear slipped past the Bulwark. Send it back.|Riptear lumbers close. Brace and do not give.|Near Venomweb Vale, the abomination roams. Track it.|Need-to-know only. Keep your mind quiet and your lips shut.",
	[99158] = "The candle crate is heavy. Father Gavin is worth it.|Hold the crate of candles steady on the mountain path.|Up into the misty pines. Misty Pine Refuge is ahead.|Father Gavin wants peace for all. Find some on the way.",
	[99159] = "Fourteen logs for Father Gavin's hearth.|Don't drop a log. The wood pile is tall.|The snow is deep. Hurry back with the wood.|The hearth crackles. Rest in its glow.",
	[99160] = "Ten ice elementals. Shatter them for a safer road.|Stand firm on the ice. The elementals slide in.|The rockslide stirred them up. Stir yourself faster.|Cold air, clear head. The mountain road waits.",
	[99161] = "Avala shakes the peaks. Shake the peaks right back.|Avala calls a slide. Plant your feet and stay.|Chase the wild weather to Avala's core.|Snow drifts down after the slide. Let it settle, then act.",
	[99162] = "Lost rifles lie in the snow. Bring them home to Ironforge.|Pray to the Light there's no one to find. Wait and look.|Through the peaks of Dun Morogh, find the lost.|Snow and ice are hard on mountaineers. Honor them quietly.",
	[99191] = "Sixty wool cloth for Dalaran. Stack them high.|The wool bundle is big. Keep it close.|Bolts of wool, off to Dalaran with them.|Soft wool, soft thoughts. Let it all settle.",
	[99196] = "Mulgore's tauren count on sixty wool. Count with them.|The wool pile grows tall. Stand by it and wait.|Across the plains of Mulgore with your wool.|Plains wind and warm wool. Let the quiet in.",
	[99260] = "The Standing Stones' data is lost. Make up for it here.|The Supreme Magister will see you. Stay calm when you meet him.|Valanaar awaits. Elaadrin Evengale wants to see you.|Skycutters cross the elemental plane. Ride its winds in your mind.",
}
